export const dev_seedProductionFoundation = authenticatedMutation
  .input({ workosOrganizationId: v.string() })
  .returns(v.any())
  .handler(async (ctx, args) => {
    requireAnyRole(ctx.viewer.roles, ["admin"]);
    const now = Date.now();

    await projectDevelopmentProductionFoundationWorkosFixtures(ctx, {
      now,
      workosOrganizationId: args.workosOrganizationId,
    });
    const isFairLendBootstrapOrg =
      args.workosOrganizationId === FAIRLEND_WORKOS_ORGANIZATION_ID;

    const brokerageId = await ensureBrokerage(ctx, {
      displayName: FAIRLEND_BROKERAGE_NAME,
      legalName: FAIRLEND_BROKERAGE_NAME,
      now,
      principalBrokerWorkosUserId: isFairLendBootstrapOrg
        ? FAIRLEND_PRINCIPAL_BROKER_WORKOS_USER_ID
        : ctx.viewer.subject,
      workosOrganizationId: args.workosOrganizationId,
    });
    const builderProfileId = await ensureBuilderProfile(ctx, {
      brokerageId,
      displayName: "Production Builder",
      now,
      organizationId: args.workosOrganizationId,
    });
    await ensureBuilderAccountLink(ctx, {
      brokerageId,
      builderProfileId,
      now,
      role: "owner",
      workosUserId: "user_builder",
    });
    await ensureSeedBuilderBrokerAssignment(ctx, {
      assignedBrokerWorkosUserId: isFairLendBootstrapOrg
        ? FAIRLEND_PRINCIPAL_BROKER_WORKOS_USER_ID
        : "user_broker",
      brokerageId,
      builderProfileId,
      now,
      organizationId: args.workosOrganizationId,
    });
    const templateId = await ensureProposalTemplate(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
    });
    await ensureProductionSettingsRows(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
      templateId,
    });
    const workflowRuleId = await ensureWorkflowRule(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
    });

    return {
      brokerageId,
      builderProfileId,
      templateId,
      workflowRuleId,
    };
  })
  .internal();

export const seedProductionDefaultsToProd = authenticatedMutation
  .input({})
  .returns(v.any())
  .handler(async (ctx) => {
    requireAnyRole(ctx.viewer.roles, ["admin"]);
    const workosOrganizationId = await requireProductionSeedOrganization(ctx);
    const now = Date.now();
    const isFairLendBootstrapOrg =
      workosOrganizationId === FAIRLEND_WORKOS_ORGANIZATION_ID;
    const brokerageId = await ensureBrokerage(ctx, {
      displayName: FAIRLEND_BROKERAGE_NAME,
      legalName: FAIRLEND_BROKERAGE_NAME,
      now,
      principalBrokerWorkosUserId: isFairLendBootstrapOrg
        ? FAIRLEND_PRINCIPAL_BROKER_WORKOS_USER_ID
        : ctx.viewer.subject,
      workosOrganizationId,
    });
    const templateResult = await seedProductionDefaultTemplates(ctx, {
      brokerageId,
      now,
      organizationId: workosOrganizationId,
    });
    const workflowRuleId = await ensureWorkflowRule(ctx, {
      brokerageId,
      now,
      organizationId: workosOrganizationId,
    });
    const brokerage = await ctx.db.get(brokerageId);

    return {
      brokerageId,
      settings: brokerage
        ? await buildProductionSettingsProjection(ctx, brokerage)
        : null,
      workflowRuleId,
      ...templateResult,
    };
  })
  .public();

export const dev_seedProductionProposalScenarios = authenticatedMutation
  .input({ workosOrganizationId: v.string() })
  .returns(v.any())
  .handler(async (ctx, args) => {
    requireAnyRole(ctx.viewer.roles, ["admin"]);
    const now = Date.now();

    await projectDevelopmentProductionFoundationWorkosFixtures(ctx, {
      now,
      workosOrganizationId: args.workosOrganizationId,
    });
    const isFairLendBootstrapOrg =
      args.workosOrganizationId === FAIRLEND_WORKOS_ORGANIZATION_ID;

    const brokerageId = await ensureBrokerage(ctx, {
      displayName: FAIRLEND_BROKERAGE_NAME,
      legalName: FAIRLEND_BROKERAGE_NAME,
      now,
      principalBrokerWorkosUserId: isFairLendBootstrapOrg
        ? FAIRLEND_PRINCIPAL_BROKER_WORKOS_USER_ID
        : ctx.viewer.subject,
      workosOrganizationId: args.workosOrganizationId,
    });
    const brokerage = await ctx.db.get(brokerageId);
    if (!brokerage) {
      throw new Error("Missing seeded brokerage.");
    }
    const builderProfileId = await ensureBuilderProfile(ctx, {
      brokerageId,
      displayName: "Production Builder",
      now,
      organizationId: args.workosOrganizationId,
    });
    await ensureBuilderAccountLink(ctx, {
      brokerageId,
      builderProfileId,
      now,
      role: "owner",
      workosUserId: "user_builder",
    });
    await ensureSeedBuilderBrokerAssignment(ctx, {
      assignedBrokerWorkosUserId: isFairLendBootstrapOrg
        ? FAIRLEND_PRINCIPAL_BROKER_WORKOS_USER_ID
        : "user_broker",
      brokerageId,
      builderProfileId,
      now,
      organizationId: args.workosOrganizationId,
    });
    const templateId = await ensureProposalTemplate(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
    });
    await ensureProductionSettingsRows(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
      templateId,
    });
    await ensureWorkflowRule(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
    });

    const auth = {
      brokerage,
      roles: normalizeRoleSlugs(ctx.viewer.roles),
      subject: ctx.viewer.subject,
    };
    const common = {
      auth,
      brokerageId,
      builderProfileId,
      now,
      organizationId: args.workosOrganizationId,
      templateId,
    };

    const proposals = {
      draft: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Draft",
        scenario: "draft",
      }),
      submitted: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Submitted",
        scenario: "submitted",
      }),
      approvedWithPermit: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Approved With Permit",
        scenario: "approved_with_permit",
      }),
      approvedWithWaiver: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Approved With Waiver",
        scenario: "approved_with_waiver",
      }),
      requestedChanges: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Requested Changes",
        scenario: "requested_changes",
      }),
      rejected: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Rejected",
        scenario: "rejected",
      }),
      closed: await ensureSeedScenarioProposal(ctx, {
        ...common,
        buildName: "Seed Scenario - Closed",
        scenario: "closed",
      }),
    };
    const contractorProfileId = await ensureSeedContractorProfile(ctx, {
      brokerageId,
      now,
      organizationId: args.workosOrganizationId,
    });

    return {
      brokerageId,
      builderProfileId,
      contractorProfileId,
      proposals,
      templateId,
    };
  })
  .internal();

export const generateProposalDocumentUploadUrl = authenticatedMutation
  .input({
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.string())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    if (auth.proposal.status === "closed") {
      throw new Error("Closed proposals cannot receive document uploads.");
    }
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    await requireProposalAppPermission(ctx, auth, "evidence", "create");
    return await ctx.storage.generateUploadUrl();
  })
  .public();

export const addProposalDocument = authenticatedMutation
  .input({
    documentType: v.union(
      v.literal("permit"),
      v.literal("budget"),
      v.literal("plan"),
      v.literal("supporting"),
    ),
    fileName: v.string(),
    mimeType: v.string(),
    proposalId: v.id("buildProposals"),
    sizeBytes: v.number(),
    storageId: v.optional(v.id("_storage")),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    if (auth.proposal.status === "closed") {
      throw new Error("Closed proposals cannot receive document uploads.");
    }
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    await requireProposalAppPermission(ctx, auth, "evidence", "create");
    const fileName = args.fileName.trim();
    if (!fileName) {
      throw new Error("Document file name is required.");
    }
    const now = Date.now();
    const document = {
      brokerageId: auth.brokerage._id,
      createdAt: now,
      documentType: args.documentType,
      fileName,
      mimeType: args.mimeType || "application/octet-stream",
      organizationId: args.workosOrganizationId,
      proposalId: args.proposalId,
      sizeBytes: Math.max(0, Math.round(args.sizeBytes)),
      status: "uploaded" as const,
      storageId: args.storageId,
      updatedAt: now,
      uploadedByWorkosUserId: auth.subject,
    };
    await ctx.db.insert("proposalDocuments", document);
    await writeProposalEvent(ctx, {
      auth,
      command: "addProposalDocument",
      eventType: "proposal.document.created",
      newState: JSON.stringify(document),
      proposalId: args.proposalId,
    });
    return null;
  })
  .public();

export const createDraftProposal = authenticatedMutation
  .input({
    assignedBrokerWorkosUserId: v.optional(v.string()),
    brokerageId: v.id("brokerages"),
    capitalSource: v.optional(proposalCapitalSourceInput),
    builderProfileId: v.id("builderProfiles"),
    buildName: v.string(),
    location: v.string(),
    locationLatitude: v.optional(v.number()),
    locationLongitude: v.optional(v.number()),
    locationPlaceId: v.optional(v.string()),
    proposedStartDate: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.id("buildProposals"))
  .handler(async (ctx, args) => {
    if (
      (args.locationLatitude === undefined) !==
      (args.locationLongitude === undefined)
    ) {
      throw new Error("Latitude and longitude must be provided together.");
    }
    const auth = await authorizeBrokerage(ctx, args.workosOrganizationId);
    const builderProfile = await assertBuilderProfileScope(
      ctx,
      args.builderProfileId,
      auth.brokerage._id,
    );
    if (!isBackoffice(auth.roles)) {
      await assertBuilderOwnership(ctx, args.builderProfileId, auth.subject);
      requireAnyRole(auth.roles, BUILDER_ROLES);
      const assignmentHealth = await getBuilderBrokerAssignmentHealth(ctx, {
        brokerage: auth.brokerage,
        builderProfile,
      });
      if (!assignmentHealth.healthy) {
        throw new ConvexError({
          code: "BUILDER_BROKER_ASSIGNMENT_REQUIRED",
          reason: assignmentHealth.reason,
          recoverable: true,
          safeMessage:
            "An active broker assignment is required before creating a proposal.",
        });
      }
    }

    const now = Date.now();
    const assignedBrokerWorkosUserId =
      args.assignedBrokerWorkosUserId ??
      (await requireDefaultBrokerMember(ctx, auth.brokerage)).workosUserId;
    await requireEligibleBrokerMember(ctx, {
      workosOrganizationId: auth.brokerage.workosOrganizationId,
      workosUserId: assignedBrokerWorkosUserId,
    });
    const proposalId = await ctx.db.insert("buildProposals", {
      brokerageId: auth.brokerage._id,
      assignedBrokerWorkosUserId,
      borrowerCoPayBps: 2000,
      borrowerCoPayCents: 0,
      borrowerStartingCashCents: 0,
      borrowerWorkingCapitalLimitCents: 0,
      buildName: args.buildName,
      builderProfileId: args.builderProfileId,
      capitalSource: args.capitalSource ?? "internal",
      createdAt: now,
      createdByWorkosUserId: auth.subject,
      interestAnnualBps: 925,
      lenderDrawPolicyLimitCents: 0,
      location: args.location,
      ...(args.locationLatitude === undefined
        ? {}
        : {
            locationLatitude: args.locationLatitude,
            locationLongitude: args.locationLongitude,
          }),
      ...(args.locationPlaceId?.trim()
        ? { locationPlaceId: args.locationPlaceId.trim() }
        : {}),
      organizationId: args.workosOrganizationId,
      ...(args.proposedStartDate === undefined
        ? {}
        : {
            proposedStartDate: normalizeIsoDateOnly(
              args.proposedStartDate,
              "proposedStartDate",
            ),
          }),
      reviewOutcome: "none",
      status: "draft",
      totalBudgetCents: 0,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await upsertKanbanCard(ctx, proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "createDraftProposal",
      eventType: "proposal.created",
      newState: JSON.stringify({
        assignedBrokerWorkosUserId,
        status: "draft",
      }),
      proposalId,
    });
    return proposalId;
  })
  .public();

export const createBrokerDraftProposal = authenticatedMutation
  .input({
    assignedBrokerWorkosUserId: v.optional(v.string()),
    capitalSource: v.optional(proposalCapitalSourceInput),
    buildName: v.optional(v.string()),
    location: v.optional(v.string()),
    locationLatitude: v.optional(v.number()),
    locationLongitude: v.optional(v.number()),
    locationPlaceId: v.optional(v.string()),
    proposedStartDate: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.id("buildProposals"))
  .handler(async (ctx, args) => {
    if (
      (args.locationLatitude === undefined) !==
      (args.locationLongitude === undefined)
    ) {
      throw new Error("Latitude and longitude must be provided together.");
    }
    const auth = await authorizeBrokerage(ctx, args.workosOrganizationId);
    requireAnyRole(auth.roles, BACKOFFICE_ROLES);
    const assignedBrokerWorkosUserId =
      args.assignedBrokerWorkosUserId ??
      (await requireDefaultBrokerMember(ctx, auth.brokerage)).workosUserId;
    await requireEligibleBrokerMember(ctx, {
      workosOrganizationId: auth.brokerage.workosOrganizationId,
      workosUserId: assignedBrokerWorkosUserId,
    });

    const now = Date.now();
    const proposalId = await ctx.db.insert("buildProposals", {
      brokerageId: auth.brokerage._id,
      assignedBrokerWorkosUserId,
      borrowerCoPayBps: 2000,
      borrowerCoPayCents: 0,
      borrowerStartingCashCents: 0,
      borrowerWorkingCapitalLimitCents: 0,
      buildName: args.buildName?.trim() || "Unassigned broker draft",
      capitalSource: args.capitalSource ?? "internal",
      createdAt: now,
      createdByWorkosUserId: auth.subject,
      interestAnnualBps: 925,
      lenderDrawPolicyLimitCents: 0,
      location: args.location?.trim() || "Unassigned site",
      ...(args.locationLatitude === undefined
        ? {}
        : {
            locationLatitude: args.locationLatitude,
            locationLongitude: args.locationLongitude,
          }),
      ...(args.locationPlaceId?.trim()
        ? { locationPlaceId: args.locationPlaceId.trim() }
        : {}),
      organizationId: args.workosOrganizationId,
      ...(args.proposedStartDate === undefined
        ? {}
        : {
            proposedStartDate: normalizeIsoDateOnly(
              args.proposedStartDate,
              "proposedStartDate",
            ),
          }),
      reviewOutcome: "none",
      status: "draft",
      totalBudgetCents: 0,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await upsertKanbanCard(ctx, proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "createBrokerDraftProposal",
      eventType: "proposal.created",
      newState: JSON.stringify({
        assignedBrokerWorkosUserId,
        assignment: "unassigned",
        status: "draft",
      }),
      proposalId,
    });
    return proposalId;
  })
  .public();

export const saveDraftProposalPackage = authenticatedMutation
  .input({
    borrowerCoPayBps: v.number(),
    borrowerStartingCashCents: v.optional(v.number()),
    // Deprecated compatibility input for clients deployed before the cutover.
    borrowerWorkingCapitalLimitCents: v.optional(v.number()),
    buildName: v.optional(v.string()),
    capitalSource: v.optional(proposalCapitalSourceInput),
    contractorAssignments: v.optional(
      v.array(proposalDraftContractorAssignmentInput),
    ),
    costItems: v.optional(v.array(proposalDraftCostItemInput)),
    documents: v.optional(v.array(documentInput)),
    draws: v.optional(v.array(proposalDraftDrawInput)),
    lenderDrawPolicyLimitCents: v.number(),
    location: v.optional(v.string()),
    milestones: v.array(milestoneInput),
    proposalId: v.id("buildProposals"),
    proposedStartDate: v.optional(v.string()),
    templateId: v.optional(v.id("proposalTemplates")),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      warnings: v.array(v.string()),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    if (auth.proposal.status !== "draft") {
      throw new Error("Only draft proposals can be edited.");
    }
    const borrowerStartingCashCents =
      args.borrowerStartingCashCents ?? args.borrowerWorkingCapitalLimitCents;
    if (
      borrowerStartingCashCents === undefined ||
      !Number.isFinite(borrowerStartingCashCents) ||
      borrowerStartingCashCents < 0
    ) {
      throw new Error("Borrower starting cash must be a non-negative amount.");
    }
    const normalizedBorrowerStartingCashCents = Math.round(
      borrowerStartingCashCents,
    );
    if (!isBackoffice(auth.roles)) {
      await assertBuilderOwnership(
        ctx,
        assignedBuilderProfileIdOrThrow(auth.proposal),
        auth.subject,
      );
    }
    if (args.milestones.length === 0) {
      throw new Error("At least one milestone is required.");
    }
    if (args.milestones.length > MAX_PROPOSAL_MILESTONES) {
      throw new Error(`A proposal supports at most ${MAX_PROPOSAL_MILESTONES} milestones.`);
    }
    if (
      args.milestones.some(
        (milestone) => milestone.dependencyKeys.length > MAX_PROPOSAL_MILESTONES,
      )
    ) {
      throw new Error(
        `A milestone supports at most ${MAX_PROPOSAL_MILESTONES} dependencies.`,
      );
    }
    if (args.borrowerCoPayBps < 0 || args.borrowerCoPayBps > 10_000) {
      throw new Error(
        "Proposal capital share must be between 0 and 10000 bps.",
      );
    }
    const draftWarnings: string[] = [];
    const lenderFacilityCents = Math.max(
      0,
      Math.round(args.lenderDrawPolicyLimitCents),
    );
    const plannedDrawsCents = (args.draws ?? []).reduce(
      (total, draw) => total + Math.max(0, Math.round(draw.amountCents)),
      0,
    );
    // Draft generation should warn, not hard-fail: template draw shares can
    // temporarily disagree with facility / completed-work eligibility while
    // the borrower is still shaping the schedule.
    if (plannedDrawsCents > lenderFacilityCents) {
      draftWarnings.push(
        "Planned draws exceed the lender facility. Revise the draw schedule or obtain an approved facility change.",
      );
    }
    const milestoneByKey = new Map(
      args.milestones.map((milestone) => [milestone.key, milestone]),
    );
    const additiveCostCentsByMilestoneKey = new Map<string, number>();
    for (const costItem of args.costItems ?? []) {
      if (
        normalizeCostItemBudgetTreatment(costItem.budgetTreatment) !== "add"
      ) {
        continue;
      }
      const itemTotalCents = Math.round(
        normalizeCostItemCost(costItem.costCents) *
          normalizeCostItemQuantity(costItem.quantity),
      );
      additiveCostCentsByMilestoneKey.set(
        costItem.milestoneKey,
        (additiveCostCentsByMilestoneKey.get(costItem.milestoneKey) ?? 0) +
          itemTotalCents,
      );
    }
    if (
      (args.draws ?? []).some((draw) => {
        const milestone = draw.milestoneKey
          ? milestoneByKey.get(draw.milestoneKey)
          : undefined;
        return milestone !== undefined && draw.timingDay < milestone.dayEnd;
      })
    ) {
      draftWarnings.push(
        "Planned reimbursements are scheduled before their milestone is complete.",
      );
    }
    let cumulativePlannedDrawsCents = 0;
    for (const draw of [...(args.draws ?? [])].sort(
      (left, right) =>
        left.timingDay - right.timingDay ||
        (left.order ?? 0) - (right.order ?? 0) ||
        left.drawKey.localeCompare(right.drawKey),
    )) {
      cumulativePlannedDrawsCents += Math.max(0, Math.round(draw.amountCents));
      const cumulativeEligibleCents = args.milestones.reduce(
        (total, milestone) =>
          milestone.dayEnd <= draw.timingDay
            ? total +
              calculateDrawAvailability(
                milestone.budgetCents +
                  (additiveCostCentsByMilestoneKey.get(milestone.key) ?? 0),
                args.borrowerCoPayBps,
              )
            : total,
        0,
      );
      if (cumulativePlannedDrawsCents > cumulativeEligibleCents) {
        draftWarnings.push(
          "Planned draws exceed cumulative completed-work eligibility.",
        );
        break;
      }
    }

    const now = Date.now();
    const retainedPlanKeys = args.milestones.map((milestone) => ({
      milestoneKey: milestone.key,
      submilestoneKeys: milestone.submilestones.map(
        (submilestone) => submilestone.key,
      ),
    }));
    await deleteProposalPlanChildren(ctx, args.proposalId, {
      preserveCanonicalLineage: true,
      retainedPlanKeys,
    });
    const planRows = await insertDraftProposalPlanRows(ctx, {
      auth,
      borrowerCoPayBps: args.borrowerCoPayBps,
      draws: args.draws,
      lenderDrawPolicyLimitCents: args.lenderDrawPolicyLimitCents,
      milestones: args.milestones,
      now,
      proposalId: args.proposalId,
      workosOrganizationId: args.workosOrganizationId,
    });
    const costDeltaCents = await insertDraftProposalCostItems(ctx, {
      auth,
      borrowerCoPayBps: args.borrowerCoPayBps,
      costItems: args.costItems ?? [],
      now,
      planRows,
      proposalId: args.proposalId,
      workosOrganizationId: args.workosOrganizationId,
    });
    const contractorMilestoneAssignmentCount =
      await insertDraftProposalContractorAssignments(ctx, {
        auth,
        contractorAssignments: args.contractorAssignments ?? [],
        now,
        planRows,
        proposalId: args.proposalId,
        workosOrganizationId: args.workosOrganizationId,
      });
    const totalBudgetCents = planRows.totalBudgetCents + costDeltaCents;

    if (args.documents !== undefined) {
      const documents = await collectByIndex(
        ctx,
        "proposalDocuments",
        "by_proposal",
        args.proposalId,
      );
      for (const document of documents) {
        await ctx.db.delete(document._id);
      }
      for (const document of args.documents) {
        await ctx.db.insert("proposalDocuments", {
          brokerageId: auth.brokerage._id,
          createdAt: now,
          documentType: document.documentType,
          fileName: document.fileName,
          mimeType: document.mimeType,
          organizationId: args.workosOrganizationId,
          proposalId: args.proposalId,
          sizeBytes: document.sizeBytes,
          status: "uploaded",
          storageId: document.storageId,
          updatedAt: now,
          uploadedByWorkosUserId: auth.subject,
        });
      }
    }

    await ctx.db.patch(args.proposalId, {
      borrowerCoPayBps: args.borrowerCoPayBps,
      borrowerCoPayCents: Math.round(
        (totalBudgetCents * args.borrowerCoPayBps) / 10_000,
      ),
      borrowerStartingCashCents: normalizedBorrowerStartingCashCents,
      // Dual-write until the legacy field is narrowed out after backfill.
      borrowerWorkingCapitalLimitCents: normalizedBorrowerStartingCashCents,
      buildName: args.buildName?.trim() || auth.proposal.buildName,
      ...(args.capitalSource === undefined
        ? {}
        : { capitalSource: args.capitalSource }),
      lenderDrawPolicyLimitCents: args.lenderDrawPolicyLimitCents,
      location: args.location?.trim() || auth.proposal.location,
      ...(args.proposedStartDate === undefined
        ? {}
        : {
            proposedStartDate: normalizeIsoDateOnly(
              args.proposedStartDate,
              "Proposed start date",
            ),
          }),
      templateId: args.templateId,
      totalBudgetCents,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await upsertKanbanCard(ctx, args.proposalId, now);
    if ((args.costItems?.length ?? 0) > 0) {
      await writeProposalEvent(ctx, {
        auth,
        command: "saveDraftProposalPackage",
        eventType: "proposal.cost_items.saved",
        newState: JSON.stringify({
          costItemCount: args.costItems?.length ?? 0,
        }),
        proposalId: args.proposalId,
      });
    }
    if (contractorMilestoneAssignmentCount > 0) {
      await writeProposalEvent(ctx, {
        auth,
        command: "saveDraftProposalPackage",
        eventType: "proposal.contractor.milestone_assignments_saved",
        newState: JSON.stringify({
          contractorAssignmentCount: args.contractorAssignments?.length ?? 0,
          milestoneAssignmentCount: contractorMilestoneAssignmentCount,
        }),
        proposalId: args.proposalId,
      });
    }
    if (draftWarnings.length > 0) {
      await writeProposalEvent(ctx, {
        auth,
        command: "saveDraftProposalPackage",
        eventType: "proposal.draft.schedule_warnings",
        newState: JSON.stringify({
          lenderFacilityCents,
          plannedDrawsCents,
          warningCount: draftWarnings.length,
        }),
        proposalId: args.proposalId,
        warnings: draftWarnings,
      });
    }
    return { warnings: draftWarnings };
  })
  .public();

interface DraftProposalSaveAuth {
  brokerage: Doc<"brokerages">;
  proposal: Doc<"buildProposals">;
  roles: RoleSlug[];
  subject: string;
}

interface DraftProposalSubmilestoneInput {
  budgetCents?: number;
  durationDays?: number;
  fieldGuidance?: {
    cameraAnglesTiptapJson: string;
    whatToVerifyTiptapJson: string;
  };
  key: string;
  name: string;
  order: number;
  scopeOfWorkTiptapJson?: string;
  startDay?: number;
}

interface DraftProposalMilestoneInput {
  budgetCents: number;
  dayEnd: number;
  dayStart: number;
  dependencyKeys: string[];
  durationDays: number;
  icon?: string;
  key: string;
  name: string;
  order: number;
  siteVisitGuidance?: {
    cameraAngles: string | string[];
    whatToVerify: string | string[];
  };
  submilestones: DraftProposalSubmilestoneInput[];
}

interface ProductionSubmilestoneScheduleInput {
  budgetCents?: number;
  durationDays?: number;
  fieldGuidance?: {
    cameraAnglesTiptapJson: string;
    whatToVerifyTiptapJson: string;
  };
  key: string;
  name: string;
  order: number;
  scopeOfWorkTiptapJson?: string;
  startDay?: number;
}

function normalizeProductionMilestoneSchedule<
  T extends {
    dayEnd?: number;
    dayStart?: number;
    durationDays?: number;
    submilestones?: ProductionSubmilestoneScheduleInput[];
  },
>(milestone: T) {
  const dayStart = Math.max(0, Math.round(milestone.dayStart ?? 0));
  const fallbackEnd = Math.max(
    dayStart,
    Math.round(
      milestone.dayEnd ?? dayStart + Math.max(1, milestone.durationDays ?? 1),
    ),
  );
  const requestedDurationDays = Math.max(
    1,
    Math.round(milestone.durationDays ?? fallbackEnd - dayStart),
  );
  let cursor = dayStart;
  let smallestSubmilestoneStart = Number.POSITIVE_INFINITY;
  let largestSubmilestoneEnd = dayStart;
  const submilestones = [...(milestone.submilestones ?? [])]
    .sort(
      (left, right) =>
        left.order - right.order || left.key.localeCompare(right.key),
    )
    .map((submilestone, index) => {
      const startDay = Math.max(0, Math.round(submilestone.startDay ?? cursor));
      const durationDays = Math.max(
        1,
        Math.round(submilestone.durationDays ?? 1),
      );
      const endDay = startDay + durationDays;
      cursor = endDay;
      smallestSubmilestoneStart = Math.min(smallestSubmilestoneStart, startDay);
      largestSubmilestoneEnd = Math.max(largestSubmilestoneEnd, endDay);
      return {
        ...submilestone,
        durationDays,
        key: submilestone.key.trim(),
        name: submilestone.name.trim(),
        order: Math.max(1, Math.round(submilestone.order ?? index + 1)),
        startDay,
      };
    });
  const hasSubmilestones = submilestones.length > 0;
  const scheduleDayStart = hasSubmilestones
    ? smallestSubmilestoneStart
    : dayStart;
  const durationDays = hasSubmilestones
    ? Math.max(1, largestSubmilestoneEnd - scheduleDayStart)
    : Math.max(requestedDurationDays, largestSubmilestoneEnd - dayStart);
  return {
    dayEnd: scheduleDayStart + durationDays,
    dayStart: scheduleDayStart,
    durationDays,
    submilestones,
  };
}

function assertValidProductionSubmilestones(
  rows: readonly ProductionSubmilestoneScheduleInput[],
  label: string,
) {
  if (rows.length === 0) {
    throw new Error(`${label} must contain at least one valid Sub-milestone.`);
  }
  const keys = new Set<string>();
  for (const row of rows) {
    const key = row.key.trim();
    const name = row.name.trim();
    if (!key || !name) {
      throw new Error(
        `${label} contains a Sub-milestone with an empty key or name.`,
      );
    }
    if (keys.has(key)) {
      throw new Error(
        `${label} contains duplicate Sub-milestone key ${key}.`,
      );
    }
    keys.add(key);
  }
}

function sumProductionSubmilestoneBudgetCents(
  rows: ProductionSubmilestoneScheduleInput[],
) {
  return rows.reduce(
    (total, row) => total + Math.max(0, Math.round(row.budgetCents ?? 0)),
    0,
  );
}

interface DraftProposalDrawInput {
  amountCents: number;
  customDate?: boolean;
  drawKey: string;
  label: string;
  milestoneKey?: string;
  order?: number;
  timingDay: number;
}

interface DraftProposalCostItemInput {
  budgetSubmilestoneKey?: null | string;
  budgetTreatment?: CostItemBudgetTreatment;
  costCents: number;
  description?: string;
  deliveryEndDay?: number;
  deliveryInstructions?: string;
  deliveryLocation?: string;
  deliveryStartDay?: number;
  itemType: "equipment" | "material";
  milestoneKey: string;
  quantity: number;
  relevantSubmilestoneKeys: string[];
  specificationTiptapJson?: string;
  supplier?: string;
  title: string;
  unit?: string;
}

interface DraftProposalContractorAssignmentInput {
  contractorId?: Id<"contractorProfiles">;
  contractorName: string;
  estimatedCostCents?: number;
  estimatedHours?: number;
  milestoneKey: string;
  role: string;
  submilestoneKeys: string[];
}

interface DraftProposalSavedMilestone {
  _id: Id<"proposalMilestones">;
  budgetCents: number;
  dayEnd: number;
  drawAvailabilityCents: number;
  key: string;
}

interface DraftProposalPlanRows {
  drawIdByMilestoneKey: Map<string, Id<"proposalDrawScheduleRows">>;
  milestoneByKey: Map<string, DraftProposalSavedMilestone>;
  submilestoneByMilestoneAndKey: Map<string, Id<"proposalSubmilestones">>;
  totalBudgetCents: number;
}

async function insertDraftProposalPlanRows(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    borrowerCoPayBps: number;
    draws?: DraftProposalDrawInput[];
    lenderDrawPolicyLimitCents?: number;
    milestones: DraftProposalMilestoneInput[];
    now: number;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
): Promise<DraftProposalPlanRows> {
  const planRows: DraftProposalPlanRows = {
    drawIdByMilestoneKey: new Map(),
    milestoneByKey: new Map(),
    submilestoneByMilestoneAndKey: new Map(),
    totalBudgetCents: 0,
  };
  // Tracks cumulative drawn from auto-generated milestone draws for clamping.
  let cumulativeAutoDrawnCents = 0;

  for (const rawRow of [...input.milestones].sort(
    (a, b) => a.order - b.order,
  )) {
    const schedule = normalizeProductionMilestoneSchedule(rawRow);
    const budgetCents =
      schedule.submilestones.length > 0
        ? sumProductionSubmilestoneBudgetCents(schedule.submilestones)
        : rawRow.budgetCents;
    const row = {
      ...rawRow,
      ...schedule,
      budgetCents,
    };
    const drawAvailabilityCents = calculateDrawAvailability(
      row.budgetCents,
      input.borrowerCoPayBps,
    );
    const milestoneId = await insertDraftProposalMilestone(ctx, input, {
      drawAvailabilityCents,
      row,
    });
    planRows.totalBudgetCents += row.budgetCents;
    planRows.milestoneByKey.set(row.key, {
      _id: milestoneId,
      budgetCents: row.budgetCents,
      dayEnd: row.dayEnd,
      drawAvailabilityCents,
      key: row.key,
    });
    for (const submilestone of row.submilestones) {
      const submilestoneId = await insertDraftProposalSubmilestone(ctx, input, {
        milestoneId,
        row,
        submilestone,
      });
      planRows.submilestoneByMilestoneAndKey.set(
        `${row.key}:${submilestone.key}`,
        submilestoneId,
      );
    }
    if (input.draws === undefined) {
      // Clamp auto-generated draw to cumulative milestone capacity available
      // at this draw's timing day (backend eligibility: dayEnd <= timingDay).
      const cumulativeAvailable = [...planRows.milestoneByKey.values()].reduce(
        (total, m) =>
          m.dayEnd <= row.dayEnd ? total + m.drawAvailabilityCents : total,
        0,
      );
      const limit = input.lenderDrawPolicyLimitCents ?? Infinity;
      const remainingMilestoneCapacity = Math.max(
        0,
        cumulativeAvailable - cumulativeAutoDrawnCents,
      );
      const remainingLenderLimit = Math.max(
        0,
        limit - cumulativeAutoDrawnCents,
      );
      const maxAllowed = Math.min(
        remainingMilestoneCapacity,
        remainingLenderLimit,
      );
      const clampedAmount = Math.min(drawAvailabilityCents, maxAllowed);
      const drawId = await insertDraftProposalMilestoneDraw(ctx, input, {
        drawAvailabilityCents: clampedAmount,
        milestoneId,
        row,
      });
      cumulativeAutoDrawnCents += clampedAmount;
      planRows.drawIdByMilestoneKey.set(row.key, drawId);
    }
  }

  if (input.draws !== undefined) {
    await insertDraftProposalDrawRows(ctx, input, planRows);
  }

  return planRows;
}

async function insertDraftProposalMilestone(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  milestone: {
    drawAvailabilityCents: number;
    row: DraftProposalMilestoneInput;
  },
) {
  const existing = await ctx.db
    .query("proposalMilestones")
    .withIndex("by_proposal_key", (query) =>
      query
        .eq("proposalId", input.proposalId)
        .eq("key", milestone.row.key),
    )
    .unique();
  const values = {
    brokerageId: input.auth.brokerage._id,
    budgetCents: milestone.row.budgetCents,
    createdAt: input.now,
    dayEnd: milestone.row.dayEnd,
    dayStart: milestone.row.dayStart,
    dependencyKeys: milestone.row.dependencyKeys,
    drawAvailabilityCents: milestone.drawAvailabilityCents,
    durationDays: milestone.row.durationDays,
    icon: milestone.row.icon,
    key: milestone.row.key,
    name: milestone.row.name,
    order: milestone.row.order,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    siteVisitGuidance: milestone.row.siteVisitGuidance,
    updatedAt: input.now,
  };
  if (existing) {
    await ctx.db.patch(existing._id, values);
    return existing._id;
  }
  return await ctx.db.insert("proposalMilestones", values);
}

async function insertDraftProposalSubmilestone(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  milestone: {
    milestoneId: Id<"proposalMilestones">;
    row: DraftProposalMilestoneInput;
    submilestone: DraftProposalSubmilestoneInput;
  },
) {
  assertProposalSubmilestoneCanonicalAuthoringAllowed(
    input.auth.proposal,
    milestone.submilestone,
  );
  const scopeOfWorkTiptapJson = normalizeOptionalTiptapJson(
    milestone.submilestone.scopeOfWorkTiptapJson,
    "Sub-milestone Scope of Work",
  );
  const existingRows = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_milestone", (query) =>
      query.eq("proposalMilestoneId", milestone.milestoneId),
    )
    .collect();
  const existing = existingRows.find(
    (row) => row.key === milestone.submilestone.key,
  );
  const values = {
    brokerageId: input.auth.brokerage._id,
    budgetCents: milestone.submilestone.budgetCents,
    createdAt: input.now,
    durationDays: milestone.submilestone.durationDays,
    key: milestone.submilestone.key,
    milestoneKey: milestone.row.key,
    name: milestone.submilestone.name,
    order: milestone.submilestone.order,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    proposalMilestoneId: milestone.milestoneId,
    startDay: milestone.submilestone.startDay,
    updatedAt: input.now,
  };
  const submilestoneId = existing
    ? existing._id
    : await ctx.db.insert("proposalSubmilestones", values);
  if (existing) {
    await ctx.db.patch(existing._id, values);
  }
  if (!existing || scopeOfWorkTiptapJson !== undefined) {
    await upsertSubmilestoneScopeV1Draft(ctx, {
      authoredByWorkosUserId: input.auth.subject,
      brokerageId: input.auth.brokerage._id,
      now: input.now,
      organizationId: input.workosOrganizationId,
      proposalId: input.proposalId,
      proposalSubmilestoneId: submilestoneId,
      scopeOfWorkTiptapJson:
        scopeOfWorkTiptapJson ?? EMPTY_CANONICAL_TIPTAP_DOCUMENT,
    });
  }
  if (!existing || milestone.submilestone.fieldGuidance) {
    await upsertProposalSubmilestoneFieldGuidance(ctx, {
      auth: input.auth,
      fieldGuidance: milestone.submilestone.fieldGuidance ?? {
        cameraAnglesTiptapJson: EMPTY_CANONICAL_TIPTAP_DOCUMENT,
        whatToVerifyTiptapJson: EMPTY_CANONICAL_TIPTAP_DOCUMENT,
      },
      now: input.now,
      proposalId: input.proposalId,
      proposalSubmilestoneId: submilestoneId,
      workosOrganizationId: input.workosOrganizationId,
    });
  }
  return submilestoneId;
}

function assertProposalSubmilestoneCanonicalAuthoringAllowed(
  proposal: Pick<Doc<"buildProposals">, "submittedAt">,
  input: {
    fieldGuidance?: {
      cameraAnglesTiptapJson: string;
      whatToVerifyTiptapJson: string;
    };
    scopeOfWorkTiptapJson?: string;
  },
) {
  if (proposal.submittedAt === undefined) {
    return;
  }
  if (input.scopeOfWorkTiptapJson !== undefined) {
    throw new Error(
      "Scope authoring is unavailable after the first Proposal submission.",
    );
  }
  if (input.fieldGuidance !== undefined) {
    throw new Error(
      "Field Guidance authoring is unavailable after the first Proposal submission.",
    );
  }
}

async function upsertProposalSubmilestoneFieldGuidance(
  ctx: MutationCtx,
  input: {
    auth: Pick<DraftProposalSaveAuth, "brokerage" | "subject">;
    fieldGuidance: {
      cameraAnglesTiptapJson: string;
      whatToVerifyTiptapJson: string;
    };
    now: number;
    proposalId: Id<"buildProposals">;
    proposalSubmilestoneId: Id<"proposalSubmilestones">;
    workosOrganizationId: string;
  },
) {
  const whatToVerifyTiptapJson = normalizeRequiredTiptapJson(
    input.fieldGuidance.whatToVerifyTiptapJson,
    "Field Guidance what to verify",
  );
  const cameraAnglesTiptapJson = normalizeRequiredTiptapJson(
    input.fieldGuidance.cameraAnglesTiptapJson,
    "Field Guidance camera angles",
  );
  const existing = await ctx.db
    .query("submilestoneFieldGuidance")
    .withIndex("by_proposalSubmilestoneId", (query) =>
      query.eq("proposalSubmilestoneId", input.proposalSubmilestoneId),
    )
    .unique();
  if (existing) {
    if (
      existing.organizationId !== input.workosOrganizationId ||
      existing.brokerageId !== input.auth.brokerage._id ||
      existing.proposalId !== input.proposalId ||
      existing.proposalSubmilestoneId !== input.proposalSubmilestoneId
    ) {
      throw new Error("Field Guidance lineage is unavailable.");
    }
    await ctx.db.patch(existing._id, {
      cameraAnglesTiptapJson,
      updatedAt: input.now,
      updatedByWorkosUserId: input.auth.subject,
      whatToVerifyTiptapJson,
    });
    await attachSubmilestoneFieldGuidanceBuildLineage(ctx, {
      brokerageId: input.auth.brokerage._id,
      organizationId: input.workosOrganizationId,
      proposalId: input.proposalId,
      proposalSubmilestoneId: input.proposalSubmilestoneId,
    });
    return existing._id;
  }
  const guidanceId = await ctx.db.insert("submilestoneFieldGuidance", {
    brokerageId: input.auth.brokerage._id,
    cameraAnglesTiptapJson,
    createdAt: input.now,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    proposalSubmilestoneId: input.proposalSubmilestoneId,
    updatedAt: input.now,
    updatedByWorkosUserId: input.auth.subject,
    whatToVerifyTiptapJson,
  });
  await attachSubmilestoneFieldGuidanceBuildLineage(ctx, {
    brokerageId: input.auth.brokerage._id,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    proposalSubmilestoneId: input.proposalSubmilestoneId,
  });
  return guidanceId;
}

async function insertDraftProposalMilestoneDraw(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  milestone: {
    drawAvailabilityCents: number;
    milestoneId: Id<"proposalMilestones">;
    row: DraftProposalMilestoneInput;
  },
) {
  return await ctx.db.insert("proposalDrawScheduleRows", {
    amountCents: milestone.drawAvailabilityCents,
    brokerageId: input.auth.brokerage._id,
    createdAt: input.now,
    drawKey: `draw-${String(milestone.row.order).padStart(2, "0")}`,
    label: `${milestone.row.name} reimbursement draw`,
    milestoneKey: milestone.row.key,
    order: milestone.row.order,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    proposalMilestoneId: milestone.milestoneId,
    source: "milestone",
    timingDay: milestone.row.dayEnd,
    updatedAt: input.now,
  });
}

async function insertDraftProposalDrawRows(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    draws?: DraftProposalDrawInput[];
    now: number;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  planRows: DraftProposalPlanRows,
) {
  const draws = [...(input.draws ?? [])].sort(
    (a, b) =>
      (a.order ?? 0) - (b.order ?? 0) ||
      a.timingDay - b.timingDay ||
      a.drawKey.localeCompare(b.drawKey),
  );
  for (const [index, draw] of draws.entries()) {
    const milestoneKey = draw.milestoneKey?.trim();
    const milestone = milestoneKey
      ? planRows.milestoneByKey.get(milestoneKey)
      : undefined;
    if (milestoneKey && !milestone) {
      throw new Error(
        `Draw ${draw.drawKey} references missing milestone ${milestoneKey}.`,
      );
    }
    const drawId = await ctx.db.insert("proposalDrawScheduleRows", {
      amountCents: Math.max(0, Math.round(draw.amountCents)),
      brokerageId: input.auth.brokerage._id,
      createdAt: input.now,
      drawKey:
        draw.drawKey.trim() || `draw-${String(index + 1).padStart(2, "0")}`,
      label:
        draw.label.trim() ||
        `${milestone?.key ?? `Draw ${index + 1}`} reimbursement draw`,
      milestoneKey: milestone?.key,
      order: draw.order ?? index + 1,
      organizationId: input.workosOrganizationId,
      proposalId: input.proposalId,
      proposalMilestoneId: milestone?._id,
      source: "milestone",
      customDate: draw.customDate,
      timingDay: Math.max(0, Math.round(draw.timingDay)),
      updatedAt: input.now,
    });
    if (milestone) {
      planRows.drawIdByMilestoneKey.set(milestone.key, drawId);
    }
  }
}

async function insertDraftProposalCostItems(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    borrowerCoPayBps: number;
    costItems: DraftProposalCostItemInput[];
    now: number;
    planRows: DraftProposalPlanRows;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
) {
  const costDeltaByMilestoneKey = new Map<string, number>();
  const costDeltaBySubmilestoneKey = new Map<string, number>();
  const maintainedTargets = new Set<string>();
  for (const costItem of input.costItems) {
    const { item, milestone, totalCents } = await insertDraftProposalCostItem(
      ctx,
      input,
      costItem,
    );
    if (item.budgetTreatment === "add") {
      costDeltaByMilestoneKey.set(
        milestone.key,
        (costDeltaByMilestoneKey.get(milestone.key) ?? 0) + totalCents,
      );
      if (item.budgetSubmilestoneKey) {
        const target = `${milestone.key}:${item.budgetSubmilestoneKey}`;
        costDeltaBySubmilestoneKey.set(
          target,
          (costDeltaBySubmilestoneKey.get(target) ?? 0) + totalCents,
        );
      }
    }
    if (item.budgetTreatment === "maintain" && item.budgetSubmilestoneKey) {
      maintainedTargets.add(`${milestone.key}:${item.budgetSubmilestoneKey}`);
    }
  }
  return await applyDraftProposalCostItemDeltas(ctx, input, {
    costDeltaByMilestoneKey,
    costDeltaBySubmilestoneKey,
    maintainedTargets,
  });
}

async function insertDraftProposalCostItem(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    planRows: DraftProposalPlanRows;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  costItem: DraftProposalCostItemInput,
) {
  const milestone = getDraftProposalSavedMilestone(
    input.planRows,
    costItem.milestoneKey,
  );
  const relevantSubmilestoneKeys = await validateProposalCostItemSubmilestones(
    ctx,
    milestone,
    costItem.relevantSubmilestoneKeys,
  );
  const budgetTreatment = normalizeCostItemBudgetTreatment(
    costItem.budgetTreatment,
  );
  const budgetSubmilestoneKey = await validateProposalCostItemBudgetTarget(
    ctx,
    milestone,
    costItem.budgetSubmilestoneKey,
    budgetTreatment,
    costItem.budgetTreatment !== undefined,
  );
  const costCents = normalizeCostItemCost(costItem.costCents);
  const quantity = normalizeCostItemQuantity(costItem.quantity);
  const title = normalizeRequiredText(costItem.title, "Cost item title");
  const delivery = validateCostItemDeliveryWindow(costItem);
  const item = {
    brokerageId: input.auth.brokerage._id,
    budgetSubmilestoneKey,
    budgetTreatment,
    costCents,
    createdAt: input.now,
    createdByWorkosUserId: input.auth.subject,
    deliveryEndDay: delivery.deliveryEndDay,
    deliveryInstructions: normalizeOptionalText(costItem.deliveryInstructions),
    deliveryLocation: normalizeOptionalText(costItem.deliveryLocation),
    deliveryStartDay: delivery.deliveryStartDay,
    description: normalizeOptionalText(costItem.description),
    itemKey: await nextProposalCostItemKey(
      ctx,
      input.proposalId,
      title,
      input.now,
    ),
    itemType: costItem.itemType,
    milestoneKey: milestone.key,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
    proposalMilestoneId: milestone._id,
    quantity,
    relevantSubmilestoneKeys,
    specificationTiptapJson: normalizeOptionalTiptapJson(
      costItem.specificationTiptapJson,
      "Material specification",
    ),
    supplier: normalizeOptionalText(costItem.supplier),
    title,
    unit: normalizeOptionalText(costItem.unit),
    updatedAt: input.now,
    updatedByWorkosUserId: input.auth.subject,
  };
  const itemId = await ctx.db.insert("proposalCostItems", item);
  return {
    item: { ...item, _id: itemId },
    milestone,
    totalCents: costItemTotalCents(item),
  };
}

async function applyDraftProposalCostItemDeltas(
  ctx: MutationCtx,
  input: {
    borrowerCoPayBps: number;
    now: number;
    planRows: DraftProposalPlanRows;
    proposalId: Id<"buildProposals">;
  },
  deltas: {
    costDeltaByMilestoneKey: Map<string, number>;
    costDeltaBySubmilestoneKey: Map<string, number>;
    maintainedTargets: Set<string>;
  },
) {
  let totalDeltaCents = 0;
  for (const [target, deltaCents] of deltas.costDeltaBySubmilestoneKey) {
    const separator = target.indexOf(":");
    const milestoneKey = target.slice(0, separator);
    const submilestoneKey = target.slice(separator + 1);
    const submilestoneId = input.planRows.submilestoneByMilestoneAndKey.get(
      `${milestoneKey}:${submilestoneKey}`,
    );
    if (!submilestoneId) {
      throw new Error(`Budget sub-milestone not found: ${submilestoneKey}.`);
    }
    const submilestone = await ctx.db.get(submilestoneId);
    if (!submilestone) {
      throw new Error(`Budget sub-milestone not found: ${submilestoneKey}.`);
    }
    await ctx.db.patch(submilestone._id, {
      budgetCents: Math.max(
        0,
        Math.round((submilestone.budgetCents ?? 0) + deltaCents),
      ),
      updatedAt: input.now,
    });
  }
  for (const [milestoneKey, deltaCents] of deltas.costDeltaByMilestoneKey) {
    if (deltaCents === 0) {
      continue;
    }
    const milestone = getDraftProposalSavedMilestone(
      input.planRows,
      milestoneKey,
    );
    const nextBudgetCents = milestone.budgetCents + deltaCents;
    const nextDrawAvailabilityCents = calculateDrawAvailability(
      nextBudgetCents,
      input.borrowerCoPayBps,
    );
    await ctx.db.patch(milestone._id, {
      budgetCents: nextBudgetCents,
      drawAvailabilityCents: nextDrawAvailabilityCents,
      updatedAt: input.now,
    });
    await syncMilestoneOwnedDrawAmount(ctx, {
      amountCents: nextDrawAvailabilityCents,
      milestoneKey: milestone.key,
      proposalId: input.proposalId,
      updatedAt: input.now,
    });
    totalDeltaCents += deltaCents;
  }
  for (const target of deltas.maintainedTargets) {
    const separator = target.indexOf(":");
    const milestoneKey = target.slice(0, separator);
    const submilestoneKey = target.slice(separator + 1);
    const milestone = getDraftProposalSavedMilestone(
      input.planRows,
      milestoneKey,
    );
    await validateProposalMaintainedCostCoverage(ctx, {
      milestoneId: milestone._id,
      proposalId: input.proposalId,
      submilestoneKey,
    });
  }
  return totalDeltaCents;
}

async function insertDraftProposalContractorAssignments(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    contractorAssignments: DraftProposalContractorAssignmentInput[];
    now: number;
    planRows: DraftProposalPlanRows;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
) {
  let contractorMilestoneAssignmentCount = 0;
  for (const assignment of input.contractorAssignments) {
    contractorMilestoneAssignmentCount +=
      await insertDraftProposalContractorAssignment(ctx, input, assignment);
  }
  return contractorMilestoneAssignmentCount;
}

async function insertDraftProposalContractorAssignment(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    planRows: DraftProposalPlanRows;
    proposalId: Id<"buildProposals">;
    workosOrganizationId: string;
  },
  assignment: DraftProposalContractorAssignmentInput,
) {
  const milestone = getDraftProposalSavedMilestone(
    input.planRows,
    assignment.milestoneKey,
  );
  const role = normalizeOptionalString(assignment.role) ?? "Contractor";
  const contractor = await resolveDraftProposalAssignmentContractor(
    ctx,
    input,
    {
      assignment,
      role,
    },
  );
  const proposalContractorAssignmentId =
    await ensureProposalContractorAssignment(ctx, {
      agreedRateCents: contractor.defaultPayRateCents,
      agreedRateUnit: contractor.defaultPayRateUnit ?? "hour",
      auth: input.auth,
      contractorId: contractor._id,
      proposalId: input.proposalId,
      preserveExistingRole: true,
      role,
      workosOrganizationId: input.workosOrganizationId,
    });
  const targets = resolveDraftProposalAssignmentTargets(input.planRows, {
    assignment,
    milestone,
  });
  const estimatedHours = normalizeOptionalHours(assignment.estimatedHours);
  const estimatedCostCents = normalizeOptionalMoneyCents(
    assignment.estimatedCostCents,
  );
  for (const target of targets) {
    await ctx.db.insert("proposalMilestoneContractorAssignments", {
      assignedAt: input.now,
      assignedByWorkosUserId: input.auth.subject,
      brokerageId: input.auth.brokerage._id,
      contractorId: contractor._id,
      createdAt: input.now,
      estimatedCostCents,
      estimatedHours,
      milestoneKey: milestone.key,
      organizationId: input.workosOrganizationId,
      proposalContractorAssignmentId,
      proposalId: input.proposalId,
      proposalMilestoneId: milestone._id,
      proposalSubmilestoneId: target.id,
      role,
      status: "planned",
      submilestoneKey: target.key,
      updatedAt: input.now,
    });
  }
  return targets.length;
}

async function resolveDraftProposalAssignmentContractor(
  ctx: MutationCtx,
  input: {
    auth: DraftProposalSaveAuth;
    now: number;
    workosOrganizationId: string;
  },
  contractorInput: {
    assignment: DraftProposalContractorAssignmentInput;
    role: string;
  },
) {
  const contractorId = await resolveDraftProposalContractorProfile(ctx, {
    auth: input.auth,
    contractorId: contractorInput.assignment.contractorId,
    contractorName: contractorInput.assignment.contractorName,
    now: input.now,
    role: contractorInput.role,
    workosOrganizationId: input.workosOrganizationId,
  });
  const contractor = await getScopedContractorOrThrow(
    ctx,
    contractorId,
    input.auth.brokerage._id,
  );
  if (contractor.status !== "active") {
    throw new Error("Production contractor is inactive.");
  }
  return contractor;
}

function resolveDraftProposalAssignmentTargets(
  planRows: DraftProposalPlanRows,
  input: {
    assignment: DraftProposalContractorAssignmentInput;
    milestone: DraftProposalSavedMilestone;
  },
) {
  const submilestoneKeys = [
    ...new Set(
      input.assignment.submilestoneKeys
        .map((key) => key.trim())
        .filter((key) => key.length > 0),
    ),
  ];
  const invalidSubmilestoneKeys = submilestoneKeys.filter(
    (key) =>
      !planRows.submilestoneByMilestoneAndKey.has(
        `${input.milestone.key}:${key}`,
      ),
  );
  if (invalidSubmilestoneKeys.length > 0) {
    throw new Error(
      `Contractor sub-milestones must belong to ${input.milestone.key}: ${invalidSubmilestoneKeys.join(", ")}.`,
    );
  }
  if (submilestoneKeys.length === 0) {
    return [{ id: undefined, key: undefined }];
  }
  return submilestoneKeys.map((key) => ({
    id: planRows.submilestoneByMilestoneAndKey.get(
      `${input.milestone.key}:${key}`,
    ),
    key,
  }));
}

function getDraftProposalSavedMilestone(
  planRows: DraftProposalPlanRows,
  milestoneKey: string,
) {
  const milestone = planRows.milestoneByKey.get(milestoneKey);
  if (!milestone) {
    throw new Error(`Production milestone not found: ${milestoneKey}`);
  }
  return milestone;
}

const productionSelectedPlanNames = {
  capitalConstrained: "Capital-Constrained",
  cheapestFeasible: "Cheapest Feasible",
  fastest: "Fastest",
} as const;

function normalizeSelectedPlanMetric(value: number, label: string) {
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`${label} must be a non-negative number.`);
  }
  return Math.round(value);
}

function normalizeCapitalEventInterestRate(
  eventKind: "cashInfusion" | "cost" | "homeEquityTakeout",
  value: number | undefined,
) {
  if (eventKind !== "homeEquityTakeout") {
    return undefined;
  }
  if (
    value === undefined ||
    !Number.isFinite(value) ||
    value < 0 ||
    value > 10_000
  ) {
    throw new Error(
      "Home Equity Takeout interest rate must be between 0 and 10,000 basis points.",
    );
  }
  return Math.round(value);
}

async function normalizeProposalCapitalEventDay(
  ctx: MutationCtx,
  proposal: Pick<Doc<"buildProposals">, "_id" | "timelineRangeMax">,
  value: number,
) {
  const day = Math.round(value);
  const [milestones, draws] = await Promise.all([
    collectByIndex(
      ctx,
      "proposalMilestones",
      "by_proposal",
      proposal._id,
    ) as Promise<Doc<"proposalMilestones">[]>,
    collectByIndex(
      ctx,
      "proposalDrawScheduleRows",
      "by_proposal",
      proposal._id,
    ) as Promise<Doc<"proposalDrawScheduleRows">[]>,
  ]);
  const timelineEnd = Math.max(
    60,
    Math.round(proposal.timelineRangeMax ?? 0),
    ...milestones.map((milestone) => milestone.dayEnd + 10),
    ...draws.map((draw) => draw.timingDay + 10),
  );
  if (
    !Number.isFinite(value) ||
    day < PROPOSAL_TIMELINE_MIN_DAY ||
    day > timelineEnd
  ) {
    throw new Error(
      `Capital event day must be between T−30 and T+${timelineEnd}.`,
    );
  }
  return day;
}

export const selectProposalPlan = authenticatedMutation
  .input({
    metrics: productionSelectedPlanMetricsInput,
    planKey: productionSelectedPlanKeyInput,
    proposalId: v.id("buildProposals"),
    recommendationReason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireState(auth.proposal, "draft");
    requireAnyRole(auth.roles, BUILDER_ROLES);
    await requireProposalAppPermission(ctx, auth, "capitalEvent", "update");
    await assertProposalCollaborationEditAllowed(ctx, auth);
    const recommendationReason = args.recommendationReason.trim();
    if (!recommendationReason) {
      throw new Error("A plan recommendation reason is required.");
    }
    const now = Date.now();
    const selectedPlan = {
      metrics: {
        drawCount: normalizeSelectedPlanMetric(
          args.metrics.drawCount,
          "Draw count",
        ),
        drawFeesCents: normalizeSelectedPlanMetric(
          args.metrics.drawFeesCents,
          "Draw fees",
        ),
        interestCostCents: normalizeSelectedPlanMetric(
          args.metrics.interestCostCents,
          "Interest cost",
        ),
        minimumCashReserveCents: normalizeSelectedPlanMetric(
          args.metrics.minimumCashReserveCents,
          "Minimum cash reserve",
        ),
        projectedDurationDays: normalizeSelectedPlanMetric(
          args.metrics.projectedDurationDays,
          "Projected duration",
        ),
        ...(args.metrics.requiredWorkingCapitalCents === undefined
          ? {}
          : {
              requiredWorkingCapitalCents: normalizeSelectedPlanMetric(
                args.metrics.requiredWorkingCapitalCents,
                "Required working capital",
              ),
            }),
        startingCashCents: normalizeSelectedPlanMetric(
          args.metrics.startingCashCents,
          "Starting cash",
        ),
        totalCostCents: normalizeSelectedPlanMetric(
          args.metrics.totalCostCents,
          "Total cost",
        ),
        totalDrawAmountCents: normalizeSelectedPlanMetric(
          args.metrics.totalDrawAmountCents,
          "Total draw amount",
        ),
      },
      name: productionSelectedPlanNames[args.planKey],
      planKey: args.planKey,
      recommendationReason,
      selectedAt: now,
      selectedByWorkosUserId: auth.subject,
    };
    await ctx.db.patch(args.proposalId, {
      selectedPlan,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "selectProposalPlan",
      eventType: "proposal.plan.selected",
      newState: JSON.stringify(selectedPlan),
      priorState: auth.proposal.selectedPlan
        ? JSON.stringify(auth.proposal.selectedPlan)
        : undefined,
      proposalId: args.proposalId,
      reason: recommendationReason,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const submitProposal = authenticatedMutation
  .input({
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.id("workflowRuleSnapshots"))
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    assertProposalLifecycleTransition({
      command: "submit",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    if (!isBackoffice(auth.roles)) {
      const builderProfileId = assignedBuilderProfileIdOrThrow(auth.proposal);
      await assertBuilderOwnership(ctx, builderProfileId, auth.subject);
      const builderProfile = await assertBuilderProfileScope(
        ctx,
        builderProfileId,
        auth.brokerage._id,
      );
      const assignmentHealth = await getBuilderBrokerAssignmentHealth(ctx, {
        brokerage: auth.brokerage,
        builderProfile,
      });
      if (!assignmentHealth.healthy) {
        throw new ConvexError({
          code: "BUILDER_BROKER_ASSIGNMENT_REQUIRED",
          reason: assignmentHealth.reason,
          recoverable: true,
          safeMessage:
            "An active broker assignment is required before submitting a proposal.",
        });
      }
    }
    const milestones = await collectByIndex(
      ctx,
      "proposalMilestones",
      "by_proposal",
      args.proposalId,
    );
    if (milestones.length === 0) {
      throw new Error("At least one milestone is required before submission.");
    }

    const now = Date.now();
    await publishSavedV1ScopeDraftsForProposal(ctx, {
      actorRoles: auth.roles,
      actorWorkosUserId: auth.subject,
      brokerageId: auth.brokerage._id,
      now,
      organizationId: args.workosOrganizationId,
      proposalId: args.proposalId,
    });
    const workflowRule = await getActiveWorkflowRule(ctx, auth.brokerage._id);
    const snapshotId = await ctx.db.insert("workflowRuleSnapshots", {
      allowPermitWaiverByRoles: workflowRule.allowPermitWaiverByRoles,
      brokerageId: auth.brokerage._id,
      createdAt: now,
      organizationId: args.workosOrganizationId,
      proposalId: args.proposalId,
      proposalStates: workflowRule.proposalStates,
      requirePermitForApproval: workflowRule.requirePermitForApproval,
      ruleKey: workflowRule.ruleKey,
      settings: workflowRule.settings,
      version: workflowRule.version,
      workflowRuleId: workflowRule._id,
    });
    await ctx.db.patch(args.proposalId, {
      backOfficeApprovedByWorkosUserId: undefined,
      reviewOutcome: "none",
      status: "submitted",
      submittedAt: now,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
      workflowRuleSnapshotId: snapshotId,
    });
    await upsertKanbanCard(ctx, args.proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "submitProposal",
      eventType: "proposal.submitted",
      newState: "submitted",
      priorState: "draft",
      proposalId: args.proposalId,
    });
    return snapshotId;
  })
  .public();

