export const approveProposal = authenticatedMutation
  .input({
    permitWaiverReason: v.optional(v.string()),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    assertProposalLifecycleTransition({
      command: "approve",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    requireReason(args.reason);
    const builderProfileId = assignedBuilderProfileIdOrThrow(
      auth.proposal,
      "Assign an active builder before approving the proposal.",
    );
    await assertBuilderProfileScope(ctx, builderProfileId, auth.brokerage._id);
    const snapshot = await getWorkflowSnapshot(ctx, auth.proposal);
    const permit = await getPermitDocument(ctx, args.proposalId);
    let waiverId: Id<"documentWaivers"> | undefined;
    if (!permit && snapshot.requirePermitForApproval) {
      if (!args.permitWaiverReason?.trim()) {
        throw new Error(
          "A permit waiver reason is required when no permit waiver exists.",
        );
      }
      const actorRole = auth.roles.find((role) =>
        snapshot.allowPermitWaiverByRoles.includes(role),
      );
      if (!actorRole) {
        throw new Error("Forbidden: permit waiver");
      }
      waiverId = await ctx.db.insert("documentWaivers", {
        brokerageId: auth.brokerage._id,
        createdAt: Date.now(),
        documentType: "permit",
        grantedByRole: actorRole,
        grantedByWorkosUserId: auth.subject,
        organizationId: args.workosOrganizationId,
        proposalId: args.proposalId,
        reason: args.permitWaiverReason.trim(),
      });
    }

    const now = Date.now();
    await ctx.db.patch(args.proposalId, {
      approvedAt: now,
      backOfficeApprovedByWorkosUserId: auth.subject,
      reviewOutcome: "approved",
      status: "approved",
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    const approvedProposal = await ctx.db.get(args.proposalId);
    if (!approvedProposal) {
      throw new Error("Approved proposal is unavailable.");
    }
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth: { ...auth, proposal: approvedProposal },
      now,
    });
    await createImmutableProposalRevision(ctx, {
      assignment: await getCurrentProposalLenderAssignment(ctx, args.proposalId),
      auth: { ...auth, proposal: approvedProposal },
      idempotencyKey: `system:backoffice-approval:${now}`,
      policyVersion,
      reason: "Publish the Back Office-approved proposal revision.",
    });
    await upsertKanbanCard(ctx, args.proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "approveProposal",
      eventType: "proposal.approved",
      newState: "approved",
      priorState: "submitted",
      proposalId: args.proposalId,
      reason: args.reason,
      warnings: waiverId ? ["permit-waived"] : [],
    });
    return null;
  })
  .public();

export const configureProposalReviewPolicy = authenticatedMutation
  .input({
    expectedAssignmentId: v.union(
      v.id("proposalLenderAssignments"),
      v.null(),
    ),
    expectedProposalRevisionNumber: v.union(v.number(), v.null()),
    idempotencyKey: v.string(),
    policy: proposalReviewPolicyInputValidator,
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      policyVersionId: v.id("proposalReviewPolicyVersions"),
      revisionId: v.union(v.id("proposalRevisions"), v.null()),
      revisionNumber: v.union(v.number(), v.null()),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    requireReason(args.reason);
    if (auth.proposal.status === "closed" || auth.proposal.lockedReviewPolicyId) {
      throw new Error("Review policy cannot change after policy lock or closing.");
    }
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    const policy = normalizeProposalReviewPolicy(args.policy);
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Review policy idempotency key",
    );
    const existing = await ctx.db
      .query("proposalReviewPolicyVersions")
      .withIndex("by_proposal_and_idempotency_key", (query) =>
        query
          .eq("proposalId", args.proposalId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (existing) {
      if (
        existing.configuredByWorkosUserId !== auth.subject ||
        existing.reason !== args.reason.trim() ||
        !proposalReviewPoliciesEqual(existing.policy, policy)
      ) {
        throw new Error("Review policy idempotency key was reused with different values.");
      }
      const revision = await ctx.db
        .query("proposalRevisions")
        .withIndex("by_proposal_and_idempotency_key", (query) =>
          query
            .eq("proposalId", args.proposalId)
            .eq("idempotencyKey", `policy:${idempotencyKey}`),
        )
        .unique();
      return {
        policyVersionId: existing._id,
        revisionId: revision?._id ?? null,
        revisionNumber: revision?.revisionNumber ?? null,
      };
    }
    const assignment = await getCurrentProposalLenderAssignment(
      ctx,
      args.proposalId,
    );
    assertExpectedProposalReviewBase({
      assignment,
      expectedAssignmentId: args.expectedAssignmentId,
      expectedProposalRevisionNumber: args.expectedProposalRevisionNumber,
      proposal: auth.proposal,
    });
    if (
      !assignment &&
      (policy.drawLenderQuorum !== null ||
        policy.milestoneLenderQuorum !== null)
    ) {
      throw new Error(
        "Lender-quorum policy configuration requires a current lender assignment.",
      );
    }
    if (assignment) {
      const lenderOrganization = await resolvePolicyLenderOrganization(
        ctx,
        assignment,
        "policy configuration",
      );
      validateProposalReviewPolicyQuorums(
        policy,
        (await getLenderOrganizationApprovalEligibility(ctx, lenderOrganization._id)).counts,
      );
    }
    const currentPolicy = await getCurrentProposalReviewPolicyVersion(
      ctx,
      auth.proposal,
    );
    const configuredByRole = requirePhase3BackofficeRole(auth);
    const now = Date.now();
    const policyVersionId = await ctx.db.insert(
      "proposalReviewPolicyVersions",
      {
        brokerageId: auth.brokerage._id,
        configuredAt: now,
        configuredByRole,
        configuredByWorkosUserId: auth.subject,
        idempotencyKey,
        organizationId: auth.proposal.organizationId,
        policy,
        proposalId: args.proposalId,
        reason: args.reason.trim(),
        version: (currentPolicy?.version ?? 0) + 1,
      },
    );
    await ctx.db.patch(args.proposalId, {
      currentReviewPolicyVersionId: policyVersionId,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    const policyVersion = await ctx.db.get(policyVersionId);
    const proposal = await ctx.db.get(args.proposalId);
    if (!policyVersion || !proposal) {
      throw new Error("Configured proposal review policy is unavailable.");
    }
    const revision =
      proposal.status === "approved"
        ? await createImmutableProposalRevision(ctx, {
            assignment,
            auth: { ...auth, proposal },
            idempotencyKey: `policy:${idempotencyKey}`,
            policyVersion,
            reason: args.reason,
          })
        : null;
    await writeProposalEvent(ctx, {
      auth,
      command: "configureProposalReviewPolicy",
      eventType: "proposal.review_policy.configured",
      newState: JSON.stringify({
        policy,
        policyVersionId,
        revisionId: revision?._id ?? null,
      }),
      priorState: currentPolicy
        ? JSON.stringify({
            policy: currentPolicy.policy,
            policyVersionId: currentPolicy._id,
          })
        : undefined,
      proposalId: args.proposalId,
      reason: args.reason,
    });
    return {
      policyVersionId,
      revisionId: revision?._id ?? null,
      revisionNumber: revision?.revisionNumber ?? null,
    };
  })
  .public();

export const repairMissingLenderProposalConfirmation = authenticatedMutation
  .input({
    expectedAssignmentId: v.id("proposalLenderAssignments"),
    expectedProposalRevisionNumber: v.union(v.number(), v.null()),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      assignmentId: v.id("proposalLenderAssignments"),
      confirmationCycleId: v.id("proposalLenderConfirmationCycles"),
      policyVersionId: v.id("proposalReviewPolicyVersions"),
      proposalRevisionId: v.id("proposalRevisions"),
      proposalRevisionNumber: v.number(),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    requireReason(args.reason);
    if (auth.proposal.status !== "approved") {
      throw new Error("Only an approved proposal can restore lender confirmation.");
    }
    if (auth.proposal.lockedReviewPolicyId) {
      throw new Error("Lender confirmation cannot be restored after policy lock.");
    }
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);

    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Lender confirmation repair idempotency key",
    );
    const assignment = await getCurrentProposalLenderAssignment(
      ctx,
      args.proposalId,
    );
    if (!assignment || assignment._id !== args.expectedAssignmentId) {
      throw new Error("Stale lender assignment.");
    }

    const idempotentRevision = await ctx.db
      .query("proposalRevisions")
      .withIndex("by_proposal_and_idempotency_key", (query) =>
        query
          .eq("proposalId", args.proposalId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentRevision) {
      if (
        idempotentRevision.assignmentId !== assignment._id ||
        idempotentRevision.createdByWorkosUserId !== auth.subject ||
        idempotentRevision.reason !== args.reason.trim()
      ) {
        throw new Error(
          "Lender confirmation repair idempotency key was reused with different values.",
        );
      }
      const policyVersion = await ctx.db.get(
        idempotentRevision.reviewPolicyVersionId,
      );
      if (
        !policyVersion ||
        policyVersion.proposalId !== args.proposalId ||
        policyVersion.organizationId !== auth.proposal.organizationId ||
        policyVersion.brokerageId !== auth.proposal.brokerageId
      ) {
        throw new Error("Repaired lender confirmation policy is unavailable.");
      }
      const existingCycle = await ctx.db
        .query("proposalLenderConfirmationCycles")
        .withIndex("by_assignment_and_revision", (query) =>
          query
            .eq("assignmentId", assignment._id)
            .eq("proposalRevisionId", idempotentRevision._id),
        )
        .unique();
      const confirmationCycle =
        existingCycle ??
        (await openProposalLenderConfirmationCycle(ctx, {
          assignment,
          proposal: auth.proposal,
          proposalRevisionId: idempotentRevision._id,
          proposalRevisionNumber: idempotentRevision.revisionNumber,
        }));
      return {
        assignmentId: assignment._id,
        confirmationCycleId: confirmationCycle._id,
        policyVersionId: policyVersion._id,
        proposalRevisionId: idempotentRevision._id,
        proposalRevisionNumber: idempotentRevision.revisionNumber,
      };
    }

    const currentRevision = await getCurrentProposalRevision(ctx, auth.proposal);
    if (
      (currentRevision?.revisionNumber ?? null) !==
      args.expectedProposalRevisionNumber
    ) {
      throw new Error("Stale proposal revision.");
    }
    if (currentRevision?.assignmentId !== undefined) {
      if (currentRevision.assignmentId !== assignment._id) {
        throw new Error("Current proposal revision does not match the lender assignment.");
      }
      const currentCycle = await ctx.db
        .query("proposalLenderConfirmationCycles")
        .withIndex("by_assignment_and_revision", (query) =>
          query
            .eq("assignmentId", assignment._id)
            .eq("proposalRevisionId", currentRevision._id),
        )
        .unique();
      if (currentCycle) {
        throw new Error("The current lender confirmation cycle already exists.");
      }
      const policyVersion = await getCurrentProposalReviewPolicyVersion(
        ctx,
        auth.proposal,
      );
      if (
        !policyVersion ||
        policyVersion._id !== currentRevision.reviewPolicyVersionId
      ) {
        throw new Error("Current proposal revision policy is unavailable.");
      }
      const confirmationCycle = await openProposalLenderConfirmationCycle(ctx, {
        assignment,
        proposal: auth.proposal,
        proposalRevisionId: currentRevision._id,
        proposalRevisionNumber: currentRevision.revisionNumber,
      });
      await writeProposalEvent(ctx, {
        auth,
        command: "repairMissingLenderProposalConfirmation",
        eventType: "proposal.lender_confirmation.repaired",
        newState: JSON.stringify({
          assignmentId: assignment._id,
          confirmationCycleId: confirmationCycle._id,
          proposalRevisionId: currentRevision._id,
          proposalRevisionNumber: currentRevision.revisionNumber,
        }),
        priorState: JSON.stringify({
          confirmationCycle: null,
          proposalRevisionId: currentRevision._id,
        }),
        proposalId: args.proposalId,
        reason: args.reason,
      });
      await enqueueProposalApprovalRequiredNotifications(ctx, {
        assignment,
        confirmationCycle,
        proposal: auth.proposal,
        revision: currentRevision,
      });
      return {
        assignmentId: assignment._id,
        confirmationCycleId: confirmationCycle._id,
        policyVersionId: policyVersion._id,
        proposalRevisionId: currentRevision._id,
        proposalRevisionNumber: currentRevision.revisionNumber,
      };
    }

    const now = Date.now();
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth,
      now,
    });
    const revision = await createImmutableProposalRevision(ctx, {
      assignment,
      auth,
      idempotencyKey,
      policyVersion,
      reason: args.reason,
    });
    const confirmationCycle = await ctx.db
      .query("proposalLenderConfirmationCycles")
      .withIndex("by_assignment_and_revision", (query) =>
        query
          .eq("assignmentId", assignment._id)
          .eq("proposalRevisionId", revision._id),
      )
      .unique();
    if (!confirmationCycle) {
      throw new Error("Repaired lender confirmation cycle is unavailable.");
    }
    await writeProposalEvent(ctx, {
      auth,
      command: "repairMissingLenderProposalConfirmation",
      eventType: "proposal.lender_confirmation.repaired",
      newState: JSON.stringify({
        assignmentId: assignment._id,
        confirmationCycleId: confirmationCycle._id,
        policyVersionId: policyVersion._id,
        proposalRevisionId: revision._id,
        proposalRevisionNumber: revision.revisionNumber,
      }),
      priorState: JSON.stringify({
        confirmationCycle: null,
        proposalRevisionId: null,
      }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await enqueueProposalApprovalRequiredNotifications(ctx, {
      assignment,
      confirmationCycle,
      proposal: auth.proposal,
      revision,
    });
    return {
      assignmentId: assignment._id,
      confirmationCycleId: confirmationCycle._id,
      policyVersionId: policyVersion._id,
      proposalRevisionId: revision._id,
      proposalRevisionNumber: revision.revisionNumber,
    };
  })
  .public();

export const publishProposalRevision = authenticatedMutation
  .input({
    expectedAssignmentId: v.union(
      v.id("proposalLenderAssignments"),
      v.null(),
    ),
    expectedProposalRevisionNumber: v.union(v.number(), v.null()),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      changedCheckpoints: v.array(
        v.union(
          v.literal("milestoneCount"),
          v.literal("budget"),
          v.literal("scheduleTimeline"),
          v.literal("builder"),
          v.literal("accessReviewPolicy"),
        ),
      ),
      revisionId: v.id("proposalRevisions"),
      revisionNumber: v.number(),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Proposal revision idempotency key",
    );
    const idempotentRevision = await ctx.db
      .query("proposalRevisions")
      .withIndex("by_proposal_and_idempotency_key", (query) =>
        query
          .eq("proposalId", args.proposalId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentRevision) {
      if (
        idempotentRevision.createdByWorkosUserId !== auth.subject ||
        idempotentRevision.reason !== args.reason.trim()
      ) {
        throw new Error("Proposal revision idempotency key was reused with different values.");
      }
      return {
        changedCheckpoints: idempotentRevision.changedCheckpoints,
        revisionId: idempotentRevision._id,
        revisionNumber: idempotentRevision.revisionNumber,
      };
    }
    if (auth.proposal.lockedReviewPolicyId || auth.proposal.status === "closed") {
      throw new Error("Proposal revisions cannot be published after policy lock or closing.");
    }
    const policyVersion = await getCurrentProposalReviewPolicyVersion(
      ctx,
      auth.proposal,
    );
    if (!policyVersion) {
      throw new Error("Configure the proposal review policy before publishing a revision.");
    }
    const assignment = await getCurrentProposalLenderAssignment(
      ctx,
      args.proposalId,
    );
    const priorConfirmationCycle = assignment
      ? await getCurrentProposalLenderConfirmationCycle(
          ctx,
          auth.proposal,
          assignment,
        )
      : null;
    assertExpectedProposalReviewBase({
      assignment,
      expectedAssignmentId: args.expectedAssignmentId,
      expectedProposalRevisionNumber: args.expectedProposalRevisionNumber,
      proposal: auth.proposal,
    });
    const revision = await createImmutableProposalRevision(ctx, {
      assignment,
      auth,
      idempotencyKey,
      policyVersion,
      reason: args.reason,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "publishProposalRevision",
      eventType: "proposal.revision.published",
      newState: JSON.stringify({
        changedCheckpoints: revision.changedCheckpoints,
        revisionId: revision._id,
        revisionNumber: revision.revisionNumber,
      }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    if (assignment && priorConfirmationCycle?.status === "declined") {
      const confirmationCycle = await ctx.db
        .query("proposalLenderConfirmationCycles")
        .withIndex("by_assignment_and_revision", (query) =>
          query
            .eq("assignmentId", assignment._id)
            .eq("proposalRevisionId", revision._id),
        )
        .unique();
      if (!confirmationCycle) {
        throw new Error("Published lender confirmation cycle is unavailable.");
      }
      await enqueueProposalUpdatedAfterDeclineNotifications(ctx, {
        assignment,
        confirmationCycle,
        proposal: auth.proposal,
        revision,
      });
    }
    return {
      changedCheckpoints: revision.changedCheckpoints,
      revisionId: revision._id,
      revisionNumber: revision.revisionNumber,
    };
  })
  .public();

export const lockProposalReviewPolicy = authenticatedMutation
  .input({
    expectedAssignmentId: v.union(
      v.id("proposalLenderAssignments"),
      v.null(),
    ),
    expectedProposalRevisionNumber: v.union(v.number(), v.null()),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      activeLenderMemberCount: v.number(),
      policyLockId: v.id("proposalReviewPolicyLocks"),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    requireReason(args.reason);
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Review policy lock idempotency key",
    );
    const idempotentLock = await ctx.db
      .query("proposalReviewPolicyLocks")
      .withIndex("by_proposal_and_idempotency_key", (query) =>
        query
          .eq("proposalId", args.proposalId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentLock) {
      if (
        idempotentLock.lockedByWorkosUserId !== auth.subject ||
        idempotentLock.reason !== args.reason.trim()
      ) {
        throw new Error("Review policy lock idempotency key was reused with different values.");
      }
      return {
        activeLenderMemberCount: idempotentLock.activeLenderMemberCount,
        policyLockId: idempotentLock._id,
      };
    }
    const existingLocks = await ctx.db
      .query("proposalReviewPolicyLocks")
      .withIndex("by_proposal", (query) => query.eq("proposalId", args.proposalId))
      .take(2);
    if (existingLocks.length > 0 || auth.proposal.lockedReviewPolicyId) {
      throw new Error("Proposal review policy is already locked.");
    }
    requireState(auth.proposal, "approved");
    const [policyVersion, revision, assignment] = await Promise.all([
      getCurrentProposalReviewPolicyVersion(ctx, auth.proposal),
      getCurrentProposalRevision(ctx, auth.proposal),
      getCurrentProposalLenderAssignment(ctx, args.proposalId),
    ]);
    assertExpectedProposalReviewBase({
      assignment,
      expectedAssignmentId: args.expectedAssignmentId,
      expectedProposalRevisionNumber: args.expectedProposalRevisionNumber,
      proposal: auth.proposal,
    });
    if (!policyVersion || !revision) {
      throw new Error("A current policy and proposal revision are required before lock.");
    }
    if (
      revision.reviewPolicyVersionId !== policyVersion._id ||
      !proposalReviewPoliciesEqual(
        revision.checkpoints.accessReviewPolicy,
        policyVersion.policy,
      )
    ) {
      throw new Error("Current proposal revision does not match the policy being locked.");
    }
    if (revision.assignmentId !== assignment?._id) {
      throw new Error("Current proposal revision does not match the lender assignment.");
    }
    let lenderOrganizationId: Id<"lenderOrganizations"> | undefined;
    let activeLenderMemberCount = 0;
    let eligibleLenderApproverCounts = { draw: 0, milestone: 0, proposalReview: 0 };
    if (assignment) {
      const lenderOrganization = await resolvePolicyLenderOrganization(
        ctx,
        assignment,
        "policy lock",
      );
      lenderOrganizationId = lenderOrganization._id;
      eligibleLenderApproverCounts =
        (await getLenderOrganizationApprovalEligibility(ctx, lenderOrganization._id)).counts;
      activeLenderMemberCount = eligibleLenderApproverCounts.proposalReview;
      const lenderApproval = await getCurrentProposalLenderApproval(
        ctx,
        args.proposalId,
        assignment._id,
        revision._id,
      );
      if (
        !lenderApproval ||
        !(await isActiveEligibleLenderApproval(ctx, lenderApproval, assignment))
      ) {
        throw new Error("Current lender-reviewed proposal revision is required before policy lock.");
      }
    }
    validateProposalReviewPolicyQuorums(
      policyVersion.policy,
      eligibleLenderApproverCounts,
    );
    const lockedByRole = requirePhase3BackofficeRole(auth);
    const now = Date.now();
    const policyLockId = await ctx.db.insert("proposalReviewPolicyLocks", {
      activeLenderMemberCount,
      eligibleLenderApproverCount: activeLenderMemberCount,
      eligibleLenderApproverCounts,
      ...(assignment ? { assignmentId: assignment._id } : {}),
      brokerageId: auth.brokerage._id,
      idempotencyKey,
      ...(lenderOrganizationId ? { lenderOrganizationId } : {}),
      lockedAt: now,
      lockedByRole,
      lockedByWorkosUserId: auth.subject,
      organizationId: auth.proposal.organizationId,
      policy: policyVersion.policy,
      policyVersionId: policyVersion._id,
      proposalId: args.proposalId,
      proposalRevisionId: revision._id,
      proposalRevisionNumber: revision.revisionNumber,
      reason: args.reason.trim(),
    });
    await ctx.db.patch(args.proposalId, {
      lockedReviewPolicyId: policyLockId,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "lockProposalReviewPolicy",
      eventType: "proposal.review_policy.locked",
      newState: JSON.stringify({
        activeLenderMemberCount,
        policyLockId,
        policyVersionId: policyVersion._id,
        proposalRevisionId: revision._id,
      }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    return { activeLenderMemberCount, policyLockId };
  })
  .public();

export const getProposalPhase3ReviewControl = authenticatedQuery
  .input({
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(proposalPhase3ReviewControlValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    const [policyVersions, revisions, locks] = await Promise.all([
      ctx.db
        .query("proposalReviewPolicyVersions")
        .withIndex("by_proposal", (query) => query.eq("proposalId", args.proposalId))
        .order("desc")
        .take(100),
      ctx.db
        .query("proposalRevisions")
        .withIndex("by_proposal_and_revision_number", (query) =>
          query.eq("proposalId", args.proposalId),
        )
        .order("desc")
        .take(100),
      ctx.db
        .query("proposalReviewPolicyLocks")
        .withIndex("by_proposal", (query) => query.eq("proposalId", args.proposalId))
        .take(2),
    ]);
    policyVersions.reverse();
    revisions.reverse();
    const visibleRevisions = auth.isCurrentLenderActor
      ? revisions.filter(
          (revision) =>
            revision.assignmentId === auth.currentLenderAssignment?._id,
        )
      : revisions;
    const canSeePrivateReviewControl =
      !auth.isCurrentLenderActor && isBackoffice(auth.roles);
    const canSeeLenderLockDetails =
      canSeePrivateReviewControl || auth.isCurrentLenderActor;
    let currentEligibleLenderApproverCounts = canSeePrivateReviewControl
      ? { draw: 0, milestone: 0, proposalReview: 0 }
      : undefined;
    let currentLenderEligibilityIssue: string | undefined;
    if (canSeeLenderLockDetails && auth.currentLenderAssignment) {
      try {
        const lenderOrganization = await resolvePolicyLenderOrganization(
          ctx,
          auth.currentLenderAssignment,
          "policy configuration",
        );
        currentEligibleLenderApproverCounts = (
          await getLenderOrganizationApprovalEligibility(
            ctx,
            lenderOrganization._id,
          )
        ).counts;
      } catch (error) {
        currentEligibleLenderApproverCounts = {
          draw: 0,
          milestone: 0,
          proposalReview: 0,
        };
        currentLenderEligibilityIssue = canSeePrivateReviewControl
          ? error instanceof Error
            ? error.message
            : "Assigned lender eligibility is unavailable."
          : "Assigned lender eligibility is unavailable.";
      }
    }
    const visiblePolicyVersions = policyVersions.map((version) => ({
      ...(canSeePrivateReviewControl
        ? {
            configuredAt: version.configuredAt,
            configuredByRole: version.configuredByRole,
            configuredByWorkosUserId: version.configuredByWorkosUserId,
            reason: version.reason,
          }
        : {}),
      policy: version.policy,
      policyVersionId: version._id,
      version: version.version,
    }));
    const visibleRevisionSnapshots = visibleRevisions.map((revision) => ({
      assignmentId: revision.assignmentId ?? null,
      ...(canSeePrivateReviewControl
        ? {
            backOfficeApprovedByWorkosUserId:
              revision.backOfficeApprovedByWorkosUserId,
            createdByRole: revision.createdByRole,
            createdByWorkosUserId: revision.createdByWorkosUserId,
            reason: revision.reason,
          }
        : {}),
      changedCheckpoints: revision.changedCheckpoints,
      checkpoints: revision.checkpoints,
      createdAt: revision.createdAt,
      priorLenderReviewedRevisionId:
        revision.priorLenderReviewedRevisionId ?? null,
      proposalRevisionId: revision._id,
      revisionNumber: revision.revisionNumber,
      reviewPolicyVersionId: revision.reviewPolicyVersionId,
    }));
    const lock = locks[0];
    const visibleLock = !lock
      ? null
      : canSeePrivateReviewControl
        ? {
            activeLenderMemberCount: lock.activeLenderMemberCount,
            assignmentId: lock.assignmentId ?? null,
            eligibleLenderApproverCount:
              lock.eligibleLenderApproverCount ??
              lock.activeLenderMemberCount,
            eligibleLenderApproverCounts: lock.eligibleLenderApproverCounts,
            lenderOrganizationId: lock.lenderOrganizationId ?? null,
            lockId: lock._id,
            lockedAt: lock.lockedAt,
            lockedByRole: lock.lockedByRole,
            lockedByWorkosUserId: lock.lockedByWorkosUserId,
            policy: lock.policy,
            policyVersionId: lock.policyVersionId,
            proposalRevisionId: lock.proposalRevisionId,
            proposalRevisionNumber: lock.proposalRevisionNumber,
            reason: lock.reason,
          }
        : canSeeLenderLockDetails
          ? {
            activeLenderMemberCount: lock.activeLenderMemberCount,
            assignmentId: lock.assignmentId ?? null,
            eligibleLenderApproverCount:
              lock.eligibleLenderApproverCount ??
              lock.activeLenderMemberCount,
            eligibleLenderApproverCounts: lock.eligibleLenderApproverCounts,
            lenderOrganizationId: lock.lenderOrganizationId ?? null,
            lockId: lock._id,
            lockedAt: lock.lockedAt,
            policy: lock.policy,
            policyVersionId: lock.policyVersionId,
            proposalRevisionId: lock.proposalRevisionId,
            proposalRevisionNumber: lock.proposalRevisionNumber,
          }
          : {
              lockId: lock._id,
              lockedAt: lock.lockedAt,
              policy: lock.policy,
              policyVersionId: lock.policyVersionId,
              proposalRevisionId: lock.proposalRevisionId,
              proposalRevisionNumber: lock.proposalRevisionNumber,
            };
    return {
      currentAssignmentId: auth.currentLenderAssignment?._id ?? null,
      ...(currentEligibleLenderApproverCounts
        ? { currentEligibleLenderApproverCounts }
        : {}),
      ...(currentLenderEligibilityIssue
        ? { currentLenderEligibilityIssue }
        : {}),
      currentPolicyVersionId: auth.proposal.currentReviewPolicyVersionId ?? null,
      currentRevisionId: auth.proposal.currentProposalRevisionId ?? null,
      currentRevisionNumber: auth.proposal.currentProposalRevisionNumber ?? null,
      latestLenderReviewedRevisionId:
        auth.proposal.latestLenderReviewedRevisionId ?? null,
      latestLenderReviewedRevisionNumber:
        auth.proposal.latestLenderReviewedRevisionNumber ?? null,
      lock: visibleLock,
      lockedReviewPolicyId: auth.proposal.lockedReviewPolicyId ?? null,
      policyVersions: visiblePolicyVersions,
      revisions: visibleRevisionSnapshots,
    };
  })
  .public();

export const listProposalReviewPolicyVersions = authenticatedQuery
  .input({ paginationOpts: paginationOptsValidator, proposalId: v.id("buildProposals"), workosOrganizationId: v.string() })
  .returns(paginationResultValidator(proposalReviewPolicyVersionPageItemValidator))
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalLifecycleActor(ctx, args.proposalId, args.workosOrganizationId);
    const canSeePrivate = !auth.isCurrentLenderActor && isBackoffice(auth.roles);
    const page = await ctx.db.query("proposalReviewPolicyVersions")
      .withIndex("by_proposal", (query) => query.eq("proposalId", args.proposalId))
      .order("asc").paginate(args.paginationOpts);
    return { ...page, page: page.page.map((version) => ({
      ...(canSeePrivate ? {
        configuredAt: version.configuredAt,
        configuredByRole: version.configuredByRole,
        configuredByWorkosUserId: version.configuredByWorkosUserId,
        reason: version.reason,
      } : {}),
      policy: version.policy,
      policyVersionId: version._id,
      version: version.version,
    })) };
  })
  .public();

export const listProposalRevisions = authenticatedQuery
  .input({ paginationOpts: paginationOptsValidator, proposalId: v.id("buildProposals"), workosOrganizationId: v.string() })
  .returns(paginationResultValidator(proposalRevisionPageItemValidator))
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalLifecycleActor(ctx, args.proposalId, args.workosOrganizationId);
    const canSeePrivate = !auth.isCurrentLenderActor && isBackoffice(auth.roles);
    const page = await (async () => {
      if (auth.isCurrentLenderActor) {
        const currentLenderAssignment = auth.currentLenderAssignment;
        if (!currentLenderAssignment) {
          throw new Error("Forbidden: current lender assignment");
        }
        return await ctx.db
          .query("proposalRevisions")
          .withIndex("by_assignment_and_revision_number", (query) =>
            query.eq("assignmentId", currentLenderAssignment._id),
          )
          .order("asc")
          .paginate(args.paginationOpts);
      }
      return await ctx.db
        .query("proposalRevisions")
        .withIndex("by_proposal_and_revision_number", (query) =>
          query.eq("proposalId", args.proposalId),
        )
        .order("asc")
        .paginate(args.paginationOpts);
    })();
    return {
      ...page,
      page: page.page
        .map((revision) => ({
          assignmentId: revision.assignmentId ?? null,
          ...(canSeePrivate ? {
            backOfficeApprovedByWorkosUserId: revision.backOfficeApprovedByWorkosUserId,
            createdByRole: revision.createdByRole,
            createdByWorkosUserId: revision.createdByWorkosUserId,
            reason: revision.reason,
          } : {}),
          changedCheckpoints: revision.changedCheckpoints,
          checkpoints: revision.checkpoints,
          createdAt: revision.createdAt,
          priorLenderReviewedRevisionId: revision.priorLenderReviewedRevisionId ?? null,
          proposalRevisionId: revision._id,
          revisionNumber: revision.revisionNumber,
          reviewPolicyVersionId: revision.reviewPolicyVersionId,
        })),
    };
  })
  .public();

export const listEligibleExternalLenderOrganizations = authenticatedQuery
  .input({
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      organizations: v.array(proposalLenderOrganizationOptionValidator),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    if (auth.proposal.status !== "approved") {
      return { organizations: [] };
    }

    const activeOrganizations = await ctx.db
      .query("lenderOrganizations")
      .withIndex("by_status", (query) => query.eq("status", "active"))
      .take(ELIGIBLE_LENDER_ORGANIZATION_LIMIT + 1);
    const eligibleOrganizations = [];
    for (const organization of activeOrganizations) {
      const target = await resolveAssignableLenderOrganization(
        ctx,
        organization._id,
      );
      if (!target) {
        continue;
      }
      eligibleOrganizations.push({
        lenderOrganizationId: organization._id,
        lenderOrganizationName: organization.displayName,
      });
      if (eligibleOrganizations.length >= ELIGIBLE_LENDER_ORGANIZATION_LIMIT) {
        break;
      }
    }
    const sortedOrganizations = eligibleOrganizations;
    sortedOrganizations.sort((left, right) =>
      left.lenderOrganizationName.localeCompare(right.lenderOrganizationName),
    );
    return {
      organizations: sortedOrganizations.slice(
        0,
        ELIGIBLE_LENDER_ORGANIZATION_LIMIT,
      ),
    };
  })
  .public();

export const assignExternalLenderOrganization = authenticatedMutation
  .input({
    lenderOrganizationId: v.id("lenderOrganizations"),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      assignmentId: v.id("proposalLenderAssignments"),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    if (auth.proposal.lockedReviewPolicyId || auth.proposal.status === "closed") {
      throw new Error("Lender assignment cannot change after policy lock or closing.");
    }
    assertProposalLifecycleTransition({
      command: "assign",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    requireReason(args.reason);
    const currentAssignment = await getCurrentProposalLenderAssignment(
      ctx,
      args.proposalId,
    );
    if (currentAssignment) {
      throw new Error("A current lender assignment already exists.");
    }
    const archivingAssignments = await ctx.db
      .query("proposalLenderAssignments")
      .withIndex("by_proposal_status", (query) =>
        query.eq("proposalId", args.proposalId).eq("status", "archiving"),
      )
      .take(1);
    if (archivingAssignments.length > 0) {
      throw new Error("Wait for the prior lender assignment archive to seal before assigning another organization.");
    }
    const lenderOrganization = await resolveAssignableLenderOrganization(
      ctx,
      args.lenderOrganizationId,
    );
    if (!lenderOrganization) {
      throw new Error("Lender organization is unavailable for assignment.");
    }
    const assignedByRole = auth.roles.find((role) =>
      APPROVER_ROLES.includes(role as (typeof APPROVER_ROLES)[number]),
    );
    if (!assignedByRole) {
      throw new Error("Forbidden: proposal assignment authority");
    }
    const now = Date.now();
    const assignmentId = await ctx.db.insert("proposalLenderAssignments", {
      assignedAt: now,
      assignedByRole,
      assignedByWorkosUserId: auth.subject,
      brokerageId: auth.brokerage._id,
      createdAt: now,
      lenderBrokerageId: lenderOrganization.brokerageId,
      lenderOrganizationId: lenderOrganization.lenderOrganizationId,
      lenderOrganizationName: lenderOrganization.name,
      organizationId: args.workosOrganizationId,
      proposalId: args.proposalId,
      status: "current",
    });
    const assignedProposal = await ctx.db.get(args.proposalId);
    if (!assignedProposal) {
      throw new Error("Assigned proposal is unavailable.");
    }
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth: { ...auth, proposal: assignedProposal },
      now,
    });
    const assignment = await ctx.db.get(assignmentId);
    if (!assignment) {
      throw new Error("Created lender assignment is unavailable.");
    }
    const revision = await createImmutableProposalRevision(ctx, {
      assignment,
      auth: { ...auth, proposal: assignedProposal },
      idempotencyKey: `system:lender-assignment:${assignmentId}`,
      policyVersion,
      reason: "Publish the revision for the assigned lender organization.",
    });
    const confirmationCycle = await ctx.db
      .query("proposalLenderConfirmationCycles")
      .withIndex("by_assignment_and_revision", (query) =>
        query
          .eq("assignmentId", assignment._id)
          .eq("proposalRevisionId", revision._id),
      )
      .unique();
    if (!confirmationCycle) {
      throw new Error("Created lender confirmation cycle is unavailable.");
    }
    await upsertKanbanCard(ctx, args.proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "assignExternalLenderOrganization",
      eventType: "proposal.lender_assignment.created",
      newState: JSON.stringify({
        assignmentId,
        lenderOrganizationId: lenderOrganization.lenderOrganizationId,
        status: "current",
      }),
      priorState: JSON.stringify({ externalAssignment: "unassigned" }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await enqueueProposalApprovalRequiredNotifications(ctx, {
      assignment,
      confirmationCycle,
      proposal: assignedProposal,
      revision,
    });
    return { assignmentId };
  })
  .public();

export const withdrawExternalLenderAssignment = authenticatedMutation
  .input({
    assignmentId: v.id("proposalLenderAssignments"),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    if (auth.proposal.lockedReviewPolicyId || auth.proposal.status === "closed") {
      throw new Error("Lender assignment cannot change after policy lock or closing.");
    }
    assertProposalLifecycleTransition({
      command: "withdraw",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    requireReason(args.reason);
    const assignment = await ctx.db.get(args.assignmentId);
    if (
      !assignment ||
      assignment.proposalId !== args.proposalId ||
      assignment.brokerageId !== auth.brokerage._id ||
      assignment.organizationId !== args.workosOrganizationId
    ) {
      throw new Error("Forbidden: assignment scope");
    }
    if (assignment.status !== "current") {
      throw new Error("External lender assignment is already withdrawn.");
    }
    const [currentRevision, currentConfirmationCycle] = await Promise.all([
      getCurrentProposalRevision(ctx, auth.proposal),
      getCurrentProposalLenderConfirmationCycle(
        ctx,
        auth.proposal,
        assignment,
      ),
    ]);
    const now = Date.now();
    const withdrawnByRole = requirePhase3BackofficeRole(auth);
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth,
      now,
    });
    const manifest = await createLenderAssignmentManifest(
      ctx,
      auth.proposal,
      assignment,
      now,
      policyVersion._id,
    );
    await ctx.db.patch(args.assignmentId, {
      archiveManifestId: manifest._id,
      status: "archiving",
      withdrawalReason: args.reason.trim(),
      withdrawnAt: now,
      withdrawnByRole,
      withdrawnByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "withdrawExternalLenderAssignment",
      eventType: "proposal.lender_assignment.withdrawn",
      newState: JSON.stringify({
        assignmentId: args.assignmentId,
        lenderOrganizationId: assignment.lenderOrganizationId,
        status: "archiving",
      }),
      priorState: JSON.stringify({
        assignmentId: args.assignmentId,
        status: "current",
      }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await enqueueProposalWithdrawalNotifications(ctx, {
      assignment,
      confirmationCycle: currentConfirmationCycle,
      proposal: auth.proposal,
      revision: currentRevision,
    });
    await ctx.scheduler.runAfter(
      0,
      internal.production_proposals.sealLenderAssignmentManifestBatch,
      { manifestId: manifest._id },
    );
    await upsertKanbanCard(ctx, args.proposalId, now);
    return null;
  })
  .public();

const proposalLenderArchiveStatusValidator = v.object({
  assignmentId: v.id("proposalLenderAssignments"),
  attemptCount: v.number(),
  failedAt: v.union(v.number(), v.null()),
  failureReason: v.union(v.string(), v.null()),
  lastAttemptAt: v.union(v.number(), v.null()),
  manifestId: v.id("proposalLenderAssignmentManifests"),
  phase: v.union(
    v.literal("documents"),
    v.literal("revisions"),
    v.literal("decisions"),
    v.literal("complete"),
  ),
  status: v.union(
    v.literal("building"),
    v.literal("failed"),
    v.literal("sealed"),
  ),
});

function projectProposalLenderArchiveStatus(
  manifest: Doc<"proposalLenderAssignmentManifests">,
) {
  return {
    assignmentId: manifest.assignmentId,
    attemptCount: manifest.attemptCount ?? 0,
    failedAt: manifest.failedAt ?? null,
    failureReason: manifest.failureReason ?? null,
    lastAttemptAt: manifest.lastAttemptAt ?? null,
    manifestId: manifest._id,
    phase: manifest.phase,
    status: manifest.status,
  };
}

export const getProposalLenderArchiveStatus = authenticatedQuery
  .input({
    assignmentId: v.id("proposalLenderAssignments"),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(proposalLenderArchiveStatusValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    const assignment = await ctx.db.get(args.assignmentId);
    if (
      !assignment ||
      assignment.proposalId !== auth.proposal._id ||
      assignment.brokerageId !== auth.brokerage._id ||
      assignment.organizationId !== args.workosOrganizationId
    ) {
      throw new Error("Forbidden: lender assignment archive scope");
    }
    const manifest = await ctx.db
      .query("proposalLenderAssignmentManifests")
      .withIndex("by_assignment", (query) =>
        query.eq("assignmentId", assignment._id),
      )
      .unique();
    if (!manifest) {
      throw new Error("Lender assignment archive is unavailable.");
    }
    return projectProposalLenderArchiveStatus(manifest);
  })
  .public();

export const retryProposalLenderArchive = authenticatedMutation
  .input({
    assignmentId: v.id("proposalLenderAssignments"),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(proposalLenderArchiveStatusValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, APPROVER_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    requireReason(args.reason);
    const assignment = await ctx.db.get(args.assignmentId);
    if (
      !assignment ||
      assignment.proposalId !== auth.proposal._id ||
      assignment.brokerageId !== auth.brokerage._id ||
      assignment.organizationId !== args.workosOrganizationId
    ) {
      throw new Error("Forbidden: lender assignment archive scope");
    }
    const manifest = await ctx.db
      .query("proposalLenderAssignmentManifests")
      .withIndex("by_assignment", (query) =>
        query.eq("assignmentId", assignment._id),
      )
      .unique();
    if (!manifest) {
      throw new Error("Lender assignment archive is unavailable.");
    }
    if (manifest.status === "sealed") {
      return projectProposalLenderArchiveStatus(manifest);
    }
    if (assignment.status !== "archiving") {
      throw new Error("Lender assignment is not awaiting archive recovery.");
    }
    if (auth.proposal.lockedReviewPolicyId || auth.proposal.status === "closed") {
      throw new Error("Lender assignment archive cannot resume after lock or closing.");
    }
    const now = Date.now();
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth,
      now,
    });
    await ctx.db.patch(manifest._id, {
      cursor: null,
      failedAt: undefined,
      failureReason: undefined,
      lastAttemptAt: now,
      lastRetryReason: args.reason.trim(),
      lastRetryRequestedAt: now,
      lastRetryRequestedByWorkosUserId: auth.subject,
      reviewPolicyVersionId: policyVersion._id,
      status: "building",
    });
    await ctx.scheduler.runAfter(
      0,
      internal.production_proposals.sealLenderAssignmentManifestBatch,
      { manifestId: manifest._id },
    );
    await writeProposalEvent(ctx, {
      auth,
      command: "retryProposalLenderArchive",
      eventType: "proposal.lender_assignment.archive_retry_requested",
      newState: JSON.stringify({
        assignmentId: assignment._id,
        manifestId: manifest._id,
        status: "building",
      }),
      priorState: JSON.stringify({
        attemptCount: manifest.attemptCount ?? 0,
        status: manifest.status,
      }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    const updated = await ctx.db.get(manifest._id);
    if (!updated) {
      throw new Error("Retried lender assignment archive is unavailable.");
    }
    return projectProposalLenderArchiveStatus(updated);
  })
  .public();

export const acknowledgeProposalConfirmationCheckpoint = authenticatedMutation
  .input({
    checkpoint: v.union(
      v.literal("milestoneCount"),
      v.literal("budget"),
      v.literal("scheduleTimeline"),
      v.literal("builder"),
      v.literal("accessReviewPolicy"),
    ),
    expectedAssignmentId: v.id("proposalLenderAssignments"),
    expectedConfirmationCycleId: v.id("proposalLenderConfirmationCycles"),
    expectedProposalRevisionId: v.id("proposalRevisions"),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      acknowledgementId: v.id("proposalLenderConfirmationAcknowledgements"),
      sequence: v.number(),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeLenderProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    if (!auth.isCurrentLenderActor || !auth.currentLenderAssignment) {
      throw new Error("Forbidden: lender proposal confirmation");
    }
    assertProposalLifecycleTransition({
      command: "confirm",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Proposal checkpoint acknowledgement idempotency key",
    );
    const currentRevision = await getCurrentProposalRevision(ctx, auth.proposal);
    const confirmationCycle = await getCurrentProposalLenderConfirmationCycle(
      ctx,
      auth.proposal,
      auth.currentLenderAssignment,
    );
    const idempotentAcknowledgement = await ctx.db
      .query("proposalLenderConfirmationAcknowledgements")
      .withIndex("by_cycle_and_idempotency_key", (query) =>
        query
          .eq("confirmationCycleId", args.expectedConfirmationCycleId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentAcknowledgement) {
      if (
        idempotentAcknowledgement.assignmentId !== args.expectedAssignmentId ||
        idempotentAcknowledgement.acknowledgedByWorkosUserId !== auth.subject ||
        idempotentAcknowledgement.checkpoint !== args.checkpoint ||
        idempotentAcknowledgement.proposalRevisionId !==
          args.expectedProposalRevisionId ||
        auth.currentLenderAssignment._id !== args.expectedAssignmentId ||
        currentRevision?._id !== args.expectedProposalRevisionId ||
        confirmationCycle?._id !== args.expectedConfirmationCycleId
      ) {
        throw new Error(
          "Proposal checkpoint acknowledgement idempotency key was reused with different values.",
        );
      }
      return {
        acknowledgementId: idempotentAcknowledgement._id,
        sequence: idempotentAcknowledgement.sequence,
      };
    }
    if (
      auth.currentLenderAssignment._id !== args.expectedAssignmentId ||
      !currentRevision ||
      currentRevision._id !== args.expectedProposalRevisionId ||
      !confirmationCycle ||
      confirmationCycle._id !== args.expectedConfirmationCycleId ||
      confirmationCycle.status !== "pending"
    ) {
      throw new Error("Stale or completed proposal confirmation cycle.");
    }
    const existingAcknowledgement = await ctx.db
      .query("proposalLenderConfirmationAcknowledgements")
      .withIndex("by_cycle_actor_checkpoint", (query) =>
        query
          .eq("confirmationCycleId", confirmationCycle._id)
          .eq("acknowledgedByWorkosUserId", auth.subject)
          .eq("checkpoint", args.checkpoint),
      )
      .unique();
    if (existingAcknowledgement) {
      return {
        acknowledgementId: existingAcknowledgement._id,
        sequence: existingAcknowledgement.sequence,
      };
    }
    const priorAcknowledgements = await ctx.db
      .query("proposalLenderConfirmationAcknowledgements")
      .withIndex("by_cycle_and_actor", (query) =>
        query
          .eq("confirmationCycleId", confirmationCycle._id)
          .eq("acknowledgedByWorkosUserId", auth.subject),
      )
      .collect();
    const acknowledgedByRole = auth.roles.find((role) =>
      lenderRoleSlugs.includes(role as (typeof lenderRoleSlugs)[number]),
    );
    if (!acknowledgedByRole) {
      throw new Error("Forbidden: lender proposal confirmation role");
    }
    const now = Date.now();
    const sequence = priorAcknowledgements.length + 1;
    const acknowledgementId = await ctx.db.insert(
      "proposalLenderConfirmationAcknowledgements",
      {
        acknowledgedAt: now,
        acknowledgedByRole,
        acknowledgedByWorkosUserId: auth.subject,
        assignmentId: auth.currentLenderAssignment._id,
        brokerageId: auth.brokerage._id,
        checkpoint: args.checkpoint,
        confirmationCycleId: confirmationCycle._id,
        idempotencyKey,
        organizationId: auth.organizationId,
        proposalId: args.proposalId,
        proposalRevisionId: currentRevision._id,
        sequence,
      },
    );
    await writeProposalEvent(ctx, {
      auth,
      command: "acknowledgeProposalConfirmationCheckpoint",
      eventType: "proposal.lender_confirmation.checkpoint_acknowledged",
      newState: JSON.stringify({
        acknowledgementId,
        checkpoint: args.checkpoint,
        confirmationCycleId: confirmationCycle._id,
        proposalRevisionId: currentRevision._id,
        sequence,
      }),
      proposalId: args.proposalId,
    });
    return { acknowledgementId, sequence };
  })
  .public();

export const declineExternalProposalForClosing = authenticatedMutation
  .input({
    declinedCheckpoint: v.union(
      v.literal("milestoneCount"),
      v.literal("budget"),
      v.literal("scheduleTimeline"),
      v.literal("builder"),
      v.literal("accessReviewPolicy"),
    ),
    expectedAssignmentId: v.id("proposalLenderAssignments"),
    expectedConfirmationCycleId: v.id("proposalLenderConfirmationCycles"),
    expectedProposalRevisionId: v.id("proposalRevisions"),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(v.object({ decisionId: v.id("proposalLenderApprovals") }))
  .handler(async (ctx, args) => {
    const auth = await authorizeLenderProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
      "proposal_review",
    );
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    if (!auth.isCurrentLenderActor || !auth.currentLenderAssignment) {
      throw new Error("Forbidden: lender proposal decline");
    }
    assertProposalLifecycleTransition({
      command: "confirm",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    requireReason(args.reason);
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Proposal confirmation decision idempotency key",
    );
    const idempotentDecision = await ctx.db
      .query("proposalLenderApprovals")
      .withIndex("by_confirmation_cycle_and_idempotency_key", (query) =>
        query
          .eq("confirmationCycleId", args.expectedConfirmationCycleId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentDecision) {
      if (
        idempotentDecision.approverWorkosUserId !== auth.subject ||
        idempotentDecision.status !== "declined" ||
        idempotentDecision.declinedCheckpoint !== args.declinedCheckpoint ||
        idempotentDecision.reason !== args.reason.trim()
      ) {
        throw new Error(
          "Proposal confirmation decision idempotency key was reused with different values.",
        );
      }
      return { decisionId: idempotentDecision._id };
    }
    const currentRevision = await getCurrentProposalRevision(ctx, auth.proposal);
    const confirmationCycle = await getCurrentProposalLenderConfirmationCycle(
      ctx,
      auth.proposal,
      auth.currentLenderAssignment,
    );
    if (
      auth.currentLenderAssignment._id !== args.expectedAssignmentId ||
      !currentRevision ||
      currentRevision._id !== args.expectedProposalRevisionId ||
      !confirmationCycle ||
      confirmationCycle._id !== args.expectedConfirmationCycleId ||
      confirmationCycle.status !== "pending"
    ) {
      throw new Error("Stale or completed proposal confirmation cycle.");
    }
    const approverRole = auth.roles.find((role) =>
      LENDER_PROPOSAL_DECISION_ROLES.includes(
        role as (typeof LENDER_PROPOSAL_DECISION_ROLES)[number],
      ),
    );
    if (!approverRole) {
      throw new Error("Forbidden: lender proposal decline role");
    }
    const now = Date.now();
    assertProposalLenderApprovalTimestamps({
      declinedAt: now,
      status: "declined",
    });
    const decisionId = await ctx.db.insert("proposalLenderApprovals", {
      approverRole,
      approverWorkosUserId: auth.subject,
      assignmentId: auth.currentLenderAssignment._id,
      brokerageId: auth.brokerage._id,
      confirmationCycleId: confirmationCycle._id,
      createdAt: now,
      declinedAt: now,
      declinedCheckpoint: args.declinedCheckpoint,
      idempotencyKey,
      lenderOrganizationId:
        auth.currentLenderAssignment.lenderOrganizationId,
      organizationId: auth.organizationId,
      proposalId: args.proposalId,
      proposalRevisionId: currentRevision._id,
      proposalRevisionNumber: currentRevision.revisionNumber,
      reason: args.reason.trim(),
      status: "declined",
    });
    await ctx.db.patch(confirmationCycle._id, {
      closedAt: now,
      decisionId,
      status: "declined",
    });
    await ctx.db.patch(args.proposalId, {
      latestLenderApprovalId: undefined,
      latestLenderReviewedRevisionId: currentRevision._id,
      latestLenderReviewedRevisionNumber: currentRevision.revisionNumber,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await upsertKanbanCard(ctx, args.proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "declineExternalProposalForClosing",
      eventType: "proposal.lender_confirmation.declined",
      newState: JSON.stringify({
        confirmationCycleId: confirmationCycle._id,
        decisionId,
        declinedCheckpoint: args.declinedCheckpoint,
        proposalRevisionId: currentRevision._id,
        proposalRevisionNumber: currentRevision.revisionNumber,
        status: "declined",
      }),
      priorState: JSON.stringify({ lenderConfirmation: "pending" }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await enqueueProposalApprovalOutcomeNotifications(ctx, {
      assignment: auth.currentLenderAssignment,
      confirmationCycle,
      outcome: "rejected",
      proposal: auth.proposal,
      revision: currentRevision,
    });
    return { decisionId };
  })
  .public();

export const approveExternalProposalForClosing = authenticatedMutation
  .input({
    expectedAssignmentId: v.id("proposalLenderAssignments"),
    expectedConfirmationCycleId: v.id("proposalLenderConfirmationCycles"),
    expectedProposalRevisionId: v.id("proposalRevisions"),
    idempotencyKey: v.string(),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    workosOrganizationId: v.string(),
  })
  .returns(
    v.object({
      approvalId: v.id("proposalLenderApprovals"),
    }),
  )
  .handler(async (ctx, args) => {
    const auth = await authorizeLenderProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
      "proposal_review",
    );
    await assertNoArchivingProposalLenderAssignment(ctx, args.proposalId);
    if (!auth.isCurrentLenderActor || !auth.currentLenderAssignment) {
      throw new Error("Forbidden: lender proposal approval");
    }
    const idempotencyKey = normalizeOperationalIdempotencyKey(
      args.idempotencyKey,
      "Proposal confirmation decision idempotency key",
    );
    const idempotentDecision = await ctx.db
      .query("proposalLenderApprovals")
      .withIndex("by_confirmation_cycle_and_idempotency_key", (query) =>
        query
          .eq("confirmationCycleId", args.expectedConfirmationCycleId)
          .eq("idempotencyKey", idempotencyKey),
      )
      .unique();
    if (idempotentDecision) {
      if (
        idempotentDecision.approverWorkosUserId !== auth.subject ||
        idempotentDecision.status !== "approved" ||
        idempotentDecision.reason !== args.reason.trim()
      ) {
        throw new Error(
          "Proposal confirmation decision idempotency key was reused with different values.",
        );
      }
      return { approvalId: idempotentDecision._id };
    }
    assertProposalLifecycleTransition({
      command: "confirm",
      reviewOutcome: auth.proposal.reviewOutcome,
      state: auth.proposal.status,
    });
    requireReason(args.reason);
    const currentRevision = await getCurrentProposalRevision(
      ctx,
      auth.proposal,
    );
    if (
      !currentRevision ||
      currentRevision.assignmentId !== auth.currentLenderAssignment._id
    ) {
      throw new Error("A current proposal revision for this assignment is required.");
    }
    if (
      auth.currentLenderAssignment._id !== args.expectedAssignmentId ||
      currentRevision._id !== args.expectedProposalRevisionId
    ) {
      throw new Error("Stale proposal confirmation assignment or revision.");
    }
    const confirmationCycle = await getCurrentProposalLenderConfirmationCycle(
      ctx,
      auth.proposal,
      auth.currentLenderAssignment,
    );
    if (
      !confirmationCycle ||
      confirmationCycle._id !== args.expectedConfirmationCycleId ||
      confirmationCycle.status !== "pending"
    ) {
      throw new Error("Stale or completed proposal confirmation cycle.");
    }
    const acknowledgements = await ctx.db
      .query("proposalLenderConfirmationAcknowledgements")
      .withIndex("by_cycle_and_actor", (query) =>
        query
          .eq("confirmationCycleId", confirmationCycle._id)
          .eq("acknowledgedByWorkosUserId", auth.subject),
      )
      .collect();
    const acknowledgedCheckpoints = new Set(
      acknowledgements.map((acknowledgement) => acknowledgement.checkpoint),
    );
    if (
      PROPOSAL_CONFIRMATION_CHECKPOINTS.some(
        (checkpoint) => !acknowledgedCheckpoints.has(checkpoint),
      )
    ) {
      throw new Error(
        "Every proposal confirmation checkpoint must be acknowledged before approval.",
      );
    }
    const approverRole = auth.roles.find((role) =>
      LENDER_PROPOSAL_DECISION_ROLES.includes(
        role as (typeof LENDER_PROPOSAL_DECISION_ROLES)[number],
      ),
    );
    if (!approverRole) {
      throw new Error("Forbidden: lender proposal approval role");
    }
    const now = Date.now();
    assertProposalLenderApprovalTimestamps({
      approvedAt: now,
      status: "approved",
    });
    const approvalId = await ctx.db.insert("proposalLenderApprovals", {
      approverRole,
      approverWorkosUserId: auth.subject,
      approvedAt: now,
      assignmentId: auth.currentLenderAssignment._id,
      brokerageId: auth.brokerage._id,
      confirmationCycleId: confirmationCycle._id,
      createdAt: now,
      idempotencyKey,
      lenderOrganizationId:
        auth.currentLenderAssignment.lenderOrganizationId,
      organizationId: auth.organizationId,
      proposalId: args.proposalId,
      proposalRevisionId: currentRevision._id,
      proposalRevisionNumber: currentRevision.revisionNumber,
      reason: args.reason.trim(),
      status: "approved",
    });
    await ctx.db.patch(confirmationCycle._id, {
      closedAt: now,
      decisionId: approvalId,
      status: "approved",
    });
    await ctx.db.patch(args.proposalId, {
      latestLenderApprovalId: approvalId,
      latestLenderReviewedRevisionId: currentRevision._id,
      latestLenderReviewedRevisionNumber: currentRevision.revisionNumber,
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await upsertKanbanCard(ctx, args.proposalId, now);
    await writeProposalEvent(ctx, {
      auth,
      command: "approveExternalProposalForClosing",
      eventType: "proposal.lender_confirmation.approved",
      newState: JSON.stringify({
        approvalId,
        assignmentId: auth.currentLenderAssignment._id,
        confirmationCycleId: confirmationCycle._id,
        proposalRevisionId: currentRevision._id,
        proposalRevisionNumber: currentRevision.revisionNumber,
        status: "approved",
      }),
      priorState: JSON.stringify({ lenderConfirmation: "pending" }),
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await enqueueProposalApprovalOutcomeNotifications(ctx, {
      assignment: auth.currentLenderAssignment,
      confirmationCycle,
      outcome: "approved",
      proposal: auth.proposal,
      revision: currentRevision,
    });
    return { approvalId };
  })
  .public();

export const getLenderProposalConfirmation = authenticatedQuery
  .input({
    historyPaginationOpts: paginationOptsValidator,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(lenderProposalConfirmationProjectionValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeLenderProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    if (!auth.isCurrentLenderActor || !auth.currentLenderAssignment) {
      throw new Error("Forbidden: lender proposal confirmation");
    }
    const cycles = await paginateProposalConfirmationCycles(
      ctx,
      args.proposalId,
      args.historyPaginationOpts,
      auth.currentLenderAssignment._id,
    );
    const history = await Promise.all(
      cycles.page.map((cycle) =>
        projectProposalConfirmationCycle(ctx, cycle, {
          includePrivateActors: true,
          includePrivateReason: true,
        }),
      ),
    );
    const currentCycle = await getCurrentProposalLenderConfirmationCycle(
      ctx,
      auth.proposal,
      auth.currentLenderAssignment,
    );
    const currentProjection = currentCycle
      ? await projectProposalConfirmationCycle(ctx, currentCycle, {
          includePrivateActors: true,
          includePrivateReason: true,
        })
      : null;
    const actorAcknowledgements = currentProjection?.acknowledgements.filter(
      (acknowledgement) =>
        acknowledgement.acknowledgedByWorkosUserId === auth.subject,
    ) ?? [];
    const acknowledgedCheckpoints = new Set(
      actorAcknowledgements.map((acknowledgement) => acknowledgement.checkpoint),
    );
    const canAcknowledge = currentCycle?.status === "pending";
    const decisionAuthorized = Boolean(
      auth.roles.includes("admin") ||
        (auth.lenderOrganization?.permissions.proposalReview &&
          auth.roles.some((role) =>
            LENDER_PROPOSAL_DECISION_ROLES.includes(
              role as (typeof LENDER_PROPOSAL_DECISION_ROLES)[number],
            ),
          )),
    );
    const canDecide = Boolean(
      canAcknowledge &&
        decisionAuthorized &&
        PROPOSAL_CONFIRMATION_CHECKPOINTS.every((checkpoint) =>
          acknowledgedCheckpoints.has(checkpoint),
        ),
    );
    const currentApproval = await getLenderApprovalForCurrentProposalRevision(
      ctx,
      auth.proposal,
      auth.currentLenderAssignment,
    );
    const closingGateSatisfied = Boolean(
      currentCycle?.status === "approved" &&
        currentApproval &&
        (await isActiveEligibleLenderApproval(
          ctx,
          currentApproval,
          auth.currentLenderAssignment,
        )),
    );
    return {
      canAcknowledge,
      canDecide,
      closingGateSatisfied,
      currentCycle: currentProjection,
      decisionAuthorized,
      history: { ...cycles, page: history },
      lenderNeedsAction: currentCycle?.status === "pending",
    };
  })
  .public();

export const getBackofficeProposalRemediation = authenticatedQuery
  .input({
    historyPaginationOpts: paginationOptsValidator,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(backofficeProposalRemediationProjectionValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalLifecycleActor(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    if (auth.isCurrentLenderActor || !isBackoffice(auth.roles)) {
      throw new Error("Forbidden: Back Office proposal remediation");
    }
    const cycles = await paginateProposalConfirmationCycles(
      ctx,
      args.proposalId,
      args.historyPaginationOpts,
    );
    const history = await Promise.all(
      cycles.page.map((cycle) =>
        projectProposalConfirmationCycle(ctx, cycle, {
          includePrivateActors: true,
          includePrivateReason: true,
        }),
      ),
    );
    const currentCycle = auth.currentLenderAssignment
      ? await getCurrentProposalLenderConfirmationCycle(
          ctx,
          auth.proposal,
          auth.currentLenderAssignment,
        )
      : null;
    const currentProjection = currentCycle
      ? await projectProposalConfirmationCycle(ctx, currentCycle, {
          includePrivateActors: true,
          includePrivateReason: true,
        })
      : null;
    const currentDecision = currentCycle
      ? await getProposalConfirmationDecision(ctx, currentCycle)
      : null;
    const remediation =
      currentCycle?.status === "declined" &&
      currentDecision?.status === "declined" &&
      currentDecision.declinedCheckpoint &&
      currentDecision.reason &&
      auth.currentLenderAssignment
        ? {
            confirmationCycleId: currentCycle._id,
            declinedCheckpoint: currentDecision.declinedCheckpoint,
            declinedProposalRevisionId: currentCycle.proposalRevisionId,
            declinedProposalRevisionNumber:
              currentCycle.proposalRevisionNumber,
            editableProposalId: args.proposalId,
            privateReason: currentDecision.reason,
            publishBase: {
              expectedAssignmentId: auth.currentLenderAssignment._id,
              expectedProposalRevisionNumber:
                currentCycle.proposalRevisionNumber,
            },
            updateRequired: true as const,
          }
        : null;
    return {
      currentCycle: currentProjection,
      history: { ...cycles, page: history },
      lenderNeedsAction: currentCycle?.status === "pending",
      remediation,
    };
  })
  .public();

export const getBuilderProposalConfirmationState = authenticatedQuery
  .input({
    historyPaginationOpts: paginationOptsValidator,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(builderProposalConfirmationProjectionValidator)
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, BUILDER_ROLES);
    const assignment = await getCurrentProposalLenderAssignment(
      ctx,
      args.proposalId,
    );
    const cycles = await paginateProposalConfirmationCycles(
      ctx,
      args.proposalId,
      args.historyPaginationOpts,
    );
    const currentCycle = assignment
      ? await getCurrentProposalLenderConfirmationCycle(
          ctx,
          auth.proposal,
          assignment,
        )
      : null;
    const lenderConfirmation = currentCycle
      ? currentCycle.status === "approved"
        ? ("approved" as const)
        : currentCycle.status === "declined"
          ? ("declined" as const)
          : ("pending" as const)
      : ("pending" as const);
    return {
      currentProposalRevisionNumber:
        auth.proposal.currentProposalRevisionNumber ?? null,
      history: {
        ...cycles,
        page: cycles.page.map((cycle) => ({
          closedAt: cycle.closedAt ?? null,
          cycleNumber: cycle.cycleNumber,
          openedAt: cycle.openedAt,
          proposalRevisionNumber: cycle.proposalRevisionNumber,
          status: cycle.status,
        })),
      },
      lifecycle: projectProposalLifecycle(auth.proposal, assignment
        ? { lenderConfirmation, state: "assigned" }
        : { lenderConfirmation: "pending", state: "unassigned" }),
      updateRequired: currentCycle?.status === "declined",
    };
  })
  .public();

export const listProposalLenderAssignmentHistory = authenticatedQuery
  .input({
    paginationOpts: v.optional(paginationOptsValidator),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.optional(v.string()),
  })
  .returns(
    paginationResultValidator(proposalLenderAssignmentProjectionValidator),
  )
  .handler(async (ctx, args) => {
    let lenderOrganizationId: Id<"lenderOrganizations"> | undefined;
    if (args.workosOrganizationId) {
      const auth = await authorizeProposal(
        ctx,
        args.proposalId,
        args.workosOrganizationId,
      );
      requireAnyRole(auth.roles, BACKOFFICE_ROLES);
    } else {
      const identity = await ctx.auth.getUserIdentity();
      if (!identity) {
        throw new Error("Unauthorized");
      }
      const authorization = await resolveActiveLenderOrganizationContext(
        ctx,
        identity,
        "lenderOrganization",
      );
      lenderOrganizationId = authorization.activeOrganization.lenderOrganizationId;
    }

    const paginationOpts = args.paginationOpts ?? { cursor: null, numItems: 50 };
    let page;
    if (lenderOrganizationId) {
      const scopedLenderOrganizationId = lenderOrganizationId;
      page = await ctx.db
        .query("proposalLenderAssignments")
        .withIndex("by_proposal_lender_organization", (query) =>
          query
            .eq("proposalId", args.proposalId)
            .eq("lenderOrganizationId", scopedLenderOrganizationId),
        )
        .order("desc")
        .paginate(paginationOpts);
    } else {
      page = await ctx.db
        .query("proposalLenderAssignments")
        .withIndex("by_proposal", (query) =>
          query.eq("proposalId", args.proposalId),
        )
        .order("desc")
        .paginate(paginationOpts);
    }
    if (lenderOrganizationId && page.page.length === 0 && paginationOpts.cursor === null) {
      throw new Error("Forbidden: lender assignment history");
    }
    return {
      ...page,
      page: page.page.map(
        lenderOrganizationId
          ? projectLenderVisibleProposalAssignment
          : projectProposalLenderAssignment,
      ),
    };
  })
  .public();

export const updateSubmittedProposalDrawScheduleRow = authenticatedMutation
  .input({
    amountCents: v.optional(v.number()),
    drawKey: v.string(),
    label: v.optional(v.string()),
    proposalId: v.id("buildProposals"),
    reason: v.string(),
    timingDay: v.optional(v.number()),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    requireAnyRole(auth.roles, BACKOFFICE_ROLES);
    requireBackofficeProposalWrite(auth, auth.proposal);
    await assertProposalCollaborationEditAllowed(ctx, auth);
    requireReason(args.reason);
    if (!["submitted", "approved"].includes(auth.proposal.status)) {
      throw new Error(
        "Only submitted or approved proposal draw schedules can be edited.",
      );
    }
    if (args.amountCents !== undefined && args.amountCents < 0) {
      throw new Error("Draw amount cannot be negative.");
    }
    if (args.timingDay !== undefined && args.timingDay < 0) {
      throw new Error("Draw timing day cannot be negative.");
    }

    const draw = await ctx.db
      .query("proposalDrawScheduleRows")
      .withIndex("by_proposal_key", (q) =>
        q.eq("proposalId", args.proposalId).eq("drawKey", args.drawKey),
      )
      .unique();
    if (!draw) {
      throw new Error("Draw schedule row not found.");
    }

    const priorState = JSON.stringify({
      amountCents: draw.amountCents,
      label: draw.label,
      timingDay: draw.timingDay,
    });
    const now = Date.now();
    const patch = {
      amountCents: args.amountCents ?? draw.amountCents,
      label: args.label?.trim() || draw.label,
      timingDay: args.timingDay ?? draw.timingDay,
      updatedAt: now,
    };
    await ctx.db.patch(draw._id, patch);
    await ctx.db.patch(args.proposalId, {
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await ensureProposalApprovedAmountCoversDrawSchedule(ctx, auth.proposal, {
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "updateSubmittedProposalDrawScheduleRow",
      eventType: "proposal.draw_schedule.updated",
      newState: JSON.stringify({
        amountCents: patch.amountCents,
        label: patch.label,
        timingDay: patch.timingDay,
      }),
      priorState,
      proposalId: args.proposalId,
      reason: args.reason,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const createProductionTimelineMilestone = authenticatedMutation
  .input({
    milestone: productionTimelineMilestoneInput,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await requireProductionTimelineDraftStructureWrite(ctx, auth);
    await requireProposalAppPermission(ctx, auth, "milestone", "create");
    if ((args.milestone.submilestones ?? []).length > 0) {
      await requireProposalAppPermission(ctx, auth, "submilestone", "create");
    }
    const milestoneId = await insertProductionMilestoneFromInput(
      ctx,
      auth,
      args.milestone,
    );
    const milestone = await ctx.db.get(milestoneId);
    if (milestone) {
      await upsertProposalMilestoneDrawAvailability(ctx, auth, {
        amountCents: milestone.drawAvailabilityCents,
        drawKey: args.milestone.drawKey,
        milestone,
        proposalId: args.proposalId,
        timingDay: Math.max(
          Math.round(args.milestone.dayEnd),
          Math.round(args.milestone.dayStart),
        ),
      });
    }
    await recalculateProposalBudget(ctx, auth, args.proposalId);
    await writeProposalEvent(ctx, {
      auth,
      command: "createProductionTimelineMilestone",
      eventType: "proposal.milestone.created",
      newState: JSON.stringify(args.milestone),
      proposalId: args.proposalId,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const updateProductionTimelineMilestone = authenticatedMutation
  .input({
    budgetCents: v.optional(v.number()),
    dayEnd: v.optional(v.number()),
    dayStart: v.optional(v.number()),
    dependencyKeys: v.optional(v.array(v.string())),
    drawAvailabilityCents: v.optional(v.number()),
    durationDays: v.optional(v.number()),
    evidenceState: v.optional(v.string()),
    icon: v.optional(v.string()),
    lane: v.optional(v.number()),
    markerLabel: v.optional(v.string()),
    milestoneKey: v.string(),
    name: v.optional(v.string()),
    order: v.optional(v.number()),
    policyState: v.optional(v.string()),
    proposalId: v.id("buildProposals"),
    status: v.optional(v.string()),
    submilestones: v.optional(v.array(submilestoneInput)),
    tone: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await requireProductionTimelineDraftStructureWrite(ctx, auth);
    await requireProposalAppPermission(ctx, auth, "milestone", "update");
    if (args.submilestones !== undefined) {
      await requireProposalAppPermission(ctx, auth, "submilestone", "update");
    }
    const milestone = await getProductionMilestoneOrThrow(
      ctx,
      args.proposalId,
      args.milestoneKey,
    );
    const nextDayStart = Math.round(args.dayStart ?? milestone.dayStart);
    if (nextDayStart < 0) {
      throw new Error("Milestone start day must be on or after T0.");
    }
    const existingDurationDays = Math.max(
      1,
      Math.round(
        milestone.durationDays ?? milestone.dayEnd - milestone.dayStart,
      ),
    );
    const nextRequestedDurationDays =
      args.durationDays ??
      (args.dayStart !== undefined && args.dayEnd === undefined
        ? existingDurationDays
        : undefined);
    const nextDayEnd = Math.round(
      args.dayEnd ??
        (nextRequestedDurationDays === undefined
          ? milestone.dayEnd
          : nextDayStart + nextRequestedDurationDays),
    );
    if (nextDayEnd < 0) {
      throw new Error("Milestone end day must be on or after T0.");
    }
    if (nextDayEnd < nextDayStart && nextRequestedDurationDays === undefined) {
      throw new Error("Milestone end day must be after start day.");
    }
    const dayStartDelta = nextDayStart - Math.round(milestone.dayStart);
    const existingSubmilestones = (await ctx.db
      .query("proposalSubmilestones")
      .withIndex("by_milestone", (q) =>
        q.eq("proposalMilestoneId", milestone._id),
      )
      .collect()) as Doc<"proposalSubmilestones">[];
    const schedule = normalizeProductionMilestoneSchedule({
      dayEnd: nextDayEnd,
      dayStart: nextDayStart,
      durationDays: nextRequestedDurationDays,
      submilestones:
        args.submilestones === undefined
          ? existingSubmilestones.map((submilestone) => ({
              budgetCents: submilestone.budgetCents,
              durationDays: submilestone.durationDays,
              key: submilestone.key,
              name: submilestone.name,
              order: submilestone.order,
              startDay:
                submilestone.startDay === undefined
                  ? undefined
                  : Math.max(
                      0,
                      Math.round(submilestone.startDay + dayStartDelta),
                    ),
            }))
          : args.submilestones,
    });
    if (
      args.submilestones !== undefined &&
      schedule.submilestones.length > 0
    ) {
      assertValidProductionSubmilestones(
        schedule.submilestones,
        `Milestone ${milestone.key}`,
      );
    }
    const budgetDerivedFromSubmilestones =
      args.submilestones !== undefined && schedule.submilestones.length > 0;
    const unscopedAdditiveCostCents = budgetDerivedFromSubmilestones
      ? (
          await ctx.db
            .query("proposalCostItems")
            .withIndex("by_milestone", (q) =>
              q.eq("proposalMilestoneId", milestone._id),
            )
            .collect()
        ).reduce(
          (total, item) =>
            normalizeCostItemBudgetTreatment(item.budgetTreatment) === "add" &&
            !item.budgetSubmilestoneKey
              ? total + costItemTotalCents(item)
              : total,
          0,
        )
      : 0;
    const nextBudgetCents = budgetDerivedFromSubmilestones
      ? sumProductionSubmilestoneBudgetCents(schedule.submilestones) +
        unscopedAdditiveCostCents
      : args.budgetCents === undefined
        ? milestone.budgetCents
        : Math.max(0, Math.round(args.budgetCents));
    const now = Date.now();
    const nextDrawAvailabilityCents =
      args.drawAvailabilityCents === undefined
        ? calculateDrawAvailability(
            nextBudgetCents,
            auth.proposal.borrowerCoPayBps,
          )
        : Math.max(0, Math.round(args.drawAvailabilityCents));
    const patch = {
      ...(args.budgetCents === undefined && !budgetDerivedFromSubmilestones
        ? {}
        : { budgetCents: nextBudgetCents }),
      ...(args.dayEnd === undefined ? {} : { dayEnd: Math.round(args.dayEnd) }),
      ...(args.dayStart === undefined
        ? {}
        : { dayStart: Math.round(args.dayStart) }),
      ...(args.dependencyKeys === undefined
        ? {}
        : { dependencyKeys: args.dependencyKeys }),
      ...(args.drawAvailabilityCents === undefined &&
      args.budgetCents === undefined &&
      !budgetDerivedFromSubmilestones
        ? {}
        : { drawAvailabilityCents: nextDrawAvailabilityCents }),
      ...(args.durationDays === undefined
        ? {}
        : { durationDays: Math.max(1, Math.round(args.durationDays)) }),
      ...(args.evidenceState === undefined
        ? {}
        : { evidenceState: args.evidenceState }),
      ...(args.icon === undefined ? {} : { icon: args.icon }),
      ...(args.lane === undefined ? {} : { lane: args.lane }),
      ...(args.markerLabel === undefined
        ? {}
        : { markerLabel: args.markerLabel }),
      ...(args.name === undefined
        ? {}
        : { name: args.name.trim() || milestone.name }),
      ...(args.order === undefined
        ? {}
        : { order: Math.max(1, Math.round(args.order)) }),
      ...(args.policyState === undefined
        ? {}
        : { policyState: args.policyState }),
      ...(args.status === undefined ? {} : { timelineStatus: args.status }),
      ...(args.tone === undefined ? {} : { tone: args.tone }),
      updatedAt: now,
    };
    Object.assign(patch, {
      dayEnd: schedule.dayEnd,
      dayStart: schedule.dayStart,
      durationDays: schedule.durationDays,
    });
    await ctx.db.patch(milestone._id, patch);
    if (args.submilestones !== undefined || dayStartDelta !== 0) {
      await replaceProductionSubmilestones(ctx, auth, {
        milestone,
        proposalId: args.proposalId,
        rejectEmpty: args.submilestones !== undefined,
        rows: schedule.submilestones,
      });
    }
    await recalculateProposalBudget(ctx, auth, args.proposalId);
    await writeProposalEvent(ctx, {
      auth,
      command: "updateProductionTimelineMilestone",
      eventType: "proposal.milestone.updated",
      newState: JSON.stringify(patch),
      priorState: JSON.stringify(milestone),
      proposalId: args.proposalId,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const deleteProductionTimelineMilestone = authenticatedMutation
  .input({
    milestoneKey: v.string(),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await requireProductionTimelineDraftStructureWrite(ctx, auth);
    await requireProposalAppPermission(ctx, auth, "milestone", "delete");
    await requireProposalAppPermission(ctx, auth, "submilestone", "delete");
    const milestone = await getProductionMilestoneOrThrow(
      ctx,
      args.proposalId,
      args.milestoneKey,
    );
    await deleteProductionMilestoneCascade(ctx, args.proposalId, milestone);
    await recalculateProposalBudget(ctx, auth, args.proposalId);
    await writeProposalEvent(ctx, {
      auth,
      command: "deleteProductionTimelineMilestone",
      eventType: "proposal.milestone.deleted",
      priorState: JSON.stringify(milestone),
      proposalId: args.proposalId,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const createProposalCostItem = authenticatedMutation
  .input({
    ...productionCostItemCreateInput,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.id("proposalCostItems"))
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalCostItemWrite(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
      "create",
      args.reason,
    );
    const milestone = await getProductionMilestoneOrThrow(
      ctx,
      args.proposalId,
      args.milestoneKey,
    );
    const relevantSubmilestoneKeys =
      await validateProposalCostItemSubmilestones(
        ctx,
        milestone,
        args.relevantSubmilestoneKeys,
      );
    const budgetTreatment = normalizeCostItemBudgetTreatment(
      args.budgetTreatment,
    );
    const budgetSubmilestoneKey = await validateProposalCostItemBudgetTarget(
      ctx,
      milestone,
      args.budgetSubmilestoneKey,
      budgetTreatment,
      args.budgetTreatment !== undefined,
    );
    const now = Date.now();
    const costCents = normalizeCostItemCost(args.costCents);
    const quantity = normalizeCostItemQuantity(args.quantity);
    const delivery = validateCostItemDeliveryWindow(args);
    const item = {
      brokerageId: auth.brokerage._id,
      budgetSubmilestoneKey,
      budgetTreatment,
      costCents,
      createdAt: now,
      createdByWorkosUserId: auth.subject,
      deliveryEndDay: delivery.deliveryEndDay,
      deliveryInstructions: normalizeOptionalText(args.deliveryInstructions),
      deliveryLocation: normalizeOptionalText(args.deliveryLocation),
      deliveryStartDay: delivery.deliveryStartDay,
      description: normalizeOptionalText(args.description),
      itemKey: await nextProposalCostItemKey(
        ctx,
        args.proposalId,
        args.title,
        now,
      ),
      itemType: args.itemType,
      milestoneKey: milestone.key,
      organizationId: args.workosOrganizationId,
      proposalId: args.proposalId,
      proposalMilestoneId: milestone._id,
      quantity,
      relevantSubmilestoneKeys,
      specificationTiptapJson: normalizeOptionalTiptapJson(
        args.specificationTiptapJson,
        "Material specification",
      ),
      supplier: normalizeOptionalText(args.supplier),
      title: normalizeRequiredText(args.title, "Cost item title"),
      unit: normalizeOptionalText(args.unit),
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    };
    const itemId = await ctx.db.insert("proposalCostItems", item);
    await applyProposalCostItemBudgetChange(ctx, auth, {
      nextItem: { ...item, _id: itemId },
      proposalId: args.proposalId,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "createProposalCostItem",
      eventType: "proposal.cost_item.created",
      newState: JSON.stringify({ ...item, _id: itemId }),
      proposalId: args.proposalId,
      reason: args.reason,
      warnings: proposalCostItemAuditWarnings(auth.proposal),
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return itemId;
  })
  .public();

export const updateProposalCostItem = authenticatedMutation
  .input({
    ...productionCostItemUpdateInput,
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalCostItemWrite(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
      "update",
      args.reason,
    );
    const item = await getProposalCostItemOrThrow(
      ctx,
      args.proposalId,
      args.itemId,
    );
    const milestone =
      args.milestoneKey === undefined || args.milestoneKey === item.milestoneKey
        ? await getProposalMilestoneByIdOrThrow(ctx, item.proposalMilestoneId)
        : await getProductionMilestoneOrThrow(
            ctx,
            args.proposalId,
            args.milestoneKey,
          );
    const milestoneChanged = milestone._id !== item.proposalMilestoneId;
    const relevantSubmilestoneKeys =
      args.relevantSubmilestoneKeys === undefined && !milestoneChanged
        ? item.relevantSubmilestoneKeys
        : await validateProposalCostItemSubmilestones(
            ctx,
            milestone,
            args.relevantSubmilestoneKeys ?? [],
          );
    const budgetTreatment = normalizeCostItemBudgetTreatment(
      args.budgetTreatment ?? item.budgetTreatment,
    );
    const requestedBudgetSubmilestoneKey =
      args.budgetSubmilestoneKey === undefined
        ? milestoneChanged
          ? undefined
          : item.budgetSubmilestoneKey
        : args.budgetSubmilestoneKey;
    const budgetSubmilestoneKey = await validateProposalCostItemBudgetTarget(
      ctx,
      milestone,
      requestedBudgetSubmilestoneKey,
      budgetTreatment,
      budgetTreatment === "add" &&
        (args.budgetTreatment !== undefined ||
          args.budgetSubmilestoneKey !== undefined ||
          item.budgetSubmilestoneKey !== undefined),
    );
    const now = Date.now();
    const delivery = validateCostItemDeliveryWindow({
      deliveryEndDay:
        args.deliveryEndDay === undefined
          ? item.deliveryEndDay
          : args.deliveryEndDay,
      deliveryStartDay:
        args.deliveryStartDay === undefined
          ? item.deliveryStartDay
          : args.deliveryStartDay,
    });
    const patch = {
      budgetSubmilestoneKey,
      budgetTreatment,
      ...(args.costCents === undefined
        ? {}
        : { costCents: normalizeCostItemCost(args.costCents) }),
      ...(args.description === undefined
        ? {}
        : { description: normalizeOptionalText(args.description) }),
      ...(args.deliveryEndDay === undefined
        ? {}
        : { deliveryEndDay: delivery.deliveryEndDay }),
      ...(args.deliveryInstructions === undefined
        ? {}
        : {
            deliveryInstructions: normalizeOptionalText(
              args.deliveryInstructions,
            ),
          }),
      ...(args.deliveryLocation === undefined
        ? {}
        : { deliveryLocation: normalizeOptionalText(args.deliveryLocation) }),
      ...(args.deliveryStartDay === undefined
        ? {}
        : { deliveryStartDay: delivery.deliveryStartDay }),
      ...(args.itemType === undefined ? {} : { itemType: args.itemType }),
      ...(milestoneChanged
        ? {
            milestoneKey: milestone.key,
            proposalMilestoneId: milestone._id,
          }
        : {}),
      ...(args.quantity === undefined
        ? {}
        : { quantity: normalizeCostItemQuantity(args.quantity) }),
      relevantSubmilestoneKeys,
      ...(args.supplier === undefined
        ? {}
        : { supplier: normalizeOptionalText(args.supplier) }),
      ...(args.specificationTiptapJson === undefined
        ? {}
        : {
            specificationTiptapJson: normalizeOptionalTiptapJson(
              args.specificationTiptapJson,
              "Material specification",
            ),
          }),
      ...(args.title === undefined
        ? {}
        : { title: normalizeRequiredText(args.title, "Cost item title") }),
      ...(args.unit === undefined
        ? {}
        : { unit: normalizeOptionalText(args.unit) }),
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    };
    const nextItem = { ...item, ...patch };
    await ctx.db.patch(item._id, patch);
    await applyProposalCostItemBudgetChange(ctx, auth, {
      nextItem,
      priorItem: item,
      proposalId: args.proposalId,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "updateProposalCostItem",
      eventType: "proposal.cost_item.updated",
      newState: JSON.stringify(nextItem),
      priorState: JSON.stringify(item),
      proposalId: args.proposalId,
      reason: args.reason,
      warnings: proposalCostItemAuditWarnings(auth.proposal),
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const deleteProposalCostItem = authenticatedMutation
  .input({
    itemId: v.id("proposalCostItems"),
    proposalId: v.id("buildProposals"),
    reason: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposalCostItemWrite(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
      "delete",
      args.reason,
    );
    const item = await getProposalCostItemOrThrow(
      ctx,
      args.proposalId,
      args.itemId,
    );
    await ctx.db.delete(item._id);
    await applyProposalCostItemBudgetChange(ctx, auth, {
      priorItem: item,
      proposalId: args.proposalId,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "deleteProposalCostItem",
      eventType: "proposal.cost_item.deleted",
      priorState: JSON.stringify(item),
      proposalId: args.proposalId,
      reason: args.reason,
      warnings: proposalCostItemAuditWarnings(auth.proposal),
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const createActiveBuildCostItem = authenticatedMutation
  .input({
    ...productionCostItemCreateInput,
    buildId: v.id("activeBuilds"),
    expectedRevision: v.optional(v.number()),
    idempotencyKey: v.optional(v.string()),
    submilestoneKey: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.union(v.id("buildCostItems"), activeBuildCostItemScopedMutationResult))
  .handler(async (ctx, args) => {
    const auth = await authorizeActiveBuildCostItemWrite(
      ctx,
      args.buildId,
      args.workosOrganizationId,
      "create",
      args.reason,
      { requireReason: false },
    );
    const milestone = await getActiveBuildMilestoneOrThrow(
      ctx,
      args.buildId,
      args.milestoneKey,
    );
    const canonicalSubmilestoneKey = canonicalOptionalSubmilestoneKey(
      args.submilestoneKey,
    );
    const scopedSubmilestone = canonicalSubmilestoneKey !== undefined
      ? await activeBuildMaterialTarget(ctx, {
          buildId: args.buildId,
          milestone,
          submilestoneKey: canonicalSubmilestoneKey,
        })
      : undefined;
    const scopedMaterialCommand = scopedSubmilestone !== undefined;
    const scopedIdempotencyKey = scopedMaterialCommand
      ? requireScopedMaterialCommandInput(args)
      : undefined;
    const command = "createActiveBuildCostItem";
    const fingerprint = scopedMaterialCommand
      ? await canonicalCommandFingerprint(command, {
          ...args,
          relevantSubmilestoneKeys: canonicalStringKeyList(
            args.relevantSubmilestoneKeys,
          ),
          submilestoneKey: scopedSubmilestone.key,
        })
      : undefined;
    if (scopedMaterialCommand) {
      const existing = await findSubmilestoneIdempotentAudit(ctx, {
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        submilestoneId: scopedSubmilestone._id,
      });
      if (existing) {
        return materialScopedMutationReplay(existing);
      }
      assertExpectedSubmilestoneRevision(
        scopedSubmilestone,
        args.expectedRevision!,
      );
    }
    const relevantSubmilestoneKeys = await validateBuildCostItemSubmilestones(
      ctx,
      milestone,
      args.relevantSubmilestoneKeys,
    );
    const scopedRelevantSubmilestoneKeys = scopedSubmilestone
      ? canonicalStringKeyList([
          ...relevantSubmilestoneKeys,
          scopedSubmilestone.key,
        ])
      : relevantSubmilestoneKeys;
    if (
      (args.budgetTreatment !== undefined && args.budgetTreatment !== "add") ||
      normalizeCostItemBudgetSubmilestoneKey(args.budgetSubmilestoneKey)
    ) {
      throw new Error(
        "Budget treatment and target can only be selected during proposal planning.",
      );
    }
    // Active-build cost items retain the historical additive behavior. Budget
    // treatment is selected during proposal planning and copied at closing.
    const budgetTreatment = "add" as const;
    const budgetSubmilestoneKey = undefined;
    const now = Date.now();
    const costCents = normalizeCostItemCost(args.costCents);
    const quantity = normalizeCostItemQuantity(args.quantity);
    const delivery = validateCostItemDeliveryWindow(args);
    const item = {
      brokerageId: auth.brokerage._id,
      budgetSubmilestoneKey,
      budgetTreatment,
      buildId: args.buildId,
      buildMilestoneId: milestone._id,
      costCents,
      createdAt: now,
      createdByWorkosUserId: auth.subject,
      deliveryEndDay: delivery.deliveryEndDay,
      deliveryInstructions: normalizeOptionalText(args.deliveryInstructions),
      deliveryLocation: normalizeOptionalText(args.deliveryLocation),
      deliveryStartDay: delivery.deliveryStartDay,
      description: normalizeOptionalText(args.description),
      itemKey: await nextBuildCostItemKey(ctx, args.buildId, args.title, now),
      itemType: args.itemType,
      milestoneKey: milestone.key,
      organizationId: args.workosOrganizationId,
      proposalId: auth.proposal._id,
      quantity,
      relevantSubmilestoneKeys: scopedRelevantSubmilestoneKeys,
      specificationTiptapJson: normalizeOptionalTiptapJson(
        args.specificationTiptapJson,
        "Material specification",
      ),
      supplier: normalizeOptionalText(args.supplier),
      title: normalizeRequiredText(args.title, "Cost item title"),
      unit: normalizeOptionalText(args.unit),
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    };
    const itemId = await ctx.db.insert("buildCostItems", item);
    const nextRevision = scopedSubmilestone
      ? (scopedSubmilestone.workflowRevision ?? 0) + 1
      : undefined;
    if (scopedSubmilestone && nextRevision !== undefined) {
      await ctx.db.patch(scopedSubmilestone._id, {
        updatedAt: now,
        workflowRevision: nextRevision,
      });
    }
    await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
      buildId: args.buildId,
      deltaCents: budgetTreatment === "add" ? costItemTotalCents(item) : 0,
      milestone,
      submilestoneKey: budgetSubmilestoneKey,
    });
    await writeActiveBuildEvent(ctx, {
      auth,
      build: auth.build,
      command,
      ...(scopedSubmilestone
        ? {
            entityId: String(scopedSubmilestone._id),
            entityType: "buildSubmilestone",
          }
        : {}),
      eventType: "active_build.cost_item.created",
      resourceType: "material",
      newState: JSON.stringify({
        ...item,
        _id: itemId,
        ...(nextRevision === undefined
          ? {}
          : {
              submilestoneKey: scopedSubmilestone?.key,
              workflowRevision: nextRevision,
            }),
      }),
      reason: args.reason,
    });
    if (scopedSubmilestone && nextRevision !== undefined) {
      const result = {
        itemId,
        replayed: false,
        revision: nextRevision,
      };
      await insertSubmilestoneCommandReceipt(ctx, {
        buildId: args.buildId,
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        organizationId: auth.build.organizationId,
        result,
        submilestoneId: scopedSubmilestone._id,
      });
      return result;
    }
    return itemId;
  })
  .public();

export const updateActiveBuildCostItem = authenticatedMutation
  .input({
    ...productionBuildCostItemUpdateInput,
    buildId: v.id("activeBuilds"),
    expectedRevision: v.optional(v.number()),
    idempotencyKey: v.optional(v.string()),
    submilestoneKey: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.union(v.null(), activeBuildCostItemScopedMutationResult))
  .handler(async (ctx, args) => {
    const auth = await authorizeActiveBuildCostItemWrite(
      ctx,
      args.buildId,
      args.workosOrganizationId,
      "update",
      args.reason,
    );
    const item = await getBuildCostItemOrThrow(ctx, args.buildId, args.itemId);
    const milestone =
      args.milestoneKey === undefined || args.milestoneKey === item.milestoneKey
        ? await ctx.db.get(item.buildMilestoneId)
        : await getActiveBuildMilestoneOrThrow(
            ctx,
            args.buildId,
            args.milestoneKey,
          );
    if (!milestone) {
      throw new Error("Production active-build milestone not found.");
    }
    const milestoneChanged = milestone._id !== item.buildMilestoneId;
    const canonicalSubmilestoneKey = canonicalOptionalSubmilestoneKey(
      args.submilestoneKey,
    );
    const scopedSubmilestone = canonicalSubmilestoneKey !== undefined
      ? await activeBuildMaterialTarget(ctx, {
          buildId: args.buildId,
          milestone,
          submilestoneKey: canonicalSubmilestoneKey,
        })
      : undefined;
    if (scopedSubmilestone && item && item.milestoneKey !== milestone.key) {
      throw new ConvexError({
        code: "MATERIAL_SCOPE_MISMATCH",
        message:
          "The material does not belong to the requested canonical Milestone scope.",
      });
    }
    const scopedMaterialCommand = scopedSubmilestone !== undefined;
    const scopedIdempotencyKey = scopedMaterialCommand
      ? requireScopedMaterialCommandInput(args)
      : undefined;
    const command = "updateActiveBuildCostItem";
    const fingerprint = scopedMaterialCommand
      ? await canonicalCommandFingerprint(command, {
          ...args,
          relevantSubmilestoneKeys:
            args.relevantSubmilestoneKeys === undefined
              ? undefined
              : canonicalStringKeyList(args.relevantSubmilestoneKeys),
          submilestoneKey: scopedSubmilestone.key,
        })
      : undefined;
    if (scopedMaterialCommand) {
      const existing = await findSubmilestoneIdempotentAudit(ctx, {
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        submilestoneId: scopedSubmilestone._id,
      });
      if (existing) {
        return materialScopedMutationReplay(existing);
      }
      assertExpectedSubmilestoneRevision(
        scopedSubmilestone,
        args.expectedRevision!,
      );
    }
    const relevantSubmilestoneKeys =
      args.relevantSubmilestoneKeys === undefined && !milestoneChanged
        ? item.relevantSubmilestoneKeys
        : await validateBuildCostItemSubmilestones(
            ctx,
            milestone,
            args.relevantSubmilestoneKeys ?? [],
          );
    const scopedRelevantSubmilestoneKeys = scopedSubmilestone
      ? canonicalStringKeyList([
          ...relevantSubmilestoneKeys,
          scopedSubmilestone.key,
        ])
      : relevantSubmilestoneKeys;
    const budgetTreatment = normalizeCostItemBudgetTreatment(
      item.budgetTreatment,
    );
    const requestedBudgetSubmilestoneKey = item.budgetSubmilestoneKey;
    if (
      args.budgetTreatment !== undefined &&
      args.budgetTreatment !== budgetTreatment
    ) {
      throw new Error(
        "Budget treatment can only be changed during proposal planning.",
      );
    }
    if (
      args.budgetSubmilestoneKey !== undefined &&
      normalizeCostItemBudgetSubmilestoneKey(args.budgetSubmilestoneKey) !==
        normalizeCostItemBudgetSubmilestoneKey(requestedBudgetSubmilestoneKey)
    ) {
      throw new Error(
        "Budget sub-milestone target can only be changed during proposal planning.",
      );
    }
    const budgetSubmilestoneKey = await validateBuildCostItemBudgetTarget(
      ctx,
      milestone,
      requestedBudgetSubmilestoneKey,
      budgetTreatment,
    );
    const now = Date.now();
    const delivery = validateCostItemDeliveryWindow({
      deliveryEndDay:
        args.deliveryEndDay === undefined
          ? item.deliveryEndDay
          : args.deliveryEndDay,
      deliveryStartDay:
        args.deliveryStartDay === undefined
          ? item.deliveryStartDay
          : args.deliveryStartDay,
    });
    const patch = {
      budgetSubmilestoneKey,
      budgetTreatment,
      ...(args.costCents === undefined
        ? {}
        : { costCents: normalizeCostItemCost(args.costCents) }),
      ...(args.description === undefined
        ? {}
        : { description: normalizeOptionalText(args.description) }),
      ...(args.deliveryEndDay === undefined
        ? {}
        : { deliveryEndDay: delivery.deliveryEndDay }),
      ...(args.deliveryInstructions === undefined
        ? {}
        : {
            deliveryInstructions: normalizeOptionalText(
              args.deliveryInstructions,
            ),
          }),
      ...(args.deliveryLocation === undefined
        ? {}
        : { deliveryLocation: normalizeOptionalText(args.deliveryLocation) }),
      ...(args.deliveryStartDay === undefined
        ? {}
        : { deliveryStartDay: delivery.deliveryStartDay }),
      ...(args.itemType === undefined ? {} : { itemType: args.itemType }),
      ...(milestoneChanged
        ? {
            buildMilestoneId: milestone._id,
            milestoneKey: milestone.key,
          }
        : {}),
      ...(args.quantity === undefined
        ? {}
        : { quantity: normalizeCostItemQuantity(args.quantity) }),
      relevantSubmilestoneKeys: scopedRelevantSubmilestoneKeys,
      ...(args.supplier === undefined
        ? {}
        : { supplier: normalizeOptionalText(args.supplier) }),
      ...(args.specificationTiptapJson === undefined
        ? {}
        : {
            specificationTiptapJson: normalizeOptionalTiptapJson(
              args.specificationTiptapJson,
              "Material specification",
            ),
          }),
      ...(args.title === undefined
        ? {}
        : { title: normalizeRequiredText(args.title, "Cost item title") }),
      ...(args.unit === undefined
        ? {}
        : { unit: normalizeOptionalText(args.unit) }),
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    };
    const nextItem = { ...item, ...patch };
    await ctx.db.patch(item._id, patch);
    const priorTotal =
      normalizeCostItemBudgetTreatment(item.budgetTreatment) === "add"
        ? costItemTotalCents(item)
        : 0;
    const nextTotal =
      budgetTreatment === "add" ? costItemTotalCents(nextItem) : 0;
    let priorMilestoneForValidation = milestone;
    if (milestoneChanged) {
      const priorMilestone = await ctx.db.get(item.buildMilestoneId);
      if (!priorMilestone) {
        throw new Error("Production active-build milestone not found.");
      }
      priorMilestoneForValidation = priorMilestone;
      await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
        buildId: args.buildId,
        deltaCents: -priorTotal,
        milestone: priorMilestone,
        submilestoneKey: item.budgetSubmilestoneKey,
      });
      await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
        buildId: args.buildId,
        deltaCents: nextTotal,
        milestone,
        submilestoneKey: budgetSubmilestoneKey,
      });
    } else {
      if (item.budgetSubmilestoneKey === budgetSubmilestoneKey) {
        await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
          buildId: args.buildId,
          deltaCents: nextTotal - priorTotal,
          milestone,
          submilestoneKey: budgetSubmilestoneKey,
        });
      } else {
        await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
          buildId: args.buildId,
          deltaCents: -priorTotal,
          milestone,
          submilestoneKey: item.budgetSubmilestoneKey,
        });
        await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
          buildId: args.buildId,
          deltaCents: nextTotal,
          milestone,
          submilestoneKey: budgetSubmilestoneKey,
        });
      }
    }
    if (item.budgetSubmilestoneKey) {
      await validateBuildMaintainedCostCoverage(ctx, {
        buildId: args.buildId,
        milestoneId: priorMilestoneForValidation._id,
        submilestoneKey: item.budgetSubmilestoneKey,
      });
    }
    if (budgetSubmilestoneKey) {
      await validateBuildMaintainedCostCoverage(ctx, {
        buildId: args.buildId,
        milestoneId: milestone._id,
        submilestoneKey: budgetSubmilestoneKey,
      });
    }
    const nextRevision = scopedSubmilestone
      ? (scopedSubmilestone.workflowRevision ?? 0) + 1
      : undefined;
    if (scopedSubmilestone && nextRevision !== undefined) {
      await ctx.db.patch(scopedSubmilestone._id, {
        updatedAt: now,
        workflowRevision: nextRevision,
      });
    }
    await writeActiveBuildEvent(ctx, {
      auth,
      build: auth.build,
      command,
      ...(scopedSubmilestone
        ? {
            entityId: String(scopedSubmilestone._id),
            entityType: "buildSubmilestone",
          }
        : {}),
      eventType: "active_build.cost_item.updated",
      resourceType: "material",
      newState: JSON.stringify({
        ...nextItem,
        ...(nextRevision === undefined
          ? {}
          : {
              submilestoneKey: scopedSubmilestone?.key,
              workflowRevision: nextRevision,
            }),
      }),
      priorState: JSON.stringify(item),
      reason: args.reason,
    });
    if (scopedSubmilestone && nextRevision !== undefined) {
      const result = {
        itemId: item._id,
        replayed: false,
        revision: nextRevision,
      };
      await insertSubmilestoneCommandReceipt(ctx, {
        buildId: args.buildId,
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        organizationId: auth.build.organizationId,
        result,
        submilestoneId: scopedSubmilestone._id,
      });
      return result;
    }
    return null;
  })
  .public();

export const deleteActiveBuildCostItem = authenticatedMutation
  .input({
    buildId: v.id("activeBuilds"),
    itemId: v.id("buildCostItems"),
    expectedRevision: v.optional(v.number()),
    idempotencyKey: v.optional(v.string()),
    milestoneKey: v.optional(v.string()),
    reason: v.optional(v.string()),
    submilestoneKey: v.optional(v.string()),
    workosOrganizationId: v.string(),
  })
  .returns(v.union(v.null(), activeBuildCostItemScopedMutationResult))
  .handler(async (ctx, args) => {
    const auth = await authorizeActiveBuildCostItemWrite(
      ctx,
      args.buildId,
      args.workosOrganizationId,
      "delete",
      args.reason,
    );
    const canonicalSubmilestoneKey = canonicalOptionalSubmilestoneKey(
      args.submilestoneKey,
    );
    const scopedMilestoneKey = args.milestoneKey?.trim();
    if (canonicalSubmilestoneKey !== undefined && !scopedMilestoneKey) {
      throw new ConvexError({
        code: "MILESTONE_KEY_REQUIRED",
        message:
          "A non-empty Milestone key is required for a scoped material command.",
      });
    }
    let item =
      canonicalSubmilestoneKey !== undefined
        ? undefined
        : await getBuildCostItemOrThrow(ctx, args.buildId, args.itemId);
    const milestone = item
      ? await ctx.db.get(item.buildMilestoneId)
      : await getActiveBuildMilestoneOrThrow(
          ctx,
          args.buildId,
          scopedMilestoneKey ?? args.milestoneKey!,
        );
    if (!milestone) {
      throw new Error("Production active-build milestone not found.");
    }
    const scopedSubmilestone = canonicalSubmilestoneKey !== undefined
      ? await activeBuildMaterialTarget(ctx, {
          buildId: args.buildId,
          milestone,
          submilestoneKey: canonicalSubmilestoneKey,
        })
      : undefined;
    if (scopedSubmilestone && item && item.milestoneKey !== milestone.key) {
      throw new ConvexError({
        code: "MATERIAL_SCOPE_MISMATCH",
        message:
          "The material does not belong to the requested canonical Milestone scope.",
      });
    }
    const scopedMaterialCommand = scopedSubmilestone !== undefined;
    const scopedIdempotencyKey = scopedMaterialCommand
      ? requireScopedMaterialCommandInput(args)
      : undefined;
    const command = "deleteActiveBuildCostItem";
    const fingerprint = scopedMaterialCommand
      ? await canonicalCommandFingerprint(command, {
          ...args,
          milestoneKey: milestone.key,
          submilestoneKey: scopedSubmilestone.key,
        })
      : undefined;
    if (scopedMaterialCommand) {
      const existing = await findSubmilestoneIdempotentAudit(ctx, {
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        submilestoneId: scopedSubmilestone._id,
      });
      if (existing) {
        return materialScopedMutationReplay(existing);
      }
      assertExpectedSubmilestoneRevision(
        scopedSubmilestone,
        args.expectedRevision!,
      );
    }
    if (!item) {
      item = await getBuildCostItemOrThrow(ctx, args.buildId, args.itemId);
    }
    if (item.milestoneKey !== milestone.key) {
      throw new ConvexError({
        code: "MATERIAL_SCOPE_MISMATCH",
        message:
          "The material does not belong to the requested canonical Milestone scope.",
      });
    }
    await ctx.db.delete(item._id);
    await applyActiveBuildCostItemBudgetDelta(ctx, auth, {
      buildId: args.buildId,
      deltaCents:
        normalizeCostItemBudgetTreatment(item.budgetTreatment) === "add"
          ? -costItemTotalCents(item)
        : 0,
      milestone,
      submilestoneKey: item.budgetSubmilestoneKey,
    });
    const nextRevision = scopedSubmilestone
      ? (scopedSubmilestone.workflowRevision ?? 0) + 1
      : undefined;
    if (scopedSubmilestone && nextRevision !== undefined) {
      await ctx.db.patch(scopedSubmilestone._id, {
        updatedAt: Date.now(),
        workflowRevision: nextRevision,
      });
    }
    await writeActiveBuildEvent(ctx, {
      auth,
      build: auth.build,
      command,
      ...(scopedSubmilestone
        ? {
            entityId: String(scopedSubmilestone._id),
            entityType: "buildSubmilestone",
          }
        : {}),
      eventType: "active_build.cost_item.deleted",
      resourceType: "material",
      newState: JSON.stringify({
        itemId: item._id,
        ...(scopedSubmilestone === undefined
          ? {}
          : {
              submilestoneKey: scopedSubmilestone.key,
              workflowRevision: nextRevision,
            }),
      }),
      priorState: JSON.stringify({
        ...item,
        ...(scopedSubmilestone === undefined
          ? {}
          : { submilestoneKey: scopedSubmilestone.key }),
      }),
      reason: args.reason,
    });
    if (scopedSubmilestone && nextRevision !== undefined) {
      const result = {
        itemId: item._id,
        replayed: false,
        revision: nextRevision,
      };
      await insertSubmilestoneCommandReceipt(ctx, {
        buildId: args.buildId,
        command,
        fingerprint: fingerprint!,
        idempotencyKey: scopedIdempotencyKey!,
        organizationId: auth.build.organizationId,
        result,
        submilestoneId: scopedSubmilestone._id,
      });
      return result;
    }
    return null;
  })
  .public();

export const createProductionTimelineDraw = authenticatedMutation
  .input({
    amountCents: v.number(),
    customDate: v.optional(v.boolean()),
    drawKey: v.string(),
    itemMilestoneKey: v.optional(v.string()),
    label: v.string(),
    order: v.optional(v.number()),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
    x: v.number(),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await requireProductionTimelineEditable(ctx, auth);
    await requireProposalAppPermission(ctx, auth, "draw", "create");
    const existing = await ctx.db
      .query("proposalDrawScheduleRows")
      .withIndex("by_proposal_key", (q) =>
        q.eq("proposalId", args.proposalId).eq("drawKey", args.drawKey),
      )
      .unique();
    if (existing) {
      throw new Error("Production draw already exists.");
    }
    if (!Number.isFinite(args.x) || Math.round(args.x) < 0) {
      throw new Error("Draw timing day must be on or after T0.");
    }
    const draws = await collectByIndex(
      ctx,
      "proposalDrawScheduleRows",
      "by_proposal",
      args.proposalId,
    );
    const milestone =
      args.itemMilestoneKey === undefined
        ? null
        : await getProductionMilestoneOrThrow(
            ctx,
            args.proposalId,
            args.itemMilestoneKey,
          );
    const now = Date.now();
    await ctx.db.insert("proposalDrawScheduleRows", {
      amountCents: Math.max(0, Math.round(args.amountCents)),
      brokerageId: auth.brokerage._id,
      createdAt: now,
      customDate: args.customDate ?? true,
      drawKey: args.drawKey,
      label: args.label.trim() || "Reimbursement draw",
      ...(args.itemMilestoneKey === undefined
        ? {}
        : { milestoneKey: args.itemMilestoneKey }),
      order: args.order ?? draws.length + 1,
      organizationId: auth.proposal.organizationId,
      proposalId: args.proposalId,
      ...(milestone === null ? {} : { proposalMilestoneId: milestone._id }),
      source: "manual",
      timingDay: Math.max(0, Math.round(args.x)),
      updatedAt: now,
    });
    await ensureProposalApprovedAmountCoversDrawSchedule(ctx, auth.proposal, {
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "createProductionTimelineDraw",
      eventType: "proposal.draw.created",
      newState: JSON.stringify(args),
      proposalId: args.proposalId,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const updateProductionTimelineDraw = authenticatedMutation
  .input({
    amountCents: v.optional(v.number()),
    customDate: v.optional(v.boolean()),
    drawKey: v.string(),
    itemMilestoneKey: v.optional(v.string()),
    label: v.optional(v.string()),
    order: v.optional(v.number()),
    proposalId: v.id("buildProposals"),
    workosOrganizationId: v.string(),
    x: v.optional(v.number()),
  })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const auth = await authorizeProposal(
      ctx,
      args.proposalId,
      args.workosOrganizationId,
    );
    await requireProductionTimelineEditable(ctx, auth);
    await requireProposalAppPermission(ctx, auth, "draw", "update");
    const draw = await getProductionDrawOrThrow(
      ctx,
      args.proposalId,
      args.drawKey,
    );
    if (
      args.x !== undefined &&
      (!Number.isFinite(args.x) || Math.round(args.x) < 0)
    ) {
      throw new Error("Draw timing day must be on or after T0.");
    }
    const milestone =
      args.itemMilestoneKey === undefined
        ? undefined
        : await getProductionMilestoneOrThrow(
            ctx,
            args.proposalId,
            args.itemMilestoneKey,
          );
    const now = Date.now();
    const patch = {
      ...(args.amountCents === undefined
        ? {}
        : { amountCents: Math.max(0, Math.round(args.amountCents)) }),
      ...(args.customDate === undefined ? {} : { customDate: args.customDate }),
      ...(milestone === undefined
        ? {}
        : {
            milestoneKey: args.itemMilestoneKey,
            proposalMilestoneId: milestone._id,
          }),
      ...(args.label === undefined
        ? {}
        : { label: args.label.trim() || draw.label }),
      ...(args.order === undefined
        ? {}
        : { order: Math.max(1, Math.round(args.order)) }),
      ...(args.x === undefined
        ? {}
        : { customDate: true, timingDay: Math.max(0, Math.round(args.x)) }),
      updatedAt: now,
    };
    await ctx.db.patch(draw._id, patch);
    await ensureProposalApprovedAmountCoversDrawSchedule(ctx, auth.proposal, {
      updatedAt: now,
      updatedByWorkosUserId: auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth,
      command: "updateProductionTimelineDraw",
      eventType: "proposal.draw.updated",
      newState: JSON.stringify(patch),
      priorState: JSON.stringify(draw),
      proposalId: args.proposalId,
    });
    await pushProposalPlanningSnapshot(ctx, args.proposalId);
    return null;
  })
  .public();

export const deleteProductionTimelineDraw = authenticatedMutation
