function requireIntegrationText(value: string, label: string) {
  const normalized = value.trim();
  if (!normalized) {
    throw new ConvexError(`${label} is required.`);
  }
  return normalized;
}

function requireIntegrationReason(reason: string) {
  const normalized = reason.trim();
  if (normalized.length < 8) {
    throw new ConvexError("Provide a reason with at least 8 characters.");
  }
  return normalized;
}

function normalizeIntegrationEndpointUrl(value: string) {
  const normalized = value.trim();
  let endpointUrl: URL;
  try {
    endpointUrl = new URL(normalized);
  } catch {
    throw new ConvexError("Enter a valid HTTPS endpoint URL.");
  }
  if (endpointUrl.protocol !== "https:") {
    throw new ConvexError("Integration endpoints must use HTTPS.");
  }
  const hostname = endpointUrl.hostname
    .toLowerCase()
    .replaceAll("[", "")
    .replaceAll("]", "");
  const ipv4Parts = hostname.split(".").map(Number);
  const isIpv4 =
    ipv4Parts.length === 4 &&
    ipv4Parts.every(
      (part) => Number.isInteger(part) && part >= 0 && part <= 255,
    );
  const isPrivateIpv4 =
    isIpv4 &&
    (ipv4Parts[0] === 10 ||
      ipv4Parts[0] === 127 ||
      (ipv4Parts[0] === 169 && ipv4Parts[1] === 254) ||
      (ipv4Parts[0] === 172 && ipv4Parts[1] >= 16 && ipv4Parts[1] <= 31) ||
      (ipv4Parts[0] === 192 && ipv4Parts[1] === 168));
  const isPrivateHostname =
    hostname === "localhost" ||
    hostname.endsWith(".localhost") ||
    hostname.endsWith(".local") ||
    hostname.endsWith(".internal") ||
    hostname === "::1" ||
    hostname.startsWith("fc") ||
    hostname.startsWith("fd") ||
    hostname.startsWith("fe80:");
  if (isPrivateIpv4 || isPrivateHostname) {
    throw new ConvexError(
      "Integration endpoint hosts must be publicly routable.",
    );
  }
  const allowedHosts = process.env.DRAWFLOW_WEBHOOK_ALLOWED_HOSTS?.split(",")
    .map((host) => host.trim().toLowerCase())
    .filter(Boolean);
  if (
    allowedHosts?.length &&
    !allowedHosts.some(
      (allowedHost) =>
        hostname === allowedHost || hostname.endsWith(`.${allowedHost}`),
    )
  ) {
    throw new ConvexError("Integration endpoint host is not allowlisted.");
  }
  endpointUrl.username = "";
  endpointUrl.password = "";
  endpointUrl.hash = "";
  return endpointUrl.toString();
}

function normalizeIntegrationEventTypes(eventTypes: string[]) {
  const normalized = [
    ...new Set(eventTypes.map((eventType) => eventType.trim()).filter(Boolean)),
  ];
  if (normalized.length === 0) {
    throw new ConvexError("Select at least one event subscription.");
  }
  return normalized;
}

function sanitizeIntegrationError(value?: string) {
  const normalized = normalizeOptionalString(value);
  if (!normalized) {
    return;
  }
  return normalized
    .replace(/dfwhsec_[A-Za-z0-9-]+/g, "[secret redacted]")
    .replace(
      /(authorization|secret|token|signature)\s*[:=]\s*\S+/gi,
      "$1: [redacted]",
    )
    .slice(0, 500);
}

function integrationEndpointAuditState(endpoint: Doc<"integrationEndpoints">) {
  return JSON.stringify({
    endpointUrl: endpoint.endpointUrl,
    eventTypes: endpoint.eventTypes,
    name: endpoint.name,
    payloadVersion: endpoint.payloadVersion,
    secretFingerprint: endpoint.secretFingerprint,
    secretVersion: endpoint.secretVersion,
    status: endpoint.status,
    validatedAt: endpoint.validatedAt,
  });
}

async function writeIntegrationEvent(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    command: string;
    endpoint: Doc<"integrationEndpoints">;
    eventType: string;
    newState?: string;
    organizationId: string;
    priorState?: string;
    reason: string;
  },
) {
  const now = Date.now();
  await ctx.db.insert("auditEvents", {
    actorRoles: input.auth.roles,
    actorWorkosUserId: input.auth.subject,
    brokerageId: input.auth.brokerage._id,
    command: input.command,
    createdAt: now,
    entityId: String(input.endpoint._id),
    entityType: "integrationEndpoint",
    eventType: input.eventType,
    newState: input.newState,
    organizationId: input.organizationId,
    priorState: input.priorState,
    reason: input.reason,
    warnings: [],
  });
  await ctx.db.insert("eventOutbox", {
    brokerageId: input.auth.brokerage._id,
    createdAt: now,
    eventType: input.eventType,
    organizationId: input.organizationId,
    payloadPreview: JSON.stringify({
      endpointId: String(input.endpoint._id),
      status: input.endpoint.status,
    }),
    relatedEntityId: input.endpoint._id,
    relatedEntityType: "integrationEndpoint",
    status: "pending",
  });
}

async function getRecipientDeliveryOrThrow(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  deliveryId: Id<"recipientDeliveries">,
  workosOrganizationId: string,
) {
  const auth = await authorizeBrokerage(ctx, workosOrganizationId);
  const delivery = await ctx.db.get(deliveryId);
  if (
    !delivery ||
    delivery.brokerageId !== auth.brokerage._id ||
    delivery.organizationId !== workosOrganizationId ||
    delivery.recipientWorkosUserId !== auth.subject
  ) {
    throw new ConvexError("Delivery unavailable.");
  }
  return delivery;
}

async function authorizeBrokerage(
  ctx: QueryCtx | MutationCtx,
  workosOrganizationId: string,
  viewer?: AuthorizedViewer,
) {
  const scope = await resolveBrokerageScope(ctx, workosOrganizationId, viewer);
  if (!scope.brokerage) {
    throw new Error("Forbidden: brokerage");
  }

  return {
    brokerage: scope.brokerage,
    roles: scope.roles,
    subject: scope.subject,
  };
}

async function resolveBrokerageScope(
  ctx: QueryCtx | MutationCtx,
  workosOrganizationId: string,
  viewer?: AuthorizedViewer,
) {
  const activeViewer =
    viewer ?? (ctx as unknown as { viewer: AuthorizedViewer }).viewer;
  const roles = normalizeRoleSlugs(activeViewer.roles);
  const subject = activeViewer.subject;
  const membership = await ctx.db
    .query("workosOrganizationMemberships")
    .withIndex("by_user", (q) => q.eq("workosUserId", subject))
    .filter((q) => q.eq(q.field("workosOrganizationId"), workosOrganizationId))
    .first();
  const activeTokenOrganizationId = activeViewer.organizationId?.trim();
  if (
    (!membership || membership.status !== "active") &&
    activeTokenOrganizationId !== workosOrganizationId
  ) {
    throw new Error("Forbidden: WorkOS membership");
  }

  const brokerage = await ctx.db
    .query("brokerages")
    .withIndex("by_workos_organization", (q) =>
      q.eq("workosOrganizationId", workosOrganizationId),
    )
    .unique();
  const activeBrokerage = brokerage?.status === "active" ? brokerage : null;

  return { brokerage: activeBrokerage, roles, subject };
}

async function authorizeActiveBuild(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  buildId: Id<"activeBuilds">,
  workosOrganizationId: string,
) {
  return await authorizeActiveBuildForViewer(
    ctx,
    ctx.viewer,
    buildId,
    workosOrganizationId,
  );
}

async function authorizeActiveBuildForViewer(
  ctx: QueryCtx | MutationCtx,
  viewer: AuthorizedViewer,
  buildId: Id<"activeBuilds">,
  workosOrganizationId: string,
) {
  const auth = await authorizeBrokerage(ctx, workosOrganizationId, viewer);
  const build = await ctx.db.get(buildId);
  if (!build || build.brokerageId !== auth.brokerage._id) {
    return null;
  }
  const proposal = await ctx.db.get(build.proposalId);
  if (!proposal || proposal.brokerageId !== auth.brokerage._id) {
    return null;
  }
  if (isBackoffice(auth.roles)) {
    await assertBackofficeProposalRead(ctx, auth, proposal);
  } else {
    const builderProfileId = assignedBuilderProfileIdOrThrow(proposal);
    await requireAnyBuilderStaffViewPermission(ctx, auth, {
      buildId,
      builderProfileId,
      proposalId: proposal._id,
      scope: "activeBuild",
    });
  }
  return { ...auth, build, proposal };
}

async function authorizeActiveBuildOrThrow(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  buildId: Id<"activeBuilds">,
  workosOrganizationId: string,
) {
  const auth = await authorizeActiveBuild(ctx, buildId, workosOrganizationId);
  if (!auth) {
    throw new Error("Forbidden: active build scope");
  }
  return auth;
}

/** Narrow Contractor admission used only by the canonical start command. */
async function authorizeActiveBuildForStart(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  buildId: Id<"activeBuilds">,
  workosOrganizationId: string
): Promise<Awaited<ReturnType<typeof authorizeActiveBuildOrThrow>>> {
  if (!ctx.viewer.roles.includes("contractor")) {
    return await authorizeActiveBuildOrThrow(
      ctx,
      buildId,
      workosOrganizationId
    );
  }
  const access = await authorizeActiveBuildAccess(ctx, {
    buildId,
    organizationId: workosOrganizationId,
  });
  return {
    brokerage: access.brokerage,
    build: access.build,
    proposal: access.proposal,
    roles: normalizeRoleSlugs(ctx.viewer.roles),
    subject: ctx.viewer.subject,
  };
}

function requireBackofficeActiveBuildWrite(auth: {
  proposal: Doc<"buildProposals">;
  roles: RoleSlug[];
  subject: string;
}) {
  requireAnyRole(auth.roles, BACKOFFICE_ROLES);
  requireBackofficeProposalWrite(auth, auth.proposal);
}

function requireApproverActiveBuildWrite(auth: {
  proposal: Doc<"buildProposals">;
  roles: RoleSlug[];
  subject: string;
}) {
  requireAnyRole(auth.roles, APPROVER_ROLES);
  requireBackofficeProposalWrite(auth, auth.proposal);
}

async function getPrimaryLoanFacility(
  ctx: QueryCtx | MutationCtx,
  buildId: Id<"activeBuilds">,
) {
  const facilities = (await collectByIndex(
    ctx,
    "loanFacilities",
    "by_build",
    buildId,
  )) as Doc<"loanFacilities">[];
  return (
    facilities.find(
      (facility) =>
        facility.facilityKind === undefined ||
        facility.facilityKind === "construction",
    ) ?? null
  );
}

async function authorizeProposal(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  proposalId: Id<"buildProposals">,
  workosOrganizationId: string,
) {
  return await authorizeProposalForViewer(
    ctx,
    ctx.viewer,
    proposalId,
    workosOrganizationId,
  );
}

async function authorizeProposalForViewer(
  ctx: QueryCtx | MutationCtx,
  viewer: AuthorizedViewer,
  proposalId: Id<"buildProposals">,
  workosOrganizationId: string,
) {
  const auth = await authorizeBrokerage(ctx, workosOrganizationId, viewer);
  const proposal = await ctx.db.get(proposalId);
  if (!proposal || proposal.brokerageId !== auth.brokerage._id) {
    throw new Error("Forbidden: proposal scope");
  }
  if (isBackoffice(auth.roles)) {
    try {
      await assertBackofficeProposalRead(ctx, auth, proposal);
    } catch (error) {
      if (
        await hasActiveCollaborationParticipant(ctx, proposal._id, auth.subject)
      ) {
        return { ...auth, proposal };
      }
      throw error;
    }
  } else {
    if (
      !proposal.builderProfileId &&
      (await hasActiveCollaborationParticipant(ctx, proposal._id, auth.subject))
    ) {
      return { ...auth, proposal };
    }
    const builderProfileId = assignedBuilderProfileIdOrThrow(proposal);
    try {
      await requireAnyBuilderStaffViewPermission(ctx, auth, {
        builderProfileId,
        proposalId: proposal._id,
        scope: "proposal",
      });
    } catch (error) {
      if (
        await hasActiveCollaborationParticipant(ctx, proposal._id, auth.subject)
      ) {
        return { ...auth, proposal };
      }
      throw error;
    }
  }
  return { ...auth, proposal };
}

async function assertBuilderProfileScope(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  brokerageId: Id<"brokerages">,
) {
  const builder = await ctx.db.get(builderProfileId);
  if (
    !builder ||
    builder.brokerageId !== brokerageId ||
    builder.status !== "active"
  ) {
    throw new Error("Forbidden: builder scope");
  }
  return builder;
}

function assignedBuilderProfileIdOrThrow(
  proposal: Pick<Doc<"buildProposals">, "builderProfileId">,
  message = "Proposal is not assigned to a builder.",
) {
  if (!proposal.builderProfileId) {
    throw new Error(message);
  }
  return proposal.builderProfileId;
}

async function assertBuilderOwnership(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  workosUserId: string,
) {
  const link = await getActiveBuilderAccountLink(
    ctx,
    builderProfileId,
    workosUserId,
  );
  if (!link || link.status !== "active") {
    throw new Error("Forbidden: builder ownership");
  }
  await assertBuilderAccountLinkNotDeleted(ctx, link, builderProfileId);
}

async function getActiveBuilderAccountLink(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  workosUserId: string,
) {
  const link = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_builder_user", (q) =>
      q
        .eq("builderProfileId", builderProfileId)
        .eq("workosUserId", workosUserId),
    )
    .unique();
  return link?.status === "active" ? link : null;
}

async function assertBuilderAccountLinkNotDeleted(
  ctx: QueryCtx | MutationCtx,
  link: Doc<"builderAccountLinks">,
  builderProfileId: Id<"builderProfiles">,
) {
  const workosOrganizationId =
    await builderProfileBrokerageWorkosOrganizationId(ctx, builderProfileId);
  const workosState = await builderAccountLinkWorkosState(ctx, {
    link,
    workosOrganizationId,
  });
  if (workosState.hidden) {
    throw new Error("Forbidden: builder account is not active in WorkOS");
  }
}

async function builderProfileBrokerageWorkosOrganizationId(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
) {
  const builderProfile = await ctx.db.get(builderProfileId);
  if (!builderProfile) {
    throw new Error("Forbidden: builder scope");
  }
  const brokerage = await ctx.db.get(builderProfile.brokerageId);
  if (!brokerage || brokerage.status !== "active") {
    throw new Error("Forbidden: brokerage");
  }
  return brokerage.workosOrganizationId;
}

async function builderAccountLinkWorkosState(
  ctx: QueryCtx | MutationCtx,
  input: {
    link: Doc<"builderAccountLinks">;
    workosOrganizationId: string;
  },
) {
  const user = await getWorkosUserForBuilderAccountLink(ctx, input.link);
  if (user?.status === "deleted") {
    return { hidden: true as const, membership: null, user };
  }

  const membership = await getBuilderAccountLinkWorkosMembership(ctx, {
    ...input,
    user,
  });
  if (input.link.role === "staff" && membership?.status === "pending") {
    if (
      workosMembershipRoleSlugs(membership).includes("builder-staff") ||
      isBuilderStaffRoleSyncPending(input.link, membership)
    ) {
      return {
        hidden: false as const,
        identityStatus: "pending" as const,
        membership,
        user,
      };
    }
    return { hidden: true as const, membership, user };
  }

  if (membership && membership.status !== "active") {
    return { hidden: true as const, membership, user };
  }

  if (
    input.link.role === "staff" &&
    membership?.status === "active" &&
    !workosMembershipRoleSlugs(membership).includes("builder-staff")
  ) {
    if (isBuilderStaffRoleSyncPending(input.link, membership)) {
      return {
        hidden: false as const,
        identityStatus: "pending" as const,
        membership,
        user,
      };
    }
    return { hidden: true as const, membership, user };
  }

  const projected = Boolean(user && membership);
  return {
    hidden: false as const,
    identityStatus: projected ? ("active" as const) : ("pending" as const),
    membership,
    user,
  };
}

function isBuilderStaffRoleSyncPending(
  link: Doc<"builderAccountLinks">,
  membership: Doc<"workosOrganizationMemberships">,
) {
  return (
    Boolean(link.workosMembershipId) &&
    link.workosMembershipId === membership.workosMembershipId &&
    link.updatedAt >= (membership.updatedAt ?? 0)
  );
}

async function getBuilderAccountLinkWorkosMembership(
  ctx: QueryCtx | MutationCtx,
  input: {
    link: Doc<"builderAccountLinks">;
    user?: Doc<"users"> | null;
    workosOrganizationId: string;
  },
) {
  if (input.link.workosMembershipId) {
    const workosMembershipId = input.link.workosMembershipId;
    const membership = await ctx.db
      .query("workosOrganizationMemberships")
      .withIndex("by_workos_membership_id", (q) =>
        q.eq("workosMembershipId", workosMembershipId),
      )
      .unique();
    if (membership) {
      return membership;
    }
  }

  const workosUserId = input.user?.workosUserId ?? input.link.workosUserId;
  return await ctx.db
    .query("workosOrganizationMemberships")
    .withIndex("by_user", (q) => q.eq("workosUserId", workosUserId))
    .filter((q) =>
      q.eq(q.field("workosOrganizationId"), input.workosOrganizationId),
    )
    .first();
}

function workosMembershipRoleSlugs(
  membership: Pick<
    Doc<"workosOrganizationMemberships">,
    "roleSlug" | "roleSlugs"
  >,
) {
  return normalizeRoleSlugs([
    membership.roleSlug,
    ...(membership.roleSlugs ?? []),
  ]);
}

type BuilderStaffPermissionResource =
  (typeof BUILDER_STAFF_PERMISSION_RESOURCES)[number];
type BuilderStaffPermissionAction =
  (typeof BUILDER_STAFF_PERMISSION_ACTIONS)[number];
type BuilderStaffPermissionScope = "proposal" | "activeBuild";

interface BuilderStaffPermissionContext {
  action: BuilderStaffPermissionAction;
  builderProfileId: Id<"builderProfiles">;
  buildId?: Id<"activeBuilds">;
  proposalId: Id<"buildProposals">;
  resourceType: BuilderStaffPermissionResource;
  scope: BuilderStaffPermissionScope;
}

interface BuilderStaffPermissionSnapshot {
  grants: Array<{
    canCreate: boolean;
    canDelete: boolean;
    canUpdate: boolean;
    canView: boolean;
    resourceType: BuilderStaffPermissionResource;
  }>;
  mode: "full" | "limited";
  role: "backoffice" | "lender" | "owner" | "staff";
}

async function requireBuilderStaffPermission(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    roles: RoleSlug[];
    subject: string;
  },
  input: BuilderStaffPermissionContext,
) {
  const snapshot = await getBuilderStaffPermissionSnapshot(ctx, auth, input);
  if (snapshot.mode === "full") {
    return snapshot;
  }
  const grant = snapshot.grants.find(
    (candidate) => candidate.resourceType === input.resourceType,
  );
  if (!grant?.[permissionFieldForAction(input.action)]) {
    throw new Error(
      `Forbidden: builder staff ${input.resourceType}.${input.action}`,
    );
  }
  return snapshot;
}

async function requireAnyBuilderStaffViewPermission(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    roles: RoleSlug[];
    subject: string;
  },
  input: Omit<BuilderStaffPermissionContext, "action" | "resourceType">,
) {
  const snapshot = await getBuilderStaffPermissionSnapshot(ctx, auth, {
    ...input,
    action: "view",
    resourceType: "milestone",
  });
  if (snapshot.mode === "full") {
    return snapshot;
  }
  if (
    !snapshot.grants.some(
      (grant) =>
        grant.canView || grant.canCreate || grant.canUpdate || grant.canDelete,
    )
  ) {
    throw new Error("Forbidden: builder staff view");
  }
  return snapshot;
}

async function getBuilderStaffPermissionSnapshot(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    roles: RoleSlug[];
    subject: string;
  },
  input: BuilderStaffPermissionContext,
): Promise<BuilderStaffPermissionSnapshot> {
  if (isBackoffice(auth.roles)) {
    return {
      grants: fullBuilderStaffPermissionGrants(),
      mode: "full",
      role: "backoffice",
    };
  }
  const link = await getActiveBuilderAccountLinkForStaffViewer(
    ctx,
    input.builderProfileId,
    auth,
  );
  if (!link) {
    throw new Error("Forbidden: builder ownership");
  }
  await assertBuilderAccountLinkNotDeleted(ctx, link, input.builderProfileId);
  if (link.role === "owner") {
    return {
      grants: fullBuilderStaffPermissionGrants(),
      mode: "full",
      role: "owner",
    };
  }

  const rows =
    input.scope === "proposal"
      ? await ctx.db
          .query("builderStaffPermissionGrants")
          .withIndex("by_link", (q) => q.eq("builderAccountLinkId", link._id))
          .filter((q) =>
            q.and(
              q.eq(q.field("scope"), "proposal"),
              q.eq(q.field("proposalId"), input.proposalId),
            ),
          )
          .collect()
      : await ctx.db
          .query("builderStaffPermissionGrants")
          .withIndex("by_link", (q) => q.eq("builderAccountLinkId", link._id))
          .filter((q) =>
            q.and(
              q.eq(q.field("scope"), "activeBuild"),
              q.eq(q.field("buildId"), input.buildId),
            ),
          )
          .collect();

  return {
    grants: normalizeBuilderStaffPermissionRows(rows),
    mode: "limited",
    role: "staff",
  };
}

async function proposalAppPermissionProjection(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
): Promise<BuilderStaffPermissionSnapshot> {
  if (!auth.proposal.builderProfileId) {
    return {
      grants: fullBuilderStaffPermissionGrants(),
      mode: "full",
      role: isBackoffice(auth.roles) ? "backoffice" : "owner",
    };
  }
  return await getBuilderStaffPermissionSnapshot(ctx, auth, {
    builderProfileId: auth.proposal.builderProfileId,
    proposalId: auth.proposal._id,
    action: "view",
    resourceType: "milestone",
    scope: "proposal",
  });
}

async function activeBuildAppPermissionProjection(
  ctx: QueryCtx | MutationCtx,
  auth: {
    build: Doc<"activeBuilds">;
    email?: string;
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
): Promise<BuilderStaffPermissionSnapshot> {
  return await getBuilderStaffPermissionSnapshot(ctx, auth, {
    buildId: auth.build._id,
    builderProfileId: auth.build.builderProfileId,
    proposalId: auth.proposal._id,
    action: "view",
    resourceType: "milestone",
    scope: "activeBuild",
  });
}

function canUseAppPermission(
  permissions: BuilderStaffPermissionSnapshot,
  resourceType: BuilderStaffPermissionResource,
  action: BuilderStaffPermissionAction,
) {
  if (permissions.mode === "full") {
    return true;
  }
  const grant = permissions.grants.find(
    (candidate) => candidate.resourceType === resourceType,
  );
  return Boolean(grant?.[permissionFieldForAction(action)]);
}

async function requireProposalAppPermission(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
  resourceType: BuilderStaffPermissionResource,
  action: BuilderStaffPermissionAction,
) {
  if (!auth.proposal.builderProfileId) {
    if (isBackoffice(auth.roles)) {
      return;
    }
    throw new Error("Proposal is not assigned to a builder.");
  }
  await requireBuilderStaffPermission(ctx, auth, {
    builderProfileId: auth.proposal.builderProfileId,
    proposalId: auth.proposal._id,
    resourceType,
    action,
    scope: "proposal",
  });
}

async function requireActiveBuildAppPermission(
  ctx: QueryCtx | MutationCtx,
  auth: {
    build: Doc<"activeBuilds">;
    email?: string;
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
  resourceType: BuilderStaffPermissionResource,
  action: BuilderStaffPermissionAction,
) {
  await requireBuilderStaffPermission(ctx, auth, {
    buildId: auth.build._id,
    builderProfileId: auth.build.builderProfileId,
    proposalId: auth.proposal._id,
    resourceType,
    action,
    scope: "activeBuild",
  });
}

function permissionFieldForAction(action: BuilderStaffPermissionAction) {
  switch (action) {
    case "create":
      return "canCreate";
    case "view":
      return "canView";
    case "update":
      return "canUpdate";
    case "delete":
      return "canDelete";
  }
}

function fullBuilderStaffPermissionGrants(): BuilderStaffPermissionSnapshot["grants"] {
  return BUILDER_STAFF_PERMISSION_RESOURCES.map((resourceType) => ({
    canCreate: true,
    canDelete: true,
    canUpdate: true,
    canView: true,
    resourceType,
  }));
}

function lenderProposalReviewPermissionProjection(): BuilderStaffPermissionSnapshot {
  return {
    grants: BUILDER_STAFF_PERMISSION_RESOURCES.map((resourceType) => ({
      canCreate: false,
      canDelete: false,
      canUpdate: false,
      canView: true,
      resourceType,
    })),
    mode: "limited",
    role: "lender",
  };
}

function normalizeBuilderStaffPermissionRows(
  rows: Array<Doc<"builderStaffPermissionGrants">>,
) {
  const byResource = new Map<
    BuilderStaffPermissionResource,
    {
      canCreate: boolean;
      canDelete: boolean;
      canUpdate: boolean;
      canView: boolean;
      resourceType: BuilderStaffPermissionResource;
    }
  >();
  for (const resourceType of BUILDER_STAFF_PERMISSION_RESOURCES) {
    byResource.set(resourceType, {
      canCreate: false,
      canDelete: false,
      canUpdate: false,
      canView: false,
      resourceType,
    });
  }
  for (const row of rows) {
    if (!isBuilderStaffPermissionResource(row.resourceType)) {
      continue;
    }
    byResource.set(row.resourceType, {
      canCreate: row.canCreate,
      canDelete: row.canDelete,
      canUpdate: row.canUpdate,
      canView: row.canView,
      resourceType: row.resourceType,
    });
  }
  return [...byResource.values()];
}

function isBuilderStaffPermissionResource(
  value: string,
): value is BuilderStaffPermissionResource {
  return (BUILDER_STAFF_PERMISSION_RESOURCES as readonly string[]).includes(
    value,
  );
}

async function getOwnedBuilderProfile(
  ctx: QueryCtx | MutationCtx,
  brokerageId: Id<"brokerages">,
  workosUserId: string,
) {
  const ownedBuilderProfiles = await getOwnedBuilderProfiles(
    ctx,
    brokerageId,
    workosUserId,
  );
  return ownedBuilderProfiles[0] ?? null;
}

async function getOwnedBuilderProfiles(
  ctx: QueryCtx | MutationCtx,
  brokerageId: Id<"brokerages">,
  workosUserId: string,
) {
  const links = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_user", (q) => q.eq("workosUserId", workosUserId))
    .collect();
  const ownedBuilderProfiles: Doc<"builderProfiles">[] = [];
  const seenBuilderProfileIds = new Set<string>();

  for (const link of links) {
    if (link.status !== "active") {
      continue;
    }
    const builderProfile = await ctx.db.get(link.builderProfileId);
    if (
      !builderProfile ||
      builderProfile.brokerageId !== brokerageId ||
      builderProfile.status !== "active"
    ) {
      continue;
    }
    const builderProfileKey = String(builderProfile._id);
    if (seenBuilderProfileIds.has(builderProfileKey)) {
      continue;
    }
    seenBuilderProfileIds.add(builderProfileKey);
    ownedBuilderProfiles.push(builderProfile);
  }

  return ownedBuilderProfiles;
}

async function getActiveOrganizationMembership(
  ctx: QueryCtx | MutationCtx,
  workosUserId: string,
  workosOrganizationId: string,
) {
  const memberships = await ctx.db
    .query("workosOrganizationMemberships")
    .withIndex("by_user", (q) => q.eq("workosUserId", workosUserId))
    .collect();
  return (
    memberships.find(
      (membership) =>
        membership.workosOrganizationId === workosOrganizationId &&
        membership.status === "active",
    ) ?? null
  );
}

async function getWorkosUserById(
  ctx: QueryCtx | MutationCtx,
  workosUserId: string,
) {
  return await ctx.db
    .query("users")
    .withIndex("by_workos_user_id", (q) => q.eq("workosUserId", workosUserId))
    .first();
}

async function getWorkosUserByEmail(
  ctx: QueryCtx | MutationCtx,
  email: string,
) {
  const normalized = email.trim().toLowerCase();
  if (!normalized) {
    return null;
  }
  const users = await ctx.db.query("users").collect();
  return (
    users
      .filter((user) => user.email.trim().toLowerCase() === normalized)
      .sort(workosUserEmailResolutionSort)[0] ?? null
  );
}

async function getWorkosUserForBuilderAccountLink(
  ctx: QueryCtx | MutationCtx,
  link: Doc<"builderAccountLinks">,
) {
  const user = await getWorkosUserById(ctx, link.workosUserId);
  const assignedEmail = normalizeBuilderStaffAssignedEmail(link.assignedEmail);
  if (!assignedEmail) {
    return user;
  }
  const emailUser = await getWorkosUserByEmail(ctx, assignedEmail);
  if (!user) {
    return emailUser;
  }
  if (
    user.status === "deleted" &&
    emailUser &&
    emailUser.workosUserId !== user.workosUserId
  ) {
    return emailUser;
  }
  return user;
}

function workosUserEmailResolutionSort(
  left: Doc<"users">,
  right: Doc<"users">,
) {
  const leftDeleted = left.status === "deleted" ? 1 : 0;
  const rightDeleted = right.status === "deleted" ? 1 : 0;
  return (
    leftDeleted - rightDeleted ||
    (right.updatedAt ?? 0) - (left.updatedAt ?? 0) ||
    (right.createdAt ?? 0) - (left.createdAt ?? 0) ||
    String(right._id).localeCompare(String(left._id))
  );
}

async function getActiveBuilderStaffAccountLinkByEmail(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  email: string,
) {
  const assignedEmail = normalizeBuilderStaffAssignedEmail(email);
  if (!assignedEmail) {
    return null;
  }
  const links = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_builder_assigned_email", (q) =>
      q
        .eq("builderProfileId", builderProfileId)
        .eq("assignedEmail", assignedEmail),
    )
    .collect();
  return (
    links
      .filter(
        (link) =>
          link.status === "active" &&
          link.role === "staff" &&
          link.assignedEmail === assignedEmail,
      )
      .sort(
        (left, right) =>
          left.createdAt - right.createdAt ||
          String(left._id).localeCompare(String(right._id)),
      )[0] ?? null
  );
}

async function getActiveBuilderStaffAccountLinksByEmail(
  ctx: QueryCtx | MutationCtx,
  email: string,
) {
  const assignedEmail = normalizeBuilderStaffAssignedEmail(email);
  if (!assignedEmail) {
    return [];
  }
  const links = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_assigned_email", (q) => q.eq("assignedEmail", assignedEmail))
    .collect();
  return links
    .filter(
      (link) =>
        link.status === "active" &&
        link.role === "staff" &&
        link.assignedEmail === assignedEmail,
    )
    .sort(
      (left, right) =>
        left.createdAt - right.createdAt ||
        String(left._id).localeCompare(String(right._id)),
    );
}

async function getActiveBuilderAccountLinkForStaffViewer(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  auth: {
    email?: string;
    subject: string;
  },
) {
  const direct = await getActiveBuilderAccountLink(
    ctx,
    builderProfileId,
    auth.subject,
  );
  if (direct) {
    return direct;
  }
  const email = await resolveBuilderStaffViewerEmail(ctx, auth);
  return email
    ? await getActiveBuilderStaffAccountLinkByEmail(
        ctx,
        builderProfileId,
        email,
      )
    : null;
}

async function getActiveBuilderAccountLinkByProjectedUserEmail(
  ctx: QueryCtx | MutationCtx,
  input: {
    builderProfileId: Id<"builderProfiles">;
    workosUserId: string;
  },
) {
  const user = await getWorkosUserById(ctx, input.workosUserId);
  const email = normalizeBuilderStaffAssignedEmail(user?.email);
  return email
    ? await getActiveBuilderStaffAccountLinkByEmail(
        ctx,
        input.builderProfileId,
        email,
      )
    : null;
}

async function resolveBuilderStaffViewerEmail(
  ctx: QueryCtx | MutationCtx,
  auth: {
    email?: string;
    subject: string;
  },
) {
  const identityEmail = normalizeBuilderStaffAssignedEmail(auth.email);
  if (identityEmail) {
    return identityEmail;
  }
  const user = await getWorkosUserById(ctx, auth.subject);
  return normalizeBuilderStaffAssignedEmail(user?.email);
}

async function resolveBuilderStaffWorkosUserId(
  ctx: QueryCtx | MutationCtx,
  input: {
    allowPendingEmail?: boolean;
    staffEmail?: string;
    staffWorkosUserId?: string;
  },
) {
  const explicit = input.staffWorkosUserId?.trim();
  const email = input.staffEmail?.trim();
  if (email) {
    const user = await getWorkosUserByEmail(ctx, email);
    if (user?.workosUserId) {
      return user.workosUserId;
    }
  }
  if (explicit) {
    return explicit;
  }
  if (!email) {
    throw new Error("Staff email or WorkOS user ID is required.");
  }
  if (input.allowPendingEmail) {
    return pendingBuilderStaffWorkosUserId(email);
  }
  throw new Error("Use staff provisioning before assigning an unknown email.");
}

function viewerFromBuilderStaffProvisionActor(actor: {
  organizationId?: string;
  roles: string[];
  subject: string;
}): AuthorizedViewer {
  return {
    capability: "authenticated",
    ...(actor.organizationId ? { organizationId: actor.organizationId } : {}),
    roles: normalizeRoleSlugs(actor.roles),
    subject: actor.subject,
    tokenIdentifier: `internal:${actor.subject}`,
  };
}

function builderStaffDisplayName(email: string) {
  return email.split("@")[0] || email;
}

function normalizeBuilderStaffEmail(value: string) {
  const trimmed = value.trim().toLowerCase();
  const at = trimmed.indexOf("@");
  if (at <= 0 || at !== trimmed.lastIndexOf("@") || at === trimmed.length - 1) {
    return "";
  }
  if (!trimmed.slice(at + 1).includes(".")) {
    return "";
  }
  return trimmed;
}

function normalizeBuilderStaffAssignedEmail(value?: string) {
  return value ? normalizeBuilderStaffEmail(value) || undefined : undefined;
}

async function requireBuilderStaffManagementAllowed(
  ctx: QueryCtx | MutationCtx,
  auth: {
    roles: RoleSlug[];
    subject: string;
  },
  builderProfileId: Id<"builderProfiles">,
) {
  if (isBackoffice(auth.roles)) {
    return;
  }
  const link = await getActiveBuilderAccountLink(
    ctx,
    builderProfileId,
    auth.subject,
  );
  if (!link || link.role !== "owner") {
    throw new Error("Forbidden: builder staff management");
  }
  await assertBuilderAccountLinkNotDeleted(ctx, link, builderProfileId);
}

async function buildStaffPermissionDirectory(
  ctx: QueryCtx | MutationCtx,
  input: {
    auth: {
      roles: RoleSlug[];
      subject: string;
    };
    buildId?: Id<"activeBuilds">;
    builderProfileId: Id<"builderProfiles">;
    proposalId: Id<"buildProposals">;
    scope: BuilderStaffPermissionScope;
    workosOrganizationId: string;
  },
) {
  const links = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_builder", (q) =>
      q.eq("builderProfileId", input.builderProfileId),
    )
    .collect();
  const activeLinks = links.filter((link) => link.status === "active");
  const { canonicalLinkIdById, links: canonicalActiveLinks } =
    canonicalBuilderAccountLinks(activeLinks);
  const permissionRows =
    input.scope === "proposal"
      ? await ctx.db
          .query("builderStaffPermissionGrants")
          .withIndex("by_builder", (q) =>
            q.eq("builderProfileId", input.builderProfileId),
          )
          .filter((q) =>
            q.and(
              q.eq(q.field("scope"), "proposal"),
              q.eq(q.field("proposalId"), input.proposalId),
            ),
          )
          .collect()
      : await ctx.db
          .query("builderStaffPermissionGrants")
          .withIndex("by_builder", (q) =>
            q.eq("builderProfileId", input.builderProfileId),
          )
          .filter((q) =>
            q.and(
              q.eq(q.field("scope"), "activeBuild"),
              q.eq(q.field("buildId"), input.buildId),
            ),
          )
          .collect();
  const rowsByLink = new Map<string, Doc<"builderStaffPermissionGrants">[]>();
  for (const row of permissionRows) {
    const key =
      canonicalLinkIdById.get(String(row.builderAccountLinkId)) ??
      String(row.builderAccountLinkId);
    const list = rowsByLink.get(key) ?? [];
    list.push(row);
    rowsByLink.set(key, list);
  }

  const staff = [];
  for (const link of canonicalActiveLinks.sort(
    (a, b) => builderAccountRoleRank(a.role) - builderAccountRoleRank(b.role),
  )) {
    const workosState = await builderAccountLinkWorkosState(ctx, {
      link,
      workosOrganizationId: input.workosOrganizationId,
    });
    if (workosState.hidden) {
      continue;
    }
    const user = workosState.user;
    const role = link.role;
    const assignedEmail = normalizeOptionalString(link.assignedEmail);
    const displayEmail = user?.email ?? assignedEmail;
    staff.push({
      builderAccountLinkId: link._id,
      email: displayEmail,
      identityStatus: workosState.identityStatus,
      mode: role === "owner" ? "full" : "limited",
      name:
        user?.name ??
        (assignedEmail ? builderStaffDisplayName(assignedEmail) : undefined),
      permissions:
        role === "owner"
          ? fullBuilderStaffPermissionGrants()
          : normalizeBuilderStaffPermissionRows(
              rowsByLink.get(String(link._id)) ?? [],
            ),
      role,
      status: link.status,
      workosMembershipId:
        link.workosMembershipId ?? workosState.membership?.workosMembershipId,
      workosUserId: link.workosUserId,
    });
  }

  return {
    canManage: isBackoffice(input.auth.roles)
      ? true
      : Boolean(
          (
            await getActiveBuilderAccountLink(
              ctx,
              input.builderProfileId,
              input.auth.subject,
            )
          )?.role === "owner",
        ),
    resources: BUILDER_STAFF_PERMISSION_RESOURCES,
    actions: BUILDER_STAFF_PERMISSION_ACTIONS,
    scope: input.scope,
    staff,
  };
}

async function saveBuilderStaffPermissionScope(
  ctx: MutationCtx,
  input: {
    allowPendingEmail?: boolean;
    auth: {
      brokerage: Doc<"brokerages">;
      roles: RoleSlug[];
      subject: string;
    };
    buildId?: Id<"activeBuilds">;
    builderProfileId: Id<"builderProfiles">;
    permissions: Array<{
      canCreate: boolean;
      canDelete: boolean;
      canUpdate: boolean;
      canView: boolean;
      resourceType: BuilderStaffPermissionResource;
    }>;
    proposalId: Id<"buildProposals">;
    scope: BuilderStaffPermissionScope;
    staffEmail?: string;
    staffWorkosUserId?: string;
    workosMembershipId?: string;
    workosOrganizationId: string;
  },
) {
  const requestedStaffWorkosUserId = await resolveBuilderStaffWorkosUserId(
    ctx,
    input,
  );
  const assignedEmail = normalizeBuilderStaffAssignedEmail(input.staffEmail);
  const workosMembershipId = normalizeOptionalString(input.workosMembershipId);
  const existingByUser = await getActiveBuilderAccountLink(
    ctx,
    input.builderProfileId,
    requestedStaffWorkosUserId,
  );
  const existingByEmail = assignedEmail
    ? await getActiveBuilderStaffAccountLinkByEmail(
        ctx,
        input.builderProfileId,
        assignedEmail,
      )
    : null;
  if (existingByUser?.role === "owner" || existingByEmail?.role === "owner") {
    throw new Error("Builder owners have full access and cannot be limited.");
  }
  const now = Date.now();
  if (
    existingByEmail &&
    existingByUser &&
    existingByEmail._id !== existingByUser._id
  ) {
    await mergeBuilderStaffAccountLinks(ctx, {
      duplicate: existingByUser,
      now,
      primary: existingByEmail,
      updatedByWorkosUserId: input.auth.subject,
    });
  }
  const existingLink = existingByEmail ?? existingByUser;
  if (existingLink?.role === "owner") {
    throw new Error("Builder owners have full access and cannot be limited.");
  }
  let staffWorkosUserId = requestedStaffWorkosUserId;
  if (existingLink) {
    if (
      isPendingBuilderStaffWorkosUserId(requestedStaffWorkosUserId) ||
      !isPendingBuilderStaffWorkosUserId(existingLink.workosUserId)
    ) {
      staffWorkosUserId = existingLink.workosUserId;
    }
    const linkPatch: Partial<
      Pick<
        Doc<"builderAccountLinks">,
        "assignedEmail" | "updatedAt" | "workosMembershipId" | "workosUserId"
      >
    > = {};
    if (assignedEmail && assignedEmail !== existingLink.assignedEmail) {
      linkPatch.assignedEmail = assignedEmail;
    }
    if (
      workosMembershipId &&
      workosMembershipId !== existingLink.workosMembershipId
    ) {
      linkPatch.workosMembershipId = workosMembershipId;
    }
    if (
      !isPendingBuilderStaffWorkosUserId(requestedStaffWorkosUserId) &&
      requestedStaffWorkosUserId !== existingLink.workosUserId
    ) {
      linkPatch.workosUserId = requestedStaffWorkosUserId;
      staffWorkosUserId = requestedStaffWorkosUserId;
    }
    if (Object.keys(linkPatch).length > 0) {
      await ctx.db.patch(existingLink._id, {
        ...linkPatch,
        updatedAt: now,
      });
      if (linkPatch.workosUserId) {
        await syncBuilderStaffGrantWorkosUserId(ctx, {
          builderAccountLinkId: existingLink._id,
          now,
          updatedByWorkosUserId: input.auth.subject,
          workosUserId: linkPatch.workosUserId,
        });
      }
    }
  }
  const builderAccountLinkId =
    existingLink?._id ??
    (await ensureBuilderAccountLink(ctx, {
      brokerageId: input.auth.brokerage._id,
      builderProfileId: input.builderProfileId,
      now,
      role: "staff",
      assignedEmail,
      workosMembershipId,
      workosUserId: staffWorkosUserId,
    }));
  const normalizedPermissions = normalizeBuilderStaffPermissionInput(
    input.permissions,
  );
  const existingScopeRows = existingLink
    ? await collectScopedBuilderStaffPermissionRows(ctx, {
        buildId: input.buildId,
        builderAccountLinkId,
        proposalId: input.proposalId,
        scope: input.scope,
      })
    : [];
  if (
    existingLink &&
    input.staffEmail &&
    !normalizedPermissions.some(builderStaffGrantHasAnyCapability) &&
    existingScopeRows.some(builderStaffGrantHasAnyCapability)
  ) {
    return staffWorkosUserId;
  }
  for (const permission of normalizedPermissions) {
    const existing =
      input.scope === "proposal"
        ? await ctx.db
            .query("builderStaffPermissionGrants")
            .withIndex("by_proposal_link_resource", (q) =>
              q
                .eq("proposalId", input.proposalId)
                .eq("builderAccountLinkId", builderAccountLinkId)
                .eq("resourceType", permission.resourceType),
            )
            .unique()
        : await ctx.db
            .query("builderStaffPermissionGrants")
            .withIndex("by_build_link_resource", (q) =>
              q
                .eq("buildId", input.buildId)
                .eq("builderAccountLinkId", builderAccountLinkId)
                .eq("resourceType", permission.resourceType),
            )
            .unique();
    const patch = {
      canCreate: permission.canCreate,
      canDelete: permission.canDelete,
      canUpdate: permission.canUpdate,
      canView: permission.canView,
      updatedAt: now,
      updatedByWorkosUserId: input.auth.subject,
    };
    if (existing) {
      await ctx.db.patch(existing._id, patch);
      continue;
    }
    await ctx.db.insert("builderStaffPermissionGrants", {
      ...patch,
      brokerageId: input.auth.brokerage._id,
      buildId: input.buildId,
      builderAccountLinkId,
      builderProfileId: input.builderProfileId,
      createdAt: now,
      createdByWorkosUserId: input.auth.subject,
      organizationId: input.workosOrganizationId,
      proposalId: input.proposalId,
      resourceType: permission.resourceType,
      scope: input.scope,
      workosUserId: staffWorkosUserId,
    });
  }
  return staffWorkosUserId;
}

async function mergeBuilderStaffAccountLinks(
  ctx: MutationCtx,
  input: {
    duplicate: Doc<"builderAccountLinks">;
    now: number;
    primary: Doc<"builderAccountLinks">;
    updatedByWorkosUserId: string;
  },
) {
  const duplicateGrants = await ctx.db
    .query("builderStaffPermissionGrants")
    .withIndex("by_link", (q) =>
      q.eq("builderAccountLinkId", input.duplicate._id),
    )
    .collect();
  for (const duplicateGrant of duplicateGrants) {
    const primaryGrant =
      duplicateGrant.scope === "proposal"
        ? await ctx.db
            .query("builderStaffPermissionGrants")
            .withIndex("by_proposal_link_resource", (q) =>
              q
                .eq("proposalId", duplicateGrant.proposalId)
                .eq("builderAccountLinkId", input.primary._id)
                .eq("resourceType", duplicateGrant.resourceType),
            )
            .unique()
        : await ctx.db
            .query("builderStaffPermissionGrants")
            .withIndex("by_build_link_resource", (q) =>
              q
                .eq("buildId", duplicateGrant.buildId)
                .eq("builderAccountLinkId", input.primary._id)
                .eq("resourceType", duplicateGrant.resourceType),
            )
            .unique();
    if (primaryGrant) {
      await ctx.db.patch(primaryGrant._id, {
        canCreate: primaryGrant.canCreate || duplicateGrant.canCreate,
        canDelete: primaryGrant.canDelete || duplicateGrant.canDelete,
        canUpdate: primaryGrant.canUpdate || duplicateGrant.canUpdate,
        canView: primaryGrant.canView || duplicateGrant.canView,
        updatedAt: input.now,
        updatedByWorkosUserId: input.updatedByWorkosUserId,
      });
      await ctx.db.delete(duplicateGrant._id);
      continue;
    }
    await ctx.db.patch(duplicateGrant._id, {
      builderAccountLinkId: input.primary._id,
      updatedAt: input.now,
      updatedByWorkosUserId: input.updatedByWorkosUserId,
      workosUserId: input.primary.workosUserId,
    });
  }
  await ctx.db.patch(input.duplicate._id, {
    status: "inactive",
    updatedAt: input.now,
  });
}

async function syncBuilderStaffGrantWorkosUserId(
  ctx: MutationCtx,
  input: {
    builderAccountLinkId: Id<"builderAccountLinks">;
    now: number;
    updatedByWorkosUserId: string;
    workosUserId: string;
  },
) {
  const grants = await ctx.db
    .query("builderStaffPermissionGrants")
    .withIndex("by_link", (q) =>
      q.eq("builderAccountLinkId", input.builderAccountLinkId),
    )
    .collect();
  for (const grant of grants) {
    if (grant.workosUserId === input.workosUserId) {
      continue;
    }
    await ctx.db.patch(grant._id, {
      updatedAt: input.now,
      updatedByWorkosUserId: input.updatedByWorkosUserId,
      workosUserId: input.workosUserId,
    });
  }
}

async function collectScopedBuilderStaffPermissionRows(
  ctx: QueryCtx | MutationCtx,
  input: {
    buildId?: Id<"activeBuilds">;
    builderAccountLinkId: Id<"builderAccountLinks">;
    proposalId: Id<"buildProposals">;
    scope: BuilderStaffPermissionScope;
  },
) {
  const rows = await ctx.db
    .query("builderStaffPermissionGrants")
    .withIndex("by_link", (q) =>
      q.eq("builderAccountLinkId", input.builderAccountLinkId),
    )
    .collect();
  return rows.filter((row) =>
    input.scope === "proposal"
      ? row.scope === "proposal" && row.proposalId === input.proposalId
      : row.scope === "activeBuild" && row.buildId === input.buildId,
  );
}

async function removeBuilderStaffMember(
  ctx: MutationCtx,
  input: {
    auth: {
      subject: string;
    };
    builderProfileId: Id<"builderProfiles">;
    staffWorkosUserId: string;
  },
) {
  if (input.auth.subject === input.staffWorkosUserId) {
    throw new Error("You cannot remove your own builder account.");
  }
  const directLink = await getActiveBuilderAccountLink(
    ctx,
    input.builderProfileId,
    input.staffWorkosUserId,
  );
  const link =
    directLink ??
    (await getActiveBuilderAccountLinkByProjectedUserEmail(ctx, {
      builderProfileId: input.builderProfileId,
      workosUserId: input.staffWorkosUserId,
    }));
  if (!link) {
    return;
  }
  if (link.role === "owner") {
    throw new Error("Builder owner accounts cannot be removed here.");
  }
  const now = Date.now();
  await ctx.db.patch(link._id, {
    status: "inactive",
    updatedAt: now,
  });
  const grants = await ctx.db
    .query("builderStaffPermissionGrants")
    .withIndex("by_link", (q) => q.eq("builderAccountLinkId", link._id))
    .collect();
  for (const grant of grants) {
    await ctx.db.delete(grant._id);
  }
}

function normalizeBuilderStaffPermissionInput(
  permissions: Array<{
    canCreate: boolean;
    canDelete: boolean;
    canUpdate: boolean;
    canView: boolean;
    resourceType: BuilderStaffPermissionResource;
  }>,
) {
  const byResource = new Map(
    permissions
      .filter((permission) =>
        isBuilderStaffPermissionResource(permission.resourceType),
      )
      .map((permission) => [permission.resourceType, permission]),
  );
  return BUILDER_STAFF_PERMISSION_RESOURCES.map((resourceType) => {
    const permission = byResource.get(resourceType);
    return {
      canCreate: permission?.canCreate ?? false,
      canDelete: permission?.canDelete ?? false,
      canUpdate: permission?.canUpdate ?? false,
      canView: permission?.canView ?? false,
      resourceType,
    };
  });
}

function builderAccountRoleRank(role: "owner" | "staff") {
  return role === "owner" ? 0 : 1;
}

function canonicalBuilderAccountLinks(
  links: Array<Doc<"builderAccountLinks">>,
) {
  const sorted = [...links].sort(
    (left, right) =>
      builderAccountRoleRank(left.role) - builderAccountRoleRank(right.role) ||
      left.createdAt - right.createdAt ||
      String(left._id).localeCompare(String(right._id)),
  );
  const canonicalByKey = new Map<string, Doc<"builderAccountLinks">>();
  const canonicalLinkIdById = new Map<string, string>();
  for (const link of sorted) {
    const key = builderAccountCanonicalKey(link);
    const canonical = canonicalByKey.get(key) ?? link;
    canonicalByKey.set(key, canonical);
    canonicalLinkIdById.set(String(link._id), String(canonical._id));
  }
  return {
    canonicalLinkIdById,
    links: [...canonicalByKey.values()],
  };
}

function builderAccountCanonicalKey(link: Doc<"builderAccountLinks">) {
  if (link.role === "staff") {
    const assignedEmail = normalizeBuilderStaffAssignedEmail(
      link.assignedEmail,
    );
    if (assignedEmail) {
      return `staff-email:${assignedEmail}`;
    }
  }
  return `${link.role}:user:${link.workosUserId}`;
}

async function getProposalClaimLinkByToken(
  ctx: QueryCtx | MutationCtx,
  claimToken: string,
) {
  const trimmed = claimToken.trim();
  if (!trimmed) {
    return null;
  }
  const hashedToken = await shareTokenHash(trimmed);
  return await ctx.db
    .query("proposalClaimLinks")
    .withIndex("by_share_token_hash", (q) =>
      q.eq("shareTokenHash", hashedToken),
    )
    .unique();
}

function canClaimDraftProposal(roles: readonly RoleSlug[]) {
  return (
    roles.length === 0 ||
    roles.includes("member") ||
    roles.includes("admin") ||
    roles.some((role) => (BUILDER_ROLES as readonly RoleSlug[]).includes(role))
  );
}

function claimRoles(roles: readonly unknown[]) {
  const normalized = normalizeRoleSlugs(roles);
  return normalized.length > 0 ? normalized : (["member"] satisfies RoleSlug[]);
}

async function getOrCreateClaimantBuilderProfile(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      roles: RoleSlug[];
      subject: string;
    };
    claimantEmail?: string;
    now: number;
    proposal: Doc<"buildProposals">;
    workosOrganizationId: string;
  },
) {
  let builderProfile = await getOwnedBuilderProfile(
    ctx,
    input.auth.brokerage._id,
    input.auth.subject,
  );

  if (!builderProfile) {
    const user = await getWorkosUserById(ctx, input.auth.subject);
    const displayName = claimBuilderDisplayName(
      user,
      input.proposal,
      input.claimantEmail,
    );
    const builderProfileId = await ctx.db.insert("builderProfiles", {
      brokerageId: input.auth.brokerage._id,
      createdAt: input.now,
      displayName,
      legalName: displayName,
      organizationId: input.workosOrganizationId,
      status: "active",
      updatedAt: input.now,
    });
    await ctx.db.insert("builderAccountLinks", {
      brokerageId: input.auth.brokerage._id,
      builderProfileId,
      createdAt: input.now,
      role: "owner",
      status: "active",
      updatedAt: input.now,
      workosUserId: input.auth.subject,
    });
    const createdBuilderProfile = await ctx.db.get(builderProfileId);
    if (!createdBuilderProfile) {
      throw new Error("Builder profile creation failed.");
    }
    builderProfile = createdBuilderProfile;
  }

  const { workosUserId: assignedBrokerWorkosUserId } =
    await requireDefaultBrokerMember(ctx, input.auth.brokerage);
  await ensureBuilderBrokerAssignment(ctx, {
    actorRoles: input.auth.roles,
    actorWorkosUserId: input.auth.subject,
    assignedBrokerWorkosUserId,
    brokerage: input.auth.brokerage,
    builderProfile,
    command: "claimDraftProposalLink",
    now: input.now,
    reason:
      "Assigning the brokerage principal broker while linking a claimed proposal to its builder.",
  });

  return builderProfile;
}

function claimBuilderDisplayName(
  user: Doc<"users"> | null,
  proposal: Doc<"buildProposals">,
  fallbackEmail?: string,
) {
  const name = user?.name?.trim();
  if (name && name !== user?.email) {
    return name;
  }
  const email = user?.email?.trim();
  if (email) {
    return email.split("@")[0] || email;
  }
  const claimEmail = fallbackEmail?.trim();
  if (claimEmail) {
    return claimEmail.split("@")[0] || claimEmail;
  }
  return `${proposal.buildName} builder`;
}

async function builderAccountSummaries(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
) {
  const workosOrganizationId =
    await builderProfileBrokerageWorkosOrganizationId(ctx, builderProfileId);
  const links = await ctx.db
    .query("builderAccountLinks")
    .withIndex("by_builder", (q) => q.eq("builderProfileId", builderProfileId))
    .collect();
  const activeLinks = links.filter((link) => link.status === "active");
  const summaries = [];
  for (const link of activeLinks) {
    const workosState = await builderAccountLinkWorkosState(ctx, {
      link,
      workosOrganizationId,
    });
    if (workosState.hidden) {
      continue;
    }
    const user = workosState.user;
    const assignedEmail = normalizeOptionalString(link.assignedEmail);
    const displayEmail = user?.email ?? assignedEmail;
    summaries.push({
      ...(displayEmail ? { email: displayEmail } : {}),
      emailVerified: user?.emailVerified === true,
      ...(user?.name
        ? { name: user.name }
        : assignedEmail
          ? { name: builderStaffDisplayName(assignedEmail) }
          : {}),
      role: link.role,
      workosUserId: link.workosUserId,
    });
  }
  return summaries;
}

async function drawReviewBuilderContact(
  ctx: QueryCtx | MutationCtx,
  builderProfileId: Id<"builderProfiles">,
  displayName: string,
) {
  const accounts = await builderAccountSummaries(ctx, builderProfileId);
  const contact = accounts
    .slice()
    .sort(
      (left, right) =>
        builderAccountRoleRank(left.role) -
        builderAccountRoleRank(right.role),
    )[0];
  return {
    ...(contact?.name ? { contactName: contact.name } : {}),
    displayName,
    ...(contact?.email ? { email: contact.email } : {}),
    ...(contact?.role
      ? {
          role:
            contact.role === "owner" ? "Builder owner" : "Builder staff",
        }
      : {}),
  };
}

function preferredBuilderAccountEmail(
  accounts: readonly {
    email?: string;
    emailVerified: boolean;
    role: string;
  }[],
) {
  return (
    accounts.find(
      (account) => account.role === "owner" && account.emailVerified,
    )?.email ??
    accounts.find((account) => account.emailVerified)?.email ??
    accounts.find((account) => account.role === "owner")?.email ??
    accounts[0]?.email
  );
}

function workosUserSummary(
  workosUserId: string | undefined,
  user: Doc<"users"> | null,
) {
  if (!workosUserId) {
    return null;
  }
  return {
    ...(user?.email ? { email: user.email } : {}),
    ...(user?.name ? { name: user.name } : {}),
    workosUserId,
  };
}

async function buildProposalIdentityProjection(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
  brokerage: Doc<"brokerages">,
) {
  const builderProfile = proposal.builderProfileId
    ? await ctx.db.get(proposal.builderProfileId)
    : null;
  const builderAccounts = builderProfile
    ? await builderAccountSummaries(ctx, builderProfile._id)
    : [];
  const assignedBrokerUser = proposal.assignedBrokerWorkosUserId
    ? await getWorkosUserById(ctx, proposal.assignedBrokerWorkosUserId)
    : null;
  const createdByUser = await getWorkosUserById(
    ctx,
    proposal.createdByWorkosUserId,
  );
  const activeClaimLink = await ctx.db
    .query("proposalClaimLinks")
    .withIndex("by_proposal_status", (q) =>
      q.eq("proposalId", proposal._id).eq("status", "active"),
    )
    .first();
  const claimLinkActive = Boolean(
    activeClaimLink &&
    (!activeClaimLink.expiresAt || activeClaimLink.expiresAt >= Date.now()),
  );
  const builderOwnerEmail = preferredBuilderAccountEmail(builderAccounts);

  return {
    broker: workosUserSummary(
      proposal.assignedBrokerWorkosUserId,
      assignedBrokerUser,
    ),
    brokerage: {
      _id: brokerage._id,
      displayName: brokerage.displayName,
      legalName: brokerage.legalName,
      workosOrganizationId: brokerage.workosOrganizationId,
    },
    builder: builderProfile
      ? {
          _id: builderProfile._id,
          accounts: builderAccounts,
          displayName: builderProfile.displayName,
          ...(builderProfile.legalName
            ? { legalName: builderProfile.legalName }
            : {}),
          ...(builderOwnerEmail ? { ownerEmail: builderOwnerEmail } : {}),
          status: builderProfile.status,
        }
      : null,
    builderAssigned: Boolean(builderProfile),
    claimLinkActive,
    createdBy: workosUserSummary(proposal.createdByWorkosUserId, createdByUser),
    initiatedFromBackoffice:
      !proposal.builderProfileId &&
      Boolean(proposal.assignedBrokerWorkosUserId),
  };
}

function isBackoffice(roles: readonly RoleSlug[]) {
  return roles.some((role) =>
    (BACKOFFICE_ROLES as readonly RoleSlug[]).includes(role),
  );
}

function hasBuilderExecutionRole(roles: readonly RoleSlug[]) {
  return roles.some(
    (role) =>
      role === "builder" ||
      role === "builder-staff" ||
      role === "contractor",
  );
}

/** Lender review roles without Admin or Builder execution capability. */
function isLenderOnlyForBuilderExecution(roles: readonly RoleSlug[]) {
  if (roles.includes("admin")) {
    return false;
  }
  return isBackoffice(roles) && !hasBuilderExecutionRole(roles);
}

/** Parent Milestone start (no child): Admin or Builder-side, not review-only lenders. */
function canOriginateParentMilestoneStart(roles: readonly RoleSlug[]) {
  if (roles.includes("admin")) {
    return true;
  }
  if (hasBuilderExecutionRole(roles)) {
    return true;
  }
  return !isBackoffice(roles);
}

type CanonicalSubmilestoneCommandInput = {
  buildId: Id<"activeBuilds">;
  milestoneKey: string;
  submilestoneKey: string;
  workosOrganizationId: string;
};

type CanonicalSubmilestoneAuth = Awaited<
  ReturnType<typeof authorizeActiveBuildOrThrow>
>;

async function authorizeCanonicalSubmilestoneOperator(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  input: CanonicalSubmilestoneCommandInput,
): Promise<CanonicalSubmilestoneAuth> {
  const auth = await authorizeActiveBuildForStart(
    ctx,
    input.buildId,
    input.workosOrganizationId,
  );
  const { milestone, submilestone } = await activeBuildStartTarget(ctx, {
    buildId: input.buildId,
    milestoneKey: input.milestoneKey,
    submilestoneKey: input.submilestoneKey,
  });
  const ownership = await resolveCanonicalMilestoneExecutionOwnership(ctx, {
    build: auth.build,
    milestone,
    submilestone,
  });
  const operate = await resolveSubmilestoneOperateAuthority(ctx, {
    build: auth.build,
    intent: "update",
    milestoneCompleted:
      milestone.status === "complete" ||
      milestone.completionClaim !== undefined,
    ownership,
    submilestone,
    viewer: {
      roles: auth.roles,
      workosUserId: auth.subject,
    },
  });
  if (!operate.allowed) {
    throw new ConvexError({
      code:
        operate.denial === "assignment_required"
          ? "ASSIGNMENT_REQUIRED"
          : operate.denial === "lender_review_only"
            ? "LENDER_EXECUTION_FORBIDDEN"
            : "OPERATE_FORBIDDEN",
      message: operateDenialMessage(operate.denial),
    });
  }
  if (
    !(
      auth.roles.includes("admin") ||
      auth.roles.includes("contractor")
    )
  ) {
    await requireActiveBuildAppPermission(ctx, auth, "submilestone", "update");
  }
  return auth;
}

function assertProgressPercent(value: number) {
  if (!Number.isFinite(value) || value < 0 || value > 100) {
    throw new ConvexError({
      code: "INVALID_PROGRESS_PERCENT",
      message: "Progress must be between 0 and 100 percent.",
    });
  }
}

function assertExpectedSubmilestoneRevision(
  submilestone: Doc<"buildSubmilestones">,
  expectedRevision: number,
) {
  if (expectedRevision !== (submilestone.workflowRevision ?? 0)) {
    throw new ConvexError({
      code: "STALE_SUBMILESTONE_REVISION",
      message: "Sub-milestone changed; refresh before retrying the command.",
      actualRevision: submilestone.workflowRevision ?? 0,
      expectedRevision,
    });
  }
}

function assertExpectedMilestoneRevision(
  milestone: Doc<"buildMilestones">,
  expectedRevision: number,
) {
  if (expectedRevision !== (milestone.workflowRevision ?? 0)) {
    throw new ConvexError({
      code: "STALE_MILESTONE_REVISION",
      message: "Milestone changed; refresh before retrying the command.",
      actualRevision: milestone.workflowRevision ?? 0,
      expectedRevision,
    });
  }
}

function requireScopedAssignmentCommandInput(input: {
  expectedRevision?: number;
  expectedRevisions?: Record<string, number>;
  idempotencyKey?: string;
}) {
  if (
    (input.expectedRevision === undefined &&
      input.expectedRevisions === undefined) ||
    (input.expectedRevision !== undefined &&
      (!Number.isSafeInteger(input.expectedRevision) ||
        input.expectedRevision < 0))
  ) {
    throw new ConvexError({
      code: "EXPECTED_REVISION_REQUIRED",
      message:
        "Sub-milestone-scoped assignment commands require the current canonical workflow revision.",
    });
  }
  if (input.expectedRevisions !== undefined) {
    for (const revision of Object.values(input.expectedRevisions)) {
      if (!Number.isSafeInteger(revision) || revision < 0) {
        throw new ConvexError({
          code: "EXPECTED_REVISION_REQUIRED",
          message:
            "Sub-milestone-scoped assignment commands require safe canonical workflow revisions.",
        });
      }
    }
  }
  const idempotencyKey = input.idempotencyKey?.trim();
  if (!idempotencyKey) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REQUIRED",
      message:
        "Sub-milestone-scoped assignment commands require an idempotency key.",
    });
  }
  return idempotencyKey;
}

function canonicalAssignmentExpectedRevisions(
  expectedRevisions: Record<string, number> | undefined,
  targetKeys: readonly string[],
) {
  if (expectedRevisions === undefined) {
    return undefined;
  }
  const normalized = Object.entries(expectedRevisions).map(
    ([key, revision]) => [key.trim(), revision] as const,
  );
  const normalizedKeys = normalized.map(([key]) => key);
  if (
    normalized.some(([key]) => key.length === 0) ||
    new Set(normalizedKeys).size !== normalizedKeys.length
  ) {
    throw new ConvexError({
      code: "EXPECTED_REVISION_MAP_REQUIRED",
      message:
        "Each scoped assignment target must have one canonical workflow revision.",
    });
  }
  const expectedKeys = canonicalStringKeyList(targetKeys);
  const actualKeys = canonicalStringKeyList(normalizedKeys);
  const missingKeys = expectedKeys.filter((key) => !actualKeys.includes(key));
  const unknownKeys = actualKeys.filter((key) => !expectedKeys.includes(key));
  if (missingKeys.length > 0 || unknownKeys.length > 0) {
    throw new ConvexError({
      code: "EXPECTED_REVISION_MAP_REQUIRED",
      message:
        "Provide an expected workflow revision for every scoped assignment target.",
      missingSubmilestoneKeys: missingKeys,
      unknownSubmilestoneKeys: unknownKeys,
    });
  }
  return Object.fromEntries(
    normalized
      .sort(([left], [right]) => compareCanonicalStringKeys(left, right))
      .map(([key, revision]) => [key, revision]),
  ) as Record<string, number>;
}

function expectedAssignmentRevisionForTarget(input: {
  expectedRevision?: number;
  expectedRevisions?: Record<string, number>;
  submilestoneKey: string;
  targetKeys: readonly string[];
}) {
  const expectedRevisions = canonicalAssignmentExpectedRevisions(
    input.expectedRevisions,
    input.targetKeys,
  );
  const revision =
    expectedRevisions?.[input.submilestoneKey] ?? input.expectedRevision;
  if (
    revision === undefined ||
    !Number.isSafeInteger(revision) ||
    revision < 0
  ) {
    throw new ConvexError({
      code: "EXPECTED_REVISION_REQUIRED",
      message:
        "Sub-milestone-scoped assignment commands require the current canonical workflow revision.",
      submilestoneKey: input.submilestoneKey,
    });
  }
  return revision;
}

function requireScopedMaterialCommandInput(input: {
  expectedRevision?: number;
  idempotencyKey?: string;
}) {
  if (
    input.expectedRevision === undefined ||
    !Number.isSafeInteger(input.expectedRevision) ||
    input.expectedRevision < 0
  ) {
    throw new ConvexError({
      code: "EXPECTED_REVISION_REQUIRED",
      message:
        "Sub-milestone-scoped material commands require the current canonical workflow revision.",
    });
  }
  const idempotencyKey = input.idempotencyKey?.trim();
  if (!idempotencyKey) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REQUIRED",
      message:
        "Sub-milestone-scoped material commands require an idempotency key.",
    });
  }
  return idempotencyKey;
}

function compareCanonicalStringKeys(left: string, right: string) {
  return left === right ? 0 : left < right ? -1 : 1;
}

function canonicalStringKeyList(keys: readonly string[]) {
  return [...new Set(
    keys
      .map((key) => key.trim())
      .filter((key) => key.length > 0),
  )].sort(compareCanonicalStringKeys);
}

function canonicalOptionalSubmilestoneKey(value: string | undefined) {
  if (value === undefined) {
    return undefined;
  }
  const normalized = value.trim();
  if (!normalized) {
    throw new ConvexError({
      code: "SUBMILESTONE_NOT_FOUND",
      message: "A non-empty Sub-milestone key is required for a scoped command.",
    });
  }
  return normalized;
}

function materialScopedMutationReplay(
  existing: Doc<"buildSubmilestoneCommandReceipts">,
) {
  let parsed: unknown;
  try {
    parsed = JSON.parse(existing.resultJson);
  } catch {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message: "The stored material command receipt is invalid.",
    });
  }
  if (!parsed || typeof parsed !== "object") {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message: "The stored material command receipt is invalid.",
    });
  }
  const result = parsed as {
    itemId?: unknown;
    revision?: unknown;
  };
  if (
    typeof result.itemId !== "string" ||
    !Number.isSafeInteger(result.revision) ||
    (result.revision as number) < 0
  ) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message: "The stored material command receipt has an invalid result.",
    });
  }
  return {
    itemId: result.itemId as Id<"buildCostItems">,
    replayed: true,
    revision: result.revision as number,
  };
}

async function replayScopedAssignmentCommand(
  ctx: MutationCtx,
  input: {
    command: string;
    fingerprint: string;
    idempotencyKey: string;
    submilestoneIds: Id<"buildSubmilestones">[];
  },
) {
  const receipts = await Promise.all(
    input.submilestoneIds.map((submilestoneId) =>
      findSubmilestoneIdempotentAudit(ctx, {
        command: input.command,
        fingerprint: input.fingerprint,
        idempotencyKey: input.idempotencyKey,
        submilestoneId,
      }),
    ),
  );
  const existing = receipts.filter(
    (receipt): receipt is NonNullable<typeof receipt> => receipt !== null,
  );
  if (existing.length === 0) return null;
  if (existing.length !== receipts.length) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message:
        "This idempotency key has an incomplete Sub-milestone assignment receipt; refresh before retrying.",
    });
  }
  const result = JSON.parse(existing[0]!.resultJson) as {
    assignmentIds?: unknown;
  };
  if (
    !Array.isArray(result.assignmentIds) ||
    result.assignmentIds.some((assignmentId) => typeof assignmentId !== "string")
  ) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message: "The stored assignment receipt has an invalid result.",
    });
  }
  return result.assignmentIds as Id<"milestoneContractorAssignments">[];
}

function normalizeEvidenceRequirementInputs(
  requirements: Array<{
    description?: string;
    kind: "photo" | "document" | "site_visit" | "any";
    label: string;
    locationRequired?: boolean;
    required: boolean;
    requirementKey: string;
  }>,
) {
  if (requirements.length === 0) {
    throw new ConvexError({
      code: "EVIDENCE_REQUIREMENT_EMPTY",
      message: "At least one Evidence requirement is required.",
    });
  }
  const seen = new Set<string>();
  return requirements.map((requirement) => {
    const requirementKey = requirement.requirementKey.trim();
    const label = requirement.label.trim();
    if (!requirementKey || !label) {
      throw new ConvexError({
        code: "EVIDENCE_REQUIREMENT_INVALID",
        message: "Evidence requirements need a non-empty key and label.",
      });
    }
    if (seen.has(requirementKey)) {
      throw new ConvexError({
        code: "EVIDENCE_REQUIREMENT_DUPLICATE",
        message: `Evidence requirement key ${requirementKey} is duplicated.`,
        requirementKey,
      });
    }
    seen.add(requirementKey);
    return {
      ...(requirement.description?.trim()
        ? { description: requirement.description.trim() }
        : {}),
      kind: requirement.kind,
      label,
      locationRequired: requirement.locationRequired === true,
      required: requirement.required,
      requirementKey,
    };
  });
}

function canonicalCommandPayload(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => canonicalCommandPayload(item));
  }
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(record)
        .sort()
        .map((key) => [key, canonicalCommandPayload(record[key])]),
    );
  }
  return value;
}

async function canonicalCommandFingerprint(command: string, payload: unknown) {
  const commandPayload =
    payload && typeof payload === "object" && !Array.isArray(payload)
      ? Object.fromEntries(
          Object.entries(payload as Record<string, unknown>).filter(
            ([key]) =>
              key !== "expectedRevision" && key !== "expectedRevisions",
          ),
        )
      : payload;
  return await sha256Hex(
    JSON.stringify({
      command,
      payload: canonicalCommandPayload(commandPayload),
    }),
  );
}

function assertSubmilestoneReceiptIdentity(
  existing: Doc<"buildSubmilestoneCommandReceipts">,
  input: { command: string; fingerprint: string },
) {
  if (
    existing.command !== input.command ||
    existing.fingerprint === undefined ||
    existing.fingerprint !== input.fingerprint
  ) {
    throw new ConvexError({
      code: "IDEMPOTENCY_KEY_REUSED",
      message:
        "This idempotency key already belongs to a different canonical command or payload.",
      command: input.command,
    });
  }
}

async function findSubmilestoneIdempotentAudit(
  ctx: MutationCtx,
  input: {
    command: string;
    fingerprint: string;
    idempotencyKey: string;
    submilestoneId: Id<"buildSubmilestones">;
  },
) {
  const existing = await ctx.db
    .query("buildSubmilestoneCommandReceipts")
    .withIndex("by_submilestone_idempotency", (query) =>
      query
        .eq("buildSubmilestoneId", input.submilestoneId)
        .eq("idempotencyKey", input.idempotencyKey),
    )
    .first();
  if (existing) {
    assertSubmilestoneReceiptIdentity(existing, input);
  }
  return existing;
}

async function insertSubmilestoneCommandReceipt(
  ctx: MutationCtx,
  input: {
    buildId: Id<"activeBuilds">;
    command: string;
    fingerprint: string;
    idempotencyKey: string;
    organizationId: string;
    result: Record<string, unknown>;
    submilestoneId: Id<"buildSubmilestones">;
  },
) {
  const existing = await findSubmilestoneIdempotentAudit(ctx, {
    command: input.command,
    fingerprint: input.fingerprint,
    idempotencyKey: input.idempotencyKey,
    submilestoneId: input.submilestoneId,
  });
  if (existing) {
    assertSubmilestoneReceiptIdentity(existing, input);
    return existing._id;
  }
  return await ctx.db.insert("buildSubmilestoneCommandReceipts", {
    buildId: input.buildId,
    command: input.command,
    createdAt: Date.now(),
    fingerprint: input.fingerprint,
    idempotencyKey: input.idempotencyKey,
    organizationId: input.organizationId,
    resultJson: JSON.stringify(input.result),
    buildSubmilestoneId: input.submilestoneId,
  });
}

async function ensureDraftSubmilestoneEvidencePackage(
  ctx: MutationCtx,
  input: {
    auth: CanonicalSubmilestoneAuth;
    milestone: Doc<"buildMilestones">;
    submilestone: Doc<"buildSubmilestones">;
  },
) {
  return await ensureActiveSubmilestoneEvidencePackageDraft(ctx, {
    actorRoles: input.auth.roles,
    actorWorkosUserId: input.auth.subject,
    build: input.auth.build,
    milestone: input.milestone,
    submilestone: input.submilestone,
  });
}
async function getScopedSubmilestonePackageRevision(
  ctx: MutationCtx,
  input: {
    auth: CanonicalSubmilestoneAuth;
    milestone: Doc<"buildMilestones">;
    packageRevisionId: Id<"buildSubmilestoneEvidencePackageRevisions">;
    submilestone: Doc<"buildSubmilestones">;
  },
) {
  const packageRevision = await ctx.db.get(input.packageRevisionId);
  if (
    !packageRevision ||
    packageRevision.buildId !== input.auth.build._id ||
    packageRevision.organizationId !== input.auth.build.organizationId ||
    packageRevision.brokerageId !== input.auth.brokerage._id ||
    packageRevision.proposalId !== input.auth.proposal._id ||
    packageRevision.buildMilestoneId !== input.milestone._id ||
    packageRevision.buildSubmilestoneId !== input.submilestone._id
  ) {
    throw new ConvexError({
      code: "EVIDENCE_PACKAGE_NOT_FOUND",
      message: "Evidence Package revision is unavailable for this Sub-milestone.",
    });
  }
  return packageRevision;
}

function resolveBorrowerStartingCashCents(record: {
  borrowerStartingCashCents?: number;
  borrowerWorkingCapitalLimitCents?: number;
  timelineStartingCashCents?: number;
}) {
  return Math.max(
    0,
    Math.round(
      record.borrowerStartingCashCents ??
        record.timelineStartingCashCents ??
        record.borrowerWorkingCapitalLimitCents ??
        0,
    ),
  );
}

function withBorrowerStartingCash<
  T extends {
    borrowerStartingCashCents?: number;
    borrowerWorkingCapitalLimitCents?: number;
    timelineStartingCashCents?: number;
  },
>(record: T): T & { borrowerStartingCashCents: number } {
  return {
    ...record,
    borrowerStartingCashCents: resolveBorrowerStartingCashCents(record),
  };
}

type ProposalDirectoryCard = {
  activeBuildId?: string;
  approvedAt?: number;
  assignedBrokerEmail?: string;
  assignedBrokerName?: string;
  assignedBrokerWorkosUserId?: string;
  borrowerCoPayBps: number;
  borrowerCoPayCents?: number;
  borrowerStartingCashCents: number;
  builderAssigned: boolean;
  builderEmail?: string;
  builderLegalName?: string;
  builderName: string;
  builderProfileId?: string;
  closedAt?: number;
  column: Doc<"buildProposals">["status"];
  createdAt: number;
  createdByEmail?: string;
  createdByName?: string;
  createdByWorkosUserId: string;
  href: string;
  interestAnnualBps?: number;
  lenderDrawPolicyLimitCents: number;
  location: string;
  locationLatitude?: number;
  locationLongitude?: number;
  locationPlaceId?: string;
  planKey?: "capitalConstrained" | "cheapestFeasible" | "fastest";
  planName?: string;
  proposedStartDate?: string;
  proposalId: string;
  reviewOutcome: Doc<"buildProposals">["reviewOutcome"];
  statusLabel: string;
  submittedAt?: number;
  subtitle: string;
  title: string;
  totalBudgetCents: number;
  updatedAt: number;
  updatedByWorkosUserId: string;
};

async function productionProposalDirectoryCard(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
): Promise<ProposalDirectoryCard> {
  const { card } = await productionProposalDirectoryMatchContext(ctx, proposal);
  return card;
}

async function productionProposalDirectoryMatchContext(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
) {
  const assignment = await proposalDirectoryIdentityProjection(ctx, proposal);
  const attachedAccountEmails = uniqueNormalizedSearchValues(
    (assignment.builder?.accounts ?? []).map((account) => account.email),
  );
  const attachedAccountNames = uniqueNormalizedSearchValues(
    (assignment.builder?.accounts ?? []).map((account) => account.name),
  );
  const card: ProposalDirectoryCard = {
    ...(proposal.activeBuildId
      ? { activeBuildId: String(proposal.activeBuildId) }
      : {}),
    ...(proposal.approvedAt === undefined
      ? {}
      : { approvedAt: proposal.approvedAt }),
    ...(assignment.broker?.email
      ? { assignedBrokerEmail: assignment.broker.email }
      : {}),
    ...(assignment.broker?.name
      ? { assignedBrokerName: assignment.broker.name }
      : {}),
    ...(proposal.assignedBrokerWorkosUserId
      ? {
          assignedBrokerWorkosUserId: proposal.assignedBrokerWorkosUserId,
        }
      : {}),
    borrowerCoPayBps: proposal.borrowerCoPayBps,
    ...(proposal.borrowerCoPayCents === undefined
      ? {}
      : { borrowerCoPayCents: proposal.borrowerCoPayCents }),
    borrowerStartingCashCents: resolveBorrowerStartingCashCents(proposal),
    builderAssigned: Boolean(assignment.builder),
    ...(assignment.builder?.ownerEmail
      ? { builderEmail: assignment.builder.ownerEmail }
      : {}),
    ...(assignment.builder?.legalName
      ? { builderLegalName: assignment.builder.legalName }
      : {}),
    builderName: assignment.builder?.displayName ?? "Unassigned builder",
    ...(assignment.builder?._id
      ? { builderProfileId: String(assignment.builder._id) }
      : {}),
    ...(proposal.closedAt === undefined ? {} : { closedAt: proposal.closedAt }),
    column: proposal.status,
    createdAt: proposal.createdAt,
    ...(assignment.createdBy?.email
      ? { createdByEmail: assignment.createdBy.email }
      : {}),
    ...(assignment.createdBy?.name
      ? { createdByName: assignment.createdBy.name }
      : {}),
    createdByWorkosUserId: proposal.createdByWorkosUserId,
    href: `/backoffice/proposals/${proposal._id}`,
    ...(proposal.interestAnnualBps === undefined
      ? {}
      : { interestAnnualBps: proposal.interestAnnualBps }),
    lenderDrawPolicyLimitCents: proposal.lenderDrawPolicyLimitCents,
    location: proposal.location,
    ...(proposal.locationLatitude === undefined
      ? {}
      : { locationLatitude: proposal.locationLatitude }),
    ...(proposal.locationLongitude === undefined
      ? {}
      : { locationLongitude: proposal.locationLongitude }),
    ...(proposal.locationPlaceId
      ? { locationPlaceId: proposal.locationPlaceId }
      : {}),
    ...(proposal.selectedPlan?.planKey
      ? { planKey: proposal.selectedPlan.planKey }
      : {}),
    ...(proposal.selectedPlan?.name
      ? { planName: proposal.selectedPlan.name }
      : {}),
    ...(proposal.proposedStartDate
      ? { proposedStartDate: proposal.proposedStartDate }
      : {}),
    proposalId: String(proposal._id),
    reviewOutcome: proposal.reviewOutcome,
    statusLabel: productionProposalStatusLabel(proposal),
    ...(proposal.submittedAt === undefined
      ? {}
      : { submittedAt: proposal.submittedAt }),
    subtitle: proposal.location,
    title: proposal.buildName,
    totalBudgetCents: proposal.totalBudgetCents,
    updatedAt: proposal.updatedAt,
    updatedByWorkosUserId: proposal.updatedByWorkosUserId,
  };
  return {
    attachedBuilder: assignment.builder
      ? {
          accountEmails: attachedAccountEmails,
          accountNames: attachedAccountNames,
          displayName: assignment.builder.displayName,
          ...(assignment.builder.legalName
            ? { legalName: assignment.builder.legalName }
            : {}),
          ...(assignment.builder.ownerEmail
            ? { preferredEmail: assignment.builder.ownerEmail }
            : {}),
        }
      : null,
    card,
  };
}

async function proposalDirectoryIdentityProjection(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
) {
  const builder = proposal.builderProfileId
    ? await ctx.db.get(proposal.builderProfileId)
    : null;
  const builderAccounts = builder
    ? await builderAccountSummaries(ctx, builder._id)
    : [];
  const [assignedBroker, createdBy] = await Promise.all([
    proposal.assignedBrokerWorkosUserId
      ? getWorkosUserById(ctx, proposal.assignedBrokerWorkosUserId)
      : null,
    getWorkosUserById(ctx, proposal.createdByWorkosUserId),
  ]);
  const builderOwnerEmail = preferredBuilderAccountEmail(builderAccounts);
  return {
    broker: workosUserSummary(
      proposal.assignedBrokerWorkosUserId,
      assignedBroker,
    ),
    builder: builder
      ? {
          _id: builder._id,
          accounts: builderAccounts,
          displayName: builder.displayName,
          ...(builder.legalName ? { legalName: builder.legalName } : {}),
          ...(builderOwnerEmail ? { ownerEmail: builderOwnerEmail } : {}),
        }
      : null,
    createdBy: workosUserSummary(proposal.createdByWorkosUserId, createdBy),
  };
}

function proposalDirectoryCardMatches(input: {
  attachedBuilder?: {
    accountEmails: string[];
    accountNames: string[];
    displayName: string;
    legalName?: string;
    preferredEmail?: string;
  } | null;
  card: ProposalDirectoryCard;
  filters?: {
    approvedFrom?: number;
    approvedTo?: number;
    assignedBrokerWorkosUserId?: string;
    assignment?: "assigned" | "unassigned";
    builderProfileId?: Id<"builderProfiles">;
    closingState?: "active_build" | "pending_closing" | "pre_closing";
    closedFrom?: number;
    closedTo?: number;
    createdFrom?: number;
    createdTo?: number;
    maxBorrowerStartingCashCents?: number;
    maxBorrowerCoPayBps?: number;
    maxBudgetCents?: number;
    maxInterestAnnualBps?: number;
    maxLenderDrawPolicyLimitCents?: number;
    minBorrowerStartingCashCents?: number;
    minBorrowerCoPayBps?: number;
    minBudgetCents?: number;
    minInterestAnnualBps?: number;
    minLenderDrawPolicyLimitCents?: number;
    planKey?:
      | "capitalConstrained"
      | "cheapestFeasible"
      | "fastest"
      | "unselected";
    proposedStartFrom?: string;
    proposedStartTo?: string;
    reviewOutcome?: Doc<"buildProposals">["reviewOutcome"];
    stage?: Doc<"buildProposals">["status"];
    submittedFrom?: number;
    submittedTo?: number;
    updatedFrom?: number;
    updatedTo?: number;
  };
  proposal: Doc<"buildProposals">;
  search?: string;
}) {
  const { card, filters, proposal } = input;
  if (filters?.stage && card.column !== filters.stage) {
    return false;
  }
  if (filters?.reviewOutcome && card.reviewOutcome !== filters.reviewOutcome) {
    return false;
  }
  if (filters?.assignment === "assigned" && !card.builderAssigned) {
    return false;
  }
  if (filters?.assignment === "unassigned" && card.builderAssigned) {
    return false;
  }
  if (
    filters?.builderProfileId &&
    card.builderProfileId !== String(filters.builderProfileId)
  ) {
    return false;
  }
  if (
    filters?.assignedBrokerWorkosUserId &&
    card.assignedBrokerWorkosUserId !== filters.assignedBrokerWorkosUserId
  ) {
    return false;
  }
  if (filters?.planKey === "unselected" && card.planKey !== undefined) {
    return false;
  }
  if (
    filters?.planKey &&
    filters.planKey !== "unselected" &&
    card.planKey !== filters.planKey
  ) {
    return false;
  }
  if (filters?.closingState === "active_build" && !card.activeBuildId) {
    return false;
  }
  if (
    filters?.closingState === "pending_closing" &&
    !(card.column === "approved" && !card.activeBuildId)
  ) {
    return false;
  }
  if (
    filters?.closingState === "pre_closing" &&
    (card.activeBuildId || card.column === "approved")
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.totalBudgetCents,
      filters?.minBudgetCents,
      filters?.maxBudgetCents,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.borrowerCoPayBps,
      filters?.minBorrowerCoPayBps,
      filters?.maxBorrowerCoPayBps,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.borrowerStartingCashCents,
      filters?.minBorrowerStartingCashCents,
      filters?.maxBorrowerStartingCashCents,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.lenderDrawPolicyLimitCents,
      filters?.minLenderDrawPolicyLimitCents,
      filters?.maxLenderDrawPolicyLimitCents,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.interestAnnualBps,
      filters?.minInterestAnnualBps,
      filters?.maxInterestAnnualBps,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(card.createdAt, filters?.createdFrom, filters?.createdTo)
  ) {
    return false;
  }
  if (
    !numberInRange(card.updatedAt, filters?.updatedFrom, filters?.updatedTo)
  ) {
    return false;
  }
  if (
    !numberInRange(
      card.submittedAt,
      filters?.submittedFrom,
      filters?.submittedTo,
    )
  ) {
    return false;
  }
  if (
    !numberInRange(card.approvedAt, filters?.approvedFrom, filters?.approvedTo)
  ) {
    return false;
  }
  if (!numberInRange(card.closedAt, filters?.closedFrom, filters?.closedTo)) {
    return false;
  }
  if (
    filters?.proposedStartFrom &&
    (!card.proposedStartDate ||
      card.proposedStartDate < filters.proposedStartFrom)
  ) {
    return false;
  }
  if (
    filters?.proposedStartTo &&
    (!card.proposedStartDate ||
      card.proposedStartDate > filters.proposedStartTo)
  ) {
    return false;
  }

  const terms = normalizeProposalDirectorySearch(input.search);
  if (terms.length === 0) {
    return true;
  }
  const attachedBuilder = input.attachedBuilder ?? null;
  const searchText = JSON.stringify({
    assignment: {
      brokerEmail: card.assignedBrokerEmail,
      brokerName: card.assignedBrokerName,
      brokerWorkosUserId: card.assignedBrokerWorkosUserId,
      builderAccountEmails: attachedBuilder?.accountEmails ?? [],
      builderAccountNames: attachedBuilder?.accountNames ?? [],
      builderEmail: attachedBuilder?.preferredEmail ?? card.builderEmail,
      builderLegalName: attachedBuilder?.legalName ?? card.builderLegalName,
      builderName: attachedBuilder?.displayName ?? card.builderName,
      builderProfileId: card.builderProfileId,
    },
    card,
    formatted: {
      borrowerStartingCash: centsToCurrency(card.borrowerStartingCashCents),
      budget: centsToCurrency(card.totalBudgetCents),
      lenderDrawPolicyLimit: centsToCurrency(card.lenderDrawPolicyLimitCents),
    },
    proposal: withBorrowerStartingCash(proposal),
  }).toLowerCase();
  return terms.every((term) => searchText.includes(term));
}

function uniqueNormalizedSearchValues(
  values: ReadonlyArray<string | undefined>,
) {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const value of values) {
    const normalized = value?.trim();
    if (!normalized) {
      continue;
    }
    const key = normalized.toLowerCase();
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    result.push(normalized);
  }
  return result;
}

function normalizeProposalDirectorySearch(search: string | undefined) {
  return (search ?? "").trim().toLowerCase().split(/\s+/).filter(Boolean);
}

function numberInRange(
  value: number | undefined,
  minimum: number | undefined,
  maximum: number | undefined,
) {
  if (minimum !== undefined && (value === undefined || value < minimum)) {
    return false;
  }
  if (maximum !== undefined && (value === undefined || value > maximum)) {
    return false;
  }
  return true;
}

function productionDashboardProposalCard(
  card: Doc<"proposalKanbanCards"> | null,
  proposal: Doc<"buildProposals">,
  directoryCard?: ProposalDirectoryCard,
) {
  return {
    address: card?.subtitle ?? proposal.location,
    approvedAt: proposal.approvedAt,
    borrowerStartingCashCents: resolveBorrowerStartingCashCents(proposal),
    builderAssigned: Boolean(proposal.builderProfileId),
    builder: card?.builderName ?? "Unassigned builder",
    builderEmail: directoryCard?.builderEmail,
    builderProfileId: proposal.builderProfileId
      ? String(proposal.builderProfileId)
      : undefined,
    closeLabel:
      proposal.status === "approved" && !proposal.activeBuildId
        ? "Pending closing"
        : undefined,
    column: card?.column ?? proposal.status,
    createdAt: proposal.createdAt,
    href: card?.href ?? `/backoffice/proposals/${proposal._id}`,
    ...(proposal.interestAnnualBps === undefined
      ? {}
      : { interestAnnualBps: proposal.interestAnnualBps }),
    id: String(proposal._id),
    lenderDrawPolicyLimitCents: proposal.lenderDrawPolicyLimitCents,
    loanAmount: centsToCurrency(
      card?.totalBudgetCents ?? proposal.totalBudgetCents,
    ),
    ltv: 0,
    name: card?.title ?? proposal.buildName,
    proposalId: String(proposal._id),
    reviewOutcome: proposal.reviewOutcome,
    status: proposal.status,
    statusLabel: productionProposalStatusLabel(proposal),
    submittedAt: proposal.submittedAt,
    tag: "production",
    totalBudgetCents: proposal.totalBudgetCents,
    updatedAt: proposal.updatedAt,
  };
}

function productionProposalStatusLabel(proposal: Doc<"buildProposals">) {
  if (proposal.reviewOutcome === "rejected") {
    return "Rejected";
  }
  if (proposal.reviewOutcome === "requested_changes") {
    return "Changes requested";
  }
  if (proposal.status === "approved" && !proposal.activeBuildId) {
    return "Approved - pending closing";
  }
  return titleCase(proposal.status);
}

function productionProposalColumnDescription(
  column: (typeof PROPOSAL_COLUMNS)[number],
  proposals: ReturnType<typeof productionDashboardProposalCard>[],
) {
  const count = proposals.filter(
    (proposal) => proposal.column === column,
  ).length;
  if (column === "approved") {
    return `${count} approved proposals pending or ready for closing`;
  }
  if (column === "submitted") {
    return `${count} submitted proposals in lender review`;
  }
  if (column === "closed") {
    return `${count} proposals converted to active builds`;
  }
  return `${count} draft proposals`;
}

function productionBuildDisplayId(build: Doc<"activeBuilds">) {
  return `B-${String(build._id).slice(-8).toUpperCase()}`;
}

function productionQueueAgeLabel(timestamp: number, asOfDate: string) {
  const asOfTime = Date.parse(`${asOfDate}T00:00:00.000Z`);
  const elapsedDays = Math.max(
    0,
    Math.floor((asOfTime - timestamp) / 86_400_000),
  );
  if (elapsedDays === 0) {
    return "Today";
  }
  if (elapsedDays === 1) {
    return "1 day old";
  }
  return `${elapsedDays} days old`;
}

function productionDrawUrgencyRank(
  status: Doc<"plannedDrawScheduleRows">["status"],
): number {
  switch (status) {
    case "requested":
      return 0;
    case "in_review":
      return 1;
    case "ready_for_admin":
      return 2;
    case "approved_for_release":
      return 3;
    case "planned":
      return 4;
    case "released":
      return 5;
  }
  return 6;
}

function productionDrawMonthLabel(monthKey: string) {
  const [yearText, monthText] = monthKey.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  if (!(Number.isFinite(year) && Number.isFinite(month))) {
    return monthKey;
  }
  return new Date(Date.UTC(year, month - 1, 1)).toLocaleDateString("en-US", {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}

function buildBrokerageDrawChartSeries(
  draws: Array<{
    amountCents: number;
    scheduledDateIso: string;
    status: Doc<"plannedDrawScheduleRows">["status"];
  }>,
) {
  const bucketTotals = new Map<
    string,
    {
      approvedCents: number;
      plannedCents: number;
      releasedCents: number;
      requestedCents: number;
    }
  >();
  for (const draw of draws) {
    if (draw.status === "rejected") {
      continue;
    }
    const periodKey = draw.scheduledDateIso.slice(0, 7);
    const existing = bucketTotals.get(periodKey) ?? {
      approvedCents: 0,
      plannedCents: 0,
      releasedCents: 0,
      requestedCents: 0,
    };
    if (draw.status === "planned") {
      existing.plannedCents += draw.amountCents;
    } else if (
      draw.status === "requested" ||
      draw.status === "in_review" ||
      draw.status === "ready_for_admin"
    ) {
      existing.requestedCents += draw.amountCents;
    } else if (draw.status === "approved_for_release") {
      existing.approvedCents += draw.amountCents;
    } else if (draw.status === "released") {
      existing.releasedCents += draw.amountCents;
    }
    bucketTotals.set(periodKey, existing);
  }
  const periodKeys = [...bucketTotals.keys()].sort();
  if (periodKeys.length === 0) {
    return [];
  }
  return periodKeys.map((periodKey) => {
    const totals = bucketTotals.get(periodKey)!;
    return {
      approvedCents: totals.approvedCents,
      periodKey,
      periodLabel: productionDrawMonthLabel(periodKey),
      plannedCents: totals.plannedCents,
      releasedCents: totals.releasedCents,
      requestedCents: totals.requestedCents,
    };
  });
}

type ProductionSiteVisitOperationalStatus =
  | "open"
  | "in_field"
  | "expired"
  | "complete"
  | "cancelled";

function productionSiteVisitOperationalStatus(
  visit: Pick<
    Doc<"buildSiteVisits">,
    "status" | "tokenConsumedAt" | "tokenExpiresAt" | "tokenOpenedAt"
  >,
  now = Date.now(),
): ProductionSiteVisitOperationalStatus {
  if (visit.status === "complete") {
    return "complete";
  }
  if (visit.status === "cancelled") {
    return "cancelled";
  }
  if (visit.tokenExpiresAt <= now) {
    return "expired";
  }
  if (visit.tokenOpenedAt) {
    return "in_field";
  }
  return "open";
}

async function projectBackofficeBuildRosterRow(
  ctx: QueryCtx,
  {
    auth,
    build,
    staffCanRead,
  }: {
    auth: BackofficeBuildRosterAuth;
    build: Doc<"activeBuilds">;
    staffCanRead: boolean;
  },
): Promise<BackofficeBuildRosterRowWithStorage | null> {
  const proposal = await ctx.db.get(build.proposalId);
  if (!proposal || !(canReadBackofficeProposal(auth, proposal) || staffCanRead)) {
    return null;
  }

  const [
    builder,
    milestones,
    plannedDraws,
    drawRequests,
    loan,
    evidence,
    visits,
  ] = await Promise.all([
      ctx.db.get(build.builderProfileId),
      ctx.db
        .query("buildMilestones")
        .withIndex("by_build_order", (q) => q.eq("buildId", build._id))
        .take(100),
      ctx.db
        .query("plannedDrawScheduleRows")
        .withIndex("by_build_order", (q) => q.eq("buildId", build._id))
        .take(100),
      ctx.db
        .query("activeBuildDrawRequests")
        .withIndex("by_build", (q) => q.eq("buildId", build._id))
        .take(100),
      ctx.db
        .query("loanFacilities")
        .withIndex("by_build", (q) => q.eq("buildId", build._id))
        .unique(),
      ctx.db
        .query("buildEvidenceAssets")
        .withIndex("by_build", (q) => q.eq("buildId", build._id))
        .take(100),
      ctx.db
        .query("buildSiteVisits")
        .withIndex("by_build", (q) => q.eq("buildId", build._id))
        .take(100),
    ]);

  const resolvedVisitCounts = backofficeBuildRosterVisitCounts(
    visits,
    build.organizationId,
  );
  const milestonesComplete = milestones.filter(
    (milestone) => milestone.status === "complete",
  ).length;
  const milestonesInReview = milestones.filter(
    productionMilestoneNeedsBackofficeReview,
  ).length;
  const drawRequestsPending = drawRequests.filter(
    (request) => request.status === "requested",
  ).length;
  const milestonesBehindSchedule = milestones.filter((milestone) =>
    productionMilestoneIsBehindSchedule(
      milestone,
      productionDaysActive(build.startDate),
    ),
  ).length;
  const firstImage = evidence.find(
    (asset) => asset.storageId && asset.mimeType.startsWith("image/"),
  );
  const activeMilestone =
    milestones.find((milestone) => milestone.status !== "complete") ??
    milestones[0];
  const phase = productionBuildRosterPhase({
    build,
    drawRequestsPending,
    expiredSiteVisits: resolvedVisitCounts.expired,
    loan,
    milestones,
    milestonesInReview,
  });

  return {
    activeMilestoneName:
      activeMilestone?.name ?? `${milestones.length} milestones`,
    buildId: build._id,
    buildName: build.buildName,
    buildStatus: build.status,
    buildStatusLabel: productionBuildStatusLabel(build.status),
    builderName: builder?.displayName ?? "Builder",
    ...(proposal.closedAt === undefined ? {} : { closedAt: proposal.closedAt }),
    daysActive: productionDaysActive(build.startDate),
    displayId: productionBuildDisplayId(build),
    drawCount: plannedDraws.length,
    drawRequestsPending,
    href: `/backoffice/builds/${build._id}`,
    imageStorageId: firstImage?.storageId ?? null,
    ...(loan ? { loanStatus: loan.status } : {}),
    location: build.location,
    ...(build.locationLatitude === undefined
      ? {}
      : { locationLatitude: build.locationLatitude }),
    ...(build.locationLongitude === undefined
      ? {}
      : { locationLongitude: build.locationLongitude }),
    milestonesBehindSchedule,
    milestonesComplete,
    milestonesInReview,
    milestonesTotal: milestones.length,
    phase,
    proposalStatus: proposal.status,
    siteVisitsExpired: resolvedVisitCounts.expired,
    siteVisitsOpen: resolvedVisitCounts.open,
    startDate: build.startDate,
    totalBudgetCents: build.totalBudgetCents,
    updatedAt: build.updatedAt,
  };
}

function backofficeBuildRosterVisitCounts(
  visits: Doc<"buildSiteVisits">[],
  organizationId: string,
): { expired: number; open: number } {
  const counts = { expired: 0, open: 0 };
  const now = Date.now();
  for (const visit of visits) {
    if (visit.organizationId !== organizationId) {
      continue;
    }
    const operationalStatus = productionSiteVisitOperationalStatus(visit, now);
    if (operationalStatus === "expired") {
      counts.expired += 1;
    }
    if (operationalStatus === "open" || operationalStatus === "in_field") {
      counts.open += 1;
    }
  }
  return counts;
}

function backofficeBuildRosterSearchText(row: BackofficeBuildRosterRowWithStorage) {
  const phaseLabel =
    row.phase === "attention"
      ? "needs attention"
      : row.phase === "active"
        ? "active"
        : row.phase;
  return [
    row.displayId,
    row.buildName,
    row.builderName,
    row.location,
    row.activeMilestoneName,
    row.buildStatusLabel,
    phaseLabel,
  ]
    .join(" ")
    .toLowerCase();
}

function productionSiteVisitTokenState(
  visit: Pick<
    Doc<"buildSiteVisits">,
    "status" | "tokenConsumedAt" | "tokenExpiresAt" | "tokenOpenedAt"
  >,
  now = Date.now(),
): "not_sent" | "live" | "opened" | "consumed" | "expired" {
  if (visit.tokenConsumedAt) {
    return "consumed";
  }
  if (visit.status === "complete") {
    return "consumed";
  }
  if (visit.status === "cancelled") {
    return "expired";
  }
  if (visit.tokenExpiresAt <= now) {
    return "expired";
  }
  if (visit.tokenOpenedAt) {
    return "opened";
  }
  return "live";
}

function productionSiteVisitUrgencyRank(
  status: ProductionSiteVisitOperationalStatus,
) {
  switch (status) {
    case "expired":
      return 0;
    case "open":
      return 1;
    case "in_field":
      return 2;
    case "complete":
      return 3;
    case "cancelled":
      return 4;
    default:
      return 5;
  }
}

function productionSiteVisitScheduledLabel(
  buildStartDate: string,
  requestedDay: number,
) {
  const startMs = Date.parse(`${buildStartDate}T00:00:00Z`);
  if (!Number.isFinite(startMs)) {
    return `Day ${requestedDay}`;
  }
  const scheduled = new Date(startMs + requestedDay * 86_400_000);
  return scheduled.toLocaleDateString("en-US", {
    day: "numeric",
    month: "short",
    weekday: "short",
  });
}

function productionDaysActive(startDate: string, asOfDate?: string) {
  const startMs = Date.parse(`${startDate}T00:00:00Z`);
  if (!Number.isFinite(startMs)) {
    return 0;
  }
  const asOfMs = asOfDate ? Date.parse(`${asOfDate}T00:00:00Z`) : Date.now();
  if (!Number.isFinite(asOfMs)) {
    return 0;
  }
  return Math.max(0, Math.floor((asOfMs - startMs) / 86_400_000));
}

function daysBetweenIso(startIso: string, endIso: string) {
  return Math.max(0, signedDaysBetweenIso(startIso, endIso));
}

function signedDaysBetweenIso(startIso: string, endIso: string) {
  const parseDay = (value: string) => {
    const dayPart = value.includes("T") ? value.slice(0, 10) : value;
    const ms = Date.parse(`${dayPart}T00:00:00Z`);
    return Number.isFinite(ms) ? ms : Date.now();
  };
  return Math.round((parseDay(endIso) - parseDay(startIso)) / 86_400_000);
}

function normalizeIsoDate(value: unknown, message: string) {
  if (typeof value !== "string") {
    throw new Error(message);
  }
  const day = value.slice(0, 10);
  const parsed = Date.parse(`${day}T00:00:00Z`);
  if (!(/^\d{4}-\d{2}-\d{2}$/.test(day) && Number.isFinite(parsed))) {
    throw new Error(message);
  }
  return day;
}

function normalizePositiveCents(value: unknown, message: string) {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(message);
  }
  const rounded = Math.round(value);
  if (rounded <= 0) {
    throw new Error(message);
  }
  return rounded;
}

function activeBuildTimelineDrawStatus(
  status: Doc<"plannedDrawScheduleRows">["status"],
) {
  if (
    status === "requested" ||
    status === "in_review" ||
    status === "ready_for_admin"
  ) {
    return "requested" as const;
  }
  if (status === "approved_for_release" || status === "released") {
    return "approved" as const;
  }
  if (status === "rejected" || status === "withdrawn" || status === "cancelled") {
    return "rejected" as const;
  }
  return "draft" as const;
}

function activeBuildTimelineRequestStatus(
  status: Doc<"activeBuildDrawRequests">["status"],
) {
  if (
    status === "requested" ||
    status === "in_review" ||
    status === "ready_for_admin"
  ) {
    return "requested" as const;
  }
  if (
    status === "approved" ||
    status === "approved_for_release" ||
    status === "released"
  ) {
    return "approved" as const;
  }
  return "rejected" as const;
}

function activeBuildDrawCanonicalStatus(
  status: Doc<"activeBuildDrawRequests">["status"],
): Exclude<Doc<"activeBuildDrawRequests">["status"], "approved"> {
  if (status === "approved") {
    return "approved_for_release";
  }
  return status;
}

function activeBuildTimelineMilestoneStatus(
  milestone: Doc<"buildMilestones">,
  schedule?: {
    currentDay: number;
    milestones: readonly Doc<"buildMilestones">[];
  },
) {
  if (milestone.status === "complete") {
    return "complete" as const;
  }
  if (milestone.completionClaim) {
    return "review" as const;
  }
  if (milestone.status === "in_progress") {
    return "ready" as const;
  }
  if (
    schedule &&
    schedule.currentDay >= milestone.dayStart &&
    activeBuildMilestoneDependencyBlockers(milestone, schedule.milestones)
      .length === 0
  ) {
    return "ready" as const;
  }
  return "upcoming" as const;
}

function activeBuildTimelineMilestoneTone(
  milestone: Doc<"buildMilestones">,
  status: ReturnType<typeof activeBuildTimelineMilestoneStatus>,
  currentDay: number,
) {
  if (status === "complete") {
    return "complete" as const;
  }
  if (currentDay > milestone.dayEnd) {
    return "warning" as const;
  }
  if (status === "ready" || status === "review") {
    return "active" as const;
  }
  return "upcoming" as const;
}

function activeBuildMilestoneDependencyBlockers(
  milestone: Doc<"buildMilestones">,
  milestones: readonly Doc<"buildMilestones">[],
) {
  const byKey = new Map(milestones.map((row) => [row.key, row]));
  return (milestone.dependencyKeys ?? []).filter((key) => {
    const dependency = byKey.get(key);
    return !dependency || dependency.status !== "complete";
  });
}

function activeBuildMilestoneLifecycleState(
  milestone: Doc<"buildMilestones">,
  milestones?: readonly Doc<"buildMilestones">[],
) {
  if (
    milestone.status === "complete" ||
    milestone.completionReview?.status === "approved"
  ) {
    return "complete" as const;
  }
  if (milestone.completionReview?.status === "rejected") {
    return "revision_requested" as const;
  }
  if (milestone.completionClaim) {
    return "completion_submitted" as const;
  }
  if (milestone.status === "in_progress") {
    return "in_progress" as const;
  }
  if (
    milestones &&
    activeBuildMilestoneDependencyBlockers(milestone, milestones).length > 0
  ) {
    return "blocked" as const;
  }
  return "scheduled" as const;
}

function activeBuildMilestoneSummary(input: {
  assignments: readonly Doc<"milestoneContractorAssignments">[];
  includeSubmilestones: boolean;
  milestone: Doc<"buildMilestones">;
  milestones?: readonly Doc<"buildMilestones">[];
  submilestones: readonly Doc<"buildSubmilestones">[];
}) {
  const assignmentCount = input.assignments.filter(
    (assignment) =>
      assignment.buildMilestoneId === input.milestone._id ||
      assignment.milestoneKey === input.milestone.key,
  ).length;
  const lifecycleState = activeBuildMilestoneLifecycleState(
    input.milestone,
    input.milestones,
  );
  const milestoneSubmilestones = input.submilestones
    .filter((submilestone) => submilestone.milestoneKey === input.milestone.key)
    .sort((a, b) => a.order - b.order || a.key.localeCompare(b.key));
  const completedSubmilestoneCount = milestoneSubmilestones.filter(
    (submilestone) => submilestone.status === "complete",
  ).length;
  const totalSubmilestoneCount = milestoneSubmilestones.length;
  const normalizedProgressPercent =
    lifecycleState === "complete"
      ? 100
      : Math.max(0, Math.min(100, input.milestone.progressPercent ?? 0));
  const reconciliationIssues: Array<{
    code: string;
    message: string;
    severity: "warning";
  }> = [];

  if (
    (lifecycleState === "completion_submitted" ||
      lifecycleState === "complete") &&
    completedSubmilestoneCount < totalSubmilestoneCount
  ) {
    reconciliationIssues.push({
      code:
        lifecycleState === "complete"
          ? "complete_with_incomplete_submilestones"
          : "completion_submitted_with_incomplete_submilestones",
      message: `${totalSubmilestoneCount - completedSubmilestoneCount} sub-milestone${
        totalSubmilestoneCount - completedSubmilestoneCount === 1
          ? " is"
          : "s are"
      } not complete.`,
      severity: "warning",
    });
  }
  if (
    lifecycleState === "completion_submitted" &&
    normalizedProgressPercent < 100
  ) {
    reconciliationIssues.push({
      code: "completion_submitted_below_full_progress",
      message: `Completion was submitted while progress is ${normalizedProgressPercent}%.`,
      severity: "warning",
    });
  }
  if (
    lifecycleState !== "complete" &&
    lifecycleState !== "completion_submitted" &&
    normalizedProgressPercent === 100
  ) {
    reconciliationIssues.push({
      code: "full_progress_without_completion",
      message:
        "Progress is 100% but the milestone has not been approved as complete.",
      severity: "warning",
    });
  }
  if (input.milestone.drawAvailabilityCents > input.milestone.budgetCents) {
    reconciliationIssues.push({
      code: "draw_availability_exceeds_budget",
      message: "Available draw value exceeds the milestone budget.",
      severity: "warning",
    });
  }

  return {
    assignmentCount,
    assignmentCoverage:
      assignmentCount > 0 ? ("assigned" as const) : ("unassigned" as const),
    budgetCents: input.milestone.budgetCents,
    completedSubmilestoneCount,
    drawAvailabilityCents: input.milestone.drawAvailabilityCents,
    lifecycleState,
    normalizedProgressPercent,
    reconciliationIssues,
    reconciliationState:
      reconciliationIssues.length > 0
        ? ("needs_review" as const)
        : ("consistent" as const),
    submilestoneCoverage:
      totalSubmilestoneCount === 0
        ? ("not_applicable" as const)
        : completedSubmilestoneCount === totalSubmilestoneCount
          ? ("complete" as const)
          : ("incomplete" as const),
    submilestoneRecovery:
      totalSubmilestoneCount === 0
        ? {
            message:
              "This Milestone has no valid Sub-milestones. Add one through the canonical roadmap revision before starting work.",
            state: "recovery_required" as const,
          }
        : undefined,
    submilestoneSnapshot: input.includeSubmilestones
      ? milestoneSubmilestones.map((submilestone) => ({
          ...(submilestone.budgetCents === undefined
            ? {}
            : { budgetCents: submilestone.budgetCents }),
          canonicalId: submilestone._id,
          ...(submilestone.durationDays === undefined
            ? {}
            : { durationDays: submilestone.durationDays }),
          key: submilestone.key,
          name: submilestone.name,
          order: submilestone.order,
          ...(submilestone.startDay === undefined
            ? {}
            : { startDay: submilestone.startDay }),
          status: submilestone.status,
        }))
      : [],
    totalSubmilestoneCount,
  };
}

function activeBuildSiteVisitCompletionReviewView(
  visit?: Doc<"buildSiteVisits">,
) {
  if (!visit) {
    return;
  }
  const siteVisit = {
    ...(visit.completedAt ? { completedAt: visit.completedAt } : {}),
    ...(visit.note ? { note: visit.note } : {}),
    ...(visit.recordNote ? { recordNote: visit.recordNote } : {}),
    ...(visit.recordNoteFormat
      ? { recordNoteFormat: visit.recordNoteFormat }
      : {}),
    requestedAt: visit.requestedAt,
    requestedDay: visit.requestedDay,
    status: visit.status,
    tokenExpiresAt: visit.tokenExpiresAt,
    url: visit.url,
    visitId: visit.visitId,
  };
  return {
    reviewedAt: visit.completedAt ?? visit.requestedAt,
    siteVisit,
    status: "pending" as const,
  };
}

function productionBuildDashboardStatus(
  _status: Doc<"activeBuilds">["status"],
): "behind" | "onTrack" | "overBudget" {
  return "onTrack";
}

function productionBuildStatusLabel(status: Doc<"activeBuilds">["status"]) {
  return status === "future_start" ? "Future start" : "On track";
}

function productionBuildRosterPhase({
  build,
  drawRequestsPending,
  expiredSiteVisits,
  loan,
  milestones,
  milestonesInReview,
}: {
  build: Doc<"activeBuilds">;
  drawRequestsPending: number;
  expiredSiteVisits: number;
  loan: Doc<"loanFacilities"> | null;
  milestones: Doc<"buildMilestones">[];
  milestonesInReview: number;
}): "scheduled" | "active" | "attention" | "completed" {
  if (build.status === "future_start") {
    return "scheduled";
  }
  const allMilestonesComplete =
    milestones.length > 0 &&
    milestones.every((milestone) => milestone.status === "complete");
  if (loan?.status === "closed" || allMilestonesComplete) {
    return "completed";
  }
  if (
    expiredSiteVisits > 0 ||
    drawRequestsPending > 0 ||
    milestonesInReview > 0
  ) {
    return "attention";
  }
  return "active";
}

function productionMilestoneState(
  status: Doc<"buildMilestones">["status"],
): "backlog" | "inProgress" | "inReview" {
  if (status === "in_progress") {
    return "inProgress";
  }
  if (status === "complete") {
    return "inReview";
  }
  return "backlog";
}

function productionMilestoneNeedsBackofficeReview(
  milestone: Doc<"buildMilestones">,
) {
  if (!milestone.completionClaim) {
    return false;
  }
  if (
    milestone.status === "complete" ||
    milestone.completionReview?.status === "approved"
  ) {
    return false;
  }
  return true;
}

function productionMilestoneColumn(
  milestone: Doc<"buildMilestones">,
  currentDay: number,
) {
  const siteVisitStatus = milestone.completionReview?.siteVisit?.status;
  if (siteVisitStatus === "requested") {
    return "needsSiteVisit";
  }
  if (siteVisitStatus === "complete") {
    return "inReview";
  }
  if (siteVisitStatus) {
    return "inProgress";
  }
  if (productionMilestoneIsBehindSchedule(milestone, currentDay)) {
    return "behindSchedule";
  }
  return "backlog";
}

function productionMilestoneIsBehindSchedule(
  milestone: Doc<"buildMilestones">,
  currentDay: number,
) {
  if (
    milestone.status === "complete" ||
    milestone.completionClaim ||
    milestone.completionReview?.status === "approved"
  ) {
    return false;
  }
  return currentDay > milestone.dayEnd;
}

function productionMilestoneDueLabel(
  milestone: Doc<"buildMilestones">,
  currentDay: number,
) {
  const overdueDays = currentDay - milestone.dayEnd;
  return overdueDays > 0
    ? `${overdueDays}d overdue`
    : `Day ${milestone.dayEnd}`;
}

function productionMilestonePriority(
  milestone: Doc<"buildMilestones">,
  currentDay: number,
) {
  if (
    milestone.status === "in_progress" ||
    productionMilestoneIsBehindSchedule(milestone, currentDay)
  ) {
    return "high";
  }
  return "medium";
}

function centsToCurrency(cents: number) {
  return new Intl.NumberFormat("en-US", {
    currency: "USD",
    maximumFractionDigits: 0,
    style: "currency",
  }).format(cents / 100);
}

async function assertBackofficeProposalRead(
  ctx: QueryCtx | MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    roles: RoleSlug[];
    subject: string;
  },
  proposal: Doc<"buildProposals">,
) {
  if (canReadBackofficeProposal(auth, proposal)) {
    return;
  }
  if (
    auth.roles.includes("broker-staff") &&
    (await hasPermission(
      ctx,
      auth.brokerage.workosOrganizationId,
      auth.roles,
      "proposals:read",
    ))
  ) {
    return;
  }

  throw new Error("Forbidden: proposal scope");
}

function canReadBackofficeProposal(
  auth: {
    roles: RoleSlug[];
  },
  _proposal: Doc<"buildProposals">,
) {
  if (
    auth.roles.includes("admin") ||
    auth.roles.includes("principle-broker") ||
    auth.roles.includes("broker")
  ) {
    return true;
  }
  return false;
}

function canWriteBackofficeProposal(
  auth: { roles: RoleSlug[]; subject: string },
  proposal: Doc<"buildProposals">,
) {
  if (auth.roles.includes("admin") || auth.roles.includes("principle-broker")) {
    return true;
  }
  return (
    auth.roles.includes("broker") &&
    proposal.assignedBrokerWorkosUserId === auth.subject
  );
}

function requireBackofficeProposalWrite(
  auth: { roles: RoleSlug[]; subject: string },
  proposal: Doc<"buildProposals">,
) {
  if (canWriteBackofficeProposal(auth, proposal)) {
    return;
  }
  throw new Error("Forbidden: proposal write");
}

function requireAnyRole(
  actual: readonly RoleSlug[],
  allowed: readonly RoleSlug[] | readonly string[],
) {
  const allowedRoles: readonly string[] = allowed;
  if (!actual.some((role) => allowedRoles.includes(role))) {
    throw new Error("Forbidden: role");
  }
}

function normalizeOptionalString(value?: string) {
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
}

function activeBuildCompletionReviewRecord(
  review: unknown,
): Record<string, unknown> {
  return review && typeof review === "object" && !Array.isArray(review)
    ? (review as Record<string, unknown>)
    : {};
}

function activeBuildCompletionReviewNote(review: unknown) {
  const value = activeBuildCompletionReviewRecord(review).note;
  return typeof value === "string" ? normalizeOptionalString(value) : undefined;
}

function activeBuildPendingCompletionReview(review: unknown) {
  const record = activeBuildCompletionReviewRecord(review);
  if (record.status === "approved" || record.status === "rejected") {
    return record;
  }
  const { note: _obsoleteRequestedChange, ...withoutRequestedChange } = record;
  return {
    ...withoutRequestedChange,
    status: "pending",
  };
}

function activeBuildCompletionReviewWithSiteVisit(
  review: unknown,
  siteVisit: Record<string, unknown>,
  reviewedAt: string,
) {
  const record = activeBuildCompletionReviewRecord(review);
  const hasExplicitRevisionRequest =
    record.status === "revisionRequested" &&
    Boolean(activeBuildCompletionReviewNote(record));
  const status =
    record.status === "approved" || record.status === "rejected"
      ? record.status
      : hasExplicitRevisionRequest
        ? "revisionRequested"
        : "pending";
  return {
    ...record,
    reviewedAt: record.reviewedAt ?? reviewedAt,
    siteVisit,
    status,
  };
}

function normalizeIsoDateOnly(value: string, label: string) {
  const trimmed = value.trim();
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed);
  if (!match) {
    throw new Error(`${label} must be a valid YYYY-MM-DD date.`);
  }
  const [, yearText, monthText, dayText] = match;
  const year = Number(yearText);
  const month = Number(monthText);
  const day = Number(dayText);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new Error(`${label} must be a valid YYYY-MM-DD date.`);
  }
  return trimmed;
}

function normalizeOptionalMoneyCents(value?: number) {
  if (value === undefined) {
    return;
  }
  if (!Number.isFinite(value)) {
    throw new Error("Contractor cost value must be a finite number.");
  }
  return Math.max(0, Math.round(value));
}

function normalizeOptionalHours(value?: number) {
  if (value === undefined) {
    return;
  }
  if (!Number.isFinite(value)) {
    throw new Error("Contractor hours value must be a finite number.");
  }
  return Math.max(0, Math.round(value * 100) / 100);
}

function deriveContractorAssignmentCost(input: {
  hours?: number;
  rateCents?: number;
  rateUnit?: "hour" | "day" | "fixed";
}) {
  if (input.rateCents === undefined) {
    return;
  }
  if (input.rateUnit === "fixed") {
    return input.rateCents;
  }
  if (input.rateUnit === "hour" && input.hours !== undefined) {
    return Math.round(input.rateCents * input.hours);
  }
  return;
}

function normalizeQualityRating(value: number) {
  if (!Number.isFinite(value)) {
    throw new Error("Contractor quality rating must be a finite number.");
  }
  const rounded = Math.round(value);
  if (rounded < 1 || rounded > 5) {
    throw new Error("Contractor quality rating must be between 1 and 5.");
  }
  return rounded;
}

async function getScopedContractorOrThrow(
  ctx: QueryCtx | MutationCtx,
  contractorId: Id<"contractorProfiles">,
  brokerageId: Id<"brokerages">,
) {
  const contractor = await ctx.db.get(contractorId);
  if (!contractor || contractor.brokerageId !== brokerageId) {
    throw new Error("Production contractor not found.");
  }
  return contractor;
}

async function resolveDraftProposalContractorProfile(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      roles: RoleSlug[];
      subject: string;
    };
    contractorId?: Id<"contractorProfiles">;
    contractorName: string;
    now: number;
    role: string;
    workosOrganizationId: string;
  },
) {
  if (input.contractorId) {
    const contractor = await getScopedContractorOrThrow(
      ctx,
      input.contractorId,
      input.auth.brokerage._id,
    );
    if (contractor.status !== "active") {
      throw new Error("Production contractor is inactive.");
    }
    return input.contractorId;
  }

  const contractorName = normalizeRequiredText(
    input.contractorName,
    "Contractor name",
  );
  const existing = (
    await ctx.db
      .query("contractorProfiles")
      .withIndex("by_brokerage", (q) =>
        q.eq("brokerageId", input.auth.brokerage._id),
      )
      .collect()
  ).find(
    (contractor) =>
      contractor.status === "active" &&
      contractor.name.trim().toLowerCase() === contractorName.toLowerCase(),
  );
  if (existing) {
    return existing._id;
  }

  const contractorId = await ctx.db.insert("contractorProfiles", {
    brokerageId: input.auth.brokerage._id,
    createdAt: input.now,
    kind: "company",
    name: contractorName,
    onboardingStatus: "profile_only",
    organizationId: input.workosOrganizationId,
    status: "active",
    trades: input.role.trim() ? [input.role.trim()] : [],
    updatedAt: input.now,
  });
  await writeContractorProfileEvent(ctx, {
    auth: input.auth,
    command: "saveDraftProposalPackage",
    contractorId,
    eventType: "contractor.profile.created",
    newState: JSON.stringify({
      createdFromDraftPlanning: true,
      name: contractorName,
      trades: input.role.trim() ? [input.role.trim()] : [],
    }),
    organizationId: input.workosOrganizationId,
  });
  return contractorId;
}

async function replaceContractorOperatingRows(
  ctx: MutationCtx,
  input: {
    availabilityWindows: Array<{
      dayOfWeek: number;
      effectiveEndDate?: string;
      effectiveStartDate?: string;
      endMinute: number;
      startMinute: number;
      timezone: string;
    }>;
    brokerageId: Id<"brokerages">;
    capabilities: Array<{
      capabilityKey: string;
      label: string;
      milestoneArchetypeKey?: string;
      notes?: string;
      trade?: string;
    }>;
    contractorId: Id<"contractorProfiles">;
    equipment: Array<{
      equipmentKey: string;
      name: string;
      notes?: string;
      quantity: number;
    }>;
    now: number;
    organizationId: string;
  },
) {
  const [capabilities, equipment, windows] = await Promise.all([
    collectByIndex(
      ctx,
      "contractorCapabilities",
      "by_contractor",
      input.contractorId,
    ),
    collectByIndex(
      ctx,
      "contractorEquipment",
      "by_contractor",
      input.contractorId,
    ),
    collectByIndex(
      ctx,
      "contractorAvailabilityWindows",
      "by_contractor",
      input.contractorId,
    ),
  ]);
  for (const row of capabilities) {
    await ctx.db.delete(row._id);
  }
  for (const row of equipment) {
    await ctx.db.delete(row._id);
  }
  for (const row of windows) {
    await ctx.db.delete(row._id);
  }

  for (const capability of input.capabilities) {
    const key = capability.capabilityKey.trim();
    const label = capability.label.trim();
    if (!(key && label)) {
      continue;
    }
    await ctx.db.insert("contractorCapabilities", {
      brokerageId: input.brokerageId,
      capabilityKey: key,
      contractorId: input.contractorId,
      createdAt: input.now,
      label,
      milestoneArchetypeKey: normalizeOptionalString(
        capability.milestoneArchetypeKey,
      ),
      notes: normalizeOptionalString(capability.notes),
      organizationId: input.organizationId,
      trade: normalizeOptionalString(capability.trade),
      updatedAt: input.now,
    });
  }

  for (const row of input.equipment) {
    const key = row.equipmentKey.trim();
    const name = row.name.trim();
    if (!(key && name)) {
      continue;
    }
    await ctx.db.insert("contractorEquipment", {
      brokerageId: input.brokerageId,
      contractorId: input.contractorId,
      createdAt: input.now,
      equipmentKey: key,
      name,
      notes: normalizeOptionalString(row.notes),
      organizationId: input.organizationId,
      quantity: Math.max(0, Math.round(row.quantity)),
      updatedAt: input.now,
    });
  }

  for (const window of input.availabilityWindows) {
    await ctx.db.insert("contractorAvailabilityWindows", {
      brokerageId: input.brokerageId,
      contractorId: input.contractorId,
      createdAt: input.now,
      dayOfWeek: Math.max(0, Math.min(6, Math.round(window.dayOfWeek))),
      effectiveEndDate: normalizeOptionalString(window.effectiveEndDate),
      effectiveStartDate: normalizeOptionalString(window.effectiveStartDate),
      endMinute: Math.max(0, Math.min(24 * 60, Math.round(window.endMinute))),
      organizationId: input.organizationId,
      startMinute: Math.max(
        0,
        Math.min(24 * 60, Math.round(window.startMinute)),
      ),
      timezone: window.timezone.trim() || "UTC",
      updatedAt: input.now,
    });
  }
}

async function hydrateContractorProfiles(
  ctx: QueryCtx | MutationCtx,
  profiles: Doc<"contractorProfiles">[],
) {
  return await Promise.all(
    profiles.map(async (profile) => {
      const [capabilities, equipment, availabilityWindows] = await Promise.all([
        collectByIndex(
          ctx,
          "contractorCapabilities",
          "by_contractor",
          profile._id,
        ),
        collectByIndex(
          ctx,
          "contractorEquipment",
          "by_contractor",
          profile._id,
        ),
        collectByIndex(
          ctx,
          "contractorAvailabilityWindows",
          "by_contractor",
          profile._id,
        ),
      ]);
      return {
        ...profile,
        availabilityWindows: availabilityWindows.sort(
          (a: any, b: any) =>
            a.dayOfWeek - b.dayOfWeek || a.startMinute - b.startMinute,
        ),
        capabilities: capabilities.sort((a: any, b: any) =>
          a.capabilityKey.localeCompare(b.capabilityKey),
        ),
        defaultPayRateUnit: profile.defaultPayRateUnit ?? "hour",
        equipment: equipment.sort((a: any, b: any) =>
          a.equipmentKey.localeCompare(b.equipmentKey),
        ),
        kind: profile.kind ?? "company",
        onboardingStatus:
          profile.onboardingStatus ??
          (profile.accountWorkosUserId ? "account_linked" : "profile_only"),
      };
    }),
  );
}

async function addContractorRoleToExistingMembership(
  ctx: MutationCtx,
  input: {
    now: number;
    workosOrganizationId: string;
    workosUserId: string;
  },
) {
  const membership = await ctx.db
    .query("workosOrganizationMemberships")
    .withIndex("by_user", (q) => q.eq("workosUserId", input.workosUserId))
    .filter((q) =>
      q.eq(q.field("workosOrganizationId"), input.workosOrganizationId),
    )
    .first();
  if (!membership) {
    return;
  }
  const roleSlugs = [...new Set([...membership.roleSlugs, "contractor"])];
  await ctx.db.patch(membership._id, {
    roleSlug: membership.roleSlug ?? "contractor",
    roleSlugs,
    updatedAt: input.now,
  });
}

async function writeContractorProfileEvent(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    command: string;
    contractorId: Id<"contractorProfiles">;
    eventType: string;
    newState?: string;
    organizationId: string;
    priorState?: string;
    reason?: string;
    warnings?: string[];
  },
) {
  const now = Date.now();
  await ctx.db.insert("auditEvents", {
    actorRoles: input.auth.roles,
    actorWorkosUserId: input.auth.subject,
    brokerageId: input.auth.brokerage._id,
    command: input.command,
    createdAt: now,
    entityId: String(input.contractorId),
    entityType: "contractorProfile",
    eventType: input.eventType,
    newState: input.newState,
    organizationId: input.organizationId,
    priorState: input.priorState,
    reason: input.reason,
    warnings: input.warnings ?? [],
  });
  await ctx.db.insert("eventOutbox", {
    brokerageId: input.auth.brokerage._id,
    createdAt: now,
    eventType: input.eventType,
    organizationId: input.organizationId,
    payloadPreview: JSON.stringify({
      contractorId: input.contractorId,
      newState: input.newState,
    }),
    relatedEntityId: input.contractorId,
    relatedEntityType: "contractorProfile",
    status: "pending",
  });
}

function builderContractorUnavailable(
  category: "accessDenied" | "invalidLink" | "notFound",
) {
  const referenceByCategory = {
    accessDenied: "CTR-DETAIL-ACCESS",
    invalidLink: "CTR-DETAIL-INVALID",
    notFound: "CTR-DETAIL-NOT-FOUND",
  } as const;
  return {
    availability: {
      category,
      reference: referenceByCategory[category],
    },
    detail: null,
  };
}

async function builderContractorRelationshipScope(
  ctx: QueryCtx | MutationCtx,
  input: {
    brokerageId: Id<"brokerages">;
    contractorId: Id<"contractorProfiles">;
    subject: string;
  },
) {
  const builderProfiles = await getOwnedBuilderProfiles(
    ctx,
    input.brokerageId,
    input.subject,
  );
  const builderProfileIds = new Set(
    builderProfiles.map((profile) => String(profile._id)),
  );
  if (builderProfileIds.size === 0) {
    return null;
  }

  const proposalAttachments = await ctx.db
    .query("proposalContractorAssignments")
    .withIndex("by_contractor", (q) => q.eq("contractorId", input.contractorId))
    .collect();
  const ownedProposalAttachments: Array<{
    assignment: Doc<"proposalContractorAssignments">;
    proposal: Doc<"buildProposals">;
  }> = [];
  for (const assignment of proposalAttachments) {
    if (assignment.status !== "active") {
      continue;
    }
    const proposal = await ctx.db.get(assignment.proposalId);
    if (
      proposal?.builderProfileId &&
      builderProfileIds.has(String(proposal.builderProfileId))
    ) {
      ownedProposalAttachments.push({ assignment, proposal });
    }
  }

  const ownedBuilds = (
    await ctx.db
      .query("activeBuilds")
      .withIndex("by_brokerage", (q) => q.eq("brokerageId", input.brokerageId))
      .collect()
  ).filter((build) => builderProfileIds.has(String(build.builderProfileId)));
  const ownedBuildAttachments: Array<{
    assignment: Doc<"buildContractorAssignments">;
    build: Doc<"activeBuilds">;
  }> = [];
  for (const build of ownedBuilds) {
    const assignment = await ctx.db
      .query("buildContractorAssignments")
      .withIndex("by_build_contractor", (q) =>
        q.eq("buildId", build._id).eq("contractorId", input.contractorId),
      )
      .unique();
    if (assignment && assignment.status !== "inactive") {
      ownedBuildAttachments.push({ assignment, build });
    }
  }

  if (
    ownedProposalAttachments.length === 0 &&
    ownedBuildAttachments.length === 0
  ) {
    return null;
  }

  const proposalIds = new Set(
    ownedProposalAttachments.map(({ proposal }) => String(proposal._id)),
  );
  const buildIds = new Set(
    ownedBuildAttachments.map(({ build }) => String(build._id)),
  );
  const proposalMilestoneAssignments = (
    await ctx.db
      .query("proposalMilestoneContractorAssignments")
      .withIndex("by_contractor", (q) =>
        q.eq("contractorId", input.contractorId),
      )
      .collect()
  ).filter(
    (assignment) =>
      assignment.status !== "removed" &&
      proposalIds.has(String(assignment.proposalId)),
  );
  const buildMilestoneAssignments = (
    await ctx.db
      .query("milestoneContractorAssignments")
      .withIndex("by_contractor", (q) =>
        q.eq("contractorId", input.contractorId),
      )
      .collect()
  ).filter(
    (assignment) =>
      assignment.status !== "removed" &&
      buildIds.has(String(assignment.buildId)),
  );

  return {
    buildIds,
    buildMilestoneAssignments,
    proposalMilestoneAssignments,
    scopes: [
      ...ownedBuildAttachments.map(({ assignment, build }) => ({
        buildId: build._id,
        name: build.buildName,
        role: assignment.role,
        status: assignment.status ?? "active",
        type: "build" as const,
      })),
      ...ownedProposalAttachments.map(({ assignment, proposal }) => ({
        name: proposal.buildName,
        proposalId: proposal._id,
        role: assignment.role,
        status: assignment.status,
        type: "proposal" as const,
      })),
    ],
  };
}

function builderVisibleContractorProfile(profile: any) {
  return {
    _id: profile._id,
    accountWorkosUserId: profile.accountWorkosUserId,
    availabilityWindows: profile.availabilityWindows,
    capabilities: profile.capabilities,
    city: profile.city,
    defaultPayRateCents: profile.defaultPayRateCents,
    defaultPayRateUnit: profile.defaultPayRateUnit,
    email: profile.email,
    equipment: profile.equipment,
    kind: profile.kind,
    name: profile.name,
    onboardingStatus: profile.onboardingStatus,
    phone: profile.phone,
    status: profile.status,
    trades: profile.trades,
  };
}

function builderContractorLifecycle(input: {
  hasActiveContractorMembership: boolean;
  hasMilestoneAssignment: boolean;
  hasPendingAcknowledgement: boolean;
  latestClaim?: Doc<"contractorInviteClaims">;
  latestReview?: Doc<"contractorOnboardingReviews">;
  profile: any;
}) {
  const now = Date.now();
  const invitationState =
    input.latestClaim?.state === "invited" &&
    input.latestClaim.expiresAt !== undefined &&
    input.latestClaim.expiresAt <= now
      ? "expired"
      : (input.latestClaim?.state ?? "not_invited");

  if (input.latestReview?.status === "changes_requested") {
    return {
      invitationState,
      lifecycleState: "changes_requested",
      nextAction: "contact_support",
    };
  }
  if (input.latestReview?.status === "pending_backoffice_review") {
    return {
      invitationState,
      lifecycleState: "review_required",
      nextAction: "wait_for_review",
    };
  }
  if (input.latestReview?.status === "approved_pending_workos") {
    return {
      invitationState,
      lifecycleState: "sync_pending",
      nextAction: "wait_for_sync",
    };
  }
  if (
    input.profile.accountWorkosUserId &&
    input.hasActiveContractorMembership &&
    input.hasMilestoneAssignment &&
    input.hasPendingAcknowledgement
  ) {
    return {
      invitationState,
      lifecycleState: "acknowledgement_pending",
      nextAction: "wait_for_acknowledgement",
    };
  }
  if (
    input.profile.accountWorkosUserId &&
    input.hasActiveContractorMembership
  ) {
    return {
      invitationState,
      lifecycleState: "active",
      nextAction: "none",
    };
  }
  if (input.profile.accountWorkosUserId) {
    return {
      invitationState,
      lifecycleState: "sync_pending",
      nextAction: "wait_for_sync",
    };
  }
  if (invitationState === "accepted_pending_confirmation") {
    return {
      invitationState,
      lifecycleState: "accepted_pending_confirmation",
      nextAction: "wait_for_confirmation",
    };
  }
  if (invitationState === "claimed") {
    return {
      invitationState,
      lifecycleState: "claimed",
      nextAction: "wait_for_activation",
    };
  }
  if (invitationState === "invited") {
    return {
      invitationState,
      lifecycleState: "invited",
      nextAction: "wait_for_claim",
    };
  }
  if (invitationState === "expired" || invitationState === "revoked") {
    return {
      invitationState,
      lifecycleState: invitationState,
      nextAction: "contact_support",
    };
  }
  if (input.hasMilestoneAssignment) {
    return {
      invitationState,
      lifecycleState: "assigned",
      nextAction: "invite",
    };
  }
  return {
    invitationState,
    lifecycleState: "attached",
    nextAction: "invite",
  };
}

async function assertContractorDetailReadAllowed(
  ctx: QueryCtx | MutationCtx,
  input: {
    contractor: Doc<"contractorProfiles">;
    roles: readonly RoleSlug[];
    subject: string;
  },
) {
  if (input.contractor.accountWorkosUserId === input.subject) {
    return;
  }
  requireAnyRole(input.roles, BUILDER_ROLES);
  const builderProfile = await getOwnedBuilderProfile(
    ctx,
    input.contractor.brokerageId,
    input.subject,
  );
  if (!builderProfile) {
    throw new Error("Forbidden: contractor detail");
  }
  const builds = await ctx.db
    .query("activeBuilds")
    .withIndex("by_brokerage", (q) =>
      q.eq("brokerageId", input.contractor.brokerageId),
    )
    .filter((q) => q.eq(q.field("builderProfileId"), builderProfile._id))
    .collect();
  const buildIds = new Set(builds.map((build) => String(build._id)));
  const assignments = await ctx.db
    .query("milestoneContractorAssignments")
    .withIndex("by_contractor", (q) =>
      q.eq("contractorId", input.contractor._id),
    )
    .collect();
  if (
    !assignments.some((assignment) => buildIds.has(String(assignment.buildId)))
  ) {
    throw new Error("Forbidden: contractor detail");
  }
}

async function contractorWorkHistory(
  ctx: QueryCtx | MutationCtx,
  input: {
    assignments: Doc<"milestoneContractorAssignments">[];
    brokerageId: Id<"brokerages">;
    contractorId: Id<"contractorProfiles">;
  },
) {
  const rows = [];
  for (const assignment of input.assignments) {
    const [build, milestone, submilestone] = await Promise.all([
      ctx.db.get(assignment.buildId),
      ctx.db.get(assignment.buildMilestoneId),
      assignment.buildSubmilestoneId
        ? ctx.db.get(assignment.buildSubmilestoneId)
        : Promise.resolve(null),
    ]);
    if (!build || build.brokerageId !== input.brokerageId || !milestone) {
      continue;
    }
    const evidenceAssets = await ctx.db
      .query("buildEvidenceAssets")
      .withIndex("by_build_milestone", (q) =>
        q
          .eq("buildId", assignment.buildId)
          .eq("milestoneKey", assignment.milestoneKey),
      )
      .collect();
    const evidencePhotos = await Promise.all(
      evidenceAssets
        .filter((asset) => asset.mimeType.startsWith("image/"))
        .filter((asset) =>
          assignment.submilestoneKey
            ? asset.submilestoneKey === assignment.submilestoneKey
            : asset.milestoneKey === assignment.milestoneKey,
        )
        .sort((a, b) => a.createdAt - b.createdAt)
        .map(async (asset) => ({
          evidenceKey: asset.evidenceKey,
          fileName: asset.fileName,
          label: asset.label,
          milestoneKey: asset.milestoneKey,
          previewUrl: asset.storageId
            ? await ctx.storage.getUrl(asset.storageId)
            : null,
          source: asset.source,
          submilestoneKey: asset.submilestoneKey,
          tag: asset.tag,
        })),
    );
    rows.push({
      _id: assignment._id,
      buildId: build._id,
      buildName: build.buildName,
      buildStatus: build.status,
      evidencePhotos,
      actualCostCents: assignment.actualCostCents,
      actualHours: assignment.actualHours,
      agreedRateCents: assignment.agreedRateCents,
      agreedRateUnit: assignment.agreedRateUnit,
      costNotes: assignment.costNotes,
      estimatedCostCents: assignment.estimatedCostCents,
      estimatedHours: assignment.estimatedHours,
      location: build.location,
      milestoneKey: assignment.milestoneKey,
      milestoneName: milestone.name,
      postHoc: assignment.postHoc,
      role: assignment.role,
      status: assignment.status,
      submilestones: submilestone
        ? [
            {
              key: submilestone.key,
              name: submilestone.name,
              status: submilestone.status,
            },
          ]
        : [],
      updatedAt: assignment.updatedAt,
    });
  }
  return rows.sort((a, b) => b.updatedAt - a.updatedAt);
}

function contractorPerformanceSummary(
  ratings: Doc<"contractorQualityRatings">[],
  assignments: Doc<"milestoneContractorAssignments">[] = [],
) {
  const averageQualityRating =
    ratings.length === 0
      ? null
      : Math.round(
          (ratings.reduce((sum, rating) => sum + rating.rating, 0) /
            ratings.length) *
            10,
        ) / 10;
  const totalEstimatedCostCents = assignments.reduce(
    (sum, assignment) => sum + (assignment.estimatedCostCents ?? 0),
    0,
  );
  const totalActualCostCents = assignments.reduce(
    (sum, assignment) => sum + (assignment.actualCostCents ?? 0),
    0,
  );
  return {
    averageQualityRating,
    assignmentCount: assignments.length,
    completedAssignmentCount: assignments.filter(
      (assignment) => assignment.status === "completed",
    ).length,
    totalActualCostCents,
    totalActualHours:
      Math.round(
        assignments.reduce(
          (sum, assignment) => sum + (assignment.actualHours ?? 0),
          0,
        ) * 100,
      ) / 100,
    totalEstimatedCostCents,
    totalEstimatedHours:
      Math.round(
        assignments.reduce(
          (sum, assignment) => sum + (assignment.estimatedHours ?? 0),
          0,
        ) * 100,
      ) / 100,
    totalVarianceCents:
      totalActualCostCents || totalEstimatedCostCents
        ? totalActualCostCents - totalEstimatedCostCents
        : 0,
    ratingCount: ratings.length,
  };
}

async function requireProposalContractorPlanningWrite(
  ctx: QueryCtx | MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
) {
  if (auth.proposal.status === "closed") {
    throw new Error("Closed proposals no longer accept planning contractors.");
  }
  if (isBackoffice(auth.roles)) {
    requireBackofficeProposalWrite(auth, auth.proposal);
  }
  await requireProposalAppPermission(ctx, auth, "contractor", "update");
  await assertProposalCollaborationEditAllowed(ctx, auth);
}

async function ensureProposalContractorAssignment(
  ctx: MutationCtx,
  input: {
    agreedRateCents?: number;
    agreedRateUnit?: "hour" | "day" | "fixed";
    auth: {
      brokerage: Doc<"brokerages">;
      proposal: Doc<"buildProposals">;
    };
    contractorId: Id<"contractorProfiles">;
    endDay?: number;
    notes?: string;
    proposalId: Id<"buildProposals">;
    preserveExistingRole?: boolean;
    role: string;
    startDay?: number;
    workosOrganizationId: string;
  },
) {
  const existing = await ctx.db
    .query("proposalContractorAssignments")
    .withIndex("by_proposal_contractor", (q) =>
      q
        .eq("proposalId", input.proposalId)
        .eq("contractorId", input.contractorId),
    )
    .unique();
  const now = Date.now();
  const patch = {
    agreedRateCents: normalizeOptionalMoneyCents(input.agreedRateCents),
    agreedRateUnit: input.agreedRateUnit,
    endDay:
      input.endDay === undefined
        ? undefined
        : Math.max(0, Math.round(input.endDay)),
    notes: normalizeOptionalString(input.notes),
    role: input.role.trim() || "Contractor",
    startDay:
      input.startDay === undefined
        ? undefined
        : Math.max(0, Math.round(input.startDay)),
    status: "active" as const,
    updatedAt: now,
  };
  if (existing) {
    await ctx.db.patch(existing._id, patch);
    if (input.preserveExistingRole) {
      await ctx.db.patch(existing._id, { role: existing.role });
    }
    return existing._id;
  }
  return await ctx.db.insert("proposalContractorAssignments", {
    ...patch,
    brokerageId: input.auth.brokerage._id,
    contractorId: input.contractorId,
    createdAt: now,
    organizationId: input.workosOrganizationId,
    proposalId: input.proposalId,
  });
}

async function resolveProposalAssignmentSubmilestones(
  ctx: QueryCtx | MutationCtx,
  input: {
    milestoneKey: string;
    proposalId: Id<"buildProposals">;
    submilestoneKeys: string[];
  },
) {
  if (input.submilestoneKeys.length === 0) {
    return [];
  }
  const submilestones = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_proposal", (q) => q.eq("proposalId", input.proposalId))
    .filter((q) => q.eq(q.field("milestoneKey"), input.milestoneKey))
    .collect();
  return input.submilestoneKeys.map((key) => {
    const submilestone = submilestones.find((row) => row.key === key);
    if (!submilestone) {
      throw new Error(`Proposal submilestone not found: ${key}`);
    }
    return { id: submilestone._id, key: submilestone.key };
  });
}

async function findProposalMilestoneContractorAssignment(
  ctx: QueryCtx | MutationCtx,
  input: {
    contractorId: Id<"contractorProfiles">;
    milestoneKey: string;
    proposalId: Id<"buildProposals">;
    submilestoneKey?: string;
  },
) {
  const assignments = await ctx.db
    .query("proposalMilestoneContractorAssignments")
    .withIndex("by_contractor_proposal", (q) =>
      q
        .eq("contractorId", input.contractorId)
        .eq("proposalId", input.proposalId),
    )
    .collect();
  return (
    assignments.find(
      (assignment) =>
        assignment.milestoneKey === input.milestoneKey &&
        assignment.submilestoneKey === input.submilestoneKey,
    ) ?? null
  );
}

async function proposalContractorPlanningProjection(
  ctx: QueryCtx | MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    documents: Doc<"proposalDocuments">[];
    milestones: Doc<"proposalMilestones">[];
    proposalId: Id<"buildProposals">;
    submilestones: Doc<"proposalSubmilestones">[];
  },
) {
  const [proposalContractors, milestoneAssignments, contractorProfiles] =
    await Promise.all([
      collectByIndex(
        ctx,
        "proposalContractorAssignments",
        "by_proposal",
        input.proposalId,
      ),
      collectByIndex(
        ctx,
        "proposalMilestoneContractorAssignments",
        "by_proposal",
        input.proposalId,
      ),
      ctx.db
        .query("contractorProfiles")
        .withIndex("by_brokerage", (q) =>
          q.eq("brokerageId", input.auth.brokerage._id),
        )
        .collect(),
    ]);
  const proposalContractorRows =
    proposalContractors as Doc<"proposalContractorAssignments">[];
  const milestoneAssignmentRows =
    milestoneAssignments as Doc<"proposalMilestoneContractorAssignments">[];
  const hydrated = await hydrateContractorProfiles(ctx, contractorProfiles);
  const contractorById = new Map(
    hydrated.map((contractor: any) => [String(contractor._id), contractor]),
  );
  const attachedIds = new Set(
    proposalContractorRows.map((assignment) => String(assignment.contractorId)),
  );
  const milestoneByKey = new Map(
    input.milestones.map((milestone) => [milestone.key, milestone]),
  );
  const submilestoneByComposite = new Map(
    input.submilestones.map((submilestone) => [
      `${submilestone.milestoneKey}:${submilestone.key}`,
      submilestone,
    ]),
  );
  const permitSignals = extractPermitMaterialSignals({
    documents: input.documents,
    milestones: input.milestones,
    submilestones: input.submilestones,
  });
  const assignmentViews = milestoneAssignmentRows
    .map((assignment) => {
      const contractor = contractorById.get(String(assignment.contractorId));
      const milestone = milestoneByKey.get(assignment.milestoneKey);
      if (!(contractor && milestone)) {
        return null;
      }
      const submilestone = assignment.submilestoneKey
        ? submilestoneByComposite.get(
            `${assignment.milestoneKey}:${assignment.submilestoneKey}`,
          )
        : null;
      return {
        _id: assignment._id,
        contractorId: assignment.contractorId,
        contractorName: contractor.name,
        dayEnd: milestone.dayEnd,
        dayStart: milestone.dayStart,
        estimatedCostCents: assignment.estimatedCostCents,
        estimatedHours: assignment.estimatedHours,
        milestoneKey: assignment.milestoneKey,
        milestoneName: milestone.name,
        role: assignment.role,
        status: assignment.status,
        submilestoneKey: assignment.submilestoneKey,
        submilestoneName: submilestone?.name,
      };
    })
    .filter(Boolean);
  const allocationCalendar = assignmentViews.map((assignment: any) => ({
    assignmentId: assignment._id,
    contractorId: assignment.contractorId,
    contractorName: assignment.contractorName,
    dayEnd: assignment.dayEnd,
    dayStart: assignment.dayStart,
    label: `${assignment.milestoneName} / ${assignment.role}`,
    milestoneKey: assignment.milestoneKey,
  }));
  const equipmentSchedule = assignmentViews.flatMap((assignment: any) => {
    const contractor = contractorById.get(String(assignment.contractorId));
    return (contractor?.equipment ?? []).map((equipment: any) => ({
      assignmentId: assignment._id,
      contractorId: assignment.contractorId,
      contractorName: assignment.contractorName,
      dayEnd: assignment.dayEnd,
      dayStart: assignment.dayStart,
      equipmentKey: equipment.equipmentKey,
      name: equipment.name,
      quantity: equipment.quantity,
    }));
  });
  const conflicts = detectAssignmentWindowConflicts(allocationCalendar);
  return {
    allocationCalendar,
    availableContractors: hydrated
      .filter(
        (contractor: any) =>
          contractor.status === "active" &&
          !attachedIds.has(String(contractor._id)),
      )
      .map(contractorOptionView),
    conflicts,
    equipmentSchedule,
    materialSignals: permitSignals,
    milestoneAssignments: assignmentViews,
    proposalContractors: proposalContractorRows
      .map((assignment) => {
        const contractor = contractorById.get(String(assignment.contractorId));
        if (!contractor) {
          return null;
        }
        return {
          _id: assignment._id,
          agreedRateCents:
            assignment.agreedRateCents ?? contractor.defaultPayRateCents,
          agreedRateUnit:
            assignment.agreedRateUnit ??
            contractor.defaultPayRateUnit ??
            "hour",
          city: contractor.city,
          contractorId: assignment.contractorId,
          defaultPayRateCents: contractor.defaultPayRateCents,
          defaultPayRateUnit: contractor.defaultPayRateUnit ?? "hour",
          endDay: assignment.endDay,
          email: contractor.email,
          name: contractor.name,
          onboardingStatus:
            contractor.onboardingStatus ??
            (contractor.accountWorkosUserId
              ? "account_linked"
              : "profile_only"),
          role: assignment.role,
          startDay: assignment.startDay,
          status: assignment.status,
          trades: contractor.trades,
        };
      })
      .filter(Boolean),
    recommendations: rankContractorsForPermitSignals({
      contractors: hydrated.filter(
        (contractor: any) => contractor.status === "active",
      ),
      conflicts,
      permitSignals,
    }),
    utilization: contractorUtilizationSummary({
      assignments: assignmentViews as any[],
      contractorProfiles: hydrated,
      proposalContractors: proposalContractorRows,
    }),
  };
}

function contractorOptionView(contractor: any) {
  return {
    _id: contractor._id,
    contractorId: String(contractor._id),
    city: contractor.city,
    defaultPayRateCents: contractor.defaultPayRateCents,
    defaultPayRateUnit: contractor.defaultPayRateUnit ?? "hour",
    email: contractor.email,
    name: contractor.name,
    onboardingStatus:
      contractor.onboardingStatus ??
      (contractor.accountWorkosUserId ? "account_linked" : "profile_only"),
    trades: contractor.trades,
  };
}

async function listAvailableContractorOptions(
  ctx: QueryCtx | MutationCtx,
  brokerageId: Id<"brokerages">,
) {
  const contractors = await ctx.db
    .query("contractorProfiles")
    .withIndex("by_brokerage", (q) => q.eq("brokerageId", brokerageId))
    .collect();

  return contractors
    .filter((contractor) => contractor.status === "active")
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(contractorOptionView);
}

function extractPermitMaterialSignals(input: {
  documents: Array<{ fileName: string; documentType?: string }>;
  milestones: Array<{ key: string; name: string }>;
  submilestones: Array<{ key: string; name: string }>;
}) {
  const haystack = [
    ...input.documents
      .filter((document) => document.documentType === "permit")
      .map((document) => document.fileName),
    ...input.milestones.flatMap((milestone) => [milestone.key, milestone.name]),
    ...input.submilestones.flatMap((submilestone) => [
      submilestone.key,
      submilestone.name,
    ]),
  ]
    .join(" ")
    .toLowerCase();
  const keywords = [
    ["brick", "Brick siding"],
    ["masonry", "Masonry"],
    ["siding", "Siding"],
    ["stone", "Stone veneer"],
    ["stucco", "Stucco"],
    ["roof", "Roofing"],
    ["frame", "Framing"],
    ["foundation", "Foundation"],
    ["concrete", "Concrete"],
    ["plumbing", "Plumbing"],
    ["electrical", "Electrical"],
  ] as const;
  return keywords
    .filter(([key]) => haystack.includes(key))
    .map(([key, label]) => ({ key, label, source: "permit_and_roadmap" }));
}

function rankContractorsForPermitSignals(input: {
  contractors: any[];
  conflicts: Array<{ contractorId: unknown }>;
  permitSignals: Array<{ key: string; label: string }>;
}) {
  const conflictIds = new Set(
    input.conflicts.map((conflict) => String(conflict.contractorId)),
  );
  return input.contractors
    .map((contractor) => {
      const searchable = [
        contractor.name,
        ...(contractor.trades ?? []),
        ...(contractor.capabilities ?? []).flatMap((capability: any) => [
          capability.capabilityKey,
          capability.label,
          capability.trade,
          capability.milestoneArchetypeKey,
        ]),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      const matches = input.permitSignals.filter((signal) =>
        searchable.includes(signal.key),
      );
      const score =
        matches.length * 35 +
        (contractor.defaultPayRateCents ? 10 : 0) -
        (conflictIds.has(String(contractor._id)) ? 30 : 0);
      return {
        contractorId: contractor._id,
        matchedSignals: matches,
        name: contractor.name,
        rateCents: contractor.defaultPayRateCents,
        score,
        trades: contractor.trades ?? [],
      };
    })
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
    .slice(0, 6);
}

function contractorUtilizationSummary(input: {
  assignments: Array<{
    contractorId: unknown;
    dayEnd?: number;
    dayStart?: number;
    estimatedHours?: number;
  }>;
  contractorProfiles: any[];
  proposalContractors: Array<{ contractorId: unknown }>;
}) {
  const profileById = new Map(
    input.contractorProfiles.map((profile) => [String(profile._id), profile]),
  );
  return input.proposalContractors.map((proposalContractor) => {
    const contractorId = String(proposalContractor.contractorId);
    const profile = profileById.get(contractorId);
    const assignments = input.assignments.filter(
      (assignment) => String(assignment.contractorId) === contractorId,
    );
    const assignedDays = assignments.reduce(
      (sum, assignment) =>
        sum +
        Math.max(
          1,
          Math.round((assignment.dayEnd ?? 0) - (assignment.dayStart ?? 0)),
        ),
      0,
    );
    const scheduledHours = assignments.reduce(
      (sum, assignment) => sum + (assignment.estimatedHours ?? 0),
      0,
    );
    const weeklyWindowHours = (profile?.availabilityWindows ?? []).reduce(
      (sum: number, window: any) =>
        sum + Math.max(0, window.endMinute - window.startMinute) / 60,
      0,
    );
    const capacityHours = Math.max(weeklyWindowHours, 1) * 4;
    return {
      assignedDays,
      contractorId: proposalContractor.contractorId,
      name: profile?.name ?? "Contractor",
      scheduledHours,
      utilizationPercent: Math.min(
        100,
        Math.round((scheduledHours / capacityHours) * 100),
      ),
      weeklyWindowHours,
    };
  });
}

function detectAssignmentWindowConflicts(
  assignments: Array<{
    assignmentId: unknown;
    contractorId: unknown;
    contractorName: string;
    dayEnd: number;
    dayStart: number;
    label: string;
  }>,
) {
  const conflicts = [];
  for (let i = 0; i < assignments.length; i += 1) {
    for (let j = i + 1; j < assignments.length; j += 1) {
      const left = assignments[i];
      const right = assignments[j];
      if (String(left.contractorId) !== String(right.contractorId)) {
        continue;
      }
      if (left.dayStart <= right.dayEnd && right.dayStart <= left.dayEnd) {
        conflicts.push({
          contractorId: left.contractorId,
          contractorName: left.contractorName,
          leftAssignmentId: left.assignmentId,
          leftLabel: left.label,
          overlapEndDay: Math.min(left.dayEnd, right.dayEnd),
          overlapStartDay: Math.max(left.dayStart, right.dayStart),
          rightAssignmentId: right.assignmentId,
          rightLabel: right.label,
          severity: "conflict" as const,
        });
      }
    }
  }
  return conflicts;
}

async function contractorIdentityLinkViews(
  ctx: QueryCtx | MutationCtx,
  input: {
    brokerageId: Id<"brokerages">;
    contractorId: Id<"contractorProfiles">;
  },
) {
  const [primaryLinks, linkedLinks] = await Promise.all([
    ctx.db
      .query("contractorIdentityLinks")
      .withIndex("by_primary", (q) =>
        q.eq("primaryContractorId", input.contractorId),
      )
      .collect(),
    ctx.db
      .query("contractorIdentityLinks")
      .withIndex("by_linked", (q) =>
        q.eq("linkedContractorId", input.contractorId),
      )
      .collect(),
  ]);
  const rows = [...primaryLinks, ...linkedLinks].filter(
    (row, index, all) =>
      all.findIndex((candidate) => candidate._id === row._id) === index,
  );
  return await Promise.all(
    rows.map(async (row) => {
      const isPrimary = row.primaryContractorId === input.contractorId;
      const peerId = isPrimary
        ? row.linkedContractorId
        : row.primaryContractorId;
      const peer = (await ctx.db.get(
        peerId,
      )) as Doc<"contractorProfiles"> | null;
      return {
        _id: row._id,
        confidence: row.confidence,
        direction: isPrimary ? "primary" : "linked",
        peerBrokerageId: isPrimary
          ? row.linkedBrokerageId
          : row.primaryBrokerageId,
        peerContractorId: peerId,
        peerName: peer?.name ?? "Linked contractor",
        reason: row.reason,
        status: row.status,
        updatedAt: row.updatedAt,
      };
    }),
  );
}

function contractorDetailIntelligence(input: {
  assignments: Doc<"milestoneContractorAssignments">[];
  profile: any;
  proposalAssignments: Doc<"proposalMilestoneContractorAssignments">[];
  ratings: Doc<"contractorQualityRatings">[];
}) {
  const activeBuildAssignmentCount = input.assignments.filter(
    (assignment) => assignment.status !== "removed",
  ).length;
  const plannedAssignmentCount = input.proposalAssignments.filter(
    (assignment) => assignment.status === "planned",
  ).length;
  const scheduledHours =
    input.assignments.reduce(
      (sum, assignment) => sum + (assignment.estimatedHours ?? 0),
      0,
    ) +
    input.proposalAssignments.reduce(
      (sum, assignment) => sum + (assignment.estimatedHours ?? 0),
      0,
    );
  const weeklyWindowHours = (input.profile.availabilityWindows ?? []).reduce(
    (sum: number, window: any) =>
      sum + Math.max(0, window.endMinute - window.startMinute) / 60,
    0,
  );
  const capabilityPerformance = (input.profile.capabilities ?? []).map(
    (capability: any) => {
      const searchable = [
        capability.capabilityKey,
        capability.label,
        capability.trade,
        capability.milestoneArchetypeKey,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      const matchingAssignments = input.assignments.filter((assignment) =>
        searchable.includes(assignment.milestoneKey.toLowerCase()),
      );
      const matchingRatings = input.ratings.filter((rating) =>
        matchingAssignments.some(
          (assignment) =>
            assignment.buildId === rating.buildId &&
            assignment.milestoneKey === rating.milestoneKey,
        ),
      );
      return {
        averageRating:
          matchingRatings.length === 0
            ? null
            : Math.round(
                (matchingRatings.reduce(
                  (sum, rating) => sum + rating.rating,
                  0,
                ) /
                  matchingRatings.length) *
                  10,
              ) / 10,
        capabilityKey: capability.capabilityKey,
        label: capability.label,
        ratingCount: matchingRatings.length,
        totalActualCostCents: matchingAssignments.reduce(
          (sum, assignment) => sum + (assignment.actualCostCents ?? 0),
          0,
        ),
        totalEstimatedCostCents: matchingAssignments.reduce(
          (sum, assignment) => sum + (assignment.estimatedCostCents ?? 0),
          0,
        ),
      };
    },
  );
  return {
    activeBuildAssignmentCount,
    capabilityPerformance,
    plannedAssignmentCount,
    scheduledHours: Math.round(scheduledHours * 100) / 100,
    utilizationPercent:
      weeklyWindowHours > 0
        ? Math.min(
            100,
            Math.round((scheduledHours / (weeklyWindowHours * 4)) * 100),
          )
        : null,
    weeklyWindowHours,
  };
}

async function ensureBuildContractorAssignment(
  ctx: MutationCtx,
  input: {
    agreedRateCents?: number;
    agreedRateUnit?: "hour" | "day" | "fixed";
    auth: {
      brokerage: Doc<"brokerages">;
      build: Doc<"activeBuilds">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    buildId: Id<"activeBuilds">;
    contractorId: Id<"contractorProfiles">;
    role: string;
    workosOrganizationId: string;
  },
) {
  const existing = await ctx.db
    .query("buildContractorAssignments")
    .withIndex("by_build_contractor", (q) =>
      q.eq("buildId", input.buildId).eq("contractorId", input.contractorId),
    )
    .unique();
  const now = Date.now();
  if (existing) {
    await ctx.db.patch(existing._id, {
      agreedRateCents:
        normalizeOptionalMoneyCents(input.agreedRateCents) ??
        existing.agreedRateCents,
      agreedRateUnit: input.agreedRateUnit ?? existing.agreedRateUnit,
      role: input.role.trim() || existing.role,
      status: "active",
      updatedAt: now,
    });
    return existing._id;
  }
  return await ctx.db.insert("buildContractorAssignments", {
    brokerageId: input.auth.brokerage._id,
    buildId: input.buildId,
    contractorId: input.contractorId,
    createdAt: now,
    agreedRateCents: normalizeOptionalMoneyCents(input.agreedRateCents),
    agreedRateUnit: input.agreedRateUnit,
    organizationId: input.workosOrganizationId,
    role: input.role.trim() || "Contractor",
    status: "active",
    updatedAt: now,
  });
}

async function resolveAssignmentSubmilestones(
  ctx: QueryCtx | MutationCtx,
  input: {
    buildId: Id<"activeBuilds">;
    milestoneKey: string;
    submilestoneKeys: string[];
  },
) {
  if (input.submilestoneKeys.length === 0) {
    return [];
  }
  const submilestones = await ctx.db
    .query("buildSubmilestones")
    .withIndex("by_build", (q) => q.eq("buildId", input.buildId))
    .filter((q) => q.eq(q.field("milestoneKey"), input.milestoneKey))
    .collect();
  return input.submilestoneKeys.map((key) => {
    const submilestone = submilestones.find((row) => row.key === key);
    if (!submilestone) {
      throw new ConvexError({
        code: "SUBMILESTONE_NOT_FOUND",
        message: "Submilestone is unavailable for this milestone.",
        submilestoneKey: key,
      });
    }
    return { id: submilestone._id, key: submilestone.key };
  });
}

async function findMilestoneContractorAssignment(
  ctx: QueryCtx | MutationCtx,
  input: {
    buildId: Id<"activeBuilds">;
    contractorId: Id<"contractorProfiles">;
    milestoneKey: string;
    submilestoneKey?: string;
  },
) {
  const assignments = await ctx.db
    .query("milestoneContractorAssignments")
    .withIndex("by_contractor_build", (q) =>
      q.eq("contractorId", input.contractorId).eq("buildId", input.buildId),
    )
    .collect();
  return (
    assignments.find(
      (assignment) =>
        assignment.milestoneKey === input.milestoneKey &&
        assignment.submilestoneKey === input.submilestoneKey,
    ) ?? null
  );
}

async function ensurePendingBuildAssignmentAcknowledgement(
  ctx: MutationCtx,
  input: {
    assignmentId: Id<"milestoneContractorAssignments">;
    brokerageId: Id<"brokerages">;
    contractorId: Id<"contractorProfiles">;
    now: number;
    organizationId: string;
  },
) {
  const acknowledgements = await ctx.db
    .query("contractorAcknowledgements")
    .withIndex("by_build_assignment", (q) =>
      q.eq("buildAssignmentId", input.assignmentId),
    )
    .collect();
  const existing = acknowledgements.find(
    (acknowledgement) => acknowledgement.kind === "assignment",
  );
  if (existing) {
    await ctx.db.patch(existing._id, {
      acknowledgedAt: undefined,
      state: "pending_acknowledgement",
      updatedAt: input.now,
    });
    return existing._id;
  }
  return await ctx.db.insert("contractorAcknowledgements", {
    assignmentType: "build",
    brokerageId: input.brokerageId,
    buildAssignmentId: input.assignmentId,
    contractorId: input.contractorId,
    kind: "assignment",
    organizationId: input.organizationId,
    state: "pending_acknowledgement",
    createdAt: input.now,
    updatedAt: input.now,
  });
}

async function resolveBuildAssignmentAcknowledgement(
  ctx: MutationCtx,
  assignmentId: Id<"milestoneContractorAssignments">,
  now: number,
) {
  const acknowledgements = await ctx.db
    .query("contractorAcknowledgements")
    .withIndex("by_build_assignment", (q) =>
      q.eq("buildAssignmentId", assignmentId),
    )
    .collect();
  for (const acknowledgement of acknowledgements) {
    if (
      acknowledgement.kind === "assignment" &&
      acknowledgement.state !== "resolved"
    ) {
      await ctx.db.patch(acknowledgement._id, {
        state: "resolved",
        updatedAt: now,
      });
    }
  }
}

async function upsertContractorAssignmentDelivery(
  ctx: MutationCtx,
  input: {
    assignmentId: Id<"milestoneContractorAssignments">;
    auth: ActiveBuildDeliveryAuth;
    contractor: Doc<"contractorProfiles">;
    milestone: Doc<"buildMilestones">;
    operation: "created" | "updated" | "removed";
  },
) {
  const recipientWorkosUserId = input.contractor.accountWorkosUserId;
  if (!recipientWorkosUserId) {
    return;
  }
  const now = Date.now();
  const activeKeys = [
    `contractor-assignment:${input.assignmentId}:created`,
    `contractor-assignment:${input.assignmentId}:updated`,
  ];
  if (input.operation !== "created") {
    for (const priorDedupeKey of activeKeys) {
      const priorDelivery = await ctx.db
        .query("recipientDeliveries")
        .withIndex("by_recipient_dedupe", (q) =>
          q
            .eq("organizationId", input.auth.build.organizationId)
            .eq("recipientWorkosUserId", recipientWorkosUserId)
            .eq("dedupeKey", priorDedupeKey),
        )
        .first();
      if (priorDelivery && priorDelivery.status !== "resolved") {
        await ctx.db.patch(priorDelivery._id, {
          status: "resolved",
          updatedAt: now,
        });
      }
    }
  }
  const dedupeKey = `contractor-assignment:${input.assignmentId}:${input.operation}`;
  const existing = await ctx.db
    .query("recipientDeliveries")
    .withIndex("by_recipient_dedupe", (q) =>
      q
        .eq("organizationId", input.auth.build.organizationId)
        .eq("recipientWorkosUserId", recipientWorkosUserId)
        .eq("dedupeKey", dedupeKey),
    )
    .first();
  const removed = input.operation === "removed";
  const delivery = {
    actionLabel: removed ? "View current work" : "Review assignment",
    actionRequired: !removed,
    body: removed
      ? `Your ${input.milestone.name} assignment is no longer active.`
      : `Review the ${input.milestone.name} scope and acknowledge it or request clarification.`,
    createdAt: now,
    entityId: String(input.assignmentId),
    entityLabel: `${input.auth.build.buildName} · ${input.milestone.name}`,
    entityType: "contractorAssignment",
    href: removed
      ? "/contractor/work"
      : `/contractor/builds/${input.auth.build._id}?assignmentId=${input.assignmentId}`,
    resolutionMode: "domain" as const,
    sourceLabel: "Builder",
    status: "unread" as const,
    title: removed
      ? `${input.milestone.name} assignment removed`
      : input.operation === "updated"
        ? `${input.milestone.name} assignment updated`
        : `${input.milestone.name} assignment ready`,
    updatedAt: now,
  };
  if (existing) {
    await ctx.db.patch(existing._id, delivery);
  } else {
    await ctx.db.insert("recipientDeliveries", {
      ...delivery,
      brokerageId: input.auth.brokerage._id,
      dedupeKey,
      organizationId: input.auth.build.organizationId,
      recipientWorkosUserId,
    });
  }
}

async function insertContractorQualityRating(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Pick<Doc<"brokerages">, "_id">;
      build: Doc<"activeBuilds">;
      proposal: Pick<Doc<"buildProposals">, "_id">;
      roles: RoleSlug[];
      subject: string;
    };
    buildId: Id<"activeBuilds">;
    contractorId: Id<"contractorProfiles">;
    milestoneKey: string;
    note?: string;
    rating: number;
    source: "builder_evidence" | "site_visit" | "backoffice";
    sourceEvidenceKey?: string;
    sourceVisitId?: string;
    submilestoneKey?: string;
    workosOrganizationId: string;
  },
) {
  const contractor = await getScopedContractorOrThrow(
    ctx,
    input.contractorId,
    input.auth.brokerage._id as Id<"brokerages">,
  );
  if (contractor.status !== "active") {
    throw new Error("Production contractor is inactive.");
  }
  const milestone = await getActiveBuildMilestoneOrThrow(
    ctx,
    input.buildId,
    input.milestoneKey,
  );
  const submilestone = input.submilestoneKey
    ? (
        await resolveAssignmentSubmilestones(ctx, {
          buildId: input.buildId,
          milestoneKey: input.milestoneKey,
          submilestoneKeys: [input.submilestoneKey],
        })
      )[0]
    : undefined;
  const assignment = await findMilestoneContractorAssignment(ctx, {
    buildId: input.buildId,
    contractorId: input.contractorId,
    milestoneKey: input.milestoneKey,
    submilestoneKey: input.submilestoneKey,
  });
  if (!assignment) {
    throw new Error("Contractor must be assigned before quality is rated.");
  }
  return await ctx.db.insert("contractorQualityRatings", {
    brokerageId: input.auth.brokerage._id as Id<"brokerages">,
    buildId: input.buildId,
    buildMilestoneId: milestone._id,
    buildSubmilestoneId: submilestone?.id,
    contractorId: input.contractorId,
    createdAt: Date.now(),
    createdByWorkosUserId: input.auth.subject,
    milestoneKey: input.milestoneKey,
    note: normalizeOptionalString(input.note),
    organizationId: input.workosOrganizationId,
    rating: normalizeQualityRating(input.rating),
    source: input.source,
    sourceEvidenceKey: normalizeOptionalString(input.sourceEvidenceKey),
    sourceVisitId: normalizeOptionalString(input.sourceVisitId),
    submilestoneKey: normalizeOptionalString(input.submilestoneKey),
  });
}

async function recordQualityRatingForMilestoneAssignments(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      build: Doc<"activeBuilds">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    buildId: Id<"activeBuilds">;
    milestone: Doc<"buildMilestones">;
    note?: string;
    rating: number;
    source: "builder_evidence" | "site_visit" | "backoffice";
    workosOrganizationId: string;
  },
) {
  const assignments = await ctx.db
    .query("milestoneContractorAssignments")
    .withIndex("by_build_milestone", (q) =>
      q.eq("buildId", input.buildId).eq("milestoneKey", input.milestone.key),
    )
    .collect();
  const seen = new Set<string>();
  for (const assignment of assignments) {
    const key = `${assignment.contractorId}:${assignment.submilestoneKey ?? ""}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    await insertContractorQualityRating(ctx, {
      auth: input.auth,
      buildId: input.buildId,
      contractorId: assignment.contractorId,
      milestoneKey: input.milestone.key,
      note: input.note,
      rating: input.rating,
      source: input.source,
      submilestoneKey: assignment.submilestoneKey,
      workosOrganizationId: input.workosOrganizationId,
    });
  }
}

function requireState(
  proposal: Doc<"buildProposals">,
  expected: Doc<"buildProposals">["status"],
) {
  if (proposal.status !== expected) {
    throw new Error(`Expected proposal state ${expected}.`);
  }
}

function requirePhase3BackofficeRole(auth: {
  roles: readonly RoleSlug[];
}) {
  const role = auth.roles.find((candidate) =>
    APPROVER_ROLES.includes(candidate as (typeof APPROVER_ROLES)[number]),
  );
  if (!role) {
    throw new Error("Forbidden: review policy authority");
  }
  return role;
}

function assertExpectedProposalReviewBase(input: {
  assignment: Doc<"proposalLenderAssignments"> | null;
  expectedAssignmentId: Id<"proposalLenderAssignments"> | null;
  expectedProposalRevisionNumber: number | null;
  proposal: Doc<"buildProposals">;
}) {
  const currentRevisionNumber = input.proposal.currentProposalRevisionNumber ?? null;
  if (input.expectedProposalRevisionNumber !== currentRevisionNumber) {
    throw new Error("Stale proposal revision.");
  }
  if ((input.assignment?._id ?? null) !== input.expectedAssignmentId) {
    throw new Error("Stale lender assignment.");
  }
}

async function getCurrentProposalReviewPolicyVersion(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
) {
  if (proposal.currentReviewPolicyVersionId) {
    const current = await ctx.db.get(proposal.currentReviewPolicyVersionId);
    if (
      !current ||
      current.proposalId !== proposal._id ||
      current.organizationId !== proposal.organizationId ||
      current.brokerageId !== proposal.brokerageId
    ) {
      throw new Error("Proposal review policy pointer is inconsistent.");
    }
    return current;
  }
  const versions = await ctx.db
    .query("proposalReviewPolicyVersions")
    .withIndex("by_proposal", (query) => query.eq("proposalId", proposal._id))
    .order("desc")
    .take(1);
  return versions[0] ?? null;
}

async function ensureDefaultProposalReviewPolicyVersion(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    now: number;
  },
) {
  const current = await getCurrentProposalReviewPolicyVersion(
    ctx,
    input.auth.proposal,
  );
  if (current) {
    if (!input.auth.proposal.currentReviewPolicyVersionId) {
      await ctx.db.patch(input.auth.proposal._id, {
        currentReviewPolicyVersionId: current._id,
      });
    }
    return current;
  }
  const configuredByRole = requirePhase3BackofficeRole(input.auth);
  const policyVersionId = await ctx.db.insert("proposalReviewPolicyVersions", {
    brokerageId: input.auth.brokerage._id,
    configuredAt: input.now,
    configuredByRole,
    configuredByWorkosUserId: input.auth.subject,
    idempotencyKey: "system:default-backoffice-policy",
    organizationId: input.auth.proposal.organizationId,
    policy: DEFAULT_PROPOSAL_REVIEW_POLICY,
    proposalId: input.auth.proposal._id,
    reason: "Initialize the default Back Office-only review policy.",
    version: 1,
  });
  await ctx.db.patch(input.auth.proposal._id, {
    currentReviewPolicyVersionId: policyVersionId,
  });
  const inserted = await ctx.db.get(policyVersionId);
  if (!inserted) {
    throw new Error("Failed to initialize proposal review policy.");
  }
  return inserted;
}

async function getCurrentProposalRevision(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
) {
  if (proposal.currentProposalRevisionId) {
    const current = await ctx.db.get(proposal.currentProposalRevisionId);
    if (
      !current ||
      current.proposalId !== proposal._id ||
      current.revisionNumber !== proposal.currentProposalRevisionNumber
    ) {
      throw new Error("Current proposal revision pointer is inconsistent.");
    }
    return current;
  }
  const revisions = await ctx.db
    .query("proposalRevisions")
    .withIndex("by_proposal_and_revision_number", (query) =>
      query.eq("proposalId", proposal._id),
    )
    .order("desc")
    .take(1);
  return revisions[0] ?? null;
}

async function getPriorLenderReviewedProposalRevision(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
) {
  if (proposal.latestLenderReviewedRevisionId) {
    const pointedRevision = await ctx.db.get(
      proposal.latestLenderReviewedRevisionId,
    );
    if (
      !pointedRevision ||
      pointedRevision.proposalId !== proposal._id ||
      (proposal.latestLenderReviewedRevisionNumber !== undefined &&
        pointedRevision.revisionNumber !==
          proposal.latestLenderReviewedRevisionNumber)
    ) {
      throw new Error("Latest lender-reviewed proposal revision pointer is inconsistent.");
    }
    return pointedRevision;
  }
  const decisions = await ctx.db
    .query("proposalLenderApprovals")
    .withIndex("by_proposal", (query) =>
      query.eq("proposalId", proposal._id),
    )
    .order("desc")
    .take(1_001);
  for (const decision of decisions) {
    if (!decision.proposalRevisionId) {
      continue;
    }
    const revision = await ctx.db.get(decision.proposalRevisionId);
    if (revision?.proposalId === proposal._id) {
      return revision;
    }
  }
  if (decisions.length > 1_000) {
    throw new Error(
      "Legacy lender approval history exceeds the safe revision-diff recovery boundary; run the Phase 3 lifecycle backfill.",
    );
  }
  return null;
}

async function buildProposalRevisionCheckpoints(
  ctx: QueryCtx | MutationCtx,
  input: {
    brokerage: Doc<"brokerages">;
    policy: ProposalReviewPolicySnapshot;
    proposal: Doc<"buildProposals">;
  },
): Promise<{
  checkpoints: ProposalRevisionCheckpointSnapshot;
  lenderContent: {
    costItems: ReturnType<typeof projectProposalDetailCostItem>[];
    documents: Array<{
      _id: Id<"proposalDocuments">;
      contractorVisible?: boolean;
      createdAt: number;
      documentType: "permit" | "budget" | "plan" | "supporting";
      fileName: string;
      mimeType: string;
      sizeBytes: number;
      status: "uploaded" | "linked" | "waived";
      storageId?: Id<"_storage">;
      storageUrl: null;
      updatedAt: number;
    }>;
    draws: ReturnType<typeof projectProposalDetailDraw>[];
    milestones: ReturnType<typeof projectProposalDetailMilestone>[];
    root: Infer<typeof proposalRevisionLenderContentSnapshotValidator>;
    submilestones: ReturnType<typeof projectProposalDetailSubmilestone>[];
  };
  milestones: Array<{
    dayEnd: number;
    dayStart: number;
    dependencyKeys: string[];
    durationDays: number;
    key: string;
    order: number;
  }>;
}> {
  const builderProfileId = assignedBuilderProfileIdOrThrow(
    input.proposal,
    "A proposal revision requires an assigned builder.",
  );
  const [
    builder,
    milestones,
    submilestones,
    costItems,
    draws,
    documents,
    permitWaiver,
    assignment,
    activeBuild,
  ] = await Promise.all([
    ctx.db.get(builderProfileId),
    ctx.db
      .query("proposalMilestones")
      .withIndex("by_proposal", (query) => query.eq("proposalId", input.proposal._id))
      .take(MAX_PROPOSAL_MILESTONES + 1),
    ctx.db
      .query("proposalSubmilestones")
      .withIndex("by_proposal", (query) => query.eq("proposalId", input.proposal._id))
      .take(MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS + 1),
    ctx.db
      .query("proposalCostItems")
      .withIndex("by_proposal", (query) => query.eq("proposalId", input.proposal._id))
      .take(MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS + 1),
    ctx.db
      .query("proposalDrawScheduleRows")
      .withIndex("by_proposal", (query) => query.eq("proposalId", input.proposal._id))
      .take(MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS + 1),
    ctx.db
      .query("proposalDocuments")
      .withIndex("by_proposal", (query) => query.eq("proposalId", input.proposal._id))
      .take(MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS + 1),
    getPermitWaiver(ctx, input.proposal._id),
    buildProposalIdentityProjection(ctx, input.proposal, input.brokerage),
    input.proposal.activeBuildId
      ? ctx.db.get(input.proposal.activeBuildId)
      : null,
  ]);
  if (milestones.length > MAX_PROPOSAL_MILESTONES) {
    throw new Error(`A proposal revision supports at most ${MAX_PROPOSAL_MILESTONES} milestones.`);
  }
  if (milestones.some((milestone) => milestone.dependencyKeys.length > MAX_PROPOSAL_MILESTONES)) {
    throw new Error(`A proposal revision milestone supports at most ${MAX_PROPOSAL_MILESTONES} dependencies.`);
  }
  if (
    milestones.length +
      submilestones.length +
      costItems.length +
      draws.length +
      documents.length >
    MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS
  ) {
    throw new Error(
      `A proposal revision supports at most ${MAX_PROPOSAL_REVISION_LENDER_CONTENT_ROWS} lender-visible content rows.`,
    );
  }
  if (
    !builder ||
    builder.brokerageId !== input.proposal.brokerageId ||
    builder.organizationId !== input.proposal.organizationId ||
    builder.status !== "active"
  ) {
    throw new Error("Proposal revision builder is outside the proposal scope.");
  }
  if (
    activeBuild &&
    (activeBuild.proposalId !== input.proposal._id ||
      activeBuild.brokerageId !== input.proposal.brokerageId ||
      activeBuild.organizationId !== input.proposal.organizationId)
  ) {
    throw new Error("Proposal revision active Build is outside the proposal scope.");
  }
  const scheduleMilestones = milestones
    .map((milestone) => ({
      dayEnd: milestone.dayEnd,
      dayStart: milestone.dayStart,
      dependencyKeys: [...milestone.dependencyKeys].sort(),
      durationDays: milestone.durationDays,
      key: milestone.key,
      order: milestone.order,
    }))
    .sort((left, right) =>
      left.order - right.order || left.key.localeCompare(right.key),
    );
  const milestonesFingerprint = await operationalRequestFingerprint(
    scheduleMilestones,
  );
  return {
    checkpoints: {
      accessReviewPolicy: input.policy,
      budget: { totalBudgetCents: input.proposal.totalBudgetCents },
      builder: {
        builderProfileId,
        displayName: builder.displayName,
      },
      milestoneCount: { count: scheduleMilestones.length },
      scheduleTimeline: {
        milestonesFingerprint,
        proposedStartDate: input.proposal.proposedStartDate ?? null,
        timelineRangeMax: input.proposal.timelineRangeMax ?? null,
        timelineRangeMin: input.proposal.timelineRangeMin ?? null,
      },
    },
    lenderContent: {
      costItems: costItems.map((item) =>
        projectProposalDetailCostItem(item, false),
      ),
      documents: documents.map((document) => ({
        _id: document._id,
        contractorVisible: document.contractorVisible,
        createdAt: document.createdAt,
        documentType: document.documentType,
        fileName: document.fileName,
        mimeType: document.mimeType,
        sizeBytes: document.sizeBytes,
        status: document.status,
        storageId: document.storageId,
        storageUrl: null,
        updatedAt: document.updatedAt,
      })),
      draws: draws.map((draw) => projectProposalDetailDraw(draw, false)),
      milestones: milestones.map(projectProposalDetailMilestone),
      root: {
        activeBuild: projectProposalDetailActiveBuild(activeBuild),
        assignment: projectProposalDetailAssignment(assignment, false),
        counts: {
          costItems: costItems.length,
          documents: documents.length,
          draws: draws.length,
          milestones: milestones.length,
          submilestones: submilestones.length,
        },
        permitWaiver: projectProposalDetailPermitWaiver(permitWaiver, false),
        proposal: projectProposalDetailProposal(input.proposal, false),
      },
      submilestones: submilestones.map(projectProposalDetailSubmilestone),
    },
    milestones: scheduleMilestones,
  };
}

async function createImmutableProposalRevision(
  ctx: MutationCtx,
  input: {
    assignment: Doc<"proposalLenderAssignments"> | null;
    auth: {
      brokerage: Doc<"brokerages">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    idempotencyKey: string;
    policyVersion: Doc<"proposalReviewPolicyVersions">;
    reason: string;
  },
) {
  const idempotencyKey = normalizeOperationalIdempotencyKey(
    input.idempotencyKey,
    "Proposal revision idempotency key",
  );
  const existing = await ctx.db
    .query("proposalRevisions")
    .withIndex("by_proposal_and_idempotency_key", (query) =>
      query
        .eq("proposalId", input.auth.proposal._id)
        .eq("idempotencyKey", idempotencyKey),
    )
    .unique();
  if (existing) {
    return existing;
  }
  if (input.auth.proposal.status !== "approved") {
    throw new Error("A lender-reviewable revision requires Back Office approval.");
  }
  if (!input.auth.proposal.backOfficeApprovedByWorkosUserId) {
    throw new Error("A proposal revision requires a Back Office approval reference.");
  }
  const createdByRole = requirePhase3BackofficeRole(input.auth);
  const [currentRevision, priorLenderReviewedRevision, revisionSnapshot] =
    await Promise.all([
      getCurrentProposalRevision(ctx, input.auth.proposal),
      getPriorLenderReviewedProposalRevision(ctx, input.auth.proposal),
      buildProposalRevisionCheckpoints(ctx, {
        brokerage: input.auth.brokerage,
        policy: input.policyVersion.policy,
        proposal: input.auth.proposal,
      }),
    ]);
  const revisionNumber = (currentRevision?.revisionNumber ?? 0) + 1;
  const changedCheckpoints = deterministicProposalRevisionDiff(
    priorLenderReviewedRevision?.checkpoints ?? null,
    revisionSnapshot.checkpoints,
  );
  const now = Date.now();
  requireReason(input.reason);
  const revisionId = await ctx.db.insert("proposalRevisions", {
    ...(input.assignment ? { assignmentId: input.assignment._id } : {}),
    backOfficeApprovedByWorkosUserId:
      input.auth.proposal.backOfficeApprovedByWorkosUserId,
    brokerageId: input.auth.brokerage._id,
    changedCheckpoints,
    checkpoints: revisionSnapshot.checkpoints,
    createdAt: now,
    createdByRole,
    createdByWorkosUserId: input.auth.subject,
    idempotencyKey,
    organizationId: input.auth.proposal.organizationId,
    ...(priorLenderReviewedRevision
      ? { priorLenderReviewedRevisionId: priorLenderReviewedRevision._id }
      : {}),
    proposalId: input.auth.proposal._id,
    reason: input.reason.trim(),
    revisionNumber,
    reviewPolicyVersionId: input.policyVersion._id,
  });
  for (const milestone of revisionSnapshot.milestones) {
    await ctx.db.insert("proposalRevisionMilestones", {
      brokerageId: input.auth.brokerage._id,
      organizationId: input.auth.proposal.organizationId,
      proposalId: input.auth.proposal._id,
      revisionId,
      ...milestone,
    });
  }
  const lenderContentScope = {
    brokerageId: input.auth.brokerage._id,
    organizationId: input.auth.proposal.organizationId,
    proposalId: input.auth.proposal._id,
    revisionId,
  };
  await ctx.db.insert("proposalRevisionLenderContentSnapshots", {
    ...lenderContentScope,
    ...revisionSnapshot.lenderContent.root,
    proposal: {
      ...revisionSnapshot.lenderContent.root.proposal,
      currentProposalRevisionId: revisionId,
      currentProposalRevisionNumber: revisionNumber,
      currentReviewPolicyVersionId: input.policyVersion._id,
    },
  });
  for (const document of revisionSnapshot.lenderContent.documents) {
    const { _id: sourceDocumentId, ...snapshot } = document;
    await ctx.db.insert("proposalRevisionLenderDocuments", {
      ...lenderContentScope,
      ...snapshot,
      sourceDocumentId,
    });
  }
  for (const milestone of revisionSnapshot.lenderContent.milestones) {
    const { _id: sourceMilestoneId, ...snapshot } = milestone;
    await ctx.db.insert("proposalRevisionLenderMilestones", {
      ...lenderContentScope,
      ...snapshot,
      sourceMilestoneId,
    });
  }
  for (const submilestone of revisionSnapshot.lenderContent.submilestones) {
    const { _id: sourceSubmilestoneId, ...snapshot } = submilestone;
    await ctx.db.insert("proposalRevisionLenderSubmilestones", {
      ...lenderContentScope,
      ...snapshot,
      sourceSubmilestoneId,
    });
  }
  for (const costItem of revisionSnapshot.lenderContent.costItems) {
    const { _id: sourceCostItemId, ...snapshot } = costItem;
    await ctx.db.insert("proposalRevisionLenderCostItems", {
      ...lenderContentScope,
      ...snapshot,
      sourceCostItemId,
    });
  }
  for (const draw of revisionSnapshot.lenderContent.draws) {
    const { _id: sourceDrawId, ...snapshot } = draw;
    await ctx.db.insert("proposalRevisionLenderDraws", {
      ...lenderContentScope,
      ...snapshot,
      sourceDrawId,
    });
  }
  await ctx.db.patch(input.auth.proposal._id, {
    currentProposalRevisionId: revisionId,
    currentProposalRevisionNumber: revisionNumber,
    updatedAt: now,
    updatedByWorkosUserId: input.auth.subject,
  });
  if (input.assignment) {
    await openProposalLenderConfirmationCycle(ctx, {
      assignment: input.assignment,
      proposal: input.auth.proposal,
      proposalRevisionId: revisionId,
      proposalRevisionNumber: revisionNumber,
    });
  }
  const revision = await ctx.db.get(revisionId);
  if (!revision) {
    throw new Error("Failed to create proposal revision.");
  }
  return revision;
}

async function openProposalLenderConfirmationCycle(
  ctx: MutationCtx,
  input: {
    assignment: Doc<"proposalLenderAssignments">;
    proposal: Doc<"buildProposals">;
    proposalRevisionId: Id<"proposalRevisions">;
    proposalRevisionNumber: number;
  },
) {
  const existing = await ctx.db
    .query("proposalLenderConfirmationCycles")
    .withIndex("by_assignment_and_revision", (query) =>
      query
        .eq("assignmentId", input.assignment._id)
        .eq("proposalRevisionId", input.proposalRevisionId),
    )
    .unique();
  if (existing) {
    return existing;
  }
  const [latestCycle, pendingCycles] = await Promise.all([
    ctx.db
      .query("proposalLenderConfirmationCycles")
      .withIndex("by_assignment_and_cycle_number", (query) =>
        query.eq("assignmentId", input.assignment._id),
      )
      .order("desc")
      .take(1),
    ctx.db
      .query("proposalLenderConfirmationCycles")
      .withIndex("by_assignment_and_status", (query) =>
        query.eq("assignmentId", input.assignment._id).eq("status", "pending"),
      )
      .take(2),
  ]);
  if (pendingCycles.length > 1) {
    throw new Error("Proposal assignment has multiple pending confirmation cycles.");
  }
  const now = Date.now();
  for (const pendingCycle of pendingCycles) {
    await ctx.db.patch(pendingCycle._id, {
      closedAt: now,
      status: "superseded",
      supersededAt: now,
    });
  }
  const confirmationCycleId = await ctx.db.insert(
    "proposalLenderConfirmationCycles",
    {
      assignmentId: input.assignment._id,
      brokerageId: input.proposal.brokerageId,
      createdAt: now,
      cycleNumber: (latestCycle[0]?.cycleNumber ?? 0) + 1,
      openedAt: now,
      organizationId: input.proposal.organizationId,
      proposalId: input.proposal._id,
      proposalRevisionId: input.proposalRevisionId,
      proposalRevisionNumber: input.proposalRevisionNumber,
      status: "pending",
    },
  );
  const cycle = await ctx.db.get(confirmationCycleId);
  if (!cycle) {
    throw new Error("Failed to create proposal confirmation cycle.");
  }
  return cycle;
}

async function getCurrentProposalLenderConfirmationCycle(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
  assignment: Doc<"proposalLenderAssignments">,
) {
  const revision = await getCurrentProposalRevision(ctx, proposal);
  if (!revision || revision.assignmentId !== assignment._id) {
    return null;
  }
  return await ctx.db
    .query("proposalLenderConfirmationCycles")
    .withIndex("by_assignment_and_revision", (query) =>
      query
        .eq("assignmentId", assignment._id)
        .eq("proposalRevisionId", revision._id),
    )
    .unique();
}

async function getProposalConfirmationDecision(
  ctx: QueryCtx | MutationCtx,
  cycle: Doc<"proposalLenderConfirmationCycles">,
) {
  if (cycle.decisionId) {
    const decision = await ctx.db.get(cycle.decisionId);
    if (
      !decision ||
      decision.confirmationCycleId !== cycle._id ||
      decision.proposalRevisionId !== cycle.proposalRevisionId
    ) {
      throw new Error("Proposal confirmation decision pointer is inconsistent.");
    }
    return decision;
  }
  const decisions = await ctx.db
    .query("proposalLenderApprovals")
    .withIndex("by_confirmation_cycle", (query) =>
      query.eq("confirmationCycleId", cycle._id),
    )
    .take(2);
  if (decisions.length > 1) {
    throw new Error("Proposal confirmation cycle has multiple decisions.");
  }
  return decisions[0] ?? null;
}

async function projectProposalConfirmationCycle(
  ctx: QueryCtx | MutationCtx,
  cycle: Doc<"proposalLenderConfirmationCycles">,
  options: { includePrivateActors: boolean; includePrivateReason: boolean },
) {
  const [acknowledgements, decision, revision] = await Promise.all([
    ctx.db
      .query("proposalLenderConfirmationAcknowledgements")
      .withIndex("by_cycle", (query) =>
        query.eq("confirmationCycleId", cycle._id),
      )
      .collect(),
    getProposalConfirmationDecision(ctx, cycle),
    ctx.db.get(cycle.proposalRevisionId),
  ]);
  if (!revision || revision.proposalId !== cycle.proposalId) {
    throw new Error("Proposal confirmation revision is unavailable.");
  }
  acknowledgements.sort(
    (left, right) =>
      left.sequence - right.sequence ||
      left.acknowledgedAt - right.acknowledgedAt,
  );
  return {
    acknowledgements: acknowledgements.map((acknowledgement) => ({
      acknowledgedAt: acknowledgement.acknowledgedAt,
      ...(options.includePrivateActors
        ? {
            acknowledgedByRole: acknowledgement.acknowledgedByRole,
            acknowledgedByWorkosUserId:
              acknowledgement.acknowledgedByWorkosUserId,
          }
        : {}),
      acknowledgementId: acknowledgement._id,
      checkpoint: acknowledgement.checkpoint,
      sequence: acknowledgement.sequence,
    })),
    assignmentId: cycle.assignmentId,
    changedCheckpoints: revision.changedCheckpoints,
    checkpoints: revision.checkpoints,
    confirmationCycleId: cycle._id,
    cycleNumber: cycle.cycleNumber,
    decision: decision
      ? {
          decidedAt: decision.approvedAt ?? decision.declinedAt ?? decision.createdAt,
          ...(options.includePrivateActors
            ? {
                decidedByRole: decision.approverRole,
                decidedByWorkosUserId: decision.approverWorkosUserId,
              }
            : {}),
          decisionId: decision._id,
          ...(decision.declinedCheckpoint
            ? { declinedCheckpoint: decision.declinedCheckpoint }
            : {}),
          ...(options.includePrivateReason && decision.reason
            ? { reason: decision.reason }
            : {}),
          status: decision.status,
        }
      : null,
    openedAt: cycle.openedAt,
    proposalRevisionId: cycle.proposalRevisionId,
    proposalRevisionNumber: cycle.proposalRevisionNumber,
    status: cycle.status,
  };
}

async function paginateProposalConfirmationCycles(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
  paginationOpts: PaginationOptions,
  assignmentId?: Id<"proposalLenderAssignments">,
) {
  if (assignmentId) {
    return await ctx.db
      .query("proposalLenderConfirmationCycles")
      .withIndex("by_assignment_and_cycle_number", (query) =>
        query.eq("assignmentId", assignmentId),
      )
      .order("desc")
      .paginate(paginationOpts);
  }
  return await ctx.db
    .query("proposalLenderConfirmationCycles")
    .withIndex("by_proposal", (query) => query.eq("proposalId", proposalId))
    .order("desc")
    .paginate(paginationOpts);
}

function projectLenderSnapshotRevision(
  revision: Doc<"proposalRevisions">,
) {
  if (!revision.assignmentId) {
    throw new Error("Lender snapshot revision is missing its assignment scope.");
  }
  return {
    assignmentId: revision.assignmentId,
    changedCheckpoints: revision.changedCheckpoints,
    checkpoints: revision.checkpoints,
    createdAt: revision.createdAt,
    ...(revision.priorLenderReviewedRevisionId
      ? {
          priorLenderReviewedRevisionId:
            revision.priorLenderReviewedRevisionId,
        }
      : {}),
    revisionId: revision._id,
    revisionNumber: revision.revisionNumber,
    reviewPolicyVersionId: revision.reviewPolicyVersionId,
  };
}

function projectLenderSnapshotDecision(
  decision: Doc<"proposalLenderApprovals">,
) {
  return {
    approvalId: decision._id,
    ...(decision.approvedAt === undefined
      ? {}
      : { approvedAt: decision.approvedAt }),
    ...(decision.declinedAt === undefined
      ? {}
      : { declinedAt: decision.declinedAt }),
    ...(decision.proposalRevisionId ? { proposalRevisionId: decision.proposalRevisionId } : {}),
    ...(decision.proposalRevisionNumber === undefined ? {} : { proposalRevisionNumber: decision.proposalRevisionNumber }),
    ...(!decision.proposalRevisionId || decision.proposalRevisionNumber === undefined
      ? { migrationStatus: "legacy_unlinked" as const }
      : {}),
    status: decision.status,
  };
}

function buildLenderSnapshotHistory(input: {
  assignment: Doc<"proposalLenderAssignments">;
  decisions: ReturnType<typeof projectLenderSnapshotDecision>[];
  revisions: ReturnType<typeof projectLenderSnapshotRevision>[];
}) {
  const history = [
    {
      kind: "assignment_created" as const,
      occurredAt: input.assignment.assignedAt,
    },
    ...input.revisions.map((revision) => ({
      kind: "revision_published" as const,
      occurredAt: revision.createdAt,
      proposalRevisionNumber: revision.revisionNumber,
    })),
    ...input.decisions.map((decision) => ({
      kind: "decision_recorded" as const,
      occurredAt:
        decision.status === "approved"
          ? (decision.approvedAt ?? 0)
          : (decision.declinedAt ?? 0),
      proposalRevisionNumber: decision.proposalRevisionNumber,
      status: decision.status,
    })),
    ...(input.assignment.withdrawnAt === undefined
      ? []
      : [
          {
            kind: "assignment_withdrawn" as const,
            occurredAt: input.assignment.withdrawnAt,
          },
        ]),
  ];
  return history.sort(
    (left, right) =>
      left.occurredAt - right.occurredAt || left.kind.localeCompare(right.kind),
  );
}

async function projectLenderSnapshotDocuments(
  ctx: QueryCtx | MutationCtx,
  documents: Array<
    Pick<
      Doc<"proposalDocuments">,
      | "_id"
      | "createdAt"
      | "documentType"
      | "fileName"
      | "mimeType"
      | "sizeBytes"
      | "status"
      | "storageId"
      | "updatedAt"
    >
  >,
) {
  return await Promise.all(
    documents.map(async (document) => ({
      createdAt: document.createdAt,
      documentId: document._id,
      documentType: document.documentType,
      fileName: document.fileName,
      mimeType: document.mimeType,
      sizeBytes: document.sizeBytes,
      status: document.status,
      ...(document.storageId
        ? {
            storageId: document.storageId,
            storageUrl:
              (await ctx.storage.getUrl(document.storageId)) ?? undefined,
          }
        : {}),
      updatedAt: document.updatedAt,
    })),
  );
}

async function buildLiveLenderAssignmentSnapshot(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
  assignment: Doc<"proposalLenderAssignments">,
) {
  const latestDecision = await ctx.db
    .query("proposalLenderApprovals")
    .withIndex("by_assignment", (query) => query.eq("assignmentId", assignment._id))
    .order("desc")
    .first();
  const lifecycle = projectProposalLifecycle(proposal, {
    lenderConfirmation:
      assignment.status === "withdrawn"
        ? "pending"
        : latestDecision?.status ?? "pending",
    state: assignment.status === "withdrawn" ? "withdrawn" : "assigned",
  });
  return {
    assignmentId: assignment._id,
    capturedAt: assignment.withdrawnAt ?? proposal.updatedAt,
    lifecycle,
    proposal: {
      buildName: proposal.buildName,
      location: proposal.location,
      status: proposal.status,
    },
  };
}

async function createLenderAssignmentManifest(
  ctx: MutationCtx,
  proposal: Doc<"buildProposals">,
  assignment: Doc<"proposalLenderAssignments">,
  capturedAt: number,
  reviewPolicyVersionId: Id<"proposalReviewPolicyVersions">,
) {
  const existing = await ctx.db
    .query("proposalLenderAssignmentManifests")
    .withIndex("by_assignment", (query) =>
      query.eq("assignmentId", assignment._id),
    )
    .unique();
  if (existing) {
    return existing;
  }
  const lenderOrganizationId = ctx.db.normalizeId(
    "lenderOrganizations",
    String(assignment.lenderOrganizationId),
  );
  if (!lenderOrganizationId) {
    throw new Error(
      "Lender assignment must be reconciled before its historical manifest can be frozen.",
    );
  }
  const snapshot = await buildLiveLenderAssignmentSnapshot(ctx, proposal, {
    ...assignment,
    status: "withdrawn",
    withdrawnAt: capturedAt,
  });
  // This indexed read is the transactional document/archive cutover barrier.
  // A concurrent document insert changes the range and forces Convex to retry
  // the withdrawal before it can commit the manifest boundary.
  const latestDocument = await ctx.db
    .query("proposalDocuments")
    .withIndex("by_proposal", (query) => query.eq("proposalId", proposal._id))
    .order("desc")
    .first();
  const manifestId = await ctx.db.insert("proposalLenderAssignmentManifests", {
    assignmentId: assignment._id,
    brokerageId: proposal.brokerageId,
    capturedAt: snapshot.capturedAt,
    lenderOrganizationId,
    lifecycleSnapshot: snapshot.lifecycle,
    organizationId: proposal.organizationId,
    proposalId: proposal._id,
    proposalSnapshot: snapshot.proposal,
    attemptCount: 0,
    cursor: null,
    ...(latestDocument
      ? { documentCreationTimeCutoff: latestDocument._creationTime }
      : {}),
    documentCutoffVersion: 1,
    lastAttemptAt: capturedAt,
    phase: "documents",
    reviewPolicyVersionId,
    status: "building",
    version: 2,
  });
  const inserted = await ctx.db.get(manifestId);
  if (!inserted) {
    throw new Error("Failed to freeze the lender assignment manifest.");
  }
  return inserted;
}

function archiveFailureReason(error: unknown): string {
  const message =
    error instanceof Error ? error.message : "Unknown archive finalization error.";
  return message.slice(0, 1_000);
}

export const finalizeLenderAssignmentManifest = internalMutation
  .input({ manifestId: v.id("proposalLenderAssignmentManifests") })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const manifest = await ctx.db.get(args.manifestId);
    if (!manifest || manifest.status === "sealed") return null;
    if (manifest.status !== "building" || manifest.phase !== "decisions") {
      throw new Error("Lender assignment archive is not ready for finalization.");
    }
    const [assignment, proposal] = await Promise.all([
      ctx.db.get(manifest.assignmentId),
      ctx.db.get(manifest.proposalId),
    ]);
    if (
      !assignment ||
      !proposal ||
      assignment.status !== "archiving" ||
      assignment.archiveManifestId !== manifest._id
    ) {
      throw new Error("Lender assignment archive state is inconsistent.");
    }
    const policyVersion = manifest.reviewPolicyVersionId
      ? await ctx.db.get(manifest.reviewPolicyVersionId)
      : null;
    const brokerage = await ctx.db.get(proposal.brokerageId);
    const withdrawnByRole = assignment.withdrawnByRole
      ? normalizeRoleSlugs([assignment.withdrawnByRole]).find((role) =>
          APPROVER_ROLES.includes(role as (typeof APPROVER_ROLES)[number]),
        )
      : undefined;
    if (
      !policyVersion ||
      policyVersion.proposalId !== proposal._id ||
      !brokerage ||
      !withdrawnByRole ||
      !assignment.withdrawnByWorkosUserId
    ) {
      throw new Error(
        "Lender assignment archive finalization prerequisites are unavailable.",
      );
    }
    await createImmutableProposalRevision(ctx, {
      assignment: null,
      auth: {
        brokerage,
        proposal,
        roles: [withdrawnByRole],
        subject: assignment.withdrawnByWorkosUserId,
      },
      idempotencyKey: `system:lender-withdrawal:${assignment._id}`,
      policyVersion,
      reason: assignment.withdrawalReason ?? "Withdraw lender assignment.",
    });
    const now = Date.now();
    await ctx.db.patch(manifest._id, {
      cursor: null,
      failureReason: undefined,
      failedAt: undefined,
      lastAttemptAt: now,
      phase: "complete",
      sealedAt: now,
      status: "sealed",
    });
    await ctx.db.patch(assignment._id, { status: "withdrawn" });
    await upsertKanbanCard(ctx, proposal._id, now);
    return null;
  })
  .internal();

export const sealLenderAssignmentManifestBatch = internalMutation
  .input({ manifestId: v.id("proposalLenderAssignmentManifests") })
  .returns(v.null())
  .handler(async (ctx, args) => {
    const manifest = await ctx.db.get(args.manifestId);
    if (!manifest || manifest.status === "sealed" || manifest.status === "failed") {
      return null;
    }
    try {
      const assignment = await ctx.db.get(manifest.assignmentId);
      const proposal = await ctx.db.get(manifest.proposalId);
      if (!assignment || !proposal || assignment.status !== "archiving" || assignment.archiveManifestId !== manifest._id) {
        throw new Error("Lender assignment archive state is inconsistent.");
      }

      if (manifest.phase === "documents") {
        if (
          manifest.documentCutoffVersion === 1 &&
          manifest.documentCreationTimeCutoff === undefined
        ) {
          await ctx.db.patch(manifest._id, { cursor: null, phase: "revisions" });
        } else {
          const page = manifest.documentCutoffVersion === 1
            ? await ctx.db.query("proposalDocuments")
                .withIndex("by_proposal", (query) =>
                  query
                    .eq("proposalId", proposal._id)
                    .lte("_creationTime", manifest.documentCreationTimeCutoff!),
                )
                .paginate({ cursor: manifest.cursor ?? null, numItems: LENDER_ASSIGNMENT_ARCHIVE_BATCH_SIZE })
            : await ctx.db.query("proposalDocuments")
                .withIndex("by_proposal", (query) => query.eq("proposalId", proposal._id))
                .filter((query) => query.lte(query.field("createdAt"), manifest.capturedAt))
                .paginate({ cursor: manifest.cursor ?? null, numItems: LENDER_ASSIGNMENT_ARCHIVE_BATCH_SIZE });
          for (const document of page.page) {
            const existing = await ctx.db.query("proposalLenderAssignmentManifestDocuments")
              .withIndex("by_manifest_and_document", (query) => query.eq("manifestId", manifest._id).eq("documentId", document._id)).unique();
            if (!existing) {
              const projected = (await projectLenderSnapshotDocuments(ctx, [document]))[0];
              if (!projected) continue;
              const { storageUrl: _storageUrl, ...storedDocument } = projected;
              await ctx.db.insert("proposalLenderAssignmentManifestDocuments", { manifestId: manifest._id, ...storedDocument });
            }
          }
          await ctx.db.patch(manifest._id, page.isDone
            ? { cursor: null, phase: "revisions" }
            : { cursor: page.continueCursor });
        }
      } else if (manifest.phase === "revisions") {
        const page = await ctx.db.query("proposalRevisions")
          .withIndex("by_assignment_and_revision_number", (query) => query.eq("assignmentId", assignment._id))
          .order("asc")
          .paginate({ cursor: manifest.cursor ?? null, numItems: LENDER_ASSIGNMENT_ARCHIVE_BATCH_SIZE });
        for (const revision of page.page) {
          const existing = await ctx.db.query("proposalLenderAssignmentManifestRevisions")
            .withIndex("by_manifest_and_revision", (query) => query.eq("manifestId", manifest._id).eq("revisionId", revision._id)).unique();
          if (!existing) await ctx.db.insert("proposalLenderAssignmentManifestRevisions", { manifestId: manifest._id, ...projectLenderSnapshotRevision(revision) });
        }
        await ctx.db.patch(manifest._id, page.isDone
          ? { cursor: null, phase: "decisions" }
          : { cursor: page.continueCursor });
      } else if (manifest.phase === "decisions") {
        const page = await ctx.db.query("proposalLenderApprovals")
          .withIndex("by_assignment", (query) => query.eq("assignmentId", assignment._id))
          .order("asc")
          .paginate({ cursor: manifest.cursor ?? null, numItems: LENDER_ASSIGNMENT_ARCHIVE_BATCH_SIZE });
        for (const decision of page.page) {
          const existing = await ctx.db.query("proposalLenderAssignmentManifestDecisions")
            .withIndex("by_manifest_and_approval", (query) => query.eq("manifestId", manifest._id).eq("approvalId", decision._id)).unique();
          if (!existing) await ctx.db.insert("proposalLenderAssignmentManifestDecisions", { manifestId: manifest._id, ...projectLenderSnapshotDecision(decision) });
        }
        if (!page.isDone) {
          await ctx.db.patch(manifest._id, { cursor: page.continueCursor });
        } else {
          const finalized: null = await ctx.runMutation(
            internal.production_proposals.finalizeLenderAssignmentManifest,
            { manifestId: manifest._id },
          );
          return finalized;
        }
      }
      const updated = await ctx.db.get(manifest._id);
      if (updated?.status === "building") {
        await ctx.scheduler.runAfter(0, internal.production_proposals.sealLenderAssignmentManifestBatch, { manifestId: manifest._id });
      }
      return null;
    } catch (error) {
      const failedAt = Date.now();
      await ctx.db.patch(manifest._id, {
        attemptCount: (manifest.attemptCount ?? 0) + 1,
        failedAt,
        failureReason: archiveFailureReason(error),
        lastAttemptAt: failedAt,
        status: "failed",
      });
      return null;
    }
  })
  .internal();

async function getCurrentProposalLenderAssignment(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
) {
  const assignments = await ctx.db
    .query("proposalLenderAssignments")
    .withIndex("by_proposal_status", (query) =>
      query.eq("proposalId", proposalId).eq("status", "current"),
    )
    .take(2);
  if (assignments.length > 1) {
    throw new Error("Proposal has multiple current lender assignments.");
  }
  return assignments[0] ?? null;
}

async function assertNoArchivingProposalLenderAssignment(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
) {
  const archiving = await ctx.db
    .query("proposalLenderAssignments")
    .withIndex("by_proposal_status", (query) =>
      query.eq("proposalId", proposalId).eq("status", "archiving"),
    )
    .first();
  if (archiving) {
    throw new Error(
      "The lender assignment archive is still sealing; retry this lifecycle command after archival completes.",
    );
  }
}

async function requireLenderVisibleAssignment(
  ctx: QueryCtx & { activeOrganization: ActiveLenderOrganizationContext },
  proposalId: Id<"buildProposals">,
  assignmentId: Id<"proposalLenderAssignments">,
) {
  const assignment = await ctx.db.get(assignmentId);
  if (
    !assignment ||
    assignment.proposalId !== proposalId ||
    assignment.lenderOrganizationId !== ctx.activeOrganization.lenderOrganizationId ||
    assignment.lenderBrokerageId !== ctx.activeOrganization.brokerageId
  ) {
    throw new Error("Forbidden: lender proposal assignment");
  }
  if (assignment.status === "archiving") {
    throw new Error("Lender assignment archive is still sealing.");
  }
  return assignment;
}

type ProposalLifecycleActorAuth = {
  brokerage: Doc<"brokerages">;
  currentLenderAssignment: Doc<"proposalLenderAssignments"> | null;
  lenderOrganization?: ActiveLenderOrganizationContext;
  isCurrentLenderActor: boolean;
  organizationId: string;
  proposal: Doc<"buildProposals">;
  roles: RoleSlug[];
  subject: string;
};

async function authorizeProposalLifecycleActor(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  proposalId: Id<"buildProposals">,
  workosOrganizationId: string,
  lenderPermission?: "proposal_review",
): Promise<ProposalLifecycleActorAuth> {
  const proposal = await ctx.db.get(proposalId);
  if (!proposal) {
    throw new Error("Forbidden: proposal scope");
  }

  if (workosOrganizationId === proposal.organizationId) {
    const auth = await authorizeProposal(
      ctx,
      proposalId,
      workosOrganizationId,
    );
    return {
      ...auth,
      currentLenderAssignment: await getCurrentProposalLenderAssignment(
        ctx,
        proposalId,
      ),
      isCurrentLenderActor: false,
      organizationId: proposal.organizationId,
    };
  }

  return authorizeLenderProposalLifecycleActor(
    ctx,
    proposalId,
    workosOrganizationId,
    lenderPermission,
    proposal,
  );
}

async function authorizeLenderProposalLifecycleActor(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  proposalId: Id<"buildProposals">,
  workosOrganizationId: string,
  lenderPermission?: "proposal_review",
  knownProposal?: Doc<"buildProposals">,
): Promise<ProposalLifecycleActorAuth> {
  const proposal = knownProposal ?? (await ctx.db.get(proposalId));
  if (!proposal) {
    throw new Error("Forbidden: proposal scope");
  }

  const identity = await ctx.auth.getUserIdentity();
  if (!identity) {
    throw new Error("Unauthorized");
  }
  const authorization = await resolveActiveLenderOrganizationContext(
    ctx,
    identity,
    "lenderOrganization",
  );
  if (lenderPermission) {
    await requireLenderOrganizationPermission(
      ctx,
      authorization.activeOrganization,
      lenderPermission,
    );
  }
  if (workosOrganizationId !== FAIRLEND_WORKOS_ORGANIZATION_ID) {
    throw new Error("Forbidden: active lender organization");
  }
  const currentLenderAssignment = await getCurrentProposalLenderAssignment(
    ctx,
    proposalId,
  );
  if (
    !currentLenderAssignment ||
    currentLenderAssignment.lenderOrganizationId !==
      authorization.activeOrganization.lenderOrganizationId ||
    currentLenderAssignment.lenderBrokerageId !==
      authorization.activeOrganization.brokerageId ||
    currentLenderAssignment.brokerageId !== proposal.brokerageId ||
    currentLenderAssignment.organizationId !== proposal.organizationId
  ) {
    throw new Error("Forbidden: current lender assignment");
  }
  const brokerage = await ctx.db.get(proposal.brokerageId);
  if (!brokerage || brokerage.status !== "active") {
    throw new Error("Forbidden: proposal brokerage");
  }
  return {
    brokerage,
    currentLenderAssignment,
    lenderOrganization: authorization.activeOrganization,
    isCurrentLenderActor: true,
    organizationId: proposal.organizationId,
    proposal,
    roles: normalizeRoleSlugs(authorization.viewer.roles),
    subject: authorization.viewer.subject,
  };
}

async function getCurrentProposalLenderApproval(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
  assignmentId: Id<"proposalLenderAssignments">,
  proposalRevisionId: Id<"proposalRevisions">,
) {
  const proposal = await ctx.db.get(proposalId);
  if (proposal?.latestLenderApprovalId) {
    const pointed = await ctx.db.get(proposal.latestLenderApprovalId);
    if (
      pointed?.proposalId === proposalId &&
      pointed.assignmentId === assignmentId &&
      pointed.proposalRevisionId === proposalRevisionId &&
      pointed.status === "approved"
    ) {
      return pointed;
    }
  }
  const approvals = await ctx.db
    .query("proposalLenderApprovals")
    .withIndex("by_proposal_assignment_status", (query) =>
      query
        .eq("proposalId", proposalId)
        .eq("assignmentId", assignmentId)
        .eq("status", "approved"),
    )
    .filter((query) => query.eq(query.field("proposalRevisionId"), proposalRevisionId))
    .take(2);
  if (approvals.length > 1) {
    throw new Error("Proposal has multiple current lender approvals.");
  }
  return approvals[0] ?? null;
}

async function getLenderApprovalForCurrentProposalRevision(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
  assignment: Doc<"proposalLenderAssignments">,
) {
  const revision = await getCurrentProposalRevision(ctx, proposal);
  if (!revision || revision.assignmentId !== assignment._id) {
    return null;
  }
  const confirmationCycle = await getCurrentProposalLenderConfirmationCycle(
    ctx,
    proposal,
    assignment,
  );
  if (!confirmationCycle || confirmationCycle.status !== "approved") {
    return null;
  }
  const approval = await getCurrentProposalLenderApproval(
    ctx,
    proposal._id,
    assignment._id,
    revision._id,
  );
  return approval && confirmationCycle.decisionId === approval._id
    ? approval
    : null;
}

async function isActiveEligibleLenderApproval(
  ctx: QueryCtx | MutationCtx,
  approval: Doc<"proposalLenderApprovals">,
  assignment: Doc<"proposalLenderAssignments">,
) {
  if (
    !LENDER_PROPOSAL_DECISION_ROLES.includes(
      approval.approverRole as (typeof LENDER_PROPOSAL_DECISION_ROLES)[number],
    )
  ) {
    return false;
  }
  const lenderOrganization = await resolvePolicyLenderOrganization(
    ctx,
    assignment,
    "policy lock",
  );
  const approvalOrganizationId = ctx.db.normalizeId(
    "lenderOrganizations",
    String(approval.lenderOrganizationId),
  );
  if (
    approvalOrganizationId
      ? approvalOrganizationId !== lenderOrganization._id
      : approval.lenderOrganizationId !== assignment.lenderOrganizationId &&
        approval.legacyLenderOrganizationId !==
          String(assignment.lenderOrganizationId)
  ) {
    return false;
  }
  const eligibleMembers =
    await listActiveApprovalEligibleLenderOrganizationMembers(
      ctx,
      lenderOrganization._id,
      "proposal_review",
    );
  return eligibleMembers.some(
    (member) => member.workosUserId === approval.approverWorkosUserId,
  );
}

async function evaluateProposalClosingEligibility(
  ctx: QueryCtx | MutationCtx,
  proposal: Doc<"buildProposals">,
  currentLenderAssignment: Doc<"proposalLenderAssignments"> | null,
) {
  const reasons: string[] = [];
  if (proposal.status !== "approved") {
    reasons.push("Proposal must be approved before closing.");
  }
  if (proposal.reviewOutcome !== "approved") {
    reasons.push("Current Back Office approval is required before closing.");
  }
  if (!proposal.workflowRuleSnapshotId) {
    reasons.push("Approved proposal is missing workflow rule snapshot.");
  }
  if (!proposal.builderProfileId) {
    reasons.push("Closing requires an assigned builder.");
  }
  const currentRevision = await getCurrentProposalRevision(ctx, proposal);
  if (!currentRevision) {
    reasons.push("A current immutable proposal revision is required before closing.");
  }
  const policyLock = proposal.lockedReviewPolicyId
    ? await ctx.db.get(proposal.lockedReviewPolicyId)
    : null;
  if (
    !policyLock ||
    policyLock.proposalId !== proposal._id ||
    policyLock.organizationId !== proposal.organizationId ||
    policyLock.brokerageId !== proposal.brokerageId
  ) {
    reasons.push("An immutable review policy lock is required before closing.");
  } else if (
    !currentRevision ||
    policyLock.proposalRevisionId !== currentRevision._id ||
    policyLock.policyVersionId !== proposal.currentReviewPolicyVersionId
  ) {
    reasons.push("Review policy lock does not match the current proposal revision.");
  }

  const withdrawnAssignments = currentLenderAssignment
    ? []
    : await ctx.db
        .query("proposalLenderAssignments")
        .withIndex("by_proposal_status", (query) =>
          query.eq("proposalId", proposal._id).eq("status", "withdrawn"),
        )
        .take(1);
  const requiresLenderAssignment =
    (proposal.capitalSource ?? "internal") === "external" &&
    !currentLenderAssignment &&
    withdrawnAssignments.length === 0;
  if (requiresLenderAssignment) {
    reasons.push(
      "External-capital proposals require a current lender assignment before closing.",
    );
  }

  let lenderApproval: Doc<"proposalLenderApprovals"> | null = null;
  if (currentLenderAssignment) {
    if (
      !currentRevision ||
      currentRevision.assignmentId !== currentLenderAssignment._id
    ) {
      reasons.push("Current proposal revision does not match the lender assignment.");
    } else {
      lenderApproval = await getLenderApprovalForCurrentProposalRevision(
        ctx,
        proposal,
        currentLenderAssignment,
      );
    }
    if (
      !lenderApproval ||
      !(await isActiveEligibleLenderApproval(
        ctx,
        lenderApproval,
        currentLenderAssignment,
      ))
    ) {
      reasons.push("One eligible active lender approval is required before closing.");
    }
  }

  return {
    currentRevision,
    eligible: reasons.length === 0,
    lenderApproval,
    policyLock,
    reasons,
  };
}

async function resolveAssignableLenderOrganization(
  ctx: QueryCtx | MutationCtx,
  lenderOrganizationId: Id<"lenderOrganizations">,
) {
  const { brokerage: lenderBrokerage, organization } =
    await resolveLenderOrganizationTarget(ctx, lenderOrganizationId);
  if (organization.status !== "active") {
    return null;
  }
  return {
    brokerageId: lenderBrokerage._id,
    lenderOrganizationId,
    name: organization.displayName,
  };
}

async function resolvePolicyLenderOrganization(
  ctx: QueryCtx | MutationCtx,
  assignment: Doc<"proposalLenderAssignments">,
  operation: "policy configuration" | "policy lock",
) {
  const normalizedId = ctx.db.normalizeId(
    "lenderOrganizations",
    String(assignment.lenderOrganizationId),
  );
  let candidates: Doc<"lenderOrganizations">[] = [];
  if (normalizedId) {
    const organization = await ctx.db.get(normalizedId);
    if (organization) candidates = [organization];
  } else {
    candidates = await ctx.db
      .query("lenderOrganizations")
      .withIndex("by_brokerage_and_legacy_workos_organization", (query) =>
        query
          .eq("brokerageId", assignment.lenderBrokerageId)
          .eq(
            "legacyWorkosOrganizationId",
            String(assignment.lenderOrganizationId),
          ),
      )
      .take(2);
  }
  if (
    candidates.length !== 1 ||
    candidates[0]?.status !== "active" ||
    candidates[0].brokerageId !== assignment.lenderBrokerageId
  ) {
    throw new Error(
      `Assigned lender organization requires the legacy organization cutover before ${operation}.`,
    );
  }
  return candidates[0];
}

function projectProposalLenderAssignment(
  assignment: Doc<"proposalLenderAssignments">,
) {
  return {
    assignmentId: assignment._id,
    assignedAt: assignment.assignedAt,
    assignedByRole: assignment.assignedByRole,
    assignedByWorkosUserId: assignment.assignedByWorkosUserId,
    lenderBrokerageId: assignment.lenderBrokerageId,
    lenderOrganizationId: assignment.lenderOrganizationId,
    lenderOrganizationName: assignment.lenderOrganizationName,
    status: assignment.status,
    ...(assignment.withdrawalReason === undefined
      ? {}
      : { withdrawalReason: assignment.withdrawalReason }),
    ...(assignment.withdrawnAt === undefined
      ? {}
      : { withdrawnAt: assignment.withdrawnAt }),
    ...(assignment.withdrawnByWorkosUserId === undefined
      ? {}
      : { withdrawnByWorkosUserId: assignment.withdrawnByWorkosUserId }),
  };
}

function projectLenderVisibleProposalAssignment(
  assignment: Doc<"proposalLenderAssignments">,
) {
  const projection = projectProposalLenderAssignment(assignment);
  const {
    withdrawalReason: _withdrawalReason,
    withdrawnByWorkosUserId: _withdrawnByWorkosUserId,
    ...visibleProjection
  } = projection;
  return visibleProjection;
}

function projectProposalLenderApproval(
  approval: Doc<"proposalLenderApprovals">,
) {
  return {
    approvalId: approval._id,
    ...(approval.status === "approved"
      ? { approvedAt: approval.approvedAt }
      : { declinedAt: approval.declinedAt }),
    ...(approval.proposalRevisionId
      ? { proposalRevisionId: approval.proposalRevisionId }
      : {}),
    ...(approval.proposalRevisionNumber === undefined
      ? {}
      : { proposalRevisionNumber: approval.proposalRevisionNumber }),
    status: approval.status,
  };
}

export function assertProposalLenderApprovalTimestamps(input: {
  approvedAt?: number;
  declinedAt?: number;
  status: "approved" | "declined";
}) {
  if (
    input.status === "approved" &&
    (input.approvedAt === undefined || input.declinedAt !== undefined)
  ) {
    throw new Error(
      "Approved lender decisions require approvedAt and cannot include declinedAt.",
    );
  }
  if (
    input.status === "declined" &&
    (input.declinedAt === undefined || input.approvedAt !== undefined)
  ) {
    throw new Error(
      "Declined lender decisions require declinedAt and cannot include approvedAt.",
    );
  }
}

function requireReason(reason: string) {
  if (!reason.trim()) {
    throw new Error("A reason is required.");
  }
}

function calculateDrawAvailability(
  budgetCents: number,
  borrowerCoPayBps: number,
) {
  return Math.round((budgetCents * (10_000 - borrowerCoPayBps)) / 10_000);
}

function normalizeProposalApprovedAmountCents(input: {
  requestedApprovedAmountCents: number;
  totalDrawAmountCents: number;
}) {
  const requestedApprovedAmountCents = Math.max(
    0,
    Math.round(input.requestedApprovedAmountCents),
  );
  return Math.max(
    Math.max(0, Math.round(input.totalDrawAmountCents)),
    requestedApprovedAmountCents,
  );
}

async function ensureProposalApprovedAmountCoversDrawSchedule(
  ctx: MutationCtx,
  proposal: Doc<"buildProposals">,
  input: { updatedAt: number; updatedByWorkosUserId: string },
) {
  const totalDrawAmountCents = await sumProposalDrawScheduleAmountCents(
    ctx,
    proposal._id,
  );
  const nextApprovedAmountCents = Math.max(
    proposal.lenderDrawPolicyLimitCents,
    totalDrawAmountCents,
  );

  if (nextApprovedAmountCents === proposal.lenderDrawPolicyLimitCents) {
    return;
  }

  await ctx.db.patch(proposal._id, {
    lenderDrawPolicyLimitCents: nextApprovedAmountCents,
    updatedAt: input.updatedAt,
    updatedByWorkosUserId: input.updatedByWorkosUserId,
  });
}

async function sumProposalDrawScheduleAmountCents(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
) {
  const draws = await collectByIndex(
    ctx,
    "proposalDrawScheduleRows",
    "by_proposal",
    proposalId,
  );
  return draws.reduce(
    (total: number, draw: Doc<"proposalDrawScheduleRows">) =>
      total + Math.max(0, Math.round(draw.amountCents)),
    0,
  );
}

function firstActiveMilestoneForWorkspace(
  milestones: Doc<"proposalMilestones">[],
) {
  return milestones[0] ?? null;
}

function productionTimelineStatusForMilestone(
  index: number,
  proposal: Doc<"buildProposals">,
  milestone?: Doc<"proposalMilestones">,
) {
  if (milestone?.timelineStatus === "complete" || milestone?.completionClaim) {
    return "complete" as const;
  }
  if (proposal.status === "closed") {
    return "complete" as const;
  }
  return index === 0 ? ("ready" as const) : ("upcoming" as const);
}

function productionTimelineToneForMilestone(
  index: number,
  proposal: Doc<"buildProposals">,
  milestone?: Doc<"proposalMilestones">,
) {
  if (milestone?.tone) {
    return milestone.tone;
  }
  if (milestone?.timelineStatus === "complete" || milestone?.completionClaim) {
    return "complete" as const;
  }
  if (proposal.status === "closed") {
    return "complete" as const;
  }
  if (proposal.status === "submitted") {
    return index === 0 ? ("warning" as const) : ("upcoming" as const);
  }
  if (proposal.status === "approved") {
    return index === 0 ? ("active" as const) : ("upcoming" as const);
  }
  return index === 0 ? ("active" as const) : ("upcoming" as const);
}

function productionCompletionClaimView(claim: any) {
  if (!claim) {
    return;
  }
  return {
    ...(typeof claim.actualCostCents === "number"
      ? { actualCost: centsToDollars(claim.actualCostCents) }
      : typeof claim.actualCost === "number"
        ? { actualCost: claim.actualCost }
        : {}),
    completedDay: claim.completedDay,
    ...(claim.note ? { note: claim.note } : {}),
    submittedAt: claim.submittedAt,
  };
}

function productionCompletionReviewView(review: any) {
  if (!review) {
    return;
  }
  return {
    ...(review.note ? { note: review.note } : {}),
    reviewedAt: review.reviewedAt,
    ...(review.siteVisit ? { siteVisit: review.siteVisit } : {}),
    status: review.status,
  };
}

function centsToDollars(cents: number) {
  return Math.round(cents / 100);
}

function productionPolicyState(
  proposal: Doc<"buildProposals">,
  permitWaiver: Doc<"documentWaivers"> | null,
) {
  if (proposal.reviewOutcome === "rejected") {
    return "Rejected by lender review";
  }
  if (proposal.reviewOutcome === "requested_changes") {
    return "Changes requested by lender review";
  }
  if (permitWaiver) {
    return "Permit waiver recorded";
  }
  if (proposal.status === "submitted") {
    return "Locked for lender review";
  }
  if (proposal.status === "approved" || proposal.status === "closed") {
    return "Approved reimbursement policy";
  }
  return "Draft proposal policy";
}

function productionTimelinePermissions(auth: {
  proposal: Doc<"buildProposals">;
  roles: RoleSlug[];
  subject: string;
}) {
  const backoffice = isBackoffice(auth.roles);
  const draft = auth.proposal.status === "draft";
  const liveBuild = auth.proposal.status === "approved";
  const submitted = auth.proposal.status === "submitted";
  return {
    approveProposal: submitted && backoffice,
    closeProposal: auth.proposal.status === "approved" && backoffice,
    editDraftStructure: draft,
    editSubmittedDraws: submitted && backoffice,
    requestLiveModification: liveBuild && !backoffice,
    reviewDraws: liveBuild && backoffice,
    reviewMilestones: liveBuild && backoffice,
    submitDrawRequests: liveBuild && !backoffice,
    submitMilestoneCompletion: liveBuild && !backoffice,
    submitProposal: draft,
  };
}

function iconForProductionMilestone(key: string, name?: string) {
  const normalized = `${key} ${name ?? ""}`.toLowerCase();
  if (normalized.includes("foundation") || normalized.includes("site")) {
    return "foundation";
  }
  if (normalized.includes("kitchen") || normalized.includes("cabinet")) {
    return "kitchen";
  }
  if (
    normalized.includes("plumb") ||
    normalized.includes("mechanical") ||
    normalized.includes("mep")
  ) {
    return "plumbing";
  }
  if (normalized.includes("roof") || normalized.includes("dry-in")) {
    return "roofing";
  }
  if (normalized.includes("shell") || normalized.includes("fram")) {
    return "framing";
  }
  if (normalized.includes("rough")) {
    return "roughIn";
  }
  if (normalized.includes("exterior")) {
    return "exterior";
  }
  if (normalized.includes("dry")) {
    return "drywall";
  }
  if (normalized.includes("finish") || normalized.includes("interior")) {
    return "finishes";
  }
  if (normalized.includes("close")) {
    return "closeout";
  }
  return "change";
}

async function requireProductionTimelineEditable(
  ctx: QueryCtx | MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
) {
  if (auth.proposal.status === "draft") {
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  if (auth.proposal.status === "approved") {
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  if (auth.proposal.status === "submitted" && isBackoffice(auth.roles)) {
    requireBackofficeProposalWrite(auth, auth.proposal);
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  throw new Error("Timeline is locked in this proposal state.");
}

async function requireProductionProposalPreLiveCapitalWrite(
  ctx: QueryCtx | MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
) {
  if (auth.proposal.activeBuildId) {
    throw new Error(
      "Proposal capital terms are locked after the build goes live.",
    );
  }
  if (auth.proposal.status === "draft") {
    if (isBackoffice(auth.roles)) {
      requireBackofficeProposalWrite(auth, auth.proposal);
    } else {
      await assertBuilderOwnership(
        ctx,
        assignedBuilderProfileIdOrThrow(auth.proposal),
        auth.subject,
      );
    }
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  if (
    (auth.proposal.status === "submitted" ||
      auth.proposal.status === "approved") &&
    isBackoffice(auth.roles)
  ) {
    requireBackofficeProposalWrite(auth, auth.proposal);
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  throw new Error("Proposal capital terms are locked in this proposal state.");
}

async function requireProductionTimelineDraftStructureWrite(
  ctx: QueryCtx | MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
) {
  if (auth.proposal.status === "closed") {
    throw new Error("Closed proposals cannot be edited.");
  }
  if (auth.proposal.status !== "draft") {
    if (!isBackoffice(auth.roles)) {
      throw new Error("Proposal structure is locked after submission.");
    }
    requireBackofficeProposalWrite(auth, auth.proposal);
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return;
  }
  if (isBackoffice(auth.roles)) {
    requireBackofficeProposalWrite(auth, auth.proposal);
  }
  await assertProposalCollaborationEditAllowed(ctx, auth);
}

async function authorizeProposalCostItemWrite(
  ctx: (QueryCtx | MutationCtx) & { viewer: AuthorizedViewer },
  proposalId: Id<"buildProposals">,
  workosOrganizationId: string,
  action: BuilderStaffPermissionAction,
  reason?: string,
) {
  const auth = await authorizeProposal(ctx, proposalId, workosOrganizationId);
  await requireProposalAppPermission(ctx, auth, "material", action);
  if (auth.proposal.status === "closed") {
    throw new Error("Closed proposals cannot be edited.");
  }
  if (auth.proposal.status === "draft") {
    if (isBackoffice(auth.roles)) {
      requireBackofficeProposalWrite(auth, auth.proposal);
    }
    await assertProposalCollaborationEditAllowed(ctx, auth);
    return auth;
  }
  requireAnyRole(auth.roles, BACKOFFICE_ROLES);
  requireBackofficeProposalWrite(auth, auth.proposal);
  requireReason(reason ?? "");
  await assertProposalCollaborationEditAllowed(ctx, auth);
  return auth;
}

function normalizeRequiredText(value: string, label: string) {
  const text = value.trim();
  if (!text) {
    throw new Error(`${label} is required.`);
  }
  return text;
}

function normalizeOptionalText(value: string | undefined) {
  const text = value?.trim();
  return text ? text : undefined;
}

function normalizeOptionalNonNegativeDay(
  value: number | undefined,
  label: string,
) {
  if (value === undefined) {
    return undefined;
  }
  if (!Number.isFinite(value) || !Number.isInteger(value) || value < 0) {
    throw new Error(`${label} must be a non-negative whole day.`);
  }
  return value;
}

function normalizeOptionalTiptapJson(value: string | undefined, label: string) {
  if (value === undefined) {
    return undefined;
  }
  if (!value.trim()) {
    return undefined;
  }
  if (value.length > 250_000) {
    throw new Error(`${label} exceeds the supported length.`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    throw new Error(`${label} must be valid TipTap JSON.`);
  }
  if (
    !parsed ||
    typeof parsed !== "object" ||
    !("type" in parsed) ||
    parsed.type !== "doc"
  ) {
    throw new Error(`${label} must contain a TipTap document root.`);
  }
  // Preserve the supplied canonical JSON exactly; quote-package snapshots use
  // this content verbatim rather than flattening or reserializing it.
  return value;
}

function normalizeRequiredTiptapJson(value: string, label: string) {
  const normalized = normalizeOptionalTiptapJson(value, label);
  if (normalized === undefined) {
    throw new Error(`${label} must contain TipTap JSON.`);
  }
  return normalized;
}

function validateCostItemDeliveryWindow(input: {
  deliveryEndDay?: number;
  deliveryStartDay?: number;
}) {
  const deliveryStartDay = normalizeOptionalNonNegativeDay(
    input.deliveryStartDay,
    "Delivery start day",
  );
  const deliveryEndDay = normalizeOptionalNonNegativeDay(
    input.deliveryEndDay,
    "Delivery end day",
  );
  if (
    deliveryStartDay !== undefined &&
    deliveryEndDay !== undefined &&
    deliveryEndDay < deliveryStartDay
  ) {
    throw new Error("Delivery end day cannot precede delivery start day.");
  }
  return { deliveryEndDay, deliveryStartDay };
}

function normalizeCostItemCost(value: number) {
  if (!Number.isFinite(value)) {
    throw new Error("Cost item cost must be finite.");
  }
  return Math.max(0, Math.round(value));
}

function normalizeCostItemQuantity(value: number) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error("Cost item quantity must be greater than zero.");
  }
  return Math.round(value * 1000) / 1000;
}

function costItemTotalCents(
  item: Pick<Doc<"proposalCostItems">, "costCents" | "quantity">,
) {
  return Math.round(item.costCents * item.quantity);
}

type CostItemBudgetTreatment = "add" | "logOnly" | "maintain";

type ProposalCostItemBudgetState = Pick<
  Doc<"proposalCostItems">,
  | "_id"
  | "budgetSubmilestoneKey"
  | "budgetTreatment"
  | "costCents"
  | "milestoneKey"
  | "proposalMilestoneId"
  | "quantity"
>;

function normalizeCostItemBudgetTreatment(
  value: CostItemBudgetTreatment | undefined,
): CostItemBudgetTreatment {
  return value ?? "add";
}

function normalizeCostItemBudgetSubmilestoneKey(
  value: null | string | undefined,
) {
  const key = value?.trim();
  return key ? key : undefined;
}

function proposalCostItemAuditWarnings(proposal: Doc<"buildProposals">) {
  return proposal.status === "draft"
    ? []
    : [`proposal-state:${proposal.status}`];
}

async function validateProposalCostItemSubmilestones(
  ctx: QueryCtx | MutationCtx,
  milestone: Pick<Doc<"proposalMilestones">, "_id" | "key">,
  relevantSubmilestoneKeys: string[],
) {
  const available = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", milestone._id),
    )
    .collect();
  const availableKeys = new Set(available.map((row) => row.key));
  const normalized = [
    ...new Set(
      relevantSubmilestoneKeys
        .map((key) => key.trim())
        .filter((key) => key.length > 0),
    ),
  ];
  const invalid = normalized.filter((key) => !availableKeys.has(key));
  if (invalid.length > 0) {
    throw new Error(
      `Relevant sub-milestones must belong to ${milestone.key}: ${invalid.join(", ")}.`,
    );
  }
  return normalized;
}

async function validateProposalCostItemBudgetTarget(
  ctx: QueryCtx | MutationCtx,
  milestone: Pick<Doc<"proposalMilestones">, "_id" | "key">,
  requestedKey: null | string | undefined,
  treatment: CostItemBudgetTreatment,
  requireAddTarget: boolean,
) {
  if (treatment === "logOnly") {
    return;
  }
  const budgetSubmilestoneKey =
    normalizeCostItemBudgetSubmilestoneKey(requestedKey);
  if (!budgetSubmilestoneKey) {
    if (treatment === "maintain" || (treatment === "add" && requireAddTarget)) {
      throw new Error(
        `${treatment === "add" ? "Add" : "Maintain"} requires one budget sub-milestone target.`,
      );
    }
    return;
  }
  const submilestones = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", milestone._id),
    )
    .collect();
  if (!submilestones.some((row) => row.key === budgetSubmilestoneKey)) {
    throw new Error(
      `Budget sub-milestone must belong to ${milestone.key}: ${budgetSubmilestoneKey}.`,
    );
  }
  return budgetSubmilestoneKey;
}

async function nextProposalCostItemKey(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
  title: string,
  now: number,
) {
  const base = slugifyKey(title) || "cost-item";
  let candidate = `${base}-${now.toString(36)}`;
  let attempt = 1;
  while (
    await ctx.db
      .query("proposalCostItems")
      .withIndex("by_proposal_key", (q) =>
        q.eq("proposalId", proposalId).eq("itemKey", candidate),
      )
      .unique()
  ) {
    attempt += 1;
    candidate = `${base}-${now.toString(36)}-${attempt}`;
  }
  return candidate;
}

function slugifyKey(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
}

async function getProposalCostItemOrThrow(
  ctx: QueryCtx | MutationCtx,
  proposalId: Id<"buildProposals">,
  itemId: Id<"proposalCostItems">,
) {
  const item = await ctx.db.get(itemId);
  if (!item || item.proposalId !== proposalId) {
    throw new Error("Proposal cost item not found.");
  }
  return item;
}

async function getProposalMilestoneByIdOrThrow(
  ctx: QueryCtx | MutationCtx,
  milestoneId: Id<"proposalMilestones">,
) {
  const milestone = await ctx.db.get(milestoneId);
  if (!milestone) {
    throw new Error("Production milestone not found.");
  }
  return milestone;
}

async function applyProposalCostItemBudgetChange(
  ctx: MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    subject: string;
  },
  input: {
    nextItem?: ProposalCostItemBudgetState;
    priorItem?: ProposalCostItemBudgetState;
    proposalId: Id<"buildProposals">;
  },
) {
  const operations = new Map<
    string,
    {
      deltaCents: number;
      milestoneId: Id<"proposalMilestones">;
      submilestoneKey?: string;
    }
  >();
  const addOperation = (
    item: ProposalCostItemBudgetState | undefined,
    direction: -1 | 1,
  ) => {
    if (
      !item ||
      normalizeCostItemBudgetTreatment(item.budgetTreatment) !== "add"
    ) {
      return;
    }
    const submilestoneKey = normalizeCostItemBudgetSubmilestoneKey(
      item.budgetSubmilestoneKey,
    );
    const operationKey = `${item.proposalMilestoneId}:${submilestoneKey ?? "milestone"}`;
    const current = operations.get(operationKey);
    operations.set(operationKey, {
      deltaCents:
        (current?.deltaCents ?? 0) + direction * costItemTotalCents(item),
      milestoneId: item.proposalMilestoneId,
      submilestoneKey,
    });
  };
  addOperation(input.priorItem, -1);
  addOperation(input.nextItem, 1);

  const milestoneDeltaById = new Map<Id<"proposalMilestones">, number>();
  const milestoneById = new Map<
    Id<"proposalMilestones">,
    Doc<"proposalMilestones">
  >();
  const maintainedTargets = new Set<string>();
  for (const item of [input.priorItem, input.nextItem]) {
    const target = normalizeCostItemBudgetSubmilestoneKey(
      item?.budgetSubmilestoneKey,
    );
    if (item && target) {
      maintainedTargets.add(`${item.proposalMilestoneId}:${target}`);
    }
  }
  const now = Date.now();
  for (const operation of operations.values()) {
    if (operation.deltaCents === 0) {
      continue;
    }
    const milestone = await getProposalMilestoneByIdOrThrow(
      ctx,
      operation.milestoneId,
    );
    milestoneById.set(milestone._id, milestone);
    milestoneDeltaById.set(
      milestone._id,
      (milestoneDeltaById.get(milestone._id) ?? 0) + operation.deltaCents,
    );
    if (operation.submilestoneKey) {
      const submilestones = await ctx.db
        .query("proposalSubmilestones")
        .withIndex("by_milestone", (q) =>
          q.eq("proposalMilestoneId", milestone._id),
        )
        .collect();
      const submilestone = submilestones.find(
        (row) => row.key === operation.submilestoneKey,
      );
      if (!submilestone) {
        throw new Error(
          `Budget sub-milestone not found: ${operation.submilestoneKey}.`,
        );
      }
      await ctx.db.patch(submilestone._id, {
        budgetCents: Math.max(
          0,
          Math.round((submilestone.budgetCents ?? 0) + operation.deltaCents),
        ),
        updatedAt: now,
      });
    }
  }

  for (const [milestoneId, deltaCents] of milestoneDeltaById) {
    const milestone = milestoneById.get(milestoneId);
    if (!milestone) {
      continue;
    }
    const nextMilestoneBudgetCents = Math.max(
      0,
      milestone.budgetCents + deltaCents,
    );
    const nextDrawAvailabilityCents = calculateDrawAvailability(
      nextMilestoneBudgetCents,
      auth.proposal.borrowerCoPayBps,
    );
    await ctx.db.patch(milestone._id, {
      budgetCents: nextMilestoneBudgetCents,
      drawAvailabilityCents: nextDrawAvailabilityCents,
      updatedAt: now,
    });
    await syncMilestoneOwnedDrawAmount(ctx, {
      amountCents: nextDrawAvailabilityCents,
      milestoneKey: milestone.key,
      proposalId: input.proposalId,
      updatedAt: now,
    });
  }

  for (const target of maintainedTargets) {
    const separator = target.indexOf(":");
    const milestoneId = target.slice(0, separator) as Id<"proposalMilestones">;
    const submilestoneKey = target.slice(separator + 1);
    await validateProposalMaintainedCostCoverage(ctx, {
      milestoneId,
      proposalId: input.proposalId,
      submilestoneKey,
    });
  }

  if (milestoneDeltaById.size > 0) {
    await recalculateProposalBudget(ctx, auth, input.proposalId);
  }
}

async function validateProposalMaintainedCostCoverage(
  ctx: QueryCtx | MutationCtx,
  input: {
    milestoneId: Id<"proposalMilestones">;
    proposalId: Id<"buildProposals">;
    submilestoneKey: string;
  },
) {
  const [submilestones, costItems] = await Promise.all([
    ctx.db
      .query("proposalSubmilestones")
      .withIndex("by_milestone", (q) =>
        q.eq("proposalMilestoneId", input.milestoneId),
      )
      .collect(),
    ctx.db
      .query("proposalCostItems")
      .withIndex("by_milestone", (q) =>
        q.eq("proposalMilestoneId", input.milestoneId),
      )
      .collect(),
  ]);
  const submilestone = submilestones.find(
    (row) => row.key === input.submilestoneKey,
  );
  if (!submilestone || submilestone.proposalId !== input.proposalId) {
    throw new Error(
      `Budget sub-milestone not found: ${input.submilestoneKey}.`,
    );
  }
  const maintainedCents = costItems.reduce(
    (total, item) =>
      normalizeCostItemBudgetTreatment(item.budgetTreatment) === "maintain" &&
      item.budgetSubmilestoneKey === input.submilestoneKey
        ? total + costItemTotalCents(item)
        : total,
    0,
  );
  const budgetCents = Math.max(0, Math.round(submilestone.budgetCents ?? 0));
  if (maintainedCents > budgetCents) {
    throw new Error(
      `Maintained cost items exceed the ${submilestone.name} budget by ${maintainedCents - budgetCents} cents.`,
    );
  }
}

async function syncMilestoneOwnedDrawAmount(
  ctx: MutationCtx,
  input: {
    amountCents: number;
    milestoneKey: string;
    proposalId: Id<"buildProposals">;
    updatedAt: number;
  },
) {
  const draws = (await collectByIndex(
    ctx,
    "proposalDrawScheduleRows",
    "by_proposal",
    input.proposalId,
  )) as Doc<"proposalDrawScheduleRows">[];
  const draw = draws.find(
    (row) =>
      row.milestoneKey === input.milestoneKey &&
      (row.source === undefined || row.source === "milestone"),
  );

  if (!draw) {
    return;
  }

  await ctx.db.patch(draw._id, {
    amountCents: Math.max(0, Math.round(input.amountCents)),
    updatedAt: input.updatedAt,
  });
}

async function requireProductionTimelineLiveWrite(
  ctx: QueryCtx | MutationCtx,
  auth: {
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
) {
  if (auth.proposal.status !== "approved") {
    throw new Error(
      "Live-build timeline actions require an approved proposal.",
    );
  }
  if (isBackoffice(auth.roles)) {
    requireBackofficeProposalWrite(auth, auth.proposal);
  }
  await assertProposalCollaborationEditAllowed(ctx, auth);
}

async function insertProductionMilestoneFromInput(
  ctx: MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    proposal: Doc<"buildProposals">;
    subject: string;
  },
  milestone: {
    budgetCents: number;
    dayEnd: number;
    dayStart: number;
    dependencyKeys?: string[];
    drawAvailabilityCents?: number;
    durationDays: number;
    evidenceState: string;
    icon?: string;
    lane?: number;
    markerLabel?: string;
    milestoneKey: string;
    name: string;
    order: number;
    policyState: string;
    status?: string;
    submilestones?: {
      budgetCents?: number;
      durationDays?: number;
      fieldGuidance?: {
        cameraAnglesTiptapJson: string;
        whatToVerifyTiptapJson: string;
      };
      key: string;
      name: string;
      order: number;
      scopeOfWorkTiptapJson?: string;
      startDay?: number;
    }[];
    tone?: string;
    x: number;
  },
) {
  if (
    !Number.isFinite(milestone.dayStart) ||
    !Number.isFinite(milestone.dayEnd) ||
    !Number.isFinite(milestone.x) ||
    Math.round(milestone.dayStart) < 0 ||
    Math.round(milestone.dayEnd) < 0 ||
    Math.round(milestone.x) < 0
  ) {
    throw new Error("Milestones must start and end on or after T0.");
  }
  const existing = await ctx.db
    .query("proposalMilestones")
    .withIndex("by_proposal_key", (q) =>
      q.eq("proposalId", auth.proposal._id).eq("key", milestone.milestoneKey),
    )
    .unique();
  if (existing) {
    throw new Error("Production milestone already exists.");
  }
  const schedule = normalizeProductionMilestoneSchedule(milestone);
  const now = Date.now();
  const budgetCents =
    schedule.submilestones.length > 0
      ? sumProductionSubmilestoneBudgetCents(schedule.submilestones)
      : Math.max(0, Math.round(milestone.budgetCents));
  const milestoneId = await ctx.db.insert("proposalMilestones", {
    brokerageId: auth.brokerage._id,
    budgetCents,
    createdAt: now,
    dayEnd: schedule.dayEnd,
    dayStart: schedule.dayStart,
    dependencyKeys: milestone.dependencyKeys ?? [],
    drawAvailabilityCents:
      milestone.drawAvailabilityCents === undefined
        ? calculateDrawAvailability(budgetCents, auth.proposal.borrowerCoPayBps)
        : Math.max(0, Math.round(milestone.drawAvailabilityCents)),
    durationDays: schedule.durationDays,
    evidenceState: milestone.evidenceState,
    icon: milestone.icon,
    key: milestone.milestoneKey,
    lane: milestone.lane,
    markerLabel: milestone.markerLabel,
    name: milestone.name.trim() || "Requested milestone",
    order: Math.max(1, Math.round(milestone.order)),
    organizationId: auth.proposal.organizationId,
    policyState: milestone.policyState,
    proposalId: auth.proposal._id,
    timelineStatus: milestone.status,
    tone: milestone.tone,
    updatedAt: now,
  });
  await replaceProductionSubmilestones(ctx, auth, {
    milestone: {
      _id: milestoneId,
      key: milestone.milestoneKey,
    },
    proposalId: auth.proposal._id,
    rows: schedule.submilestones,
  });
  return milestoneId;
}

async function deleteProposalSubmilestoneCanonicalLineage(
  ctx: MutationCtx,
  submilestone: Doc<"proposalSubmilestones"> | null,
  resolved: {
    contract?: Doc<"submilestoneScopeContracts">;
    guidance?: Doc<"submilestoneFieldGuidance">;
  } = {},
  options: { validateOnly?: boolean } = {},
) {
  const contract =
    resolved.contract ??
    (submilestone
      ? await ctx.db
          .query("submilestoneScopeContracts")
          .withIndex("by_proposalSubmilestoneId", (query) =>
            query.eq("proposalSubmilestoneId", submilestone._id),
          )
          .unique()
      : null);
  const guidance =
    resolved.guidance ??
    (submilestone
      ? await ctx.db
          .query("submilestoneFieldGuidance")
          .withIndex("by_proposalSubmilestoneId", (query) =>
            query.eq("proposalSubmilestoneId", submilestone._id),
          )
          .unique()
      : null);
  const expectedProposalId =
    submilestone?.proposalId ?? contract?.proposalId ?? guidance?.proposalId;
  const expectedOrganizationId =
    submilestone?.organizationId ??
    contract?.organizationId ??
    guidance?.organizationId;
  const expectedBrokerageId =
    submilestone?.brokerageId ?? contract?.brokerageId ?? guidance?.brokerageId;
  if (contract) {
    if (
      contract.proposalId !== expectedProposalId ||
      contract.organizationId !== expectedOrganizationId ||
      contract.brokerageId !== expectedBrokerageId ||
      (submilestone !== null &&
        contract.proposalSubmilestoneId !== submilestone._id)
    ) {
      throw new Error("Scope contract lineage is unavailable.");
    }
    const publishedRevisions = await ctx.db
      .query("submilestoneScopeRevisions")
      .withIndex("by_contractId_and_status", (query) =>
        query.eq("contractId", contract._id).eq("status", "published"),
      )
      .take(1);
    if (contract.effectiveRevisionId || publishedRevisions.length > 0) {
      throw new Error(
        "Published Scope lineage cannot be removed from a Proposal draft.",
      );
    }
  }
  if (
    guidance &&
    (guidance.proposalId !== expectedProposalId ||
      guidance.organizationId !== expectedOrganizationId ||
      guidance.brokerageId !== expectedBrokerageId ||
      (submilestone !== null &&
        guidance.proposalSubmilestoneId !== submilestone._id))
  ) {
    throw new Error("Field Guidance lineage is unavailable.");
  }
  if (options.validateOnly) {
    return;
  }
  if (contract) {
    const decisions = await ctx.db
      .query("submilestoneScopeDecisions")
      .withIndex("by_contractId", (query) =>
        query.eq("contractId", contract._id),
      )
      .collect();
    for (const decision of decisions) {
      await ctx.db.delete(decision._id);
    }
    const revisions = await ctx.db
      .query("submilestoneScopeRevisions")
      .withIndex("by_contractId_and_version", (query) =>
        query.eq("contractId", contract._id),
      )
      .collect();
    for (const revision of revisions) {
      await ctx.db.delete(revision._id);
    }
    await ctx.db.delete(contract._id);
  }
  if (guidance) {
    await ctx.db.delete(guidance._id);
  }
}

async function replaceProductionSubmilestones(
  ctx: MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    proposal: Doc<"buildProposals">;
    subject: string;
  },
  input: {
    milestone: Pick<Doc<"proposalMilestones">, "_id" | "key">;
    proposalId: Id<"buildProposals">;
    rejectEmpty?: boolean;
    rows: {
      budgetCents?: number;
      durationDays?: number;
      fieldGuidance?: {
        cameraAnglesTiptapJson: string;
        whatToVerifyTiptapJson: string;
      };
      key: string;
      name: string;
      order: number;
      scopeOfWorkTiptapJson?: string;
      startDay?: number;
    }[];
  },
) {
  const nextSubmilestoneByKey = new Map(
    input.rows.map((row) => [row.key, row] as const),
  );
  const targetedCostItems = await ctx.db
    .query("proposalCostItems")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", input.milestone._id),
    )
    .collect();
  const maintainedCentsByTarget = new Map<string, number>();
  for (const item of targetedCostItems) {
    const target = item.budgetSubmilestoneKey;
    if (!target) {
      continue;
    }
    if (!nextSubmilestoneByKey.has(target)) {
      throw new Error(
        `Cannot remove budget sub-milestone ${target} while cost items target it.`,
      );
    }
    if (normalizeCostItemBudgetTreatment(item.budgetTreatment) === "maintain") {
      maintainedCentsByTarget.set(
        target,
        (maintainedCentsByTarget.get(target) ?? 0) + costItemTotalCents(item),
      );
    }
  }
  for (const [target, maintainedCents] of maintainedCentsByTarget) {
    const budgetCents = Math.max(
      0,
      Math.round(nextSubmilestoneByKey.get(target)?.budgetCents ?? 0),
    );
    if (maintainedCents > budgetCents) {
      throw new Error(
        `Maintained cost items exceed the ${target} budget by ${maintainedCents - budgetCents} cents.`,
      );
    }
  }
  if (input.rejectEmpty) {
    assertValidProductionSubmilestones(
      input.rows,
      `Milestone ${input.milestone.key}`,
    );
  }
  const existing = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", input.milestone._id),
    )
    .collect();
  const existingByKey = new Map(existing.map((row) => [row.key, row]));
  const retainedKeys = new Set(input.rows.map((row) => row.key));
  for (const row of existing) {
    if (retainedKeys.has(row.key)) {
      continue;
    }
    await deleteProposalSubmilestoneCanonicalLineage(ctx, row);
    await ctx.db.delete(row._id);
  }
  const now = Date.now();
  for (const row of [...input.rows].sort((a, b) => a.order - b.order)) {
    assertProposalSubmilestoneCanonicalAuthoringAllowed(auth.proposal, row);
    const existingRow = existingByKey.get(row.key);
    const scopeOfWorkTiptapJson = normalizeOptionalTiptapJson(
      row.scopeOfWorkTiptapJson,
      "Sub-milestone Scope of Work",
    );
    const values = {
      brokerageId: auth.brokerage._id,
      budgetCents: row.budgetCents,
      createdAt: existingRow?.createdAt ?? now,
      durationDays: row.durationDays,
      key: row.key,
      milestoneKey: input.milestone.key,
      name: row.name.trim() || "Submilestone",
      order: Math.max(1, Math.round(row.order)),
      organizationId: auth.proposal.organizationId,
      proposalId: input.proposalId,
      proposalMilestoneId: input.milestone._id,
      startDay: row.startDay,
      updatedAt: now,
    };
    const submilestoneId = existingRow
      ? existingRow._id
      : await ctx.db.insert("proposalSubmilestones", values);
    if (existingRow) {
      await ctx.db.patch(existingRow._id, values);
    }
    if (!existingRow || scopeOfWorkTiptapJson !== undefined) {
      await upsertSubmilestoneScopeV1Draft(ctx, {
        authoredByWorkosUserId: auth.subject,
        brokerageId: auth.brokerage._id,
        now,
        organizationId: auth.proposal.organizationId,
        proposalId: input.proposalId,
        proposalSubmilestoneId: submilestoneId,
        scopeOfWorkTiptapJson:
          scopeOfWorkTiptapJson ?? EMPTY_CANONICAL_TIPTAP_DOCUMENT,
      });
    }
    if (!existingRow || row.fieldGuidance !== undefined) {
      await upsertProposalSubmilestoneFieldGuidance(ctx, {
        auth,
        fieldGuidance: row.fieldGuidance ?? {
          cameraAnglesTiptapJson: EMPTY_CANONICAL_TIPTAP_DOCUMENT,
          whatToVerifyTiptapJson: EMPTY_CANONICAL_TIPTAP_DOCUMENT,
        },
        now,
        proposalId: input.proposalId,
        proposalSubmilestoneId: submilestoneId,
        workosOrganizationId: auth.proposal.organizationId,
      });
    }
  }
}

async function upsertProposalMilestoneDrawAvailability(
  ctx: MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    proposal: Doc<"buildProposals">;
  },
  input: {
    amountCents: number;
    drawKey?: string;
    milestone: Pick<
      Doc<"proposalMilestones">,
      "_id" | "key" | "name" | "organizationId"
    >;
    proposalId: Id<"buildProposals">;
    timingDay: number;
  },
) {
  const amountCents = Math.max(0, Math.round(input.amountCents));
  const now = Date.now();
  const drawRows = (await collectByIndex(
    ctx,
    "proposalDrawScheduleRows",
    "by_proposal",
    input.proposalId,
  )) as Doc<"proposalDrawScheduleRows">[];
  const requestedDrawKey = normalizeProposalTimelineDrawKey(
    input.drawKey,
    input.milestone.key,
  );
  const existing =
    drawRows.find((row) => row.milestoneKey === input.milestone.key) ??
    drawRows.find((row) => row.drawKey === requestedDrawKey);

  if (existing) {
    await ctx.db.patch(existing._id, {
      amountCents,
      milestoneKey: input.milestone.key,
      proposalMilestoneId: input.milestone._id,
      updatedAt: now,
    });
    return;
  }

  await ctx.db.insert("proposalDrawScheduleRows", {
    amountCents,
    brokerageId: auth.brokerage._id,
    createdAt: now,
    customDate: false,
    drawKey: requestedDrawKey,
    label: `${input.milestone.name} reimbursement draw`,
    milestoneKey: input.milestone.key,
    order: drawRows.length + 1,
    organizationId: input.milestone.organizationId,
    proposalId: input.proposalId,
    proposalMilestoneId: input.milestone._id,
    source: "milestone",
    timingDay: Math.max(0, Math.round(input.timingDay)),
    updatedAt: now,
  });
}

function normalizeProposalTimelineDrawKey(
  drawKey: string | undefined,
  milestoneKey: string,
) {
  const trimmedDrawKey = drawKey?.trim();
  if (trimmedDrawKey && !/^draw\s+\d+$/i.test(trimmedDrawKey)) {
    return trimmedDrawKey;
  }
  return `${milestoneKey}-draw`;
}

async function deleteProductionMilestoneCascade(
  ctx: MutationCtx,
  proposalId: Id<"buildProposals">,
  milestone: Doc<"proposalMilestones">,
) {
  const submilestones = await ctx.db
    .query("proposalSubmilestones")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", milestone._id),
    )
    .collect();
  for (const row of submilestones) {
    await deleteProposalSubmilestoneCanonicalLineage(ctx, row);
    await ctx.db.delete(row._id);
  }
  const costItems = await ctx.db
    .query("proposalCostItems")
    .withIndex("by_milestone", (q) =>
      q.eq("proposalMilestoneId", milestone._id),
    )
    .collect();
  for (const item of costItems) {
    await ctx.db.delete(item._id);
  }
  const evidenceAssets = await ctx.db
    .query("proposalEvidenceAssets")
    .withIndex("by_proposal_milestone", (q) =>
      q.eq("proposalId", proposalId).eq("milestoneKey", milestone.key),
    )
    .collect();
  for (const asset of evidenceAssets) {
    if (asset.storageId) {
      await ctx.storage.delete(asset.storageId);
    }
    await ctx.db.delete(asset._id);
  }
  const draws = await collectByIndex(
    ctx,
    "proposalDrawScheduleRows",
    "by_proposal",
    proposalId,
  );
  for (const draw of draws.filter(
    (row: any) => row.milestoneKey === milestone.key,
  )) {
    await ctx.db.delete(draw._id);
  }
  await ctx.db.delete(milestone._id);
}

async function recalculateProposalBudget(
  ctx: MutationCtx,
  auth: { proposal?: Doc<"buildProposals">; subject: string },
  proposalId: Id<"buildProposals">,
) {
  const proposal = auth.proposal ?? (await ctx.db.get(proposalId));
  if (!proposal) {
    throw new Error("Production proposal not found.");
  }
  const milestones = await collectByIndex(
    ctx,
    "proposalMilestones",
    "by_proposal",
    proposalId,
  );
  const capitalEvents = await collectByIndex(
    ctx,
    "proposalCapitalEvents",
    "by_proposal",
    proposalId,
  );
  const milestoneBudgetCents = milestones.reduce(
    (total: number, milestone: any) => total + milestone.budgetCents,
    0,
  );
  const capitalSpikeBudgetCents = capitalEvents.reduce(
    (total: number, event: any) =>
      event.eventKind === "cost" ? total + event.amountCents : total,
    0,
  );
  const totalBudgetCents = milestoneBudgetCents + capitalSpikeBudgetCents;
  const totalDrawAmountCents = await sumProposalDrawScheduleAmountCents(
    ctx,
    proposalId,
  );
  const lenderDrawPolicyLimitCents = Math.max(
    Math.max(0, Math.round(proposal.lenderDrawPolicyLimitCents)),
    totalDrawAmountCents,
  );
  await ctx.db.patch(proposalId, {
    borrowerCoPayCents: Math.round(
      (totalBudgetCents * proposal.borrowerCoPayBps) / 10_000,
    ),
    lenderDrawPolicyLimitCents,
    totalBudgetCents,
    updatedAt: Date.now(),
    updatedByWorkosUserId: auth.subject,
  });
  await upsertKanbanCard(ctx, proposalId, Date.now());
  return totalBudgetCents;
}

async function refreshProposalMilestoneDrawAvailability(
  ctx: MutationCtx,
  proposalId: Id<"buildProposals">,
  input: { borrowerCoPayBps: number; updatedAt: number },
) {
  const milestones = (await collectByIndex(
    ctx,
    "proposalMilestones",
    "by_proposal",
    proposalId,
  )) as Doc<"proposalMilestones">[];

  for (const milestone of milestones) {
    const drawAvailabilityCents = calculateDrawAvailability(
      milestone.budgetCents,
      input.borrowerCoPayBps,
    );
    await ctx.db.patch(milestone._id, {
      drawAvailabilityCents,
      updatedAt: input.updatedAt,
    });
  }
}

async function applyProductionTimelineModificationRequest(
  ctx: MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    proposal: Doc<"buildProposals">;
    roles: RoleSlug[];
    subject: string;
  },
  request: Doc<"proposalTimelineModificationRequests">,
) {
  if (request.requestType === "createMilestone") {
    const milestone = request.requestedPayload?.milestone;
    if (!milestone) {
      throw new Error("milestone payload is required.");
    }
    await insertProductionMilestoneFromInput(ctx, auth, milestone);
    await recalculateProposalBudget(ctx, auth, request.proposalId);
    return;
  }
  if (!request.milestoneKey) {
    throw new Error("milestoneKey is required.");
  }
  const milestone = await getProductionMilestoneOrThrow(
    ctx,
    request.proposalId,
    request.milestoneKey,
  );
  if (request.requestType === "deleteMilestone") {
    await deleteProductionMilestoneCascade(ctx, request.proposalId, milestone);
    await recalculateProposalBudget(ctx, auth, request.proposalId);
    return;
  }
  if (request.requestType === "updateMilestoneBudget") {
    const budgetCents = request.requestedPayload?.budgetCents;
    if (typeof budgetCents !== "number" || budgetCents < 0) {
      throw new Error("budgetCents is required.");
    }
    await ctx.db.patch(milestone._id, {
      budgetCents: Math.round(budgetCents),
      drawAvailabilityCents: calculateDrawAvailability(
        Math.round(budgetCents),
        auth.proposal.borrowerCoPayBps,
      ),
      updatedAt: Date.now(),
    });
    await recalculateProposalBudget(ctx, auth, request.proposalId);
  }
}

async function insertProductionCapitalEvent(
  ctx: MutationCtx,
  auth: {
    brokerage: Doc<"brokerages">;
    proposal: Doc<"buildProposals">;
  },
  input: {
    amountCents: number;
    capitalEventKey: string;
    eventKind: "cashInfusion" | "cost" | "homeEquityTakeout";
    interestAnnualBps?: number;
    label: string;
    order?: number;
    proposalId: Id<"buildProposals">;
    x: number;
  },
) {
  const existing = await ctx.db
    .query("proposalCapitalEvents")
    .withIndex("by_proposal_key", (q) =>
      q
        .eq("proposalId", input.proposalId)
        .eq("capitalEventKey", input.capitalEventKey),
    )
    .unique();
  if (existing) {
    throw new Error("Production capital event already exists.");
  }
  if (
    input.eventKind === "homeEquityTakeout" &&
    (!Number.isFinite(input.amountCents) || input.amountCents <= 0)
  ) {
    throw new Error("Home Equity Takeout amount must be greater than zero.");
  }
  const rows = await collectByIndex(
    ctx,
    "proposalCapitalEvents",
    "by_proposal",
    input.proposalId,
  );
  const x = await normalizeProposalCapitalEventDay(ctx, auth.proposal, input.x);
  const now = Date.now();
  await ctx.db.insert("proposalCapitalEvents", {
    amountCents: Math.max(0, Math.round(input.amountCents)),
    brokerageId: auth.brokerage._id,
    capitalEventKey: input.capitalEventKey,
    createdAt: now,
    eventKind: input.eventKind,
    ...(input.interestAnnualBps === undefined
      ? {}
      : { interestAnnualBps: input.interestAnnualBps }),
    label:
      input.label.trim() ||
      (input.eventKind === "cashInfusion"
        ? "Cash infusion"
        : input.eventKind === "homeEquityTakeout"
          ? "Home Equity Takeout"
          : "Capital spike"),
    order: input.order ?? rows.length + 1,
    organizationId: auth.proposal.organizationId,
    proposalId: input.proposalId,
    updatedAt: now,
    x,
  });
}

