type SeedScenario =
  | "draft"
  | "submitted"
  | "approved_with_permit"
  | "approved_with_waiver"
  | "requested_changes"
  | "rejected"
  | "closed";

async function ensureSeedScenarioProposal(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    brokerageId: Id<"brokerages">;
    buildName: string;
    builderProfileId: Id<"builderProfiles">;
    now: number;
    organizationId: string;
    scenario: SeedScenario;
    templateId: Id<"proposalTemplates">;
  },
) {
  const existing = (
    await ctx.db
      .query("buildProposals")
      .withIndex("by_brokerage", (q) => q.eq("brokerageId", input.brokerageId))
      .collect()
  ).find((proposal) => proposal.buildName === input.buildName);
  if (existing) {
    return existing._id;
  }

  const { workosUserId: assignedBrokerWorkosUserId } =
    await requireDefaultBrokerMember(ctx, input.auth.brokerage);
  const proposalId = await ctx.db.insert("buildProposals", {
    assignedBrokerWorkosUserId,
    brokerageId: input.brokerageId,
    borrowerCoPayBps: 2000,
    borrowerStartingCashCents: 40_000_000,
    borrowerWorkingCapitalLimitCents: 40_000_000,
    buildName: input.buildName,
    builderProfileId: input.builderProfileId,
    capitalSource: "internal",
    createdAt: input.now,
    createdByWorkosUserId: "user_builder",
    interestAnnualBps: 925,
    lenderDrawPolicyLimitCents: 55_000_000,
    location: `${input.buildName.replace("Seed Scenario - ", "")} Site, Toronto, ON`,
    organizationId: input.organizationId,
    reviewOutcome: "none",
    status: "draft",
    templateId: input.templateId,
    totalBudgetCents: 0,
    updatedAt: input.now,
    updatedByWorkosUserId: "user_builder",
  });
  await upsertKanbanCard(ctx, proposalId, input.now);
  await writeProposalEvent(ctx, {
    auth: input.auth,
    command: "dev_seedProductionProposalScenarios",
    eventType: "proposal.created",
    newState: "draft",
    proposalId,
  });

  await seedProposalPackage(ctx, {
    ...input,
    includePermit:
      input.scenario === "approved_with_permit" || input.scenario === "closed",
    proposalId,
  });

  if (input.scenario === "draft") {
    return proposalId;
  }

  await seedSubmitProposal(ctx, {
    auth: input.auth,
    now: input.now,
    organizationId: input.organizationId,
    proposalId,
  });
  if (input.scenario === "submitted") {
    return proposalId;
  }

  if (input.scenario === "requested_changes") {
    await ctx.db.patch(proposalId, {
      reviewOutcome: "requested_changes",
      status: "draft",
      updatedAt: input.now,
      updatedByWorkosUserId: input.auth.subject,
    });
    await upsertKanbanCard(ctx, proposalId, input.now);
    await writeProposalEvent(ctx, {
      auth: input.auth,
      command: "dev_seedProductionProposalScenarios",
      eventType: "proposal.changes_requested",
      newState: "draft",
      priorState: "submitted",
      proposalId,
      reason: "Seeded request-changes review path.",
    });
    return proposalId;
  }

  if (input.scenario === "rejected") {
    await ctx.db.patch(proposalId, {
      reviewOutcome: "rejected",
      updatedAt: input.now,
      updatedByWorkosUserId: input.auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth: input.auth,
      command: "dev_seedProductionProposalScenarios",
      eventType: "proposal.rejected",
      newState: "submitted",
      priorState: "submitted",
      proposalId,
      reason: "Seeded rejection review path.",
    });
    return proposalId;
  }

  await seedApproveProposal(ctx, {
    auth: input.auth,
    now: input.now,
    organizationId: input.organizationId,
    permitWaiverReason:
      input.scenario === "approved_with_waiver"
        ? "Seeded waiver: municipal permit follows closing in this scenario."
        : undefined,
    proposalId,
  });
  if (input.scenario !== "closed") {
    return proposalId;
  }

  await seedCloseProposal(ctx, {
    auth: input.auth,
    buildStartDate: "2099-09-01",
    ianaTimezone: "America/Toronto",
    loanFacility: {
      interestAnnualBps: 925,
      principalCents: 55_000_000,
    },
    now: input.now,
    organizationId: input.organizationId,
    proposalId,
  });
  return proposalId;
}

async function seedProposalPackage(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    brokerageId: Id<"brokerages">;
    includePermit: boolean;
    now: number;
    organizationId: string;
    proposalId: Id<"buildProposals">;
  },
) {
  const milestones = [
    {
      budgetCents: 30_000_000,
      dayEnd: 30,
      dayStart: 0,
      dependencyKeys: [] as string[],
      durationDays: 30,
      key: "foundation",
      name: "Foundation",
      order: 1,
      submilestones: [
        {
          budgetCents: 14_000_000,
          durationDays: 12,
          key: "forms-and-pour",
          name: "Forms and pour",
          order: 1,
          startDay: 0,
        },
        {
          budgetCents: 16_000_000,
          durationDays: 8,
          key: "waterproofing",
          name: "Waterproofing and backfill",
          order: 2,
          startDay: 12,
        },
      ],
    },
    {
      budgetCents: 45_000_000,
      dayEnd: 75,
      dayStart: 31,
      dependencyKeys: ["foundation"],
      durationDays: 45,
      key: "shell-dry-in",
      name: "Shell and Dry-In",
      order: 2,
      submilestones: [] as {
        budgetCents: number;
        durationDays: number;
        key: string;
        name: string;
        order: number;
        startDay: number;
      }[],
    },
  ];
  let totalBudgetCents = 0;
  for (const milestone of milestones) {
    totalBudgetCents += milestone.budgetCents;
    const drawAvailabilityCents = calculateDrawAvailability(
      milestone.budgetCents,
      2000,
    );
    const proposalMilestoneId = await ctx.db.insert("proposalMilestones", {
      brokerageId: input.brokerageId,
      budgetCents: milestone.budgetCents,
      createdAt: input.now,
      dayEnd: milestone.dayEnd,
      dayStart: milestone.dayStart,
      dependencyKeys: milestone.dependencyKeys,
      drawAvailabilityCents,
      durationDays: milestone.durationDays,
      key: milestone.key,
      name: milestone.name,
      order: milestone.order,
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      updatedAt: input.now,
    });
    for (const submilestone of milestone.submilestones) {
      const proposalSubmilestoneId = await ctx.db.insert(
        "proposalSubmilestones",
        {
        brokerageId: input.brokerageId,
        budgetCents: submilestone.budgetCents,
        createdAt: input.now,
        durationDays: submilestone.durationDays,
        key: submilestone.key,
        milestoneKey: milestone.key,
        name: submilestone.name,
        order: submilestone.order,
        organizationId: input.organizationId,
        proposalId: input.proposalId,
        proposalMilestoneId,
        startDay: submilestone.startDay,
        updatedAt: input.now,
        },
      );
      await upsertSubmilestoneScopeV1Draft(ctx, {
        authoredByWorkosUserId: input.auth.subject,
        brokerageId: input.brokerageId,
        now: input.now,
        organizationId: input.organizationId,
        proposalId: input.proposalId,
        proposalSubmilestoneId,
        scopeOfWorkTiptapJson: labeledCanonicalTiptapDocument(
          `${submilestone.name} contractual Scope.`,
        ),
      });
      await upsertProposalSubmilestoneFieldGuidance(ctx, {
        auth: input.auth,
        fieldGuidance: {
          cameraAnglesTiptapJson: labeledCanonicalTiptapDocument(
            `Capture the work area and completed ${submilestone.name} from multiple angles.`,
          ),
          whatToVerifyTiptapJson: labeledCanonicalTiptapDocument(
            `Verify the completed ${submilestone.name} against its contractual Scope.`,
          ),
        },
        now: input.now,
        proposalId: input.proposalId,
        proposalSubmilestoneId,
        workosOrganizationId: input.organizationId,
      });
    }
    await ctx.db.insert("proposalDrawScheduleRows", {
      amountCents: drawAvailabilityCents,
      brokerageId: input.brokerageId,
      createdAt: input.now,
      drawKey: `draw-${String(milestone.order).padStart(2, "0")}`,
      label: `${milestone.name} reimbursement draw`,
      milestoneKey: milestone.key,
      order: milestone.order,
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      proposalMilestoneId,
      source: "milestone",
      timingDay: milestone.dayEnd,
      updatedAt: input.now,
    });
  }

  if (input.includePermit) {
    await ctx.db.insert("proposalDocuments", {
      brokerageId: input.brokerageId,
      createdAt: input.now,
      documentType: "permit",
      fileName: "seed-permit.pdf",
      mimeType: "application/pdf",
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      sizeBytes: 4096,
      status: "uploaded",
      updatedAt: input.now,
      uploadedByWorkosUserId: "user_builder",
    });
  } else {
    await ctx.db.insert("proposalDocuments", {
      brokerageId: input.brokerageId,
      createdAt: input.now,
      documentType: "budget",
      fileName: "seed-budget.pdf",
      mimeType: "application/pdf",
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      sizeBytes: 2048,
      status: "uploaded",
      updatedAt: input.now,
      uploadedByWorkosUserId: "user_builder",
    });
  }

  await ctx.db.insert("proposalEvidenceAssets", {
    brokerageId: input.brokerageId,
    createdAt: input.now,
    evidenceKey: `seed-site-photo-${String(input.proposalId)}`,
    fileName: "seed-site-photo.jpg",
    label: "Seed site photo",
    locationVerified: true,
    milestoneKey: "foundation",
    mimeType: "image/jpeg",
    organizationId: input.organizationId,
    proposalId: input.proposalId,
    sizeBytes: 2048,
    source: "seeded_production_workspace",
    tag: "site-photo",
    updatedAt: input.now,
  });

  await ctx.db.patch(input.proposalId, {
    totalBudgetCents,
    updatedAt: input.now,
  });
}

async function seedSubmitProposal(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    now: number;
    organizationId: string;
    proposalId: Id<"buildProposals">;
  },
) {
  const workflowRule = await getActiveWorkflowRule(
    ctx,
    input.auth.brokerage._id,
  );
  const snapshotId = await ctx.db.insert("workflowRuleSnapshots", {
    allowPermitWaiverByRoles: workflowRule.allowPermitWaiverByRoles,
    brokerageId: input.auth.brokerage._id,
    createdAt: input.now,
    organizationId: input.organizationId,
    proposalId: input.proposalId,
    proposalStates: workflowRule.proposalStates,
    requirePermitForApproval: workflowRule.requirePermitForApproval,
    ruleKey: workflowRule.ruleKey,
    settings: workflowRule.settings,
    version: workflowRule.version,
    workflowRuleId: workflowRule._id,
  });
  await ctx.db.patch(input.proposalId, {
    backOfficeApprovedByWorkosUserId: undefined,
    reviewOutcome: "none",
    status: "submitted",
    submittedAt: input.now,
    updatedAt: input.now,
    updatedByWorkosUserId: input.auth.subject,
    workflowRuleSnapshotId: snapshotId,
  });
  await upsertKanbanCard(ctx, input.proposalId, input.now);
  await writeProposalEvent(ctx, {
    auth: input.auth,
    command: "dev_seedProductionProposalScenarios",
    eventType: "proposal.submitted",
    newState: "submitted",
    priorState: "draft",
    proposalId: input.proposalId,
  });
}

async function seedApproveProposal(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    now: number;
    organizationId: string;
    permitWaiverReason?: string;
    proposalId: Id<"buildProposals">;
  },
) {
  let waiverWarnings: string[] = [];
  if (input.permitWaiverReason) {
    await ctx.db.insert("documentWaivers", {
      brokerageId: input.auth.brokerage._id,
      createdAt: input.now,
      documentType: "permit",
      grantedByRole: "admin",
      grantedByWorkosUserId: input.auth.subject,
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      reason: input.permitWaiverReason,
    });
    waiverWarnings = ["permit-waived"];
  }

  await ctx.db.patch(input.proposalId, {
    approvedAt: input.now,
    reviewOutcome: "approved",
    status: "approved",
    updatedAt: input.now,
    updatedByWorkosUserId: input.auth.subject,
  });
  await upsertKanbanCard(ctx, input.proposalId, input.now);
  await writeProposalEvent(ctx, {
    auth: input.auth,
    command: "dev_seedProductionProposalScenarios",
    eventType: "proposal.approved",
    newState: "approved",
    priorState: "submitted",
    proposalId: input.proposalId,
    reason: input.permitWaiverReason
      ? "Seeded approval with permit waiver."
      : "Seeded approval with uploaded permit.",
    warnings: waiverWarnings,
  });
}

const LEGACY_ACTIVE_BUILD_LOAN_WARNING =
  "loan_facility_not_reconstructed_missing_authoritative_terms";

async function repairLegacyClosedProposalActiveBuildAggregate(
  ctx: MutationCtx,
  input: {
    auth: {
      brokerage: Doc<"brokerages">;
      proposal: Doc<"buildProposals">;
      roles: RoleSlug[];
      subject: string;
    };
    buildStartDate: string;
    ianaTimezone?: string;
    reason: string;
    warnings?: string[];
  },
) {
  requireReason(input.reason);
  const buildStartDate = normalizeIsoDateOnly(
    input.buildStartDate,
    "Legacy Active Build start date",
  );
  const timezone =
    input.ianaTimezone === undefined
      ? undefined
      : validateBuildTimezone(input.ianaTimezone);
  const { brokerage, proposal } = input.auth;
  if (proposal.status !== "closed") {
    throw new Error("Legacy Active Build repair requires a closed proposal.");
  }
  if (
    proposal.brokerageId !== brokerage._id ||
    proposal.organizationId !== brokerage.workosOrganizationId
  ) {
    throw new Error("Legacy Active Build repair scope does not match.");
  }

  const validateExistingBuild = (build: Doc<"activeBuilds">) => {
    if (
      build.proposalId !== proposal._id ||
      build.brokerageId !== brokerage._id ||
      build.organizationId !== proposal.organizationId
    ) {
      throw new Error("Legacy Active Build repair found a cross-scope build.");
    }
  };
  const warningsForBuild = async (buildId: Id<"activeBuilds">) => {
    const loan = await ctx.db
      .query("loanFacilities")
      .withIndex("by_build", (q) => q.eq("buildId", buildId))
      .first();
    return loan ? [] : [LEGACY_ACTIVE_BUILD_LOAN_WARNING];
  };

  if (proposal.activeBuildId) {
    const linkedBuild = await ctx.db.get(proposal.activeBuildId);
    if (!linkedBuild) {
      throw new Error("Legacy proposal references a missing Active Build.");
    }
    validateExistingBuild(linkedBuild);
    if (timezone !== undefined) {
      await ctx.db.patch(linkedBuild._id, {
        timezone,
        updatedAt: Date.now(),
      });
      const repairedBuild = await ctx.db.get(linkedBuild._id);
      if (repairedBuild) {
        await scheduleCurrentMilestoneSystemPostActivations(ctx, {
          build: repairedBuild,
        });
      }
    }
    return {
      buildId: linkedBuild._id,
      operation: "already_repaired" as const,
      warnings: await warningsForBuild(linkedBuild._id),
    };
  }

  const existingBuilds = await ctx.db
    .query("activeBuilds")
    .withIndex("by_proposal", (q) => q.eq("proposalId", proposal._id))
    .take(2);
  if (existingBuilds.length > 1) {
    throw new Error("Legacy proposal has multiple Active Build records.");
  }
  const existingBuild = existingBuilds[0];
  if (existingBuild) {
    validateExistingBuild(existingBuild);
    const now = Date.now();
    let repairedBuild = existingBuild;
    if (timezone !== undefined) {
      await ctx.db.patch(existingBuild._id, {
        timezone,
        updatedAt: now,
      });
      repairedBuild = (await ctx.db.get(existingBuild._id)) ?? existingBuild;
      await scheduleCurrentMilestoneSystemPostActivations(ctx, {
        build: repairedBuild,
      });
    }
    const warnings = await warningsForBuild(existingBuild._id);
    await ctx.db.patch(proposal._id, {
      activeBuildId: existingBuild._id,
      updatedAt: now,
      updatedByWorkosUserId: input.auth.subject,
    });
    await writeProposalEvent(ctx, {
      auth: input.auth,
      command: "repairLegacyClosedProposalActiveBuild",
      eventType: "proposal.active_build.relinked",
      newState: JSON.stringify({ activeBuildId: existingBuild._id }),
      priorState: JSON.stringify({ activeBuildId: null, status: "closed" }),
      proposalId: proposal._id,
      reason: input.reason,
      warnings,
    });
    await writeActiveBuildEvent(ctx, {
      auth: { ...input.auth, proposal },
      build: repairedBuild,
      command: "repairLegacyClosedProposalActiveBuild",
      eventType: "active_build.relinked_to_legacy_proposal",
      newState: JSON.stringify({ proposalId: proposal._id }),
      reason: input.reason,
      warnings,
    });
    return {
      buildId: existingBuild._id,
      operation: "relinked" as const,
      warnings,
    };
  }

  const warnings = [
    ...new Set([
      LEGACY_ACTIVE_BUILD_LOAN_WARNING,
      ...(input.warnings ?? [])
        .map((warning) => warning.trim())
        .filter(Boolean),
    ]),
  ];
  const buildId = await seedCloseProposal(ctx, {
    activeBuildEventType: "active_build.created_from_legacy_proposal",
    auth: input.auth,
    buildStartDate,
    ianaTimezone: timezone,
    command: "repairLegacyClosedProposalActiveBuild",
    now: Date.now(),
    organizationId: proposal.organizationId,
    proposalEventType: "proposal.active_build.repaired",
    proposalId: proposal._id,
    proposalNewState: JSON.stringify({
      activeBuildMaterialized: true,
      loanFacilityCreated: false,
      status: "closed",
    }),
    reason: input.reason,
    warnings,
  });
  return { buildId, operation: "created" as const, warnings };
}

async function copyProposalContractorsToActiveBuild(
  ctx: MutationCtx,
  input: {
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    buildId: Id<"activeBuilds">;
    buildMilestoneIds: Map<string, Id<"buildMilestones">>;
    buildStartDate: string;
    buildSubmilestoneIds: Map<string, Id<"buildSubmilestones">>;
    now: number;
    organizationId: string;
    proposalId: Id<"buildProposals">;
  },
) {
  const proposalContractors = await collectByIndex(
    ctx,
    "proposalContractorAssignments",
    "by_proposal",
    input.proposalId,
  );
  const buildContractorAssignmentByProposalAssignment = new Map<
    string,
    Id<"buildContractorAssignments">
  >();
  for (const assignment of proposalContractors) {
    if (assignment.status !== "active") {
      continue;
    }
    const contractor = (await ctx.db.get(
      assignment.contractorId,
    )) as Doc<"contractorProfiles"> | null;
    if (
      !contractor ||
      contractor.brokerageId !== input.auth.brokerage._id ||
      contractor.status !== "active"
    ) {
      continue;
    }
    const buildContractorAssignmentId = await ctx.db.insert(
      "buildContractorAssignments",
      {
        agreedRateCents:
          assignment.agreedRateCents ?? contractor.defaultPayRateCents,
        agreedRateUnit:
          assignment.agreedRateUnit ?? contractor.defaultPayRateUnit ?? "hour",
        brokerageId: input.auth.brokerage._id,
        buildId: input.buildId,
        contractorId: assignment.contractorId,
        createdAt: input.now,
        endDate: undefined,
        notes: assignment.notes,
        organizationId: input.organizationId,
        role: assignment.role,
        startDate: input.buildStartDate,
        status: "active",
        updatedAt: input.now,
      },
    );
    buildContractorAssignmentByProposalAssignment.set(
      String(assignment._id),
      buildContractorAssignmentId,
    );
  }
  const proposalMilestoneContractors = await collectByIndex(
    ctx,
    "proposalMilestoneContractorAssignments",
    "by_proposal",
    input.proposalId,
  );
  for (const assignment of proposalMilestoneContractors) {
    if (assignment.status === "removed") {
      continue;
    }
    const buildMilestoneId = input.buildMilestoneIds.get(
      String(assignment.proposalMilestoneId),
    );
    const buildContractorAssignmentId =
      buildContractorAssignmentByProposalAssignment.get(
        String(assignment.proposalContractorAssignmentId),
      );
    if (!(buildMilestoneId && buildContractorAssignmentId)) {
      continue;
    }
    await ctx.db.insert("milestoneContractorAssignments", {
      actualCostCents: undefined,
      actualHours: undefined,
      agreedRateCents: assignment.agreedRateCents,
      agreedRateUnit: assignment.agreedRateUnit,
      assignedAt: input.now,
      assignedByWorkosUserId: assignment.assignedByWorkosUserId,
      brokerageId: input.auth.brokerage._id,
      buildContractorAssignmentId,
      buildId: input.buildId,
      buildMilestoneId,
      buildSubmilestoneId: assignment.proposalSubmilestoneId
        ? input.buildSubmilestoneIds.get(
            String(assignment.proposalSubmilestoneId),
          )
        : undefined,
      contractorId: assignment.contractorId,
      costNotes: assignment.note,
      createdAt: input.now,
      estimatedCostCents: assignment.estimatedCostCents,
      estimatedHours: assignment.estimatedHours,
      milestoneKey: assignment.milestoneKey,
      note: assignment.note,
      organizationId: input.organizationId,
      postHoc: false,
      role: assignment.role,
      status:
        assignment.status === "completed"
          ? "completed"
          : new Date(`${input.buildStartDate}T00:00:00Z`).getTime() > input.now
            ? "planned"
            : "active",
      submilestoneKey: assignment.submilestoneKey,
      updatedAt: input.now,
    });
  }
}

async function seedCloseProposal(
  ctx: MutationCtx,
  input: {
    activeBuildEventType?: string;
    activeBuildNewState?: string;
    auth: { brokerage: Doc<"brokerages">; roles: RoleSlug[]; subject: string };
    buildStartDate: string;
    ianaTimezone?: string;
    command?: string;
    loanFacility?: { interestAnnualBps: number; principalCents: number };
    now: number;
    organizationId: string;
    proposalId: Id<"buildProposals">;
    proposalEventType?: string;
    proposalNewState?: string;
    reason?: string;
    warnings?: string[];
  },
) {
  const proposal = await ctx.db.get(input.proposalId);
  if (!proposal?.workflowRuleSnapshotId) {
    throw new Error("Seeded proposal is missing workflow rule snapshot.");
  }
  let reviewPolicyLock = proposal.lockedReviewPolicyId
    ? await ctx.db.get(proposal.lockedReviewPolicyId)
    : null;
  if (!reviewPolicyLock && proposal.status === "approved") {
    if (!proposal.backOfficeApprovedByWorkosUserId) {
      await ctx.db.patch(proposal._id, {
        backOfficeApprovedByWorkosUserId: input.auth.subject,
      });
    }
    const approvedProposal = await ctx.db.get(proposal._id);
    if (!approvedProposal) {
      throw new Error("Seeded proposal is unavailable before policy lock.");
    }
    const policyVersion = await ensureDefaultProposalReviewPolicyVersion(ctx, {
      auth: { ...input.auth, proposal: approvedProposal },
      now: input.now,
    });
    const revisionProposal = await ctx.db.get(proposal._id);
    if (!revisionProposal) {
      throw new Error("Seeded proposal is unavailable before revision.");
    }
    const revision = await createImmutableProposalRevision(ctx, {
      assignment: null,
      auth: { ...input.auth, proposal: revisionProposal },
      idempotencyKey: "system:seed-review-policy-revision",
      policyVersion,
      reason: "Create the canonical review-policy revision for seeded closing.",
    });
    const reviewPolicyLockId = await ctx.db.insert(
      "proposalReviewPolicyLocks",
      {
        activeLenderMemberCount: 0,
        brokerageId: input.auth.brokerage._id,
        eligibleLenderApproverCount: 0,
        eligibleLenderApproverCounts: {
          draw: 0,
          milestone: 0,
          proposalReview: 0,
        },
        idempotencyKey: "system:seed-review-policy-lock",
        lockedAt: input.now,
        lockedByRole: requirePhase3BackofficeRole(input.auth),
        lockedByWorkosUserId: input.auth.subject,
        organizationId: input.organizationId,
        policy: policyVersion.policy,
        policyVersionId: policyVersion._id,
        proposalId: proposal._id,
        proposalRevisionId: revision._id,
        proposalRevisionNumber: revision.revisionNumber,
        reason: "Lock the canonical review policy for seeded closing.",
      },
    );
    await ctx.db.patch(proposal._id, {
      lockedReviewPolicyId: reviewPolicyLockId,
    });
    reviewPolicyLock = await ctx.db.get(reviewPolicyLockId);
  }
  const permit = await getPermitDocument(ctx, input.proposalId);
  const permitWaiver = await getPermitWaiver(ctx, input.proposalId);
  const assignedBuilderProfileId = assignedBuilderProfileIdOrThrow(proposal);
  const timezone =
    input.ianaTimezone === undefined
      ? undefined
      : validateBuildTimezone(input.ianaTimezone);
  const buildId = await ctx.db.insert("activeBuilds", {
    brokerageId: input.auth.brokerage._id,
    borrowerStartingCashCents: resolveBorrowerStartingCashCents(proposal),
    buildName: proposal.buildName,
    builderProfileId: assignedBuilderProfileId,
    createdAt: input.now,
    location: proposal.location,
    locationLatitude: proposal.locationLatitude,
    locationLongitude: proposal.locationLongitude,
    locationPlaceId: proposal.locationPlaceId,
    organizationId: input.organizationId,
    permitDocumentId: permit?._id,
    permitWaiverId: permitWaiver?._id,
    proposalId: input.proposalId,
    ...(reviewPolicyLock
      ? {
          reviewPolicyLockId: reviewPolicyLock._id,
          reviewPolicySnapshot: reviewPolicyLock.policy,
        }
      : {}),
    startDate: input.buildStartDate,
    status:
      new Date(`${input.buildStartDate}T00:00:00Z`).getTime() > input.now
        ? "future_start"
        : "active",
    ...(timezone ? { timezone } : {}),
    timelineMinimumCashReserveCents: proposal.timelineMinimumCashReserveCents,
    timelineRangeMax: proposal.timelineRangeMax,
    timelineRangeMin: PROPOSAL_TIMELINE_MIN_DAY,
    timelineStartingCashCents: proposal.timelineStartingCashCents,
    totalBudgetCents: proposal.totalBudgetCents,
    updatedAt: input.now,
    workflowRuleSnapshotId: proposal.workflowRuleSnapshotId,
  });
  await ctx.db.insert("buildBrokerAssignments", {
    assignedBrokerWorkosUserId:
      proposal.assignedBrokerWorkosUserId ??
      (await requireDefaultBrokerMember(ctx, input.auth.brokerage))
        .workosUserId,
    brokerageId: input.auth.brokerage._id,
    buildId,
    createdAt: input.now,
    organizationId: input.organizationId,
    role: "primary",
  });
  if (input.loanFacility) {
    await ctx.db.insert("loanFacilities", {
      brokerageId: input.auth.brokerage._id,
      buildId,
      createdAt: input.now,
      facilityKind: "construction",
      interestAnnualBps: input.loanFacility.interestAnnualBps,
      interestAccrualStartDate: input.buildStartDate,
      interestStartsOn: "funds_released",
      organizationId: input.organizationId,
      paybackDate: addDaysIso(
        input.buildStartDate,
        proposal.timelineRangeMax ?? 365,
      ),
      principalCents: input.loanFacility.principalCents,
      proposalId: input.proposalId,
      status: "active",
      updatedAt: input.now,
    });
  }
  await ctx.db.insert("buildCapitalPlans", {
    borrowerCoPayBps: proposal.borrowerCoPayBps,
    borrowerStartingCashCents: resolveBorrowerStartingCashCents(proposal),
    borrowerWorkingCapitalLimitCents:
      resolveBorrowerStartingCashCents(proposal),
    brokerageId: input.auth.brokerage._id,
    buildId,
    createdAt: input.now,
    lenderDrawPolicyLimitCents: proposal.lenderDrawPolicyLimitCents,
    organizationId: input.organizationId,
    proposalId: input.proposalId,
    source: "proposal_closing_copy",
    updatedAt: input.now,
    version: 1,
  });

  const buildMilestoneIds = new Map<string, Id<"buildMilestones">>();
  const buildSubmilestoneIds = new Map<string, Id<"buildSubmilestones">>();
  const milestones = await collectByIndex(
    ctx,
    "proposalMilestones",
    "by_proposal",
    input.proposalId,
  );
  for (const milestone of milestones) {
    const buildMilestoneId = await ctx.db.insert("buildMilestones", {
      brokerageId: input.auth.brokerage._id,
      budgetCents: milestone.budgetCents,
      buildId,
      completionClaim: milestone.completionClaim,
      completionReview: milestone.completionReview,
      createdAt: input.now,
      dayEnd: milestone.dayEnd,
      dayStart: milestone.dayStart,
      dependencyKeys: milestone.dependencyKeys,
      drawAvailabilityCents: milestone.drawAvailabilityCents,
      durationDays: milestone.durationDays,
      evidenceState: milestone.evidenceState,
      key: milestone.key,
      name: milestone.name,
      order: milestone.order,
      organizationId: input.organizationId,
      policyState: milestone.policyState,
      proposalMilestoneId: milestone._id,
      siteVisitGuidance: milestone.siteVisitGuidance
        ? normalizeSiteVisitGuidance(milestone.siteVisitGuidance)
        : undefined,
      status:
        milestone.completionReview?.status === "approved"
          ? "complete"
          : "planned",
      workflowRevision: 0,
      updatedAt: input.now,
    });
    buildMilestoneIds.set(milestone._id, buildMilestoneId);
  }

  const submilestones = await collectByIndex(
    ctx,
    "proposalSubmilestones",
    "by_proposal",
    input.proposalId,
  );
  for (const submilestone of submilestones) {
    const buildMilestoneId = buildMilestoneIds.get(
      submilestone.proposalMilestoneId,
    );
    if (!buildMilestoneId) {
      continue;
    }
    const buildSubmilestoneId = await ctx.db.insert("buildSubmilestones", {
      brokerageId: input.auth.brokerage._id,
      budgetCents: submilestone.budgetCents,
      buildId,
      buildMilestoneId,
      createdAt: input.now,
      durationDays: submilestone.durationDays,
      key: submilestone.key,
      milestoneKey: submilestone.milestoneKey,
      name: submilestone.name,
      order: submilestone.order,
      organizationId: input.organizationId,
      proposalSubmilestoneId: submilestone._id,
      startDay: submilestone.startDay,
      status: "planned",
      updatedAt: input.now,
    });
    await attachSubmilestoneScopeBuildLineage(ctx, {
      brokerageId: input.auth.brokerage._id,
      buildId,
      buildSubmilestoneId,
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      proposalSubmilestoneId: submilestone._id,
    });
    await attachSubmilestoneFieldGuidanceBuildLineage(ctx, {
      brokerageId: input.auth.brokerage._id,
      buildId,
      buildSubmilestoneId,
      organizationId: input.organizationId,
      proposalId: input.proposalId,
      proposalSubmilestoneId: submilestone._id,
    });
    buildSubmilestoneIds.set(submilestone._id, buildSubmilestoneId);
  }

  const draws = await collectByIndex(
    ctx,
    "proposalDrawScheduleRows",
    "by_proposal",
    input.proposalId,
  );
  for (const draw of draws) {
    await ctx.db.insert("plannedDrawScheduleRows", {
      amountCents: draw.amountCents,
      brokerageId: input.auth.brokerage._id,
      buildId,
      buildMilestoneId: draw.proposalMilestoneId
        ? buildMilestoneIds.get(draw.proposalMilestoneId)
        : undefined,
      createdAt: input.now,
      drawKey: draw.drawKey,
      label: draw.label,
      milestoneKey: draw.milestoneKey,
      order: draw.order,
      organizationId: input.organizationId,
      proposalDrawScheduleRowId: draw._id,
      requestNote: draw.requestNote,
      requestReviewNote: draw.requestReviewNote,
      requestedAt: draw.requestedAt,
      reviewedAt: draw.reviewedAt,
      status: activeBuildDrawStatusFromProposal(draw.requestStatus),
      timingDay: draw.timingDay,
      updatedAt: input.now,
    });
  }
  await copyProposalContractorsToActiveBuild(ctx, {
    auth: input.auth,
    buildId,
    buildMilestoneIds,
    buildStartDate: input.buildStartDate,
    buildSubmilestoneIds,
    now: input.now,
    organizationId: input.organizationId,
    proposalId: input.proposalId,
  });
  await copyProposalOperationalRowsToActiveBuild(ctx, {
    auth: input.auth,
    buildId,
    now: input.now,
    organizationId: input.organizationId,
    proposalId: input.proposalId,
  });
  await copyProposalCapitalEventsToActiveBuild(ctx, {
    brokerageId: input.auth.brokerage._id,
    buildId,
    buildStartDate: input.buildStartDate,
    now: input.now,
    organizationId: input.organizationId,
    proposal,
  });
  await ctx.db.insert("capitalEvents", {
    amountCents: 0,
    brokerageId: input.auth.brokerage._id,
    buildId,
    createdAt: input.now,
    eventDate: input.buildStartDate,
    eventType: "borrower_copay",
    label: "Capital plan opened at loan closing",
    organizationId: input.organizationId,
  });
  await ctx.db.patch(input.proposalId, {
    activeBuildId: buildId,
    closedAt: proposal.closedAt ?? input.now,
    status: "closed",
    updatedAt: input.now,
    updatedByWorkosUserId: input.auth.subject,
  });
  await upsertKanbanCard(ctx, input.proposalId, input.now);
  await writeProposalEvent(ctx, {
    auth: input.auth,
    command: input.command ?? "dev_seedProductionProposalScenarios",
    eventType: input.proposalEventType ?? "proposal.closed",
    newState: input.proposalNewState ?? "closed",
    priorState: proposal.status,
    proposalId: input.proposalId,
    reason: input.reason ?? "Seeded offline loan closing.",
    warnings: input.warnings,
  });
  const build = await ctx.db.get(buildId);
  if (build) {
    await ensureActiveBuildPlanningActivationRevision(ctx, {
      actor: {
        actorRoles: input.auth.roles,
        actorWorkosUserId: input.auth.subject,
      },
      build,
      now: input.now,
    });
    await scheduleCurrentMilestoneSystemPostActivations(ctx, {
      build,
      now: input.now,
    });
    await writeActiveBuildEvent(ctx, {
      auth: {
        brokerage: input.auth.brokerage,
        proposal,
        roles: input.auth.roles,
        subject: input.auth.subject,
      },
      build,
      command: input.command ?? "dev_seedProductionProposalScenarios",
      eventType: input.activeBuildEventType ?? "active_build.created",
      newState:
        input.activeBuildNewState ??
        JSON.stringify({ buildId, proposalId: input.proposalId }),
      reason: input.reason ?? "Seeded offline loan closing.",
      warnings: input.warnings,
    });
  }
  await ctx.db.insert("eventOutbox", {
    brokerageId: input.auth.brokerage._id,
    createdAt: input.now,
    eventType: "active_build.created",
    organizationId: input.organizationId,
    payloadPreview: JSON.stringify({
      buildId,
      proposalId: input.proposalId,
      startDate: input.buildStartDate,
    }),
    relatedEntityId: buildId,
    relatedEntityType: "activeBuild",
    status: "pending",
  });
  return buildId;
}

async function ensureSeedContractorProfile(
  ctx: MutationCtx,
  input: {
    brokerageId: Id<"brokerages">;
    now: number;
    organizationId: string;
  },
) {
  const existing = (
    await ctx.db
      .query("contractorProfiles")
      .withIndex("by_brokerage", (q) => q.eq("brokerageId", input.brokerageId))
      .collect()
  ).find((contractor) => contractor.name === "Seed Scenario Contractor LLC");
  if (existing) {
    return existing._id;
  }
  return await ctx.db.insert("contractorProfiles", {
    brokerageId: input.brokerageId,
    createdAt: input.now,
    email: "seed.contractor@example.com",
    name: "Seed Scenario Contractor LLC",
    organizationId: input.organizationId,
    phone: "555-0100",
    status: "active",
    trades: ["foundation", "framing"],
    updatedAt: input.now,
  });
}

function titleCase(value: string) {
  return value
    .split("_")
    .map((part) => `${part[0]?.toUpperCase() ?? ""}${part.slice(1)}`)
    .join(" ");
}

const AUDIT_FIELD_PRIORITY = [
  "status",
  "name",
  "label",
  "title",
  "amountCents",
  "requestedAmountCents",
  "approvedAmountCents",
  "principalCents",
  "interestAnnualBps",
  "progressPercent",
  "forecastStartDate",
  "forecastEndDate",
  "paybackDate",
  "locationVerified",
  "note",
];

function parseAuditState(value?: string): unknown {
  if (value === undefined) {
    return;
  }
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return value;
  }
}

function isAuditRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function shouldProjectAuditField(field: string): boolean {
  const lower = field.toLowerCase();
  return !(
    field.startsWith("_") ||
    lower.endsWith("id") ||
    lower.endsWith("ids") ||
    lower.endsWith("at") ||
    lower.includes("workos") ||
    lower === "organizationid" ||
    lower === "brokerageid"
  );
}

function auditFieldRank(field: string): number {
  const rank = AUDIT_FIELD_PRIORITY.indexOf(field);
  return rank === -1 ? AUDIT_FIELD_PRIORITY.length : rank;
}

function auditFieldLabel(field: string): string {
  const withoutUnit = field
    .replace(/Cents$/, "")
    .replace(/Bps$/, " rate")
    .replace(/Percent$/, " percentage");
  return titleCase(
    withoutUnit.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase(),
  );
}

function auditValueLabel(field: string, value: unknown): string {
  if (value === undefined) {
    return "Not set";
  }
  if (value === null) {
    return "None";
  }
  if (typeof value === "boolean") {
    return value ? "Yes" : "No";
  }
  if (typeof value === "number") {
    if (field.endsWith("Cents")) {
      return centsToCurrency(value);
    }
    if (field.endsWith("Bps")) {
      return `${value / 100}%`;
    }
    if (field.endsWith("Percent")) {
      return `${value}%`;
    }
    return new Intl.NumberFormat("en-US").format(value);
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) {
      return "Empty";
    }
    if (/^[a-z0-9]+(?:_[a-z0-9]+)+$/i.test(trimmed)) {
      return titleCase(trimmed.toLowerCase());
    }
    return trimmed.length > 96 ? `${trimmed.slice(0, 93)}...` : trimmed;
  }
  if (Array.isArray(value)) {
    const simpleValues = value.filter((item) =>
      ["boolean", "number", "string"].includes(typeof item),
    );
    if (simpleValues.length === value.length && value.length <= 3) {
      return simpleValues.map((item) => String(item)).join(", ") || "None";
    }
    return `${value.length} item${value.length === 1 ? "" : "s"}`;
  }
  if (isAuditRecord(value)) {
    const identifyingValue = value.label ?? value.name ?? value.status;
    return identifyingValue === undefined
      ? `${Object.keys(value).length} recorded fields`
      : auditValueLabel(field, identifyingValue);
  }
  return String(value);
}

function projectAuditStateChanges(priorState?: string, newState?: string) {
  const before = parseAuditState(priorState);
  const after = parseAuditState(newState);
  if (!(isAuditRecord(before) || isAuditRecord(after))) {
    if (before === undefined && after === undefined) {
      return [];
    }
    return [
      {
        after: auditValueLabel("state", after),
        before: auditValueLabel("state", before),
        field: "State",
      },
    ];
  }

  const beforeRecord = isAuditRecord(before) ? before : {};
  const afterRecord = isAuditRecord(after) ? after : {};
  const fields = [
    ...new Set([...Object.keys(beforeRecord), ...Object.keys(afterRecord)]),
  ]
    .filter(shouldProjectAuditField)
    .filter(
      (field) =>
        JSON.stringify(beforeRecord[field]) !==
        JSON.stringify(afterRecord[field]),
    )
    .sort((left, right) => {
      const rankDelta = auditFieldRank(left) - auditFieldRank(right);
      return rankDelta || left.localeCompare(right);
    })
    .slice(0, 5);

  return fields.map((field) => ({
    after: auditValueLabel(field, afterRecord[field]),
    before: auditValueLabel(field, beforeRecord[field]),
    field: auditFieldLabel(field),
  }));
}

function emptyProposalKanbanColumns() {
  return PROPOSAL_COLUMNS.map((id) => ({
    cards: [],
    id,
    name: titleCase(id),
  }));
}
